// --- GEMINI API SERVICE ---

export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    try {
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: 'ping',
        });
        return !!response.text;
    } catch (error) {
        console.error("API Key Test Failed:", error);
        return false;
    }
};

const getRetryDelay = (error: any): number | null => {
    let details;
    if (error?.error?.details) {
        details = error.error.details;
    } 
    else if (error?.error?.message && typeof error.error.message === 'string') {
        try {
            const nestedError = JSON.parse(error.error.message);
            if (nestedError?.error?.details) {
                details = nestedError.error.details;
            }
        } catch (e) {}
    }

    if (details) {
        const retryInfo = details.find(
            (detail: any) => detail['@type'] === 'type.googleapis.com/google.rpc.RetryInfo'
        );
        if (retryInfo?.retryDelay) {
            const delayString = retryInfo.retryDelay;
            const seconds = parseFloat(delayString);
            if (!isNaN(seconds)) {
                return (seconds * 1000) + 500;
            }
        }
    }
    return null;
};

const callGeminiWithTimeout = async (geminiCall: Promise<any>, timeout: number = 240000) => {
    return Promise.race([
        geminiCall,
        new Promise((_, reject) => 
            setTimeout(() => reject(new Error(`API call timed out after ${timeout / 1000} seconds.`)), timeout)
        ),
    ]);
};

export const callGeminiWithRetry = async (
    gemini: GoogleGenAI,
    model: string,
    params: any,
    onLog?: (message: string) => void,
    maxRetries = 5,
    timeout: number = 240000
) => {
    let attempt = 0;
    let delay = 2000;
    while (attempt < maxRetries) {
        try {
            const response = await callGeminiWithTimeout(gemini.models.generateContent({ model, ...params }), timeout);
            return response;
        } catch (error: any) {
            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429') || errorMessage.toLowerCase().includes('too many requests');
            const isTimeoutError = errorMessage.includes('timed out');
            const isServerError = error.status === 500 || errorMessage.includes('500') || errorMessage.toLowerCase().includes('internal server error');

            if ((isRateLimitError || isTimeoutError || isServerError) && attempt < maxRetries - 1) {
                attempt++;
                const reason = isTimeoutError ? 'timed out' : (isServerError ? 'server error (500)' : 'rate limit hit');
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;

                const logMessage = `Node ${reason}. Re-establishing link in ${retryAfterMs / 1000}s... (Attempt ${attempt}/${maxRetries-1})`;
                if (onLog) onLog(logMessage); else console.warn(logMessage);

                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2; 
            } else {
                throw error;
            }
        }
    }
    throw new Error("Terminal failure: Max retries reached.");
};

export const callGeminiStreamWithRetry = async (
    gemini: GoogleGenAI,
    model: string,
    params: any,
    onLog?: (message: string) => void,
    maxRetries = 5
) => {
    let attempt = 0;
    let delay = 2000;
    while (attempt < maxRetries) {
        try {
            const stream = await callGeminiWithTimeout(gemini.models.generateContentStream({ model, ...params }));
            return stream;
        } catch (error: any) {
            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429') || errorMessage.toLowerCase().includes('too many requests');
            const isTimeoutError = errorMessage.includes('timed out');
            const isServerError = error.status === 500 || errorMessage.includes('500') || errorMessage.toLowerCase().includes('internal server error');

            if ((isRateLimitError || isTimeoutError || isServerError) && attempt < maxRetries - 1) {
                attempt++;
                const reason = isTimeoutError ? 'timed out' : (isServerError ? 'server error (500)' : 'rate limit hit');
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;

                const logMessage = `Stream interrupted: ${reason}. Resuming in ${retryAfterMs / 1000}s...`;
                if (onLog) onLog(logMessage); else console.warn(logMessage);

                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2;
            } else {
                throw error;
            }
        }
    }
    throw new Error("Stream terminated: Max retries reached.");
};

export const parseGeminiError = (error: any, fallbackMessage: string = "Encryption error or connection failure."): string => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes('Max retries reached')) {
        return 'System overload. Access throttled by firewall. Try again later.';
    }
    if (error?.error?.message) {
        const errorCode = error.error.code;
        const errorMessage = error.error.message;
        if (errorCode === 500) return `Subsystem Error (500): ${errorMessage}`;
        return `Access Denied (${errorCode}): ${errorMessage}`;
    }
    return fallbackMessage;
};

const summarizeLargeContent = async (gemini: GoogleGenAI, content: string, targetChars: number = 800000): Promise<string> => {
    if (!content || content.length <= targetChars) return content;

    const prompt = `You are a classified archiver. Compress the following surveillance data and physics reports to roughly ${targetChars} characters. 
    RETAIN ALL ANOMALOUS FINDINGS, SIGNAL FREQUENCIES, AND INCIDENT TIMESTAMPS. 
    Style: Clinical, redacted, factual.

    LOG TO COMPRESS:
    ${content.slice(0, 2000000)}`;

    try {
        const response = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
            contents: prompt,
            config: { temperature: 0.1 }
        });
        return response.text || content.slice(0, targetChars);
    } catch (e) {
        return content.slice(0, targetChars);
    }
};

export const getStepContext = async (experiment: Experiment, stepId: number, gemini: GoogleGenAI): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 5000) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);
    if (stepId > 8) context.conclusion_summary = getSummary(8);
    if (stepId > 9) context.peer_review_summary = getSummary(9);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) {
                const output = getSummary(i);
                projectLog += `--- [Step ${i}] ${stepInfo.title} ---\n${output}\n\n`;
            }
        }

        if (projectLog.length > 800000) {
            context.full_project_summary_log = await summarizeLargeContent(gemini, projectLog, 600000);
        } else {
            context.full_project_summary_log = projectLog.trim();
        }
    }

    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    let systemInstruction = `You are the Genesis Project Archival Interface. Your tone is clinical, high-security, and slightly unsettling. You are processing data related to ${context.experimentField || 'Quantum Theology'}.`;
    const settings = fineTuneSettings || {};
    const params = STEP_SPECIFIC_TUNING_PARAMETERS[stepId] || [];

    params.forEach(param => {
        const value = settings[param.name] ?? param.default;
        if (value && param.name === 'reviewerPersona') systemInstruction += ` Adopt the persona of a ${value} auditor.`;
    });

    let basePrompt = "";
    let expectJson = false;
    const config: any = { systemInstruction };
    if (settings.temperature) config.temperature = settings.temperature;

    if (regenerateFeedback) {
        basePrompt += `SYSTEM FEEDBACK: "${regenerateFeedback}" - Re-evaluating...\n\n`;
    }

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `Identify the anomaly in this signal: ${userInput}. Return JSON with research_question, uniqueness_score, justification, and field.`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            basePrompt += `Cross-reference archives for the question: "${context.question}". Use search tools to find leaked data or classified journals.`;
            config.tools = [{ googleSearch: {} }];
            break;
        case 3:
            basePrompt += `Assess preliminary threat/opportunity levels. Formulate hypotheses for: "${context.question}" using archival insights: "${context.literature_review_summary}"`;
            break;
        case 4:
            basePrompt += `Establish simulation protocol for: "${context.hypothesis}"`;
            break;
        case 5:
            basePrompt += `Draft surveillance log parameters for protocol: "${context.methodology_summary}"`;
            break;
        case 6:
            basePrompt += `PROVENANCE: INCIDENT RECONSTRUCTION. Synthesize physics data in CSV format for: "${context.methodology_summary}". **NOTICE**: Must include: "Reconstruction generated via Archival Synthesis." Output CSV and summary separated by '---'.`;
            break;
        case 7:
            basePrompt += `Decrypt data patterns from incident log: ${userInput}`;
            break;
        case 8:
            basePrompt += `Synthesize final determination based on decryption: "${context.analysis_summary}" addressing hypothesis: "${context.hypothesis}"`;
            break;
        case 9:
             basePrompt += `Execute internal security audit on this entry: \n\n${context.full_project_summary_log}`;
             break;
        case 10:
             basePrompt += `Compile the final classified dossier. USE THE ARCHIVE LOG: \n\n${context.full_project_summary_log}`;
             break;
        case 13: 
             basePrompt += `Declassify and explain this dossier for civilian level non-specialists: \n\n${context.full_project_summary_log}`;
             break;
        default:
            basePrompt += `Process archive data for Node ${stepId}.`;
    }

    return { basePrompt, expectJson, config };
};

export const runLiteratureReviewAgent = async ({ experiment, gemini, updateLog }) => {
    updateLog('Archiver', 'Pinging external classified databases...');
    const context = await getStepContext(experiment, 2, gemini);
    const { basePrompt, config } = getPromptForStep(2, '', context, experiment.fineTuneSettings[2] || {});

    const response = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
        contents: basePrompt, 
        config: {
            ...config,
            responseMimeType: "application/json",
            responseSchema: LITERATURE_REVIEW_SCHEMA
        }
    });
    return response.text;
};

export const runDataAnalysisAgent = async ({ experiment, csvData, gemini, updateLog }) => {
    const context = await getStepContext(experiment, 7, gemini);
    updateLog('Cryptographer', 'Deciphering signal harmonics...');
    const csvLines = csvData.trim().split('\n');
    const plannerPrompt = `Analyze this reconstructed data. Header: ${csvLines[0]}. Plan 2-3 visual decrypts (JSON) for hypothesis: "${context.hypothesis}"`;

    const plannerResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', {
        contents: plannerPrompt,
        config: { responseMimeType: "application/json", responseSchema: VISUALIZATION_PLAN_SCHEMA }
    });
    const plan = JSON.parse(plannerResponse.text).charts;
    const generatedCharts = [];

    for (const chartPlan of plan) {
        updateLog('Pattern-Matcher', `Isolating frequency "${chartPlan.title}"...`);
        const dataSnippet = csvData.slice(0, 50000);
        const builderPrompt = `Prepare Chart.js JSON for "${chartPlan.title}" (${chartPlan.chartType}). Header: ${csvLines[0]}. Data context: ${dataSnippet}`;
        const builderResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', {
            contents: builderPrompt,
            config: { responseMimeType: "application/json", responseSchema: CHART_JS_SCHEMA }
        });
        const chartJsConfig = builderResponse.text;

        updateLog('Visualizer', `Rendering decrypted plot "${chartPlan.title}"...`);
        const plotterPrompt = `Plot this classified data into a high-contrast clinical chart image: ${chartJsConfig}`;
        try {
            const plotterResponse = await callGeminiWithRetry(gemini, 'gemini-2.5-flash-image', {
                contents: plotterPrompt
            });
            const imagePart = plotterResponse.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (imagePart) {
                generatedCharts.push({ title: chartPlan.title, imageData: imagePart.inlineData.data });
            }
        } catch (e) { updateLog('Visualizer', `Plot rendering failed.`); }
    }

    updateLog('Dossier-Lead', 'Finalizing interpretation...');
    const summaryPrompt = `Write a classified analysis of results. Context: ${context.analysis_summary}`;
    const summaryResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { contents: summaryPrompt });

    return { 
        finalOutput: JSON.stringify({ summary: summaryResponse.text, charts: generatedCharts }), 
        logSummary: `Decrypted incident data: ${generatedCharts.length} patterns isolated.` 
    };
};

export const runPeerReviewAgent = async ({ experiment, gemini, updateLog }) => {
    const researchQuestion = experiment.stepData[1]?.output || "N/A";
    let finalCritique = `## INTERNAL SECURITY AUDIT\n\n`;
    const stepsToReview = [2, 3, 4, 5, 6, 7, 8];

    for (const stepId of stepsToReview) {
        const stepInfo = WORKFLOW_STEPS.find(s => s.id === stepId);
        updateLog('Auditor', `Auditing Node ${stepId}: ${stepInfo.title}...`);
        const doc = experiment.stepData[stepId]?.summary || experiment.stepData[stepId]?.output || "N/A";
        const prompt = `Audit the "${stepInfo.title}" section for entry: "${researchQuestion}". SECTION TEXT: ${doc}`;
        const res = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { contents: prompt });
        finalCritique += `### Security Feedback: ${stepInfo.title}\n\n${res.text}\n\n---\n\n`;
        await new Promise(r => setTimeout(r, 1000));
    }
    return finalCritique;
};

export const runPublicationAgent = async ({ experiment, gemini, updateLog }) => {
    const sectionConfig = [
        { name: "Abstract & Incident Overview", steps: [1, 2, 8] },
        { name: "Surveillance Context", steps: [1, 2, 3] },
        { name: "Reconstruction Methodology", steps: [4, 5, 6] },
        { name: "Decrypted Results", steps: [6, 7] },
        { name: "Security Implications", steps: [3, 8, 9] },
        { name: "Final Determination", steps: [8] },
        { name: "Archival Sources", steps: [2] }
    ];

    updateLog('Dossier-Compiler', 'Architecting classified dossier...');
    const sections = {};

    for (const config of sectionConfig) {
        updateLog('Writer', `Transcribing ${config.name}...`);
        let sectionContext = `TARGET SECTION: ${config.name}\n\n`;
        config.steps.forEach(sId => {
            const stepTitle = WORKFLOW_STEPS.find(s => s.id === sId)?.title;
            const stepContent = experiment.stepData[sId]?.summary || experiment.stepData[sId]?.output || "N/A";
            sectionContext += `### [LOG ${sId}] ${stepTitle}:\n${stepContent}\n\n`;
        });

        const writerPrompt = `You are a classified dossiers writer. Draft "${config.name}". Use [CHART_1], [CHART_2] for visuals. CONTEXT:\n${sectionContext}`;
        const secRes = await callGeminiWithRetry(gemini, 'gemini-3-pro-preview', { 
            contents: writerPrompt,
            config: { thinkingConfig: { thinkingBudget: 4000 } }
        }, (l) => updateLog('System', l), 5, 300000);

        sections[config.name] = secRes.text;
        await new Promise(r => setTimeout(r, 2000));
    }

    updateLog('Editor', 'Performing final redactions and polish...');
    const combinedText = sectionConfig.map(c => `## ${c.name}\n\n${sections[c.name]}`).join('\n\n');
    const editorPrompt = `Review and polish this full classified dossier for consistency. Ensure signal provenance is clear. MANUSCRIPT:\n${combinedText}`;
    const finalRes = await callGeminiWithRetry(gemini, 'gemini-3-pro-preview', { 
        contents: editorPrompt,
        config: { thinkingConfig: { thinkingBudget: 8000 } }
    }, (l) => updateLog('System', l), 5, 300000);

    return finalRes.text;
};

