import React, { useState, useEffect } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';

export const LabNotebook = ({ isOpen, onClose }) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const [content, setContent] = useState(activeExperiment?.labNotebook || '');
    const { addToast } = useToast();

    const incidentTemplate = `\n\n### FIELD INCIDENT OBSERVATION\n\n*   **Timestamp:** \n*   **Location:** \n*   **Anomalous Readings:** \n*   **Subject Behavior:** \n\n---\n\n`;

    useEffect(() => {
        setContent(activeExperiment?.labNotebook || '');
    }, [activeExperiment?.labNotebook, isOpen]);

    const handleInsertTemplate = () => {
        setContent(prev => prev + incidentTemplate);
        addToast("Incident template inserted.", "info");
    };

    const handleSave = () => {
        if (activeExperiment) {
            updateExperiment({ ...activeExperiment, labNotebook: content });
            addToast("Field log updated.", "success");
            onClose();
        }
    };

    return (
         <div className={`lab-notebook-drawer ${isOpen ? 'open' : ''}`}>
            <div className="lab-notebook-header d-flex justify-content-between align-items-center">
                <h5 className="mb-0"><i className="bi bi-card-checklist me-2"></i>Field Log</h5>
                <div>
                    <button className="btn btn-outline-info btn-sm me-2" onClick={handleInsertTemplate} title="Insert Incident Template">
                        <i className="bi bi-plus-square me-1"></i> Incident Template
                    </button>
                    <button className="btn btn-primary btn-sm me-2" onClick={handleSave}>UPDATE LOG</button>
                    <button className="btn btn-secondary btn-sm" onClick={onClose}><i className="bi bi-x-lg"></i></button>
                </div>
            </div>
            <div className="lab-notebook-body">
                <textarea 
                    className="form-control lab-notebook-textarea font-monospace" 
                    value={content}
                    onChange={(e) => setContent(e.target.value)}
                    placeholder="Record un-redacted observations here..."
                />
            </div>
        </div>
    );
};

