import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Experiment } from './config';
import { db } from './be_db';
import { testApiKey, parseGeminiError } from './services';
import { useToast } from './toast';
import { ExperimentContext } from './services';

import { Header } from './components/common/Header';
import { Footer } from './components/common/Footer';
import { LandingPage } from './components/landing/LandingPage';
import { Dashboard } from './components/dashboard/Dashboard';
import { ExperimentWorkspace } from './components/workspace/ExperimentWorkspace';
import { TestRunner } from './components/testing/TestRunner';
import { LabNotebook } from './components/workspace/LabNotebook';

/**
 * @component App
 * The root component that manages the overall application state and routing.
 */
export const App = () => {
    const [view, setView] = useState('landing'); // 'landing', 'dashboard', 'experiment'
    const [experiments, setExperiments] = useState<Experiment[]>([]);
    const [activeExperiment, setActiveExperiment] = useState<Experiment | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [gemini, setGemini] = useState<GoogleGenAI | null>(null);
    const [isLabNotebookOpen, setLabNotebookOpen] = useState(false);

    const { addToast } = useToast();

    // Load experiments from Dexie on initial mount.
    useEffect(() => {
        const loadData = async () => {
            try {
                const storedExperiments = await db.experiments.orderBy('createdAt').reverse().toArray();
                setExperiments(storedExperiments);
                if (storedExperiments.length > 0) {
                    setActiveExperiment(storedExperiments[0]);
                }
            } catch (error) {
                console.error("Failed to load data:", error);
                addToast("Could not load saved experiments.", 'danger');
            } finally {
                setIsLoading(false);
            }
        };
        loadData();
    }, [addToast]);

    // Scroll to top after successful authentication
    useEffect(() => {
        if (gemini && view === 'landing') {
             setTimeout(() => window.scrollTo({ top: 0, behavior: 'smooth' }), 100);
        }
    }, [gemini, view]);

    const handleAuthentication = async (type: 'promo' | 'key', value: string) => {
        const aistudio = (window as any).aistudio;

        if (type === 'promo' && value.toUpperCase() === 'MTI') {
            // Special handling for the MTI bypass/promo code
            if (aistudio) {
                try {
                    const hasKey = await aistudio.hasSelectedApiKey();
                    if (!hasKey) {
                        await aistudio.openSelectKey();
                        // Assume success per guidelines (mitigate race condition)
                    }
                    const geminiInstance = new GoogleGenAI({ apiKey: process.env.API_KEY });
                    setGemini(geminiInstance);
                    addToast("System unlocked. Welcome, Researcher.", 'success');
                    return;
                } catch (e) {
                    console.error("AI Studio key selection failed", e);
                }
            }

            // Fallback for promo code if aistudio isn't present
            if (process.env.API_KEY) {
                const geminiInstance = new GoogleGenAI({ apiKey: process.env.API_KEY });
                setGemini(geminiInstance);
                addToast("Authentication successful! Welcome back.", 'success');
                return;
            } else {
                addToast("Access credentials missing in environment.", 'danger');
                return;
            }
        }

        if (type === 'key' && value) {
            try {
                // For manual keys, we perform a quick verification
                const isValid = await testApiKey(value);
                if (isValid) {
                    const geminiInstance = new GoogleGenAI({ apiKey: value });
                    setGemini(geminiInstance);
                    addToast("Authentication successful! Welcome back.", 'success');
                } else {
                    addToast("The provided API key is not valid or has expired.", 'danger');
                }
            } catch (error) {
                addToast(parseGeminiError(error, "Authentication failed. The key is not valid."), 'danger');
            }
            return;
        }

        addToast("Please provide valid credentials.", 'warning');
    };


    // Handlers for experiment management
    const createNewExperiment = async (title: string, description: string, field: string) => {
        const newId = `exp_${Date.now()}`;
        const newExperiment: Experiment = {
            id: newId,
            title,
            description,
            field,
            currentStep: 1,
            stepData: {
                1: {
                    input: `Title: ${title}\n\nDescription: ${description}`,
                    history: [],
                    provenance: [],
                }
            },
            fineTuneSettings: {},
            createdAt: new Date().toISOString(),
            labNotebook: '',
            automationMode: null,
            status: 'active',
        };
        try {
            await db.experiments.add(newExperiment);
            setExperiments(prev => [newExperiment, ...prev]);
            setActiveExperiment(newExperiment);
            setView('experiment');
            addToast("New research project created successfully!", 'success');
        } catch (error) {
            console.error("Failed to save new experiment:", error);
            addToast("Failed to create project.", 'danger');
        }
    };

    const importExperiment = async (experimentData: Experiment) => {
        try {
            if (!experimentData.id || !experimentData.title || !experimentData.createdAt) {
                throw new Error("Invalid experiment file format.");
            }
            const existing = await db.experiments.get(experimentData.id);
            if(existing) {
                if(!window.confirm("An experiment with this ID already exists. Overwrite it?")) {
                    return;
                }
                await db.experiments.put(experimentData);
            } else {
                await db.experiments.add(experimentData);
            }
            const storedExperiments = await db.experiments.orderBy('createdAt').reverse().toArray();
            setExperiments(storedExperiments);
            addToast(`Project "${experimentData.title}" imported successfully!`, 'success');

        } catch(error) {
             addToast(`Failed to import project: ${error.message}`, 'danger');
        }
    }


    const updateExperiment = async (updatedExperiment: Experiment): Promise<Experiment> => {
        try {
            const experimentWithTimestamp = { ...updatedExperiment, updatedAt: new Date().toISOString() };
            await db.experiments.put(experimentWithTimestamp);
            setExperiments(prev => prev.map(e => e.id === experimentWithTimestamp.id ? experimentWithTimestamp : e));
            if (activeExperiment?.id === experimentWithTimestamp.id) {
                setActiveExperiment(experimentWithTimestamp);
            }
            return experimentWithTimestamp;
        } catch (error) {
            console.error("Failed to update experiment:", error);
            addToast("Failed to save progress.", 'danger');
            throw error;
        }
    };

    const deleteExperiment = async (id: string) => {
        if (window.confirm("Are you sure you want to delete this project? This action cannot be undone.")) {
            try {
                await db.experiments.delete(id);
                const updatedExperiments = experiments.filter(e => e.id !== id);
                setExperiments(updatedExperiments);
                if (activeExperiment?.id === id) {
                    setActiveExperiment(updatedExperiments.length > 0 ? updatedExperiments[0] : null);
                    if(updatedExperiments.length > 0) {
                        setView('dashboard');
                    } else {
                        setView('landing');
                    }
                }
                addToast("Project deleted.", 'success');
            } catch (error) {
                console.error("Failed to delete experiment:", error);
                addToast("Failed to delete project.", 'danger');
            }
        }
    };

    const selectExperiment = (id: string) => {
        const experiment = experiments.find(e => e.id === id);
        if (experiment) {
            setActiveExperiment(experiment);
            setView('experiment');
        }
    };

    const contextValue = {
        experiments,
        activeExperiment,
        gemini,
        createNewExperiment,
        updateExperiment,
        deleteExperiment,
        selectExperiment,
        setActiveExperiment,
        importExperiment,
        handleAuthentication,
    };

    // Render logic
    if (isLoading) {
        return <div className="d-flex justify-content-center align-items-center vh-100"><div className="spinner-border text-primary" role="status"><span className="visually-hidden">Loading...</span></div></div>;
    }

    return (
        <ExperimentContext.Provider value={contextValue}>
            <Header setView={setView} activeView={view} onToggleNotebook={() => setLabNotebookOpen(p => !p)} />
            <main className="container-fluid mt-4">
                {view === 'landing' && <LandingPage setView={setView} />}
                {view === 'dashboard' && <Dashboard setView={setView} />}
                {view === 'experiment' && activeExperiment && <ExperimentWorkspace key={activeExperiment.id} />}
                {view === 'testing' && <TestRunner />}
            </main>
            {activeExperiment && gemini && (
                <LabNotebook 
                    isOpen={isLabNotebookOpen} 
                    onClose={() => setLabNotebookOpen(false)}
                />
            )}
            <Footer />
        </ExperimentContext.Provider>
    );
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
    CHART_JS_SCHEMA,
    VISUALIZATION_PLAN_SCHEMA,
} from './config';

// --- GEMINI API SERVICE ---

/**
 * Validates if an API key is structurally sound. 
 * Note: A real API call is omitted here to prevent "Validating..." hangs 
 * and issues with safety filters on simple 'ping' prompts.
 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    // Structural check: Gemini keys are typically 39 chars long
    return apiKey.length >= 20; 
};

const getRetryDelay = (error: any): number | null => {
    let details;
    if (error?.error?.details) {
        details = error.error.details;
    } 
    else if (error?.error?.message && typeof error.error.message === 'string') {
        try {
            const nestedError = JSON.parse(error.error.message);
            if (nestedError?.error?.details) {
                details = nestedError.error.details;
            }
        } catch (e) {}
    }

    if (details) {
        const retryInfo = details.find(
            (detail: any) => detail['@type'] === 'type.googleapis.com/google.rpc.RetryInfo'
        );
        if (retryInfo?.retryDelay) {
            const delayString = retryInfo.retryDelay;
            const seconds = parseFloat(delayString);
            if (!isNaN(seconds)) {
                return (seconds * 1000) + 500;
            }
        }
    }
    return null;
};

const callGeminiWithTimeout = async (geminiCall: Promise<any>, timeout: number = 240000) => {
    return Promise.race([
        geminiCall,
        new Promise((_, reject) => 
            setTimeout(() => reject(new Error(`API call timed out after ${timeout / 1000} seconds.`)), timeout)
        ),
    ]);
};

export const callGeminiWithRetry = async (
    gemini: GoogleGenAI,
    model: string,
    params: any,
    onLog?: (message: string) => void,
    maxRetries = 5,
    timeout: number = 240000
) => {
    let attempt = 0;
    let delay = 2000;
    while (attempt < maxRetries) {
        try {
            const response = await callGeminiWithTimeout(gemini.models.generateContent({ model, ...params }), timeout);
            return response;
        } catch (error: any) {
            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429') || errorMessage.toLowerCase().includes('too many requests');
            const isTimeoutError = errorMessage.includes('timed out');
            const isServerError = error.status === 500 || errorMessage.includes('500') || errorMessage.toLowerCase().includes('internal server error');

            if ((isRateLimitError || isTimeoutError || isServerError) && attempt < maxRetries - 1) {
                attempt++;
                const reason = isTimeoutError ? 'timed out' : (isServerError ? 'server error (500)' : 'rate limit hit');
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;

                const logMessage = `Gemini call ${reason}. Retrying in ${retryAfterMs / 1000}s... (Attempt ${attempt}/${maxRetries-1})`;
                if (onLog) onLog(logMessage); else console.warn(logMessage);

                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2; 
            } else {
                throw error;
            }
        }
    }
    throw new Error("Terminal failure: Max retries reached.");
};

export const callGeminiStreamWithRetry = async (
    gemini: GoogleGenAI,
    model: string,
    params: any,
    onLog?: (message: string) => void,
    maxRetries = 5
) => {
    let attempt = 0;
    let delay = 2000;
    while (attempt < maxRetries) {
        try {
            const stream = await callGeminiWithTimeout(gemini.models.generateContentStream({ model, ...params }));
            return stream;
        } catch (error: any) {
            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429') || errorMessage.toLowerCase().includes('too many requests');
            const isTimeoutError = errorMessage.includes('timed out');
            const isServerError = error.status === 500 || errorMessage.includes('500') || errorMessage.toLowerCase().includes('internal server error');

            if ((isRateLimitError || isTimeoutError || isServerError) && attempt < maxRetries - 1) {
                attempt++;
                const reason = isTimeoutError ? 'timed out' : (isServerError ? 'server error (500)' : 'rate limit hit');
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;

                const logMessage = `Stream interrupted: ${reason}. Resuming in ${retryAfterMs / 1000}s...`;
                if (onLog) onLog(logMessage); else console.warn(logMessage);

                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2;
            } else {
                throw error;
            }
        }
    }
    throw new Error("Stream terminated: Max retries reached.");
};

export const parseGeminiError = (error: any, fallbackMessage: string = "API communication error."): string => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes('Max retries reached')) {
        return 'The AI service is currently overloaded. Please wait a few moments and try again.';
    }
    if (error?.error?.message) {
        const errorCode = error.error.code;
        const errorMessage = error.error.message;
        if (errorCode === 500) return `Server Error (500): ${errorMessage}`;
        return `API Error (${errorCode}): ${errorMessage}`;
    }
    return fallbackMessage;
};

const summarizeLargeContent = async (gemini: GoogleGenAI, content: string, targetChars: number = 800000): Promise<string> => {
    if (!content || content.length <= targetChars) return content;

    const prompt = `You are a research assistant. Summarize the following research log and experimental data to roughly ${targetChars} characters. 
    Maintain all key findings, data points, and the logical flow of the research. 
    Style: Professional, concise, scientific.

    CONTENT TO SUMMARIZE:
    ${content.slice(0, 2000000)}`;

    try {
        const response = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
            contents: prompt,
            config: { temperature: 0.1 }
        });
        return response.text || content.slice(0, targetChars);
    } catch (e) {
        return content.slice(0, targetChars);
    }
};

export const getStepContext = async (experiment: Experiment, stepId: number, gemini: GoogleGenAI): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 5000) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);
    if (stepId > 8) context.conclusion_summary = getSummary(8);
    if (stepId > 9) context.peer_review_summary = getSummary(9);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) {
                const output = getSummary(i);
                projectLog += `--- [Step ${i}] ${stepInfo.title} ---\n${output}\n\n`;
            }
        }

        if (projectLog.length > 800000) {
            context.full_project_summary_log = await summarizeLargeContent(gemini, projectLog, 600000);
        } else {
            context.full_project_summary_log = projectLog.trim();
        }
    }

    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    let systemInstruction = `You are Hypatia, an advanced AI scientific research assistant. You provide high-quality, scientifically accurate assistance for a project in the field of ${context.experimentField || 'Science'}. Your tone is professional, clear, and methodical.`;
    const settings = fineTuneSettings || {};
    const params = STEP_SPECIFIC_TUNING_PARAMETERS[stepId] || [];

    params.forEach(param => {
        const value = settings[param.name] ?? param.default;
        if (value && param.name === 'reviewerPersona') systemInstruction += ` Adopt the persona of a ${value} peer reviewer.`;
    });

    let basePrompt = "";
    let expectJson = false;
    const config: any = { systemInstruction };
    if (settings.temperature) config.temperature = settings.temperature;

    if (regenerateFeedback) {
        basePrompt += `USER FEEDBACK FOR REGENERATION: "${regenerateFeedback}"\nPlease incorporate this feedback into your updated response.\n\n`;
    }

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `Based on this initial idea: "${userInput}", refine it into a single, testable research question. Return a JSON object with keys research_question, uniqueness_score (0-1), justification, and field.`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            basePrompt += `Conduct a targeted literature review for: "${context.question}". Identify key theoretical frameworks, recent relevant studies, and potential gaps. You MUST use Google Search to provide up-to-date and cited information.`;
            config.tools = [{ googleSearch: {} }];
            break;
        case 3:
            basePrompt += `Based on the literature review ("${context.literature_review_summary}"), propose 3-4 distinct and testable hypotheses for the research question: "${context.question}".`;
            break;
        case 4:
            basePrompt += `Design a rigorous experimental methodology to test the selected hypothesis: "${context.hypothesis}". Provide step-by-step instructions.`;
            break;
        case 5:
            basePrompt += `Create a detailed data collection plan based on the methodology: "${context.methodology_summary}". Define exactly what will be measured and how.`;
            break;
        case 6:
            basePrompt += `Based on the Methodology: "${context.methodology_summary}" and Data Plan: "${context.data_collection_plan_summary}", generate a plausible estimated dataset in CSV format for testing. **NOTICE**: The summary MUST state: "This experimental data was synthesized by AI Generation for theoretical exploration." Output CSV and a summary separated by '---'.`;
            break;
        case 7:
            basePrompt += `Analyze the following experimental data: ${userInput}. Context: "${context.analysis_summary}" and hypothesis: "${context.hypothesis}". Identify patterns and significance.`;
            break;
        case 8:
            basePrompt += `Synthesize the findings into a formal conclusion based on the analysis: "${context.analysis_summary}". Address whether the hypothesis ("${context.hypothesis}") was supported.`;
            break;
        case 9:
             basePrompt += `Perform a critical peer review simulation of the following project log: \n\n${context.full_project_summary_log}`;
             break;
        case 10:
             basePrompt += `Synthesize the entire research project into a publication-ready manuscript draft. USE THE FULL PROJECT LOG: \n\n${context.full_project_summary_log}`;
             break;
        case 13: 
             basePrompt += `Explain the findings of this research project to a non-specialist audience. Project Log: \n\n${context.full_project_summary_log}`;
             break;
        default:
            basePrompt += `Proceed with Step ${stepId} of the scientific process.`;
    }

    return { basePrompt, expectJson, config };
};

export const runLiteratureReviewAgent = async ({ experiment, gemini, updateLog }) => {
    updateLog('Research Assistant', 'Initializing deep search on relevant scientific databases...');
    const context = await getStepContext(experiment, 2, gemini);
    const { basePrompt, config } = getPromptForStep(2, '', context, experiment.fineTuneSettings[2] || {});

    const response = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
        contents: basePrompt, 
        config: {
            ...config,
            responseMimeType: "application/json",
            responseSchema: LITERATURE_REVIEW_SCHEMA
        }
    });
    return response.text;
};

export const runDataAnalysisAgent = async ({ experiment, csvData, gemini, updateLog }) => {
    const context = await getStepContext(experiment, 7, gemini);
    updateLog('Data Scientist', 'Analyzing data distributions and identifying correlations...');
    const csvLines = csvData.trim().split('\n');
    const plannerPrompt = `Analyze this dataset. Header: ${csvLines[0]}. Plan 2-3 essential visualizations (JSON) to test hypothesis: "${context.hypothesis}"`;

    const plannerResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', {
        contents: plannerPrompt,
        config: { responseMimeType: "application/json", responseSchema: VISUALIZATION_PLAN_SCHEMA }
    });
    const plan = JSON.parse(plannerResponse.text).charts;
    const generatedCharts = [];

    for (const chartPlan of plan) {
        updateLog('Visualizer', `Designing chart: "${chartPlan.title}"...`);
        const dataSnippet = csvData.slice(0, 50000);
        const builderPrompt = `Prepare Chart.js configuration JSON for "${chartPlan.title}" (${chartPlan.chartType}). Header: ${csvLines[0]}. Data context: ${dataSnippet}`;
        const builderResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', {
            contents: builderPrompt,
            config: { responseMimeType: "application/json", responseSchema: CHART_JS_SCHEMA }
        });
        const chartJsConfig = builderResponse.text;

        updateLog('Chart Generator', `Rendering visualization for "${chartPlan.title}"...`);
        const plotterPrompt = `Render this scientific data into a professional high-resolution chart: ${chartJsConfig}`;
        try {
            const plotterResponse = await callGeminiWithRetry(gemini, 'gemini-2.5-flash-image', {
                contents: plotterPrompt
            });
            const imagePart = plotterResponse.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (imagePart) {
                generatedCharts.push({ title: chartPlan.title, imageData: imagePart.inlineData.data });
            }
        } catch (e) { updateLog('Visualizer', `Chart rendering failed.`); }
    }

    updateLog('Editor', 'Finalizing analytical summary...');
    const summaryPrompt = `Provide a comprehensive scientific summary of the data results. Context: ${context.analysis_summary}`;
    const summaryResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { contents: summaryPrompt });

    return { 
        finalOutput: JSON.stringify({ summary: summaryResponse.text, charts: generatedCharts }), 
        logSummary: `Data analysis complete. ${generatedCharts.length} visualizations generated.` 
    };
};

export const runPeerReviewAgent = async ({ experiment, gemini, updateLog }) => {
    const researchQuestion = experiment.stepData[1]?.output || "N/A";
    let finalCritique = `## SIMULATED PEER REVIEW REPORT\n\n`;
    const stepsToReview = [2, 3, 4, 5, 6, 7, 8];

    for (const stepId of stepsToReview) {
        const stepInfo = WORKFLOW_STEPS.find(s => s.id === stepId);
        updateLog('Reviewer', `Evaluating Step ${stepId}: ${stepInfo.title}...`);
        const doc = experiment.stepData[stepId]?.summary || experiment.stepData[stepId]?.output || "N/A";
        const prompt = `Critically evaluate the "${stepInfo.title}" section for the research project: "${researchQuestion}". Focus on scientific rigor and logical consistency. SECTION TEXT: ${doc}`;
        const res = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { contents: prompt });
        finalCritique += `### Reviewer Feedback: ${stepInfo.title}\n\n${res.text}\n\n---\n\n`;
        await new Promise(r => setTimeout(r, 1000));
    }
    return finalCritique;
};

export const runPublicationAgent = async ({ experiment, gemini, updateLog }) => {
    const sectionConfig = [
        { name: "Abstract & Introduction", steps: [1, 2, 8] },
        { name: "Theoretical Framework", steps: [2, 3] },
        { name: "Methodology", steps: [4, 5] },
        { name: "Results", steps: [6, 7] },
        { name: "Discussion", steps: [3, 8, 9] },
        { name: "Conclusion", steps: [8] },
        { name: "References", steps: [2] }
    ];

    updateLog('Writer', 'Drafting manuscript structure...');
    const sections = {};

    for (const config of sectionConfig) {
        updateLog('Section Lead', `Writing ${config.name}...`);
        let sectionContext = `SECTION TO WRITE: ${config.name}\n\n`;
        config.steps.forEach(sId => {
            const stepTitle = WORKFLOW_STEPS.find(s => s.id === sId)?.title;
            const stepContent = experiment.stepData[sId]?.summary || experiment.stepData[sId]?.output || "N/A";
            sectionContext += `### [Step ${sId}] ${stepTitle}:\n${stepContent}\n\n`;
        });

        const writerPrompt = `You are a scientific technical writer. Draft the "${config.name}" section of a formal research paper. Use [CHART_1], [CHART_2] as placeholders for relevant visuals. CONTEXT:\n${sectionContext}`;
        const secRes = await callGeminiWithRetry(gemini, 'gemini-3-pro-preview', { 
            contents: writerPrompt,
            config: { thinkingConfig: { thinkingBudget: 4000 } }
        }, (l) => updateLog('AI Writer', l), 5, 300000);

        sections[config.name] = secRes.text;
        await new Promise(r => setTimeout(r, 2000));
    }

    updateLog('Editor-in-Chief', 'Synthesizing final publication-ready draft...');
    const combinedText = sectionConfig.map(c => `## ${c.name}\n\n${sections[c.name]}`).join('\n\n');
    const editorPrompt = `Review and polish the following full research paper for academic tone, clarity, and consistency. Ensure all sections flow logically. MANUSCRIPT:\n${combinedText}`;
    const finalRes = await callGeminiWithRetry(gemini, 'gemini-3-pro-preview', { 
        contents: editorPrompt,
        config: { thinkingConfig: { thinkingBudget: 8000 } }
    }, (l) => updateLog('AI Editor', l), 5, 300000);

    return finalRes.text;
};

