 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

const getRetryDelay = (error: any): number | null => {
    let details;
    if (error?.error?.details) {
        details = error.error.details;
    } 
    else if (error?.error?.message && typeof error.error.message === 'string') {
        try {
            const nestedError = JSON.parse(error.error.message);
            if (nestedError?.error?.details) {
                details = nestedError.error.details;
            }
        } catch (e) {}
    }

    if (details) {
        const retryInfo = details.find(
            (detail: any) => detail['@type'] === 'type.googleapis.com/google.rpc.RetryInfo'
        );
        if (retryInfo?.retryDelay) {
            const delayString = retryInfo.retryDelay;
            const seconds = parseFloat(delayString);
            if (!isNaN(seconds)) {
                return (seconds * 1000) + 500;
            }
        }
    }
    return null;
};

const callGeminiWithTimeout = async (geminiCall: Promise<any>, timeout: number = 60000) => {
    return Promise.race([
        geminiCall,
        new Promise((_, reject) => 
            setTimeout(() => reject(new Error(`Link timeout after ${timeout / 1000}s.`)), timeout)
        ),
    ]);
};

export const callGeminiWithRetry = async (
    gemini: GoogleGenAI,
    model: string,
    params: { contents: any, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 3,
    timeout: number = 60000
) => {
    let attempt = 0;
    let delay = 1000;
    while (attempt < maxRetries) {
        try {
            const response = await callGeminiWithTimeout(gemini.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }), timeout);
            return response;
        } catch (error: any) {
            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429') || errorMessage.toLowerCase().includes('too many requests');
            const isTimeoutError = errorMessage.includes('timeout') || errorMessage.includes('timed out');
            const isServerError = error.status === 500 || errorMessage.includes('500') || errorMessage.toLowerCase().includes('internal server error');

            if ((isRateLimitError || isTimeoutError || isServerError) && attempt < maxRetries - 1) {
                attempt++;
                const reason = isTimeoutError ? 'timeout' : (isServerError ? 'server error' : 'rate limit');
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;

                const logMessage = `Transmission ${reason}. Re-syncing in ${retryAfterMs / 1000}s... (Attempt ${attempt})`;
                if (onLog) onLog(logMessage);

                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2; 
            } else {
                throw error;
            }
        }
    }
    throw new Error("Terminal connection failure.");
};

export const callGeminiStreamWithRetry = async (
    gemini: GoogleGenAI,
    model: string,
    params: { contents: any, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 3
) => {
    let attempt = 0;
    let delay = 1000;
    while (attempt < maxRetries) {
        try {
            // Initiating a stream is usually fast, so we don't apply timeout here but to the initiation only.
            const stream = await gemini.models.generateContentStream({
                model,
                contents: params.contents,
                config: params.config
            });
            return stream;
        } catch (error: any) {
            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429');

            if (isRateLimitError && attempt < maxRetries - 1) {
                attempt++;
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;
                if (onLog) onLog(`Stream throttled. Resuming in ${retryAfterMs / 1000}s...`);
                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2;
            } else {
                throw error;
            }
        }
    }
    throw new Error("Stream connection failed.");
};

export const parseGeminiError = (error: any, fallbackMessage: string = "Discovery link failed."): string => {
    console.error("Gemini API Error:", error);
    const msg = error?.message || "";
    if (msg.includes('Terminal connection failure')) return 'Link failure: Server is non-responsive.';
    if (msg.includes('safety')) return 'Signal blocked: Subject matter violates safety protocols.';
    return fallbackMessage;
};

