export const runDataAnalysisAgent = async ({ experiment, csvData, gemini, updateLog }) => {
    const context = await getStepContext(experiment, 7, gemini);
    updateLog('Hypatia', 'Processing dataset distributions...');
    const csvLines = csvData.trim().split('\n');
    const plannerPrompt = `Analyze CSV. Header: ${csvLines[0]}. Plan 2 visualizations (JSON) for: "${context.hypothesis}"`;

    const plannerResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', {
        contents: [{ parts: [{ text: plannerPrompt }] }],
        config: { responseMimeType: "application/json", responseSchema: VISUALIZATION_PLAN_SCHEMA }
    });
    const plan = JSON.parse(plannerResponse.text).charts;
    const generatedCharts = [];

    for (const chartPlan of plan) {
        updateLog('Hypatia', `Configuring visualization: "${chartPlan.title}"...`);
        const builderPrompt = `Prepare Chart.js JSON for "${chartPlan.title}" (${chartPlan.chartType}). Header: ${csvLines[0]}.`;
        const builderResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', {
            contents: [{ parts: [{ text: builderPrompt }] }],
            config: { responseMimeType: "application/json", responseSchema: CHART_JS_SCHEMA }
        });

        updateLog('Hypatia', `Rendering chart: "${chartPlan.title}"...`);
        const plotterPrompt = `Render scientific chart image from this config: ${builderResponse.text}`;
        try {
            const plotterResponse = await callGeminiWithRetry(gemini, 'gemini-2.5-flash-image', {
                contents: [{ parts: [{ text: plotterPrompt }] }]
            });
            const imagePart = plotterResponse.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (imagePart) {
                generatedCharts.push({ title: chartPlan.title, imageData: imagePart.inlineData.data });
            }
        } catch (e) { updateLog('Hypatia', `Render failed for "${chartPlan.title}".`); }
    }

    const summaryPrompt = `Summarize analysis results. Context: ${context.analysis_summary}`;
    const summaryResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
        contents: [{ parts: [{ text: summaryPrompt }] }] 
    });

    return { 
        finalOutput: JSON.stringify({ summary: summaryResponse.text, charts: generatedCharts }), 
        logSummary: `Data analysis complete. ${generatedCharts.length} patterns identified.` 
    };
};

export const runPeerReviewAgent = async ({ experiment, gemini, updateLog }) => {
    let finalCritique = `## PEER REVIEW FEEDBACK\n\n`;
    const stepsToReview = [1, 2, 3, 4, 5, 6, 7, 8];

    for (const stepId of stepsToReview) {
        const stepInfo = WORKFLOW_STEPS.find(s => s.id === stepId);
        updateLog('Hypatia', `Reviewing section: ${stepInfo.title}...`);
        const doc = experiment.stepData[stepId]?.summary || experiment.stepData[stepId]?.output || "N/A";
        const prompt = `Critique: "${stepInfo.title}" for: "${experiment.title}". TEXT: ${doc}`;
        const res = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
            contents: [{ parts: [{ text: prompt }] }] 
        });
        finalCritique += `### Feedback: ${stepInfo.title}\n\n${res.text}\n\n---\n\n`;
