/**
 * Validates if an API key is structurally sound. 
 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

const getRetryDelay = (error: any): number | null => {
    let details;
    if (error?.error?.details) {
        details = error.error.details;
    } 
    else if (error?.error?.message && typeof error.error.message === 'string') {
        try {
            const nestedError = JSON.parse(error.error.message);
            if (nestedError?.error?.details) {
                details = nestedError.error.details;
            }
        } catch (e) {}
    }

    if (details) {
        const retryInfo = details.find(
            (detail: any) => detail['@type'] === 'type.googleapis.com/google.rpc.RetryInfo'
        );
        if (retryInfo?.retryDelay) {
            const delayString = retryInfo.retryDelay;
            const seconds = parseFloat(delayString);
            if (!isNaN(seconds)) {
                return (seconds * 1000) + 500;
            }
        }
    }
    return null;
};

const callGeminiWithTimeout = async (geminiCall: Promise<any>, timeout: number = 240000) => {
    return Promise.race([
        geminiCall,
        new Promise((_, reject) => 
            setTimeout(() => reject(new Error(`Link timeout after ${timeout / 1000}s.`)), timeout)
        ),
    ]);
};

export const callGeminiWithRetry = async (
    gemini: GoogleGenAI,
    model: string,
    params: { contents: any, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 3,
    timeout: number = 240000
) => {
    let attempt = 0;
    let delay = 1000;
    while (attempt < maxRetries) {
        try {
            const response = await callGeminiWithTimeout(gemini.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }), timeout);
            return response;
        } catch (error: any) {
            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429') || errorMessage.toLowerCase().includes('too many requests');
            const isTimeoutError = errorMessage.includes('timeout') || errorMessage.includes('timed out');
            const isServerError = error.status === 500 || errorMessage.includes('500') || errorMessage.toLowerCase().includes('internal server error');

            if ((isRateLimitError || isTimeoutError || isServerError) && attempt < maxRetries - 1) {
                attempt++;
                const reason = isTimeoutError ? 'timeout' : (isServerError ? 'server error' : 'rate limit');
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;

                const logMessage = `Transmission ${reason}. Re-syncing in ${retryAfterMs / 1000}s... (Attempt ${attempt})`;
                if (onLog) onLog(logMessage);

                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2; 
            } else {
                throw error;
            }
        }
    }
    throw new Error("Terminal connection failure.");
};

export const callGeminiStreamWithRetry = async (
    gemini: GoogleGenAI,
    model: string,
    params: { contents: any, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 3
) => {
    let attempt = 0;
    let delay = 1000;
    while (attempt < maxRetries) {
        try {
            const stream = await gemini.models.generateContentStream({
                model,
                contents: params.contents,
                config: params.config
            });
            return stream;
        } catch (error: any) {
            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429');

            if (isRateLimitError && attempt < maxRetries - 1) {
                attempt++;
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;
                if (onLog) onLog(`Stream throttled. Resuming in ${retryAfterMs / 1000}s...`);
                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2;
            } else {
                throw error;
            }
        }
    }
    throw new Error("Stream connection failed.");
};

export const parseGeminiError = (error: any, fallbackMessage: string = "Discovery link failed."): string => {
    console.error("Gemini API Error:", error);
    const msg = error?.message || "";
    if (msg.includes('Terminal connection failure') || msg.includes('timeout')) return 'Link failure: Server is non-responsive. Please verify your connection or try again later.';
    if (msg.includes('safety')) return 'Signal blocked: Subject matter violates safety protocols.';
    return fallbackMessage;
};

const summarizeLargeContent = async (gemini: GoogleGenAI, content: string, targetChars: number = 800000): Promise<string> => {
    if (!content || content.length <= targetChars) return content;

    const prompt = `Summarize this research log to ~${targetChars} chars. Retain findings and data points.
    ${content.slice(0, 1000000)}`;

    try {
        const response = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
            contents: prompt,
            config: { temperature: 0.1 }
        });
        return response.text || content.slice(0, targetChars);
    } catch (e) {
        return content.slice(0, targetChars);
    }
};

export const getStepContext = async (experiment: Experiment, stepId: number, gemini: GoogleGenAI): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 500) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);
    if (stepId > 8) context.conclusion_summary = getSummary(8);
    if (stepId > 9) context.peer_review_summary = getSummary(9);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) {
                const output = getSummary(i);
                projectLog += `[Step ${i}] ${stepInfo.title}: ${output}\n\n`;
            }
        }
        context.full_project_summary_log = projectLog.trim();
    }

    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    let systemInstruction = `You are Hypatia, an AI scientific research assistant for a project in ${context.experimentField || 'Science'}. Tone: Professional, clear, methodical.`;
    const settings = fineTuneSettings || {};
    const params = STEP_SPECIFIC_TUNING_PARAMETERS[stepId] || [];

    params.forEach(param => {
        const value = settings[param.name] ?? param.default;
        if (value && param.name === 'reviewerPersona') systemInstruction += ` Act as a ${value} reviewer.`;
    });

    let basePrompt = "";
    let expectJson = false;
    const config: any = { systemInstruction };
    if (settings.temperature) config.temperature = settings.temperature;

    if (regenerateFeedback) {
        basePrompt += `REGENERATE FEEDBACK: "${regenerateFeedback}"\n\n`;
    }

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `Idea: "${userInput}". Refine into one testable question. JSON keys: research_question, uniqueness_score (0-1), justification, field.`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            basePrompt += `Literature review for: "${context.question}". Use Google Search.`;
            config.tools = [{ googleSearch: {} }];
            break;
        case 3:
            basePrompt += `Formulate 3 hypotheses for: "${context.question}" based on: "${context.literature_review_summary}"`;
            break;
        case 4:
            basePrompt += `Design methodology for: "${context.hypothesis}"`;
            break;
        case 5:
            basePrompt += `Create data plan for: "${context.methodology_summary}"`;
            break;
        case 6:
            basePrompt += `Generate plausible CSV data for: "${context.methodology_summary}". Must state: "This data was synthesized by AI Generation." Split summary and CSV with '---'.`;
            break;
        case 7:
            basePrompt += `Analyze data: ${userInput}. Context: "${context.analysis_summary}", Hypothesis: "${context.hypothesis}".`;
            break;
        case 8:
            basePrompt += `Draft conclusion for: "${context.analysis_summary}". State if "${context.hypothesis}" was supported.`;
            break;
        case 9:
             basePrompt += `Peer review this log: \n\n${context.full_project_summary_log}`;
             break;
        case 10:
             basePrompt += `Write publication draft using log: \n\n${context.full_project_summary_log}`;
             break;
        case 13: 
             basePrompt += `Explain research to non-experts: \n\n${context.full_project_summary_log}`;
             break;
        default:
            basePrompt += `Proceed with Step ${stepId}.`;
    }

    return { basePrompt, expectJson, config };
};

export const runLiteratureReviewAgent = async ({ experiment, gemini, updateLog }) => {
    updateLog('Hypatia', 'Syncing with global research databases...');
    const context = await getStepContext(experiment, 2, gemini);
    const { basePrompt, config } = getPromptForStep(2, '', context, experiment.fineTuneSettings[2] || {});

    const response = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
        contents: basePrompt, 
        config: {
            ...config,
            responseMimeType: "application/json",
            responseSchema: LITERATURE_REVIEW_SCHEMA
        }
    });
    return response.text;
};

export const runDataAnalysisAgent = async ({ experiment, csvData, gemini, updateLog }) => {
    const context = await getStepContext(experiment, 7, gemini);
    updateLog('Hypatia', 'Processing dataset distributions...');
    const csvLines = csvData.trim().split('\n');
    const plannerPrompt = `Analyze CSV. Header: ${csvLines[0]}. Plan 2 visualizations (JSON) for: "${context.hypothesis}"`;

    const plannerResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', {
        contents: plannerPrompt,
        config: { responseMimeType: "application/json", responseSchema: VISUALIZATION_PLAN_SCHEMA }
    });
    const plan = JSON.parse(plannerResponse.text).charts;
    const generatedCharts = [];

    for (const chartPlan of plan) {
        updateLog('Hypatia', `Configuring visualization: "${chartPlan.title}"...`);
        const builderPrompt = `Prepare Chart.js JSON for "${chartPlan.title}" (${chartPlan.chartType}). Header: ${csvLines[0]}.`;
        const builderResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', {
            contents: builderPrompt,
            config: { responseMimeType: "application/json", responseSchema: CHART_JS_SCHEMA }
        });

        updateLog('Hypatia', `Rendering chart: "${chartPlan.title}"...`);
        const plotterPrompt = `Render scientific chart image from this config: ${builderResponse.text}`;
        try {
            const plotterResponse = await callGeminiWithRetry(gemini, 'gemini-2.5-flash-image', {
                contents: plotterPrompt
            });
            const imagePart = plotterResponse.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (imagePart) {
                generatedCharts.push({ title: chartPlan.title, imageData: imagePart.inlineData.data });
            }
        } catch (e) { updateLog('Hypatia', `Render failed for "${chartPlan.title}".`); }
    }

    const summaryPrompt = `Summarize analysis results. Context: ${context.analysis_summary}`;
    const summaryResponse = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
        contents: summaryPrompt 
    });

    return { 
        finalOutput: JSON.stringify({ summary: summaryResponse.text, charts: generatedCharts }), 
        logSummary: `Data analysis complete. ${generatedCharts.length} patterns identified.` 
    };
};

export const runPeerReviewAgent = async ({ experiment, gemini, updateLog }) => {
    let finalCritique = `## PEER REVIEW FEEDBACK\n\n`;
    const stepsToReview = [1, 2, 3, 4, 5, 6, 7, 8];

    for (const stepId of stepsToReview) {
        const stepInfo = WORKFLOW_STEPS.find(s => s.id === stepId);
        updateLog('Hypatia', `Reviewing section: ${stepInfo.title}...`);
        const doc = experiment.stepData[stepId]?.summary || experiment.stepData[stepId]?.output || "N/A";
        const prompt = `Critique: "${stepInfo.title}" for: "${experiment.title}". TEXT: ${doc}`;
        const res = await callGeminiWithRetry(gemini, 'gemini-3-flash-preview', { 
            contents: prompt 
        });
        finalCritique += `### Feedback: ${stepInfo.title}\n\n${res.text}\n\n---\n\n`;
    }
    return finalCritique;
};

export const runPublicationAgent = async ({ experiment, gemini, updateLog }) => {
    const sections = ["Intro", "Theory", "Methods", "Results", "Discussion", "Conc"];
    let fullPaper = `# ${experiment.title}\n\n`;

    for (const secName of sections) {
        updateLog('Hypatia', `Drafting ${secName}...`);
        const writerPrompt = `Draft the "${secName}" section for a research paper. Use [CHART_1] for visuals if needed. Context:\n${experiment.stepData[1]?.output}`;
        const secRes = await callGeminiWithRetry(gemini, 'gemini-3-pro-preview', { 
            contents: writerPrompt,
            config: { thinkingConfig: { thinkingBudget: 4000 } }
        });
        fullPaper += `## ${secName}\n\n${secRes.text}\n\n`;
    }

    updateLog('Hypatia', 'Finalizing draft...');
    return fullPaper;
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
