export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, setActiveExperiment, isAuthenticated } = useExperiment();
    const [activeStep, setActiveStep] = useState(activeExperiment.currentStep);
    const [isLoading, setIsLoading] = useState(false);
    const [isAutoGenerating, setIsAutoGenerating] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const { addToast } = useToast();

    const experimentRef = useRef(activeExperiment);
    useEffect(() => {
        experimentRef.current = activeExperiment;
    }, [activeExperiment]);

    const stepData = useMemo(() => activeExperiment.stepData[activeStep] || {}, [activeExperiment.stepData, activeStep]);
    const fineTuneSettings = useMemo(() => activeExperiment.fineTuneSettings[activeStep] || {}, [activeExperiment.fineTuneSettings, activeStep]);

    useEffect(() => {
        setActiveStep(activeExperiment.currentStep);
    }, [activeExperiment.currentStep]);

    const handleStepChange = (stepId: number) => {
        if (stepId <= activeExperiment.currentStep && !isAutoGenerating) {
            setActiveStep(stepId);
        }
    };

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated) {
            addToast("Discovery link inactive. Please verify credentials.", "danger");
            return;
        }

        setIsLoading(true);
        const logToast = (msg: string) => addToast(msg, 'info');

        try {
            const isRerunning = activeStep < activeExperiment.currentStep;
            let experimentToProcess = { ...experimentRef.current };

            if (isRerunning) {
                const newStepData = { ...experimentToProcess.stepData };
                for (let i = activeStep + 1; i <= WORKFLOW_STEPS.length; i++) delete newStepData[i];
                if (newStepData[activeStep]) {
                    delete newStepData[activeStep].output;
                    delete newStepData[activeStep].summary;
                }
                experimentToProcess = { ...experimentToProcess, stepData: newStepData, currentStep: activeStep };
                await updateExperiment(experimentToProcess);
                experimentRef.current = experimentToProcess;
            }

            const currentStepData = experimentToProcess.stepData[activeStep] || {};
            const context = await getStepContext(experimentToProcess, activeStep);
            const { basePrompt, expectJson, config } = getPromptForStep(
                activeStep,
                currentStepData.input || '',
                context,
                fineTuneSettings,
                regenerateFeedback
            );

            if (expectJson) {
                logToast(`Launching archival node ${activeStep} calculation...`);
                const response = await callGeminiWithRetry('gemini-3-flash-preview', { contents: basePrompt, config }, logToast);
                const finalOutput = response.text || '';
                const finalStepData = {
                    ...currentStepData,
                    output: finalOutput,
                    provenance: [...(currentStepData.provenance || []), { timestamp: new Date().toISOString(), prompt: basePrompt, config, output: finalOutput }]
                };

                let experimentToUpdate = { ...experimentRef.current, stepData: { ...experimentRef.current.stepData, [activeStep]: finalStepData } };
                if (activeStep === 1) {
                    try {
                        const sanitizedJson = finalOutput.replace(/```json/g, '').replace(/```/g, '').trim();
                        const parsed = JSON.parse(sanitizedJson);
                        if (parsed.field) experimentToUpdate.field = parsed.field;
                    } catch (e) {}
                }
                await updateExperiment(experimentToUpdate);
            } else {
                let finalOutput = '';
                logToast(`Synchronizing node ${activeStep} stream...`);
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config }, logToast);
                for await (const chunk of stream) {
                    finalOutput += (chunk.text || '');
                    // Update state periodically for smooth UI during streaming
                    setActiveExperiment(exp => ({ ...exp, stepData: { ...exp.stepData, [activeStep]: { ...(exp.stepData[activeStep] || {}), output: finalOutput } } }));
                }
                const latestExp = experimentRef.current;
                const finalStepData = {
                    ...(latestExp.stepData[activeStep] || {}),
                    output: finalOutput, 
                    provenance: [...((latestExp.stepData[activeStep] || {}).provenance || []), { timestamp: new Date().toISOString(), prompt: basePrompt, config, output: finalOutput }]
                };
                await updateExperiment({ ...latestExp, stepData: { ...latestExp.stepData, [activeStep]: finalStepData } });
            }
            addToast("Node successfully integrated into Project Hypatia.", "success");
        } catch (error) {
            addToast(parseGeminiError(error), 'danger');
        } finally {
            setIsLoading(false);
        }
    };

    const handleCompleteStep = async () => {
        if (activeStep === 10 || isLoading || !stepData.output) return;

        setIsLoading(true);
        try {
            const textToSummarize = (activeStep === 7 ? (JSON.parse(stepData.output).summary || stepData.output) : stepData.output).slice(0, 5000);
            const summaryPrompt = `Concisely summarize this archival node for a project dossier in exactly one sentence:\n\n${textToSummarize}`;
            const summaryResponse = await callGeminiWithRetry('gemini-3-flash-preview', { contents: summaryPrompt });

            const nextStep = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : WORKFLOW_STEPS.length + 1;
            const updatedExperiment = { 
                ...activeExperiment, 
                stepData: { ...activeExperiment.stepData, [activeStep]: { ...stepData, summary: summaryResponse.text || "Node integrated." } }, 
                currentStep: nextStep 
            };
            if(activeStep === 6 && stepData.input) updatedExperiment.stepData[7] = {...updatedExperiment.stepData[7], input: stepData.input};

            await updateExperiment(updatedExperiment);
        } catch (error) {
            addToast("Archive node summarization failed.", 'danger');
        } finally {
            setIsLoading(false);
        }
    };

    const renderStepContent = () => {
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        const stepInfo = WORKFLOW_STEPS[activeStep - 1];
        if (!stepInfo) return <div>Error: Forensic node link broken.</div>;

        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null && !isAutoGenerating) {
            return <AutomationModeSelector onSelect={(mode) => {
                updateExperiment({...activeExperiment, automationMode: mode});
                if (mode === 'automated') addToast("Agentic sequence fully active.", "success");
            }} />;
        }

        return (
            <div>
                <h4 className="fw-bold">{stepInfo.id}. {stepInfo.title}</h4>
                <p className="text-white-50">{stepInfo.description}</p>
                <hr />
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                {activeStep === 2 && <LiteratureReviewWorkspace onStepComplete={handleCompleteStep} />}
                {activeStep === 6 && <ExperimentRunner onStepComplete={handleCompleteStep} />}
                {activeStep === 7 && <DataAnalysisWorkspace onStepComplete={handleCompleteStep} />}
                {activeStep === 9 && <PeerReviewWorkspace onStepComplete={handleCompleteStep} />}
                {activeStep === 10 && <PublicationExporter />}

                {activeStep !== 2 && activeStep !== 6 && activeStep !== 7 && activeStep !== 9 && activeStep !== 10 && (
                    <GeneratedOutput
                        key={activeExperiment.id + '-' + activeStep}
                        stepId={activeStep}
                        onGenerate={handleGenerate}
                        isLoading={isLoading}
                    />
                )}
            </div>
        );
    };

    return (
        <div className="row">
            <div className="col-lg-3">
                 <div className="card sticky-top" style={{top: '80px'}}>
                    <div className="card-header fw-bold">{activeExperiment.title}</div>
                     <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                             <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                            >
                                <span>{step.id}. {step.title}</span>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                 </div>
            </div>
            <div className="col-lg-9">
                <div className="card">
                    <div className="card-body" style={{minHeight: '70vh'}}>
                        {renderStepContent()}
                    </div>
                    {activeStep <= WORKFLOW_STEPS.length && activeExperiment.automationMode !== 'automated' && !isAutoGenerating && activeStep !== 2 && activeStep !== 6 && activeStep !== 7 && activeStep !== 9 && activeStep !== 10 && (
                         <div className="card-footer d-flex justify-content-between align-items-center bottom-nav">
                             <button className="btn btn-secondary me-2" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Fine-Tune AI
                             </button>
                             <button 
                                className="btn btn-success" 
                                onClick={handleCompleteStep} 
                                disabled={isLoading || !stepData?.output}>
                                 <i className="bi bi-check-circle-fill me-1"></i> Integrate Node & Continue
                             </button>
                         </div>
                    )}
                </div>
            </div>
             {fineTuneModalOpen && (
                <FineTuneModal
                    stepId={activeStep}
                    onClose={() => setFineTuneModalOpen(false)}
                />
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { UniquenessMeter } from './UniquenessMeter';
import { DataAnalysisView } from './DataAnalysisView';

export const GeneratedOutput: React.FC<{
    stepId: number;
    onGenerate: (regenerateFeedback?: string) => Promise<void>;
    isLoading: boolean;
}> = ({ stepId, onGenerate, isLoading }) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();
    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState('');
    const [showRegenInput, setShowRegenInput] = useState(false);
    const [regenFeedback, setRegenFeedback] = useState('');

    const stepData = activeExperiment.stepData[stepId] || {};
    const output = stepData.output || '';

    useEffect(() => {
        setEditText(output);
    }, [output]);

    const handleSave = () => {
        const updatedStepData = { ...activeExperiment.stepData,
            [stepId]: { ...stepData, output: editText }
        };
        // Use the context update function to ensure data is persisted
        updateExperiment({ ...activeExperiment, stepData: updatedStepData });
        setIsEditing(false);
        addToast("Changes saved.", "success");
    };

    const handleRegenerate = () => {
        onGenerate(regenFeedback);
        setShowRegenInput(false);
        setRegenFeedback('');
    }

    const jsonParser = (text) => {
        let data;
        try {
            const sanitizedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
            if (!sanitizedText) throw new Error("AI response was empty.");

            // Defensively handle cases where grounded results might be mixed with JSON or just text
            if (!sanitizedText.startsWith('{') && !sanitizedText.startsWith('[')) {
                 // Return as markdown if not JSON
                 return <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(text) }} />;
            }

            data = JSON.parse(sanitizedText);

            // Step 1: Research Question
            if (stepId === 1) {
                const question = data.research_question || '';
                const score = data.uniqueness_score;
                const justification = data.justification || '';

                if (!question) {
                    throw new Error("Parsed JSON for Step 1 is missing 'research_question'.");
                }

                return (
                   <div>
                       <div dangerouslySetInnerHTML={{ __html: renderMarkdown(question) }} />
                       {score !== undefined && <UniquenessMeter score={score} justification={justification} />}
                   </div>
               );
           }

            // Step 2: Literature Review (Now handles both JSON and standard grounding text)
            if (stepId === 2) {
                const summary = data.summary || '';
                const references = Array.isArray(data.references) ? data.references : [];

                return (
                    <div>
                        {summary && <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(summary) }} />}
                        {references.length > 0 && (
                            <>
                                <h5 className="mt-4">References</h5>
                                <ul className="reference-list">
                                    {references.map((ref, i) => (
                                        <li key={i} className="reference-item">
                                            <div className="reference-title">{ref.title}</div>
                                            <div className="reference-meta">
                                                <em>{ref.authors?.join(', ') || 'N/A'}</em> ({ref.year || 'N/A'}). {ref.journal || ''}
                                                {ref.url && <a href={ref.url} target="_blank" rel="noopener noreferrer" className="ms-2">[Source]</a>}
                                            </div>
                                        </li>
                                    ))}
                                </ul>
                            </>
                        )}
                        {!summary && <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(text) }} />}
                    </div>
                );
            }

            // Step 7: Data Analyzer (Robust parsing)
            if (stepId === 7) {
                 const summary = data.summary || '';
                 const chartSuggestions = (Array.isArray(data.chartSuggestions) ? data.chartSuggestions : [])
                    .filter(c => c && typeof c === 'object' && c.type && c.data && Array.isArray(c.data.datasets));

                 if (!summary && chartSuggestions.length === 0) {
                    throw new Error("Parsed JSON for Step 7 is missing both 'summary' and 'chartSuggestions'.");
                 }

                 return (
                     <div>
                         <DataAnalysisView analysisData={{ summary, chartSuggestions }} />
                     </div>
                 );
            }
            throw new Error("JSON format is valid, but does not match expected structure for this step.");
        } catch (error) {
            console.warn("JSON Parse Fallback:", error);
            return <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(text) }} />;
        }
    };

    if (isLoading) {
        return (
            <div className="text-center p-5">
                 <div className="spinner-border mb-3" role="status"></div>
                <h5>Hypatia is calculating...</h5>
                <p className="text-white-50">Discovery link active. Synchronizing forensic data.</p>
            </div>
        );
    }

    if (!output) {
        return (
            <div className="text-center p-5">
                <p>FORENSIC NODE IDLE: Ready to synthesize archival content.</p>
                <button className="btn btn-primary" onClick={() => onGenerate()}>
                    <i className="bi bi-stars me-1"></i> Launch AI Synthesis
                </button>
            </div>
        );
    }

    // Check if the output is meant to be JSON
    const expectJson = (stepId === 1 || stepId === 2 || stepId === 7);

    return (
        <div className="generated-text-container">
             <div className="edit-controls">
                {isEditing ? (
                    <>
                        <button className="btn btn-sm btn-success me-1" onClick={handleSave}><i className="bi bi-check-lg"></i></button>
                        <button className="btn btn-sm btn-secondary" onClick={() => setIsEditing(false)}><i className="bi bi-x-lg"></i></button>
                    </>
                ) : (
                    <>
                        <button className="btn btn-sm btn-outline-secondary me-1" onClick={() => setShowRegenInput(p => !p)} title="Regenerate">
                           <i className="bi bi-arrow-clockwise"></i>
                        </button>
                        <button className="btn btn-sm btn-outline-secondary" onClick={() => { setIsEditing(true); setEditText(output); }} title="Edit">
                            <i className="bi bi-pencil-square"></i>
                        </button>
                    </>
                )}
            </div>
             {showRegenInput && (
                <div className="input-group mb-3">
                    <input type="text" className="form-control" placeholder="Optional: ARCHIVAL FEEDBACK OVERRIDE..." value={regenFeedback} onChange={e => setRegenFeedback(e.target.value)} />
                    <button className="btn btn-primary" onClick={handleRegenerate}>REGENERATE</button>
                </div>
            )}
            {isEditing ? (
                 <textarea className="editable-textarea" value={editText} onChange={(e) => setEditText(e.target.value)} />
            ) : (
                expectJson ? jsonParser(output) : <div dangerouslySetInnerHTML={{ __html: renderMarkdown(output) }} />
            )}
        </div>
    );
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
    CHART_JS_SCHEMA,
    VISUALIZATION_PLAN_SCHEMA,
} from './config';

// --- GEMINI API SERVICE ---

/**
 * Validates if an API key is structurally sound. 
 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

/**
 * Internal helper to get a fresh instance of the Gemini AI client.
 * GUIDELINE: Create a new instance right before making an API call.
 */
const getAiClient = () => {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Handles specific AI Studio key selection errors.
 */
const handleKeyError = async (error: any) => {
    const msg = error?.message || "";
    const isAuthError = msg.includes("Requested entity was not found") || 
                        msg.includes("403") || 
                        msg.includes("401") ||
                        msg.includes("API key");

    if (isAuthError) {
        const aistudio = (window as any).aistudio;
        if (aistudio && typeof aistudio.openSelectKey === 'function') {
            console.warn("AI Key invalid or expired. Prompting for re-selection.");
            // We trigger the select key dialog but don't await it to avoid blocking the retry loop 
            // indefinitely if the user ignores it.
            aistudio.openSelectKey();
            return true; 
        }
    }
    return false;
};

const getRetryDelay = (error: any): number | null => {
    let details;
    if (error?.error?.details) {
        details = error.error.details;
    } 
    else if (error?.error?.message && typeof error.error.message === 'string') {
        try {
            const nestedError = JSON.parse(error.error.message);
            if (nestedError?.error?.details) {
                details = nestedError.error.details;
            }
        } catch (e) {}
    }

    if (details) {
        const retryInfo = details.find(
            (detail: any) => detail['@type'] === 'type.googleapis.com/google.rpc.RetryInfo'
        );
        if (retryInfo?.retryDelay) {
            const delayString = retryInfo.retryDelay;
            const seconds = parseFloat(delayString);
            if (!isNaN(seconds)) {
                return (seconds * 1000) + 500;
            }
        }
    }
    return null;
};

const callGeminiWithTimeout = async (geminiCall: Promise<any>, timeout: number = 260000) => {
    let timerId: any;
    const timeoutPromise = new Promise((_, reject) => {
        timerId = setTimeout(() => reject(new Error(`Link timeout after ${timeout / 1000}s.`)), timeout);
    });

    try {
        const result = await Promise.race([geminiCall, timeoutPromise]);
        return result;
    } finally {
        clearTimeout(timerId);
    }
};

export const callGeminiWithRetry = async (
    model: string,
    params: { contents: any, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 3,
    timeout: number = 260000
) => {
    let attempt = 0;
    let delay = 1000;

    while (attempt < maxRetries) {
        try {
            const ai = getAiClient();

            // Passing string directly if possible for maximum reliability with text-only tasks
            const contents = params.contents;

            const response = await callGeminiWithTimeout(ai.models.generateContent({
                model,
                contents,
                config: params.config
            }), timeout);

            return response;
        } catch (error: any) {
            const keyWasReset = await handleKeyError(error);
            if (keyWasReset) {
                 // Return a specialized error that can be handled by the UI
                 throw new Error("API Authentication Error. Please verify your selected project key.");
            }

            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429') || errorMessage.toLowerCase().includes('too many requests');
            const isTimeoutError = errorMessage.includes('timeout') || errorMessage.includes('timed out');
            const isServerError = error.status === 500 || errorMessage.includes('500') || errorMessage.toLowerCase().includes('internal server error');

            if ((isRateLimitError || isTimeoutError || isServerError) && attempt < maxRetries - 1) {
                attempt++;
                const reason = isTimeoutError ? 'timeout' : (isServerError ? 'server error' : 'rate limit');
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;

                if (onLog) onLog(`Transmission ${reason}. Re-syncing in ${retryAfterMs / 1000}s... (Attempt ${attempt})`);

                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2; 
            } else {
                throw error;
            }
        }
    }
    throw new Error("Terminal connection failure.");
};

export const callGeminiStreamWithRetry = async (
    model: string,
    params: { contents: any, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 3
) => {
    let attempt = 0;
    let delay = 1000;

    while (attempt < maxRetries) {
        try {
            const ai = getAiClient();
            const contents = params.contents;

            const stream = await ai.models.generateContentStream({
                model,
                contents,
                config: params.config
            });
            return stream;
        } catch (error: any) {
            const keyWasReset = await handleKeyError(error);
            if (keyWasReset) throw new Error("API Authentication Error. Please verify your project key.");

            const errorMessage = error.toString();
            const isRateLimitError = error.status === 'RESOURCE_EXHAUSTED' || errorMessage.includes('429');

            if (isRateLimitError && attempt < maxRetries - 1) {
                attempt++;
                const serverDelay = getRetryDelay(error);
                const retryAfterMs = serverDelay ?? delay;
                if (onLog) onLog(`Stream throttled. Resuming in ${retryAfterMs / 1000}s...`);
                await new Promise(resolve => setTimeout(resolve, retryAfterMs));
                if (serverDelay === null) delay *= 2;
            } else {
                throw error;
            }
        }
    }
    throw new Error("Stream connection failed.");
};

export const parseGeminiError = (error: any, fallbackMessage: string = "Discovery link failed."): string => {
    console.error("Gemini API Error Details:", error);
    const msg = error?.message || "";
    if (msg.includes('Authentication Error')) return "Authentication required. Please select a valid API key using the dialog.";
    if (msg.includes('Terminal connection failure') || msg.includes('timeout')) return 'Link failure: Server is non-responsive. Please verify your connection or try again later.';
    if (msg.includes('safety')) return 'Signal blocked: Subject matter violates safety protocols.';
    return fallbackMessage;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 500) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);
    if (stepId > 8) context.conclusion_summary = getSummary(8);
    if (stepId > 9) context.peer_review_summary = getSummary(9);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) {
                const output = getSummary(i);
                projectLog += `[Step ${i}] ${stepInfo.title}: ${output}\n\n`;
            }
        }
        context.full_project_summary_log = projectLog.trim();
    }

    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    let systemInstruction = `You are Hypatia, an AI scientific research assistant for a project in ${context.experimentField || 'Science'}. Tone: Professional, clear, methodical.`;
    const settings = fineTuneSettings || {};
    const params = STEP_SPECIFIC_TUNING_PARAMETERS[stepId] || [];

    params.forEach(param => {
        const value = settings[param.name] ?? param.default;
        if (value && param.name === 'reviewerPersona') systemInstruction += ` Act as a ${value} reviewer.`;
    });

    let basePrompt = "";
    let expectJson = false;
    const config: any = { systemInstruction };
    if (settings.temperature) config.temperature = settings.temperature;

    if (regenerateFeedback) {
        basePrompt += `REGENERATE FEEDBACK: "${regenerateFeedback}"\n\n`;
    }

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `Idea: "${userInput}". Refine into one testable question. JSON keys: research_question, uniqueness_score (0-1), justification, field.`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            basePrompt += `Conduct a comprehensive literature review for the following question. Use Google Search to find specific papers, journals, and researchers.
            QUESTION: "${context.question}"
            Provide a summary and a list of key references found.`;
            config.tools = [{ googleSearch: {} }];
            break;
        case 3:
            basePrompt += `Formulate 3 hypotheses for: "${context.question}" based on: "${context.literature_review_summary}"`;
            break;
        case 4:
            basePrompt += `Design methodology for: "${context.hypothesis}"`;
            break;
        case 5:
            basePrompt += `Create data plan for: "${context.methodology_summary}"`;
            break;
        case 6:
            basePrompt += `Generate plausible CSV data for: "${context.methodology_summary}". Must state: "This data was synthesized by AI Generation." Split summary and CSV with '---'.`;
            break;
        case 7:
            basePrompt += `Analyze data: ${userInput}. Context: "${context.analysis_summary}", Hypothesis: "${context.hypothesis}".`;
            break;
        case 8:
            basePrompt += `Draft conclusion for: "${context.analysis_summary}". State if "${context.hypothesis}" was supported.`;
            break;
        case 9:
             basePrompt += `Peer review this log: \n\n${context.full_project_summary_log}`;
             break;
        case 10:
             basePrompt += `Write publication draft using log: \n\n${context.full_project_summary_log}`;
             break;
        case 13: 
             basePrompt += `Explain research to non-experts: \n\n${context.full_project_summary_log}`;
             break;
        default:
            basePrompt += `Proceed with Step ${stepId}.`;
    }

    return { basePrompt, expectJson, config };
};

export const runLiteratureReviewAgent = async ({ experiment, updateLog }) => {
    updateLog('Hypatia', 'Initializing research databases...');
    const context = await getStepContext(experiment, 2);
    const { basePrompt, config } = getPromptForStep(2, '', context, experiment.fineTuneSettings[2] || {});

    updateLog('Hypatia', 'Deploying search agents to global archives...');
    const response = await callGeminiWithRetry('gemini-3-pro-preview', { 
        contents: basePrompt, 
        config: config
    });

    // Extract grounding chunks if available
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sourceLinks = groundingChunks
        .filter(c => c.web?.uri)
        .map(c => `- [${c.web.title || c.web.uri}](${c.web.uri})`)
        .join('\n');

    const finalOutput = sourceLinks 
        ? `${response.text}\n\n### Verified Sources Found:\n${sourceLinks}`
        : response.text;

    return finalOutput;
};

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }) => {
