export const GeneratedOutput: React.FC<{
    stepId: number;
    onGenerate: (regenerateFeedback?: string) => Promise<void>;
    isLoading: boolean;
}> = ({ stepId, onGenerate, isLoading }) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();
    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState('');
    const [showRegenInput, setShowRegenInput] = useState(false);
    const [regenFeedback, setRegenFeedback] = useState('');

    const stepData = activeExperiment.stepData[stepId] || {};
    const output = stepData.output || '';

    useEffect(() => {
        setEditText(output);
    }, [output]);

    const handleSave = () => {
        const updatedStepData = { ...activeExperiment.stepData,
            [stepId]: { ...stepData, output: editText }
        };
        updateExperiment({ ...activeExperiment, stepData: updatedStepData });
        setIsEditing(false);
        addToast("Archival edit saved.", "success");
    };

    const handleRegenerate = () => {
        if (isLoading) return;
        onGenerate(regenFeedback);
        setShowRegenInput(false);
        setRegenFeedback('');
    };

    const handleLaunch = () => {
        if (isLoading) return;
        onGenerate();
    };

    const jsonParser = (text: string) => {
        if (!text) return null;
        try {
            const sanitizedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
            if (!sanitizedText.startsWith('{') && !sanitizedText.startsWith('[')) {
                 return <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(text) }} />;
            }

            const data = JSON.parse(sanitizedText);

            if (stepId === 1) {
                const question = data.research_question || '';
                const score = data.uniqueness_score;
                const justification = data.justification || '';
                return (
                   <div>
                       <div dangerouslySetInnerHTML={{ __html: renderMarkdown(question) }} />
                       {score !== undefined && <UniquenessMeter score={score} justification={justification} />}
                   </div>
               );
           }

            if (stepId === 2) {
                const summary = data.summary || '';
                const references = Array.isArray(data.references) ? data.references : [];
                return (
                    <div>
                        {summary && <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(summary) }} />}
                        {references.length > 0 && (
                            <div className="mt-4 border-top border-secondary pt-3">
                                <h6 className="fw-bold text-primary-glow">Archive Sources Found:</h6>
                                <ul className="reference-list list-unstyled mt-3">
                                    {references.map((ref, i) => (
                                        <li key={i} className="mb-3 p-2 rounded bg-dark border border-secondary border-opacity-25">
                                            <div className="fw-bold">{ref.title}</div>
                                            <div className="small text-white-50">
                                                {ref.authors?.join(', ')} ({ref.year}). {ref.journal}
                                                {ref.url && <a href={ref.url} target="_blank" rel="noopener noreferrer" className="ms-2 text-primary-glow"><i className="bi bi-box-arrow-up-right"></i></a>}
                                            </div>
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        )}
                        {!summary && <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(text) }} />}
                    </div>
                );
            }

            if (stepId === 7) {
                 return <DataAnalysisView analysisData={data} />;
            }

            return <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(text) }} />;
        } catch (error) {
            return <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(text) }} />;
        }
    };

    if (isLoading) {
        return (
            <div className="text-center p-5">
                 <div className="spinner-border mb-3 text-primary-glow" role="status"></div>
                <h5 className="fw-bold">Hypatia is calculating...</h5>
                <p className="text-white-50 small">Archival link active. Reconstructing forensic data streams.</p>
            </div>
        );
    }

    if (!output) {
        return (
            <div className="text-center p-5">
                <p className="text-white-50 mb-4">FORENSIC ARCHIVE IDLE: Ready to synthesize archival content.</p>
                <button 
                    className="btn btn-primary btn-lg px-4" 
                    onClick={handleLaunch}
                    disabled={isLoading}
                >
                    <i className="bi bi-rocket-takeoff-fill me-2"></i> Launch AI Synthesis
                </button>
            </div>
        );
    }

    const expectJson = (stepId === 1 || stepId === 2 || stepId === 7);

    return (
        <div className="generated-text-container position-relative">
             <div className="edit-controls d-flex gap-1" style={{ position: 'absolute', top: '-10px', right: '0', zIndex: 10 }}>
                {isEditing ? (
                    <>
                        <button className="btn btn-sm btn-success" onClick={handleSave}><i className="bi bi-check-lg"></i></button>
                        <button className="btn btn-sm btn-secondary" onClick={() => setIsEditing(false)}><i className="bi bi-x-lg"></i></button>
                    </>
                ) : (
                    <>
                        <button className="btn btn-sm btn-outline-secondary" onClick={() => setShowRegenInput(p => !p)} title="Regenerate">
                           <i className="bi bi-arrow-clockwise"></i>
                        </button>
                        <button className="btn btn-sm btn-outline-secondary" onClick={() => { setIsEditing(true); setEditText(output); }} title="Edit">
                            <i className="bi bi-pencil-square"></i>
                        </button>
                    </>
                )}
            </div>

             {showRegenInput && (
                <div className="input-group mb-3 mt-4">
                    <input type="text" className="form-control" placeholder="Optional: Provide archival feedback override..." value={regenFeedback} onChange={e => setRegenFeedback(e.target.value)} />
                    <button className="btn btn-primary" onClick={handleRegenerate} disabled={isLoading}>REGENERATE</button>
                </div>
            )}

            <div className={showRegenInput ? "mt-2" : "mt-4"}>
                {isEditing ? (
                     <textarea 
                        className="form-control font-monospace bg-dark text-white border-secondary" 
                        style={{ minHeight: '300px' }} 
                        value={editText} 
                        onChange={(e) => setEditText(e.target.value)} 
                    />
                ) : (
                    expectJson ? jsonParser(output) : <div dangerouslySetInnerHTML={{ __html: renderMarkdown(output) }} />
                )}
            </div>
        </div>
    );
};

import { marked } from 'marked';

/**
 * A centralized function to render Markdown text into HTML.
 * Includes support for KaTeX math formulas with optimized DOM handling.
 */
export const renderMarkdown = (markdownText: string): string => {
    if (!markdownText) return '';
    try {
        // Basic marked options for performance
        const html = marked.parse(markdownText, { gfm: true, breaks: true }) as string;

        // During streaming, we don't want to run KaTeX on every single partial chunk
        // because it causes massive UI lag. We only run it if the text seems "stable"
        // or contains specific math delimiters.
        const hasMath = markdownText.includes('$') || markdownText.includes('\\(') || markdownText.includes('\\[');

        if (!hasMath) return html;

        const win = window as any;
        if (win.renderMathInElement) {
            const container = document.createElement('div');
            container.innerHTML = html;
            win.renderMathInElement(container, {
                delimiters: [
                    { left: '$$', right: '$$', display: true },
                    { left: '$', right: '$', display: false },
                    { left: '\\(', right: '\\)', display: false },
                    { left: '\\[', right: '\\]', display: true }
                ],
                throwOnError: false
            });
            return container.innerHTML;
        }

        return html;
    } catch (error) {
        console.error("Markdown rendering failed:", error);
        return `<p class="text-danger">Error rendering content.</p>`;
    }
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
    CHART_JS_SCHEMA,
    VISUALIZATION_PLAN_SCHEMA,
} from './config';

// --- GEMINI API SERVICE ---

/**
 * Validates if an API key is structurally sound. 
 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

/**
 * Handles specific AI Studio key selection errors.
 */
const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    const isAuthError = msg.includes("Requested entity was not found") || 
                        msg.includes("403") || 
                        msg.includes("401") ||
                        status === 403 ||
                        status === 404;

    if (isAuthError) {
        const aistudio = (window as any).aistudio;
        if (aistudio && typeof aistudio.openSelectKey === 'function') {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

/**
 * Executes a non-streaming Gemini call.
 */
export const callGeminiWithRetry = async (
    model: string,
    params: { contents: string, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 2
) => {
    let attempt = 0;
    while (attempt <= maxRetries) {
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model: model,
                contents: params.contents,
                config: params.config
            });

            if (!response || !response.text) {
                throw new Error("Empty response from AI.");
            }
            return response;
        } catch (error: any) {
            const errorResult = await handleApiError(error);
            if (errorResult === "AUTH_RETRY_REQUIRED") throw new Error("Re-authentication required.");
            if (attempt < maxRetries) {
                attempt++;
                await new Promise(r => setTimeout(r, 1000 * attempt));
            } else throw error;
        }
    }
    throw new Error("Connection failed.");
};

/**
 * Executes a streaming Gemini call.
 */
export const callGeminiStreamWithRetry = async (
    model: string,
    params: { contents: string, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 1
) => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        return await ai.models.generateContentStream({
            model: model,
            contents: params.contents,
            config: params.config
        });
    } catch (error: any) {
        const errorResult = await handleApiError(error);
        if (errorResult === "AUTH_RETRY_REQUIRED") throw new Error("Re-authentication required.");
        throw error;
    }
};

export const parseGeminiError = (error: any, fallbackMessage: string = "Discovery link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-authentication')) return "Authentication error. Please re-select your AI Project Key.";
    if (msg.includes('safety')) return "Content blocked by safety filters.";
    return fallbackMessage;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 500) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);
    if (stepId > 8) context.conclusion_summary = getSummary(8);
    if (stepId > 9) context.peer_review_summary = getSummary(9);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) {
                projectLog += `[Step ${i}] ${stepInfo.title}: ${getSummary(i)}\n\n`;
            }
        }
        context.full_project_summary_log = projectLog.trim();
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    let systemInstruction = `You are Hypatia, a professional AI scientific research assistant. Field: ${context.experimentField}. Style: Academic, clear, rigorous.`;
    const settings = fineTuneSettings || {};

    let basePrompt = "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.7 };

    if (regenerateFeedback) {
        basePrompt += `USER FEEDBACK FOR REVISION: "${regenerateFeedback}"\n\n`;
    }

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `Idea: "${userInput}". Generate a specific research question. JSON keys: research_question, uniqueness_score (0-1), justification, field.`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            basePrompt += `Literature review for: "${context.question}". Use Google Search.`;
            config.tools = [{ googleSearch: {} }];
            break;
        case 3:
            basePrompt += `Formulate 3 hypotheses for: "${context.question}" based on: "${context.literature_review_summary}"`;
            break;
        case 4:
            basePrompt += `Design methodology for: "${context.hypothesis}"`;
            break;
        case 5:
            basePrompt += `Create data plan for: "${context.methodology_summary}"`;
            break;
        case 6:
            basePrompt += `Generate synthetic CSV data for methodology: "${context.methodology_summary}". Header line, then data. Mention synthesis.`;
            break;
        case 7:
            basePrompt += `Analyze experimental data: ${userInput}. Match against hypothesis: "${context.hypothesis}".`;
            break;
        case 8:
            basePrompt += `Draft conclusion for: "${context.analysis_summary}"`;
            break;
        case 9:
             basePrompt += `Review this research log: \n\n${context.full_project_summary_log}`;
             break;
        case 10:
             basePrompt += `Write a publication manuscript using the project log: \n\n${context.full_project_summary_log}`;
             break;
        default:
            basePrompt += `Proceed with step ${stepId}`;
    }

    return { basePrompt, expectJson, config };
};

