import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { parseGeminiError, getStepContext, getPromptForStep, callGeminiWithRetry, callGeminiStreamWithRetry } from '../../services';
import { WORKFLOW_STEPS } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, setActiveExperiment, isAuthenticated } = useExperiment();
    const [activeStep, setActiveStep] = useState(activeExperiment.currentStep);
    const [isLoading, setIsLoading] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const { addToast } = useToast();

    // Ref to track the current experiment to avoid stale closures in streaming
    const experimentRef = useRef(activeExperiment);
    useEffect(() => {
        experimentRef.current = activeExperiment;
    }, [activeExperiment]);

    const stepData = useMemo(() => activeExperiment.stepData[activeStep] || {}, [activeExperiment.stepData, activeStep]);
    const fineTuneSettings = useMemo(() => activeExperiment.fineTuneSettings[activeStep] || {}, [activeExperiment.fineTuneSettings, activeStep]);

    useEffect(() => {
        setActiveStep(activeExperiment.currentStep);
    }, [activeExperiment.currentStep]);

    const handleStepChange = (stepId: number) => {
        if (stepId <= activeExperiment.currentStep && !isLoading) {
            setActiveStep(stepId);
        }
    };

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated) {
            addToast("Authentication link inactive.", "danger");
            return;
        }

        setIsLoading(true);
        try {
            const context = await getStepContext(experimentRef.current, activeStep);
            const { basePrompt, expectJson, config } = getPromptForStep(
                activeStep,
                experimentRef.current.stepData[activeStep]?.input || '',
                context,
                fineTuneSettings,
                regenerateFeedback
            );

            if (expectJson) {
                const response = await callGeminiWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });
                const finalOutput = response.text || '';

                const updatedStepData = {
                    ...(experimentRef.current.stepData[activeStep] || {}),
                    output: finalOutput
                };

                await updateExperiment({ 
                    ...experimentRef.current, 
                    stepData: { ...experimentRef.current.stepData, [activeStep]: updatedStepData } 
                });
            } else {
                let accumulatedText = '';
                let lastUpdateTime = Date.now();
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });

                for await (const chunk of stream) {
                    accumulatedText += (chunk.text || '');
                    const now = Date.now();

                    // Throttle state updates to at most once every 200ms
                    // This prevents the browser from freezing due to re-render storms
                    if (now - lastUpdateTime > 200) {
                        const currentText = accumulatedText;
                        setActiveExperiment(exp => ({
                            ...exp,
                            stepData: {
                                ...exp.stepData,
                                [activeStep]: { ...(exp.stepData[activeStep] || {}), output: currentText }
                            }
                        }));
                        lastUpdateTime = now;
                    }
                }

                // Final update to ensure everything is captured
                await updateExperiment({
                    ...experimentRef.current,
                    stepData: {
                        ...experimentRef.current.stepData,
                        [activeStep]: { ...(experimentRef.current.stepData[activeStep] || {}), output: accumulatedText }
                    }
                });
            }
            addToast("Archive synthesis complete.", "success");
        } catch (error) {
            addToast(parseGeminiError(error), 'danger');
        } finally {
            setIsLoading(false);
        }
    };

    const handleCompleteStep = async () => {
        if (activeStep === 10 || isLoading || !stepData.output) return;

        setIsLoading(true);
        try {
            const nextStep = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : WORKFLOW_STEPS.length + 1;
            const updatedExperiment = { 
                ...activeExperiment, 
                stepData: { ...activeExperiment.stepData, [activeStep]: { ...stepData, summary: "Completed." } }, 
                currentStep: nextStep 
            };
            await updateExperiment(updatedExperiment);
        } catch (error) {
            addToast("Step finalize failed.", 'danger');
        } finally {
            setIsLoading(false);
        }
    };

    const renderStepContent = () => {
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        const stepInfo = WORKFLOW_STEPS[activeStep - 1];
        if (!stepInfo) return <div>Archive Node Disconnected.</div>;

        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => {
                updateExperiment({...activeExperiment, automationMode: mode});
            }} />;
        }

        return (
            <div>
                <h4 className="fw-bold">{stepInfo.id}. {stepInfo.title}</h4>
                <p className="text-white-50">{stepInfo.description}</p>
                <hr />
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                {activeStep === 2 && <LiteratureReviewWorkspace onStepComplete={handleCompleteStep} />}
                {activeStep === 6 && <ExperimentRunner onStepComplete={handleCompleteStep} />}
                {activeStep === 7 && <DataAnalysisWorkspace onStepComplete={handleCompleteStep} />}
                {activeStep === 9 && <PeerReviewWorkspace onStepComplete={handleCompleteStep} />}
                {activeStep === 10 && <PublicationExporter />}

                {![2, 6, 7, 9, 10].includes(activeStep) && (
                    <GeneratedOutput
                        key={activeExperiment.id + '-' + activeStep}
                        stepId={activeStep}
                        onGenerate={handleGenerate}
                        isLoading={isLoading}
                    />
                )}
            </div>
        );
    };

    return (
        <div className="row">
            <div className="col-lg-3">
                 <div className="card sticky-top" style={{top: '80px'}}>
                    <div className="card-header fw-bold text-truncate">{activeExperiment.title}</div>
                     <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                             <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                            >
                                <span className="small">{step.id}. {step.title}</span>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                 </div>
            </div>
            <div className="col-lg-9">
                <div className="card">
                    <div className="card-body" style={{minHeight: '70vh'}}>
                        {renderStepContent()}
                    </div>
                    {activeStep <= WORKFLOW_STEPS.length && activeExperiment.automationMode !== 'automated' && activeStep !== 2 && activeStep !== 6 && activeStep !== 7 && activeStep !== 9 && activeStep !== 10 && (
                         <div className="card-footer d-flex justify-content-between align-items-center bottom-nav">
                             <button className="btn btn-secondary me-2" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Fine-Tune AI
                             </button>
                             <button 
                                className="btn btn-success" 
                                onClick={handleCompleteStep} 
                                disabled={isLoading || !stepData?.output}>
                                 <i className="bi bi-check-circle-fill me-1"></i> Integrate Node & Continue
                             </button>
                         </div>
                    )}
                </div>
            </div>
             {fineTuneModalOpen && (
                <FineTuneModal
                    stepId={activeStep}
                    onClose={() => setFineTuneModalOpen(false)}
                />
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
