import React, { useState, useEffect, useMemo } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { UniquenessMeter } from './UniquenessMeter';
import { DataAnalysisView } from './DataAnalysisView';

export const GeneratedOutput: React.FC<{
    stepId: number;
    onGenerate: (regenerateFeedback?: string) => Promise<void>;
    isLoading: boolean;
}> = ({ stepId, onGenerate, isLoading }) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();
    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState('');
    const [showRegenInput, setShowRegenInput] = useState(false);
    const [regenFeedback, setRegenFeedback] = useState('');

    const stepData = activeExperiment.stepData[stepId] || {};
    const output = stepData.output || '';

    useEffect(() => {
        setEditText(output);
    }, [output]);

    const handleSave = () => {
        const updatedStepData = { ...activeExperiment.stepData,
            [stepId]: { ...stepData, output: editText }
        };
        updateExperiment({ ...activeExperiment, stepData: updatedStepData });
        setIsEditing(false);
        addToast("Archive node updated.", "success");
    };

    const handleRegenerate = () => {
        if (isLoading) return;
        onGenerate(regenFeedback);
        setShowRegenInput(false);
        setRegenFeedback('');
    };

    const handleLaunch = () => {
        if (isLoading) return;
        onGenerate();
    };

    // Memoize the rendered HTML to prevent expensive re-renders
    const renderedHtml = useMemo(() => {
        if (!output) return '';
        // If loading, render without math for performance
        return renderMarkdown(output, !isLoading);
    }, [output, isLoading]);

    const jsonParser = (text: string) => {
        if (!text) return null;
        if (isLoading) return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;

        try {
            const sanitizedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
            if (!sanitizedText.startsWith('{') && !sanitizedText.startsWith('[')) {
                 return <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
            }

            const data = JSON.parse(sanitizedText);

            if (stepId === 1) {
                const question = data.research_question || '';
                const score = data.uniqueness_score;
                const justification = data.justification || '';
                return (
                   <div>
                       <div dangerouslySetInnerHTML={{ __html: renderMarkdown(question, true) }} />
                       {score !== undefined && <UniquenessMeter score={score} justification={justification} />}
                   </div>
               );
            }

            if (stepId === 7) {
                 return <DataAnalysisView analysisData={data} />;
            }

            return <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        } catch (error) {
            return <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        }
    };

    if (isLoading && !output) {
        return (
            <div className="text-center p-5">
                 <div className="spinner-border mb-3 text-primary-glow" role="status"></div>
                <h5 className="fw-bold">Hypatia is calculating...</h5>
                <p className="text-white-50 small">Synchronizing archival node data. This process is optimized for stability.</p>
            </div>
        );
    }

    if (!output) {
        return (
            <div className="text-center p-5">
                <p className="text-white-50 mb-4">ARCHIVAL NODE IDLE: Ready to synthesize archival content.</p>
                <button 
                    className="btn btn-primary btn-lg px-4" 
                    onClick={handleLaunch}
                    disabled={isLoading}
                >
                    <i className="bi bi-rocket-takeoff-fill me-2"></i> Launch AI Synthesis
                </button>
            </div>
        );
    }

    const expectJson = (stepId === 1 || stepId === 7);

    return (
        <div className="generated-text-container position-relative">
             <div className="edit-controls d-flex gap-1" style={{ position: 'absolute', top: '-10px', right: '0', zIndex: 10 }}>
                {isEditing ? (
                    <>
                        <button className="btn btn-sm btn-success" onClick={handleSave}><i className="bi bi-check-lg"></i></button>
                        <button className="btn btn-sm btn-secondary" onClick={() => setIsEditing(false)}><i className="bi bi-x-lg"></i></button>
                    </>
                ) : (
                    <>
                        <button className="btn btn-sm btn-outline-secondary" onClick={() => setShowRegenInput(p => !p)} disabled={isLoading} title="Regenerate">
                           <i className="bi bi-arrow-clockwise"></i>
                        </button>
                        <button className="btn btn-sm btn-outline-secondary" onClick={() => { setIsEditing(true); setEditText(output); }} disabled={isLoading} title="Edit">
                            <i className="bi bi-pencil-square"></i>
                        </button>
                    </>
                )}
            </div>

             {showRegenInput && (
                <div className="input-group mb-3 mt-4">
                    <input type="text" className="form-control" placeholder="Optional archival feedback..." value={regenFeedback} onChange={e => setRegenFeedback(e.target.value)} />
                    <button className="btn btn-primary" onClick={handleRegenerate} disabled={isLoading}>REGENERATE</button>
                </div>
            )}

            <div className={showRegenInput ? "mt-2" : "mt-4"}>
                {isEditing ? (
                     <textarea 
                        className="form-control font-monospace bg-dark text-white border-secondary" 
                        style={{ minHeight: '300px' }} 
                        value={editText} 
                        onChange={(e) => setEditText(e.target.value)} 
                    />
                ) : (
                    expectJson ? jsonParser(output) : <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />
                )}
            </div>
            {isLoading && (
                <div className="mt-3 text-center">
                    <div className="spinner-border spinner-border-sm text-primary-glow me-2"></div>
                    <span className="small text-white-50">Decoding forensic archival stream...</span>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { parseGeminiError, getStepContext, getPromptForStep, callGeminiWithRetry, callGeminiStreamWithRetry } from '../../services';
import { WORKFLOW_STEPS } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, setActiveExperiment, isAuthenticated } = useExperiment();
    const [activeStep, setActiveStep] = useState(activeExperiment.currentStep);
    const [isLoading, setIsLoading] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const { addToast } = useToast();

    // Use a ref for the streaming loop to avoid closure issues without triggering re-renders
    const experimentRef = useRef(activeExperiment);
    useEffect(() => {
        experimentRef.current = activeExperiment;
    }, [activeExperiment]);

    useEffect(() => {
        setActiveStep(activeExperiment.currentStep);
    }, [activeExperiment.currentStep]);

    const stepData = useMemo(() => activeExperiment.stepData[activeStep] || {}, [activeExperiment.stepData, activeStep]);
    const fineTuneSettings = useMemo(() => activeExperiment.fineTuneSettings[activeStep] || {}, [activeExperiment.fineTuneSettings, activeStep]);

    const handleStepChange = (stepId: number) => {
        if (stepId <= activeExperiment.currentStep && !isLoading) {
            setActiveStep(stepId);
        }
    };

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated) {
            addToast("Archive link offline. Please establish credentials.", "danger");
            return;
        }

        setIsLoading(true);
        try {
            const context = await getStepContext(experimentRef.current, activeStep);
            const { basePrompt, expectJson, config } = getPromptForStep(
                activeStep,
                experimentRef.current.stepData[activeStep]?.input || '',
                context,
                fineTuneSettings,
                regenerateFeedback
            );

            if (expectJson) {
                const response = await callGeminiWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });
                const finalOutput = response.text || '';

                const updatedStepData = {
                    ...(experimentRef.current.stepData[activeStep] || {}),
                    output: finalOutput
                };

                await updateExperiment({ 
                    ...experimentRef.current, 
                    stepData: { ...experimentRef.current.stepData, [activeStep]: updatedStepData } 
                });
            } else {
                let accumulatedText = '';
                let lastUpdateTime = Date.now();
                // 800ms throttle is safer for complex DOMs like scientific apps
                const THROTTLE_MS = 800; 

                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });

                for await (const chunk of stream) {
                    accumulatedText += (chunk.text || '');
                    const now = Date.now();

                    if (now - lastUpdateTime > THROTTLE_MS) {
                        const currentText = accumulatedText;
                        setActiveExperiment(exp => {
                            if (!exp) return exp;
                            return {
                                ...exp,
                                stepData: {
                                    ...exp.stepData,
                                    [activeStep]: { ...(exp.stepData[activeStep] || {}), output: currentText }
                                }
                            };
                        });
                        lastUpdateTime = now;
                    }
                }

                // Final flush
                await updateExperiment({
                    ...experimentRef.current,
                    stepData: {
                        ...experimentRef.current.stepData,
                        [activeStep]: { ...(experimentRef.current.stepData[activeStep] || {}), output: accumulatedText }
                    }
                });
            }
            addToast("Archive synthesis successful.", "success");
        } catch (error) {
            addToast(parseGeminiError(error), 'danger');
        } finally {
            setIsLoading(false);
        }
    };

    const handleCompleteStep = async () => {
        if (activeStep === 10 || isLoading || !stepData.output) return;

        setIsLoading(true);
        try {
            const nextStep = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : WORKFLOW_STEPS.length + 1;
            const updatedExperiment = { 
                ...activeExperiment, 
                stepData: { ...activeExperiment.stepData, [activeStep]: { ...stepData, summary: "Archive node verified." } }, 
                currentStep: nextStep 
            };
            await updateExperiment(updatedExperiment);
        } catch (error) {
            addToast("Step finalize failed.", 'danger');
        } finally {
            setIsLoading(false);
        }
    };

    const renderStepContent = () => {
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        const stepInfo = WORKFLOW_STEPS[activeStep - 1];
        if (!stepInfo) return <div className="p-4 text-center">Node link corrupted. Please re-select from Dashboard.</div>;

        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => {
                updateExperiment({...activeExperiment, automationMode: mode});
            }} />;
        }

        return (
            <div>
                <h4 className="fw-bold">{stepInfo.id}. {stepInfo.title}</h4>
                <p className="text-white-50 small">{stepInfo.description}</p>
                <hr />
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                {activeStep === 2 && <LiteratureReviewWorkspace onStepComplete={handleCompleteStep} />}
                {activeStep === 6 && <ExperimentRunner onStepComplete={handleCompleteStep} />}
                {activeStep === 7 && <DataAnalysisWorkspace onStepComplete={handleCompleteStep} />}
                {activeStep === 9 && <PeerReviewWorkspace onStepComplete={handleCompleteStep} />}
                {activeStep === 10 && <PublicationExporter />}

                {![2, 6, 7, 9, 10].includes(activeStep) && (
                    <GeneratedOutput
                        key={activeExperiment.id + '-' + activeStep}
                        stepId={activeStep}
                        onGenerate={handleGenerate}
                        isLoading={isLoading}
                    />
                )}
            </div>
        );
    };

    return (
        <div className="row">
            <div className="col-lg-3">
                 <div className="card sticky-top shadow-sm" style={{top: '80px'}}>
                    <div className="card-header fw-bold text-truncate" title={activeExperiment.title}>{activeExperiment.title}</div>
                     <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                             <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                                style={{cursor: step.id <= activeExperiment.currentStep ? 'pointer' : 'not-allowed'}}
                            >
                                <span className="small">{step.id}. {step.title}</span>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                 </div>
            </div>
            <div className="col-lg-9">
                <div className="card shadow-sm">
                    <div className="card-body" style={{minHeight: '70vh'}}>
                        {renderStepContent()}
                    </div>
                    {activeStep <= WORKFLOW_STEPS.length && activeExperiment.automationMode !== 'automated' && ![2, 6, 7, 9, 10].includes(activeStep) && (
                         <div className="card-footer d-flex justify-content-between align-items-center bottom-nav py-3">
                             <button className="btn btn-outline-secondary btn-sm" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Fine-Tune AI
                             </button>
                             <button 
                                className="btn btn-success" 
                                onClick={handleCompleteStep} 
                                disabled={isLoading || !stepData?.output}>
                                 <i className="bi bi-check-circle-fill me-1"></i> Finalize Node
                             </button>
                         </div>
                    )}
                </div>
            </div>
             {fineTuneModalOpen && (
                <FineTuneModal
                    stepId={activeStep}
                    onClose={() => setFineTuneModalOpen(false)}
                />
            )}
        </div>
    );
};

import { marked } from 'marked';

/**
 * Optimized Markdown renderer with performance monitoring.
 * 
 * @param markdownText - The content to render.
 * @param isFinal - If false, skips expensive post-processing like KaTeX math rendering.
 */
export const renderMarkdown = (markdownText: string, isFinal: boolean = true): string => {
    if (!markdownText) return '';
    const startTime = performance.now();

    try {
        // Profiling the core parser
        const html = marked.parse(markdownText, { gfm: true, breaks: true }) as string;
        const parseTime = performance.now() - startTime;

        if (parseTime > 100) {
            console.warn(`[Hypatia Performance] Markdown parsing took ${parseTime.toFixed(2)}ms for ${markdownText.length} chars.`);
        }

        // Performance guard: Skip math rendering if content is still streaming or has no math markers
        if (!isFinal) return html;

        const hasMath = markdownText.includes('$') || markdownText.includes('\\(') || markdownText.includes('\\[');
        if (!hasMath) return html;

        // KaTeX post-processing
        const win = window as any;
        if (win.renderMathInElement) {
            const mathStartTime = performance.now();
            const container = document.createElement('div');
            container.innerHTML = html;
            try {
                win.renderMathInElement(container, {
                    delimiters: [
                        { left: '$$', right: '$$', display: true },
                        { left: '$', right: '$', display: false },
                        { left: '\\(', right: '\\)', display: false },
                        { left: '\\[', right: '\\]', display: true }
                    ],
                    throwOnError: false
                });
                const totalTime = performance.now() - startTime;
                if (totalTime > 200) {
                    console.warn(`[Hypatia Performance] Total render (Markdown + KaTeX) took ${totalTime.toFixed(2)}ms.`);
                }
                return container.innerHTML;
            } catch (err) {
                console.warn("KaTeX rendering error:", err);
            }
        }

        return html;
    } catch (error) {
        console.error("Markdown rendering failed:", error);
        return `<p class="text-danger">Forensic data reconstruction failed.</p>`;
    }
};

