            </div>
            <div className="col-lg-9">
                <div className="card shadow-sm">
                    <div className="card-body" style={{minHeight: '70vh'}}>
                        {renderStepContent()}
                    </div>
                    {activeStep <= WORKFLOW_STEPS.length && activeExperiment.automationMode !== 'automated' && ![2, 6, 7, 9, 10].includes(activeStep) && (
                         <div className="card-footer d-flex justify-content-between align-items-center bottom-nav py-3">
