import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { parseGeminiError, getStepContext, getPromptForStep, callGeminiWithRetry, callGeminiStreamWithRetry } from '../../services';
import { WORKFLOW_STEPS } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();

    // Local UI State
    const [activeStep, setActiveStep] = useState(activeExperiment?.currentStep || 1);
    const [isLoading, setIsLoading] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);

    // streamingText is local to this component to prevent global context updates from freezing the UI
    const [streamingText, setStreamingText] = useState<string | null>(null);

    // Sync activeStep with experiment progress if they diverge
    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading) {
            setActiveStep(activeExperiment.currentStep);
        }
    }, [activeExperiment?.currentStep, isLoading]);

    // Safety check - if no experiment, show a simpler layout but keep the structure
    if (!activeExperiment) {
        return (
            <div className="container p-5 text-center">
                <div className="card border-danger">
                    <div className="card-body">
                        <h4 className="text-danger">Archive Link Lost</h4>
                        <p>The research project session has expired. Please return to the dashboard.</p>
                    </div>
                </div>
            </div>
        );
    }

    const handleStepChange = (stepId: number) => {
        if (stepId <= activeExperiment.currentStep && !isLoading) {
            setStreamingText(null); // Reset streaming text when navigating
            setActiveStep(stepId);
        }
    };

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading) return;

        setIsLoading(true);
        setStreamingText(''); // Initialize streaming local state

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            const fineTuneSettings = activeExperiment.fineTuneSettings[activeStep] || {};

            const { basePrompt, expectJson, config } = getPromptForStep(
                activeStep,
                activeExperiment.stepData[activeStep]?.input || '',
                context,
                fineTuneSettings,
                regenerateFeedback
            );

            if (expectJson) {
                const response = await callGeminiWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });
                const finalOutput = response.text || '';

                await updateExperiment({ 
                    ...activeExperiment, 
                    stepData: { 
                        ...activeExperiment.stepData, 
                        [activeStep]: { ...(activeExperiment.stepData[activeStep] || {}), output: finalOutput } 
                    } 
                });
                setStreamingText(null);
            } else {
                let accumulated = '';
                let lastUiUpdate = Date.now();
                const UI_UPDATE_INTERVAL = 1000; // Only update UI once per second to stay smooth

                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });

                for await (const chunk of stream) {
                    accumulated += (chunk.text || '');
                    const now = Date.now();

                    if (now - lastUiUpdate > UI_UPDATE_INTERVAL) {
                        setStreamingText(accumulated);
                        lastUiUpdate = now;
                    }
                }

                // Final save to database
                await updateExperiment({
                    ...activeExperiment,
                    stepData: {
                        ...activeExperiment.stepData,
                        [activeStep]: { ...(activeExperiment.stepData[activeStep] || {}), output: accumulated }
                    }
                });
                setStreamingText(null);
            }
            addToast("Synthesis complete.", "success");
        } catch (error) {
            console.error("Stream failure:", error);
            addToast(parseGeminiError(error), 'danger');
            setStreamingText(null);
        } finally {
            setIsLoading(false);
        }
    };

    const handleCompleteStep = async () => {
        if (activeStep === 10 || isLoading) return;

        setIsLoading(true);
        try {
            const nextStep = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : WORKFLOW_STEPS.length + 1;
            await updateExperiment({ 
                ...activeExperiment, 
                stepData: { 
                    ...activeExperiment.stepData, 
                    [activeStep]: { ...(activeExperiment.stepData[activeStep] || {}), summary: "Verified." } 
                }, 
                currentStep: nextStep 
            });
            setActiveStep(nextStep);
        } catch (error) {
            addToast("Finalization failed.", 'danger');
        } finally {
            setIsLoading(false);
        }
    };

    const renderStepContent = () => {
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;

        const stepInfo = WORKFLOW_STEPS[activeStep - 1];
        if (!stepInfo) return <div className="p-4 text-center">Node selection error.</div>;

        // Handle automation mode selection
        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return (
                <AutomationModeSelector 
                    onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} 
                />
            );
        }

        // Special Step Workspaces
        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={handleCompleteStep} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={handleCompleteStep} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={handleCompleteStep} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={handleCompleteStep} />;
        if (activeStep === 10) return <PublicationExporter />;

        // Standard Text Generation Steps
        return (
            <div className="discovery-flow">
                {activeStep === 1 && <EditableStepInput stepId={1} />}

                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    return (
        <div className="container-fluid workspace-layout">
            <div className="row g-4">
                {/* Fixed Sidebar */}
                <div className="col-lg-3">
                    <div className="card sticky-top shadow-sm" style={{ top: '90px', zIndex: 10 }}>
                        <div className="card-header fw-bold text-truncate bg-dark">
                            <i className="bi bi-diagram-3-fill me-2 text-primary-glow"></i>
                            {activeExperiment.title}
                        </div>
                        <ul className="list-group list-group-flush">
                            {WORKFLOW_STEPS.map(step => (
                                <li
                                    key={step.id}
                                    className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled opacity-50' : ''}`}
                                    onClick={() => handleStepChange(step.id)}
                                    style={{ cursor: step.id <= activeExperiment.currentStep ? 'pointer' : 'default' }}
                                >
                                    <span className="small">{step.id}. {step.title}</span>
                                    {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success small"></i>}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>

                {/* Main Content Area */}
                <div className="col-lg-9">
                    <div className="card shadow-sm mb-4">
                        <div className="card-body" style={{ minHeight: '60vh' }}>
                            <div className="mb-4">
                                <h4 className="fw-bold">{activeStep <= WORKFLOW_STEPS.length ? `${activeStep}. ${WORKFLOW_STEPS[activeStep - 1].title}` : 'Project Complete'}</h4>
                                {activeStep <= WORKFLOW_STEPS.length && <p className="text-white-50 small mb-0">{WORKFLOW_STEPS[activeStep - 1].description}</p>}
                            </div>
                            <hr className="border-secondary opacity-10" />
                            {renderStepContent()}
                        </div>

                        {/* Footer Navigation */}
                        {activeStep <= WORKFLOW_STEPS.length && 
                         activeExperiment.automationMode !== 'automated' && 
                         ![2, 6, 7, 9, 10].includes(activeStep) && (
                            <div className="card-footer d-flex justify-content-between align-items-center py-3">
                                <button className="btn btn-sm btn-outline-secondary" onClick={() => setFineTuneModalOpen(true)} disabled={isLoading}>
                                    <i className="bi bi-sliders me-1"></i> AI Settings
                                </button>
                                <button 
                                    className="btn btn-success" 
                                    onClick={handleCompleteStep} 
                                    disabled={isLoading || !activeExperiment.stepData[activeStep]?.output}
                                >
                                    <i className="bi bi-check-circle-fill me-1"></i> Finalize Node
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {fineTuneModalOpen && (
                <FineTuneModal
                    stepId={activeStep}
                    onClose={() => setFineTuneModalOpen(false)}
                />
            )}
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { UniquenessMeter } from './UniquenessMeter';
import { DataAnalysisView } from './DataAnalysisView';

interface GeneratedOutputProps {
    stepId: number;
    onGenerate: (feedback?: string) => Promise<void>;
    isLoading: boolean;
    streamingText?: string | null;
}

export const GeneratedOutput: React.FC<GeneratedOutputProps> = ({ 
    stepId, 
    onGenerate, 
    isLoading, 
    streamingText 
}) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();

    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState('');
    const [showRegenInput, setShowRegenInput] = useState(false);
    const [regenFeedback, setRegenFeedback] = useState('');

    const stepData = activeExperiment.stepData[stepId] || {};
    const savedOutput = stepData.output || '';

    // Display either the active stream or the saved result
    const currentText = streamingText !== null ? streamingText : savedOutput;

    useEffect(() => {
        setEditText(savedOutput);
    }, [savedOutput]);

    const handleSave = () => {
        updateExperiment({ 
            ...activeExperiment, 
            stepData: { 
                ...activeExperiment.stepData, 
                [stepId]: { ...stepData, output: editText } 
            } 
        });
        setIsEditing(false);
        addToast("Archival node updated.", "success");
    };

    const handleLaunch = () => {
        if (isLoading) return;
        onGenerate();
    };

    const handleRegenerate = () => {
        if (isLoading) return;
        onGenerate(regenFeedback);
        setShowRegenInput(false);
        setRegenFeedback('');
    };

    const renderedHtml = useMemo(() => {
        if (!currentText) return '';
        // Skip math rendering while loading to avoid thread blocking
        return renderMarkdown(currentText, !isLoading);
    }, [currentText, isLoading]);

    const renderJsonContent = (text: string) => {
        try {
            const clean = text.replace(/```json/g, '').replace(/```/g, '').trim();
            const data = JSON.parse(clean);

            if (stepId === 1) {
                return (
                   <div>
                       <div dangerouslySetInnerHTML={{ __html: renderMarkdown(data.research_question || '', true) }} />
                       {data.uniqueness_score !== undefined && (
                           <UniquenessMeter 
                                score={data.uniqueness_score} 
                                justification={data.justification || ''} 
                           />
                       )}
                   </div>
               );
            }
            if (stepId === 7) return <DataAnalysisView analysisData={data} />;
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        } catch (e) {
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        }
    };

    // Loading Screen (Empty state while launching)
    if (isLoading && !currentText) {
        return (
            <div className="text-center p-5">
                 <div className="spinner-border mb-3 text-primary-glow" role="status"></div>
                <h5 className="fw-bold">Hypatia is calculating...</h5>
                <p className="text-white-50 small">Synchronizing archive links. This takes a moment.</p>
            </div>
        );
    }

    // Initial IDLE state
    if (!currentText && !isLoading) {
        return (
            <div className="text-center p-5 border border-secondary border-opacity-10 rounded-4 mt-4">
                <i className="bi bi-cpu-fill mb-3 opacity-20" style={{ fontSize: '3rem' }}></i>
                <p className="text-white-50 mb-4">ARCHIVE NODE IDLE: Content required for forensic reconstruction.</p>
                <button 
                    className="btn btn-primary btn-lg px-5" 
                    onClick={handleLaunch}
                    disabled={isLoading}
                >
                    <i className="bi bi-rocket-takeoff-fill me-2"></i> Launch AI Synthesis
                </button>
            </div>
        );
    }

    const isJsonStep = stepId === 1 || stepId === 7;

    return (
        <div className="generated-content-container position-relative mt-4">
            {/* Action Bar */}
            {!isLoading && !isEditing && (
                <div className="d-flex justify-content-end gap-2 mb-3">
                    <button className="btn btn-sm btn-outline-secondary" onClick={() => setShowRegenInput(p => !p)} title="Regenerate">
                        <i className="bi bi-arrow-clockwise"></i>
                    </button>
                    <button className="btn btn-sm btn-outline-secondary" onClick={() => { setIsEditing(true); setEditText(savedOutput); }} title="Edit">
                        <i className="bi bi-pencil-square"></i>
                    </button>
                </div>
            )}

            {showRegenInput && (
                <div className="input-group mb-3">
                    <input 
                        type="text" 
                        className="form-control bg-dark border-secondary" 
                        placeholder="Add archival feedback..." 
                        value={regenFeedback} 
                        onChange={e => setRegenFeedback(e.target.value)} 
                    />
                    <button className="btn btn-primary" onClick={handleRegenerate} disabled={isLoading}>REGENERATE</button>
                </div>
            )}

            {isEditing ? (
                <div className="edit-view">
                    <textarea 
                        className="form-control font-monospace bg-dark text-white border-secondary mb-3" 
                        style={{ minHeight: '350px' }} 
                        value={editText} 
                        onChange={(e) => setEditText(e.target.value)} 
                    />
                    <div className="d-flex gap-2 justify-content-end">
                        <button className="btn btn-secondary" onClick={() => setIsEditing(false)}>Cancel</button>
                        <button className="btn btn-success" onClick={handleSave}>Save Changes</button>
                    </div>
                </div>
            ) : (
                <div className="rendered-view">
                    {isJsonStep && !isLoading ? renderJsonContent(currentText) : <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />}

                    {isLoading && (
                        <div className="mt-4 pt-3 border-top border-secondary border-opacity-10 text-center">
                            <div className="spinner-border spinner-border-sm text-primary-glow me-2"></div>
                            <span className="small text-white-50">Decoding forensic stream...</span>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

import { marked } from 'marked';

/**
 * Optimized Markdown renderer.
 * 
 * @param markdownText - The content to render.
 * @param isFinal - If false, skips expensive post-processing like KaTeX math rendering.
 */
export const renderMarkdown = (markdownText: string, isFinal: boolean = true): string => {
    if (!markdownText) return '';

    try {
        // Core Markdown parsing
        const html = marked.parse(markdownText, { gfm: true, breaks: true }) as string;

        // Performance optimization: Skip heavy math rendering while content is still streaming
        if (!isFinal) return html;

        const hasMath = markdownText.includes('$') || markdownText.includes('\\(') || markdownText.includes('\\[');
        if (!hasMath) return html;

        // KaTeX post-processing for static content
        const win = window as any;
        if (win.renderMathInElement) {
            const container = document.createElement('div');
            container.innerHTML = html;
            try {
                win.renderMathInElement(container, {
                    delimiters: [
                        { left: '$$', right: '$$', display: true },
                        { left: '$', right: '$', display: false },
                        { left: '\\(', right: '\\)', display: false },
                        { left: '\\[', right: '\\]', display: true }
                    ],
                    throwOnError: false
                });
                return container.innerHTML;
            } catch (err) {
                console.warn("KaTeX post-processing error:", err);
            }
        }

        return html;
    } catch (error) {
        console.error("Markdown rendering failed:", error);
        return `<p class="text-danger">Forensic data reconstruction failure.</p>`;
    }
};

