/**
 * Validates if an API key is structurally sound. 
 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

/**
 * Handles specific AI Studio key selection errors.
 */
const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    const isAuthError = msg.includes("Requested entity was not found") || 
                        msg.includes("403") || 
                        msg.includes("401") ||
                        status === 403 ||
                        status === 404;

    if (isAuthError) {
        const aistudio = (window as any).aistudio;
        if (aistudio && typeof aistudio.openSelectKey === 'function') {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

/**
 * Validates a string against a JSON schema (basic required fields check).
 */
export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = jsonStr.replace(/```json/g, '').replace(/```/g, '').trim();
        const data = JSON.parse(cleanStr);
        if (schema && schema.required) {
            return schema.required.every((key: string) => key in data);
        }
        return true;
    } catch (e) {
        return false;
    }
};

/**
 * Agent: Subject Expert
 * Refines the generated content for scientific rigor and tone.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false
): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemInstruction = `You are a world-class Senior Scientific Subject Expert in ${context.experimentField}. 
    Your task is to review and correct the provided content. 
    1. Fix factual inaccuracies or logical inconsistencies.
    2. Improve terminology while keeping the core meaning identical.
    3. Do NOT add preamble or conversational fluff.
    ${isJson ? 'CRITICAL: You MUST return a single valid JSON block that strictly adheres to the schema. Preserve the JSON structure exactly. If the input is invalid, fix it so it parses correctly.' : 'Return the corrected text in Markdown.'}`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Please refine the following content:\n\n${content}`,
            config: { systemInstruction }
        });
        return response.text || content;
    } catch (e) {
        console.warn("Subject Expert refinement failed, returning raw content.", e);
        return content;
    }
};

/**
 * Agentic JSON Loop: JSON Expert fixes + QA Agent validates.
 */
const agenticJsonFixLoop = async (
    invalidJson: string, 
    schema: any, 
    errorMsg: string
): Promise<string | null> => {
    let currentJson = invalidJson;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    for (let cycle = 1; cycle <= 3; cycle++) {
        // 1. JSON Expert Pass
        const expertResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: `ACT AS JSON EXPERT. The following JSON failed validation for schema: ${JSON.stringify(schema)}. 
            Error: ${errorMsg}. 
            Fix the JSON string. Return ONLY the valid JSON block.
            INPUT: ${currentJson}`,
        });
        currentJson = expertResponse.text || currentJson;

        // 2. QA Agent Pass
        const qaResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `ACT AS QA AGENT. Check if this string is valid JSON and contains all required fields from this schema: ${JSON.stringify(schema)}. 
            JSON: ${currentJson}. 
            Reply exactly "PASSED" if correct, or "FAILED: [reason]" if not.`,
        });

        const qaText = (qaResponse.text || "").trim().toUpperCase();
        if (qaText === 'PASSED' && isValidJsonForSchema(currentJson, schema)) {
            return currentJson;
        }
        errorMsg = qaText;
    }
    return null; // Failed after 3 cycles
};

/**
 * Main generation workflow including Agentic Loops and Subject Expert review.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    let output = "";
    let success = false;
    let lastError = "";

    // 1. Initial Generation with 3 Retries (Total 4 attempts)
    for (let attempt = 1; attempt <= 4; attempt++) {
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            });
            output = response.text || "";

            if (expectJson) {
                if (isValidJsonForSchema(output, schema)) {
                    success = true;
                    break;
                } else {
                    lastError = "JSON Schema Mismatch";
                    console.warn(`Attempt ${attempt} failed JSON validation.`);
                    if (attempt === 4) break;
                }
            } else {
                success = true;
                break;
            }
        } catch (e: any) {
            lastError = e.message;
            if (attempt === 4) throw e;
            await new Promise(r => setTimeout(r, 1000 * attempt));
        }
    }

    // 2. Agentic Fix Loop for JSON steps if still failing
    if (expectJson && !success) {
        console.log("Triggering Agentic JSON Fix Loop...");
        const fixed = await agenticJsonFixLoop(output, schema, lastError);
        if (fixed) {
            output = fixed;
            success = true;
        } else {
            throw new Error(`Critical Error: Could not generate valid JSON after multiple agentic cycles. Error: ${lastError}`);
        }
    }

    // 3. Subject Expert Review for ALL steps
    console.log("Triggering Subject Expert Refinement...");
    output = await refineWithSubjectExpert(output, context, expectJson);

    return output;
};

