/**
 * Validates if an API key is structurally sound. 
 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

/**
 * Handles specific AI Studio key selection errors.
 */
const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    const isAuthError = msg.includes("Requested entity was not found") || 
                        msg.includes("403") || 
                        msg.includes("401") ||
                        status === 403 ||
                        status === 404;

    if (isAuthError) {
        const aistudio = (window as any).aistudio;
        if (aistudio && typeof aistudio.openSelectKey === 'function') {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

/**
 * Validates a string against a JSON schema (basic required fields check).
 */
export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = jsonStr.replace(/```json/g, '').replace(/```/g, '').trim();
        const data = JSON.parse(cleanStr);
        if (schema && schema.required) {
            return schema.required.every((key: string) => key in data);
        }
        return true;
    } catch (e) {
        return false;
    }
};

/**
 * Agent: Subject Expert
 * Refines the generated content for scientific rigor and tone.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false,
    schema?: any
): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Determine the best model for refinement
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

    const systemInstruction = `You are a world-class Senior Scientific Subject Expert in ${context.experimentField}. 
    Your task is to review and correct the provided content. 
    1. Fix factual inaccuracies or logical inconsistencies.
    2. Improve scientific terminology while keeping the core meaning identical.
    3. Do NOT add preamble or conversational fluff.
    ${isJson ? 'CRITICAL: You MUST return a single valid JSON block that strictly adheres to the schema. Preserve the JSON structure exactly.' : 'Return the corrected text in Markdown.'}`;

    const config: any = { 
        systemInstruction,
        temperature: 0.2 // Lower temperature for refinement to prevent drift
    };

    if (isJson && schema) {
        config.responseMimeType = "application/json";
        config.responseSchema = schema;
    }

    try {
        const response = await ai.models.generateContent({
            model,
            contents: `Please refine the following ${isJson ? 'JSON data' : 'scientific content'}:\n\n${content}`,
            config
        });
        const refinedText = response.text || content;

        // Final sanity check for JSON
        if (isJson && !isValidJsonForSchema(refinedText, schema)) {
            console.warn("Refined output failed JSON validation, falling back to original.");
            return content;
        }

        return refinedText;
    } catch (e) {
        console.warn("Subject Expert refinement failed, returning raw content.", e);
        return content;
    }
};

/**
 * Agentic JSON Loop: JSON Expert fixes + QA Agent validates.
 */
const agenticJsonFixLoop = async (
    invalidJson: string, 
    schema: any, 
    errorMsg: string
): Promise<string | null> => {
    let currentJson = invalidJson;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    for (let cycle = 1; cycle <= 3; cycle++) {
        try {
            // 1. JSON Expert Pass
            const expertResponse = await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: `ACT AS JSON EXPERT. The following string failed JSON validation or schema compliance. 
                Schema: ${JSON.stringify(schema)}. 
                Error Context: ${errorMsg}. 
                Fix the string so it is valid JSON and contains all required keys. Return ONLY the JSON block.
                INPUT: ${currentJson}`,
                config: { responseMimeType: "application/json", responseSchema: schema }
            });
            currentJson = expertResponse.text || currentJson;

            // 2. QA Agent Pass
            const qaResponse = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `ACT AS QA AGENT. Check if this string is valid JSON and contains all required fields from this schema: ${JSON.stringify(schema)}. 
                JSON: ${currentJson}. 
                Reply exactly "PASSED" if correct, or "FAILED: [reason]" if not.`,
            });

            const qaText = (qaResponse.text || "").trim().toUpperCase();
            if (qaText === 'PASSED' && isValidJsonForSchema(currentJson, schema)) {
                return currentJson;
            }
            errorMsg = qaText;
        } catch (e) {
            console.error(`Fix cycle ${cycle} error:`, e);
        }
    }
    return null; // Failed after 3 cycles
};

/**
 * Main generation workflow including Agentic Loops and Subject Expert review.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    let output = "";
    let success = false;
    let lastError = "";

    // 1. Initial Generation with 3 Retries (Total 4 attempts)
    for (let attempt = 1; attempt <= 4; attempt++) {
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            });
            output = response.text || "";

            if (expectJson) {
                if (isValidJsonForSchema(output, schema)) {
                    success = true;
                    break;
                } else {
                    lastError = "JSON Schema Mismatch or Malformed JSON";
                    console.warn(`Attempt ${attempt} failed JSON validation.`);
                    if (attempt === 4) break;
                }
            } else {
                success = true;
                break;
            }
        } catch (e: any) {
            lastError = e.message;
            if (attempt === 4) throw e;
            await new Promise(r => setTimeout(r, 1000 * attempt));
        }
    }

    // 2. Agentic Fix Loop for JSON steps if still failing
    if (expectJson && !success) {
        console.log("Triggering Agentic JSON Fix Loop...");
        const fixed = await agenticJsonFixLoop(output, schema, lastError);
        if (fixed) {
            output = fixed;
            success = true;
        } else {
            throw new Error(`Critical Error: Could not generate valid JSON after multiple agentic cycles. Error: ${lastError}`);
        }
    }

    // 3. Subject Expert Review for ALL steps
    // For JSON steps, we MUST pass the schema to the refiner to prevent breaking the structure
    console.log("Triggering Subject Expert Refinement...");
    output = await refineWithSubjectExpert(output, context, expectJson, schema);

    return output;
};

/**
 * Legacy wrapper maintained for standard calls, now uses the robust workflow.
 */
export const callGeminiWithRetry = async (
    model: string,
    params: { contents: string, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 2
) => {
    // We infer a generic context if not provided
    const context = { experimentField: 'Scientific Research' };
    const text = await executeStepWorkflow(model, params, context);
    return { text };
};

/**
 * Executes a streaming Gemini call. (Subject Expert review happens after stream in UI handler)
 */
export const callGeminiStreamWithRetry = async (
    model: string,
    params: { contents: string, config?: any },
    onLog?: (message: string) => void,
    maxRetries = 1
) => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        return await ai.models.generateContentStream({
            model: model,
            contents: params.contents,
            config: params.config
        });
    } catch (error: any) {
        const errorResult = await handleApiError(error);
        if (errorResult === "AUTH_RETRY_REQUIRED") throw new Error("Authentication re-sync required.");
        throw error;
    }
};

export const parseGeminiError = (error: any, fallbackMessage: string = "Discovery link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync')) return "Archive link unstable: Please re-verify your project key.";
    if (msg.includes('safety')) return "Archive protocol block: content violates safety filters.";
    if (msg.includes('Critical Error')) return error.message;
    return fallbackMessage;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 500) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);
    if (stepId > 8) context.conclusion_summary = getSummary(8);
    if (stepId > 9) context.peer_review_summary = getSummary(9);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) {
                projectLog += `[Step ${i}] ${stepInfo.title}: ${getSummary(i)}\n\n`;
            }
        }
        context.full_project_summary_log = projectLog.trim();
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    let systemInstruction = `You are Hypatia, an AI scientific researcher. Field: ${context.experimentField}. Persona: Professional, methodical, rigorous.`;
    const settings = fineTuneSettings || {};

    let basePrompt = "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.7 };

    if (regenerateFeedback) {
        basePrompt += `ARCHIVAL OVERRIDE (PI FEEDBACK): "${regenerateFeedback}"\n\n`;
    }

    // JSON Prepender Instructions
    const JSON_INSTRUCTIONS = (schema: string) => `
    CRITICAL: YOU MUST OUTPUT ONLY VALID JSON. 
    ADHERE STRICTLY TO THIS SCHEMA: ${schema}. 
    DO NOT INCLUDE ANY CONVERSATIONAL TEXT, PREAMBLE, OR POSTAMBLE. 
    IF AN ERROR OCCURS, ENSURE THE JSON OBJECT CONTAINS AN "error" KEY DESCRIBING THE ISSUE.
    `;

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt = JSON_INSTRUCTIONS(JSON.stringify(RESEARCH_QUESTION_SCHEMA)) + 
                `\n\nGoal: Refine the following initial idea into a specific, testable scientific research question. 
                Initial Idea Context: 
                "${userInput}"

                Evaluate the uniqueness and novelty of this question relative to the field of ${context.experimentField}.
                Output valid JSON with the following keys: "research_question", "uniqueness_score" (0.0 to 1.0), "justification" (brief reasoning for the score), and "field".`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            basePrompt += `Literature review for: "${context.question}". Identify key papers and gaps. Focus on identifying specific Archive Gaps for novelty.`;
            break;
        case 3:
            basePrompt += `Formulate 3 distinct hypotheses for: "${context.question}" based on literature review summary: "${context.literature_review_summary}"`;
            break;
        case 4:
            basePrompt += `Detailed experimental methodology for: "${context.hypothesis}"`;
            break;
        case 5:
            basePrompt += `Data collection plan for methodology: "${context.methodology_summary}"`;
            break;
        case 6:
            basePrompt += `Generate synthetic CSV data for: "${context.methodology_summary}". Format: header line, then rows.`;
            break;
        case 7:
            expectJson = true;
            basePrompt = JSON_INSTRUCTIONS(JSON.stringify(DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA)) + `\n\nAnalyze data: ${userInput}. Hypothesis: "${context.hypothesis}". Return valid JSON including a summary and base64 imageData for charts.`;
            config.responseMimeType = "application/json";
            config.responseSchema = DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
            break;
        case 8:
            basePrompt += `Draft conclusions from analysis summary: "${context.analysis_summary}" and check if hypothesis was supported.`;
            break;
        case 9:
             basePrompt += `Simulate a skeptical peer review of project log: \n\n${context.full_project_summary_log}`;
             break;
        case 10:
             basePrompt += `Draft a comprehensive scientific publication based on the project log: \n\n${context.full_project_summary_log}`;
             break;
        default:
            basePrompt += `Continue archival synthesis for Step ${stepId}`;
    }

    return { basePrompt, expectJson, config };
};

