/**
 * Validates if an API key is structurally sound. 
 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

/**
 * Handles specific AI Studio key selection errors.
 */
const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    const isAuthError = msg.includes("Requested entity was not found") || 
                        msg.includes("403") || 
                        msg.includes("401") ||
                        status === 403 ||
                        status === 404;

    if (isAuthError) {
        const aistudio = (window as any).aistudio;
        if (aistudio && typeof aistudio.openSelectKey === 'function') {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

/**
 * Validates a string against a JSON schema (basic required fields check).
 */
export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        if (!jsonStr) return false;
        const cleanStr = jsonStr.replace(/```json/g, '').replace(/```/g, '').trim();
        const data = JSON.parse(cleanStr);
        if (schema && schema.required) {
            return schema.required.every((key: string) => key in data && data[key] !== undefined);
        }
        return true;
    } catch (e) {
        return false;
    }
};

/**
 * Agent: Subject Expert
 * Refines the generated content for scientific rigor and tone.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false,
    schema?: any
): Promise<string> => {
    if (!content) return content;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

    const systemInstruction = `You are a Senior Scientific Editor in ${context.experimentField}. 
    Review the provided ${isJson ? 'JSON data' : 'research text'}.
    1. Standardize terminology for academic publication.
    2. Maintain the exact same core information and logic.
    3. ${isJson ? 'CRITICAL: Output ONLY the refined JSON. Do not break the schema.' : 'Output Markdown only.'}`;

    const config: any = { 
        systemInstruction,
        temperature: 0.1 
    };

    if (isJson && schema) {
        config.responseMimeType = "application/json";
        config.responseSchema = schema;
    }

    try {
        const response = await ai.models.generateContent({
            model,
            contents: `Refine the following archival node content:\n\n${content}`,
            config
        });
        const refinedText = response.text || content;

        if (isJson && !isValidJsonForSchema(refinedText, schema)) {
            console.warn("Refinement broke JSON schema. Using original output.");
            return content;
        }

        return refinedText;
    } catch (e) {
        console.error("Subject Expert refinement failed:", e);
        return content;
    }
};

/**
 * Agentic JSON Loop: JSON Specialist fixes malformed responses.
 */
const agenticJsonFixLoop = async (
    invalidJson: string, 
    schema: any, 
    errorMsg: string
): Promise<string | null> => {
    let currentJson = invalidJson;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    for (let cycle = 1; cycle <= 2; cycle++) {
        try {
            const expertResponse = await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: `FIX MALFORMED JSON. 
                Schema: ${JSON.stringify(schema)}. 
                Error: ${errorMsg}. 
                Corrupt Data: ${currentJson}. 
                Output valid JSON according to schema.`,
                config: { responseMimeType: "application/json", responseSchema: schema }
            });
            const fixed = expertResponse.text || currentJson;
            if (isValidJsonForSchema(fixed, schema)) return fixed;
            errorMsg = "Still invalid after fix attempt.";
        } catch (e) {
            console.error(`JSON Fix Cycle ${cycle} failed:`, e);
        }
    }
    return null;
};

/**
 * Core Generation Workflow with Agentic Safeguards.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    let output = "";
    let success = false;
    let lastError = "";

    // 1. Generation Phase
    for (let attempt = 1; attempt <= 3; attempt++) {
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            });
            output = response.text || "";

            if (expectJson) {
                if (isValidJsonForSchema(output, schema)) {
                    success = true;
                    break;
                }
                lastError = "Invalid JSON structure returned.";
            } else if (output.trim()) {
                success = true;
                break;
            }
        } catch (e: any) {
            lastError = e.message;
            if (attempt === 3) throw e;
            await new Promise(r => setTimeout(r, 800 * attempt));
        }
    }

    // 2. Agentic Repair Phase (JSON Only)
    if (expectJson && !success) {
        console.log("Archive Node Corrupt. Triggering Repair Agent...");
        const fixed = await agenticJsonFixLoop(output, schema, lastError);
        if (fixed) {
            output = fixed;
            success = true;
        } else {
            throw new Error(`Archival node reconstruction failed: ${lastError}`);
        }
    }

    // 3. Editorial Polish Phase
    return await refineWithSubjectExpert(output, context, expectJson, schema);
};

export const callGeminiWithRetry = async (
