    if (msg.includes('re-sync') || msg.includes('selection')) return "Archive sync required: Please verify your API key.";
    if (msg.includes('safety')) return "Security protocol block: Filtered for sensitive content.";
    if (msg.includes('node reconstruction')) return error.message;
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 400) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
