            break;
        case 10:
            basePrompt += `Draft comprehensive technical publication from project archive:\n\n${context.full_project_summary_log}`;
            break;
        default:
            basePrompt += `Continue synthesis for Step ${stepId}`;
    }

    return { basePrompt, expectJson, config };
};

