// --- UTILITIES ---

/**
 * Extracts JSON from potential markdown or conversational noise.
 */
export const extractJson = (text: string): string => {
    if (!text) return "";
    // Matches content between ```json ... ``` or just ``` ... ```
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (match) return match[1].trim();

    // If no markdown blocks, find the first '{' and last '}'
    const firstBrace = text.indexOf('{');
    const lastBrace = text.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
        return text.substring(firstBrace, lastBrace + 1).trim();
    }

    return text.trim();
};

/**
 * Validates a string against a JSON schema.
 */
export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = extractJson(jsonStr);
        if (!cleanStr) return false;
        const data = JSON.parse(cleanStr);
        if (schema && schema.required) {
            return schema.required.every((key: string) => key in data && data[key] !== undefined);
        }
        return true;
    } catch (e) {
        return false;
    }
};

// --- GEMINI API SERVICE ---

export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    if (msg.includes("Requested entity was not found") || status === 403 || status === 404) {
        const aistudio = (window as any).aistudio;
        if (aistudio?.openSelectKey) {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

/**
 * Agent: Subject Expert
 * Refines the generated content for scientific rigor.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false,
    schema?: any
): Promise<string> => {
    if (!content) return content;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

    const systemInstruction = `You are a Senior Scientific Editor in ${context.experimentField}. 
    Review the provided ${isJson ? 'JSON data' : 'research text'}.
    1. Standardize terminology for academic publication.
    2. Maintain the exact same core information and logic.
    3. ${isJson ? 'CRITICAL: Output ONLY the refined JSON. Do not add any text before or after.' : 'Output Markdown only.'}`;

    const config: any = { 
        systemInstruction,
        temperature: 0.1 
    };

    if (isJson && schema) {
        config.responseMimeType = "application/json";
        config.responseSchema = schema;
    }

    try {
        const response = await ai.models.generateContent({
            model,
            contents: `Refine the following archival node content:\n\n${content}`,
            config
        });
        const refinedText = response.text || content;

        if (isJson && !isValidJsonForSchema(refinedText, schema)) {
            console.warn("Refinement broke JSON schema. Reverting to original.");
            return extractJson(content);
        }

        return isJson ? extractJson(refinedText) : refinedText;
    } catch (e) {
        console.error("Subject Expert refinement failed:", e);
        return isJson ? extractJson(content) : content;
    }
};

/**
 * Agentic JSON Loop: Repair Agent fixes malformed output.
 */
const agenticJsonFixLoop = async (
    invalidJson: string, 
    schema: any, 
    errorMsg: string
): Promise<string | null> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    for (let cycle = 1; cycle <= 2; cycle++) {
        try {
            const expertResponse = await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: `REPAIR AGENT: The following input failed JSON schema validation.
                Schema: ${JSON.stringify(schema)}. 
                Error: ${errorMsg}. 
                Corrupt Input: ${invalidJson}. 
                Output valid JSON that adheres strictly to the schema.`,
                config: { responseMimeType: "application/json", responseSchema: schema }
            });
            const fixed = extractJson(expertResponse.text || "");
            if (isValidJsonForSchema(fixed, schema)) return fixed;
        } catch (e) {
            console.error(`JSON Repair Cycle ${cycle} failed:`, e);
        }
    }
    return null;
};

/**
 * Main Orchestration Workflow.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    let output = "";
    let success = false;
    let lastError = "";

    // 1. Primary Generation
    for (let attempt = 1; attempt <= 3; attempt++) {
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            });
            output = response.text || "";

            if (expectJson) {
                if (isValidJsonForSchema(output, schema)) {
                    output = extractJson(output);
                    success = true;
                    break;
                }
                lastError = "Schema validation failed.";
            } else if (output.trim()) {
                success = true;
                break;
            }
        } catch (e: any) {
            lastError = e.message;
            if (attempt === 3) throw e;
            await new Promise(r => setTimeout(r, 1000 * attempt));
        }
    }

    // 2. Secondary Agentic Repair (JSON Only)
    if (expectJson && !success) {
        const fixed = await agenticJsonFixLoop(output, schema, lastError);
        if (fixed) {
            output = fixed;
            success = true;
        } else {
            throw new Error(`Archival node corruption: ${lastError}`);
        }
    }

    // 3. Subject Expert Polish
    return await refineWithSubjectExpert(output, context, expectJson, schema);
};

export const callGeminiWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const context = { experimentField: 'Scientific Research' };
    const text = (await executeStepWorkflow(model, params, context));
    return { text };
};

export const callGeminiStreamWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        return await ai.models.generateContentStream({
            model: model,
            contents: params.contents,
            config: params.config
        });
    } catch (error: any) {
        const err = await handleApiError(error);
        if (err === "AUTH_RETRY_REQUIRED") throw new Error("Authentication re-sync required.");
        throw error;
    }
};

export const parseGeminiError = (error: any, fallback = "Hypatia link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync')) return "Archive link unstable: Please re-verify your project key.";
    if (msg.includes('safety')) return "Archive protocol block: content violates safety filters.";
    if (msg.includes('corruption')) return error.message;
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 500) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) projectLog += `[Phase ${i}] ${stepInfo.title}: ${getSummary(i)}\n\n`;
        }
        context.full_project_summary_log = projectLog.trim();
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    const settings = fineTuneSettings || {};
    let systemInstruction = `You are Hypatia, an advanced AI Scientific Researcher. Field: ${context.experimentField}.`;
    let basePrompt = "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.7 };

    if (regenerateFeedback) basePrompt += `[SYSTEM OVERRIDE: PI FEEDBACK: "${regenerateFeedback}"]\n\n`;

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `REFINE RESEARCH QUESTION. 
            Initial input: "${userInput}". 
            Task: Output a formal research question and uniqueness assessment based on RESEARCH_QUESTION_SCHEMA. 
            Requirement: Output ONLY valid JSON.`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            basePrompt += `Conduct a literature review for: "${context.question}". Use Google Search grounding to find gaps.`;
            break;
        case 3:
            basePrompt += `Formulate 3 hypotheses for question "${context.question}" based on Lit Review: "${context.literature_review_summary}"`;
            break;
        case 4:
            basePrompt += `Design technical methodology for: "${context.hypothesis}"`;
            break;
        case 5:
            basePrompt += `Create data collection protocol for: "${context.methodology_summary}"`;
            break;
        case 6:
            basePrompt += `Synthesize raw CSV data for methodology: "${context.methodology_summary}"`;
            break;
        case 7:
            expectJson = true;
            basePrompt += `Analyze the following CSV data: "${userInput}". Verify hypothesis "${context.hypothesis}". Return JSON summary and charts.`;
            config.responseMimeType = "application/json";
            config.responseSchema = DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
            break;
        case 8:
            basePrompt += `Draw conclusions from analysis: "${context.analysis_summary}"`;
            break;
        case 9:
            basePrompt += `Perform adversarial peer review of project log:\n\n${context.full_project_summary_log}`;
            break;
        case 10:
            basePrompt += `Draft comprehensive technical publication from project archive:\n\n${context.full_project_summary_log}`;
            break;
        default:
            basePrompt += `Continue synthesis for Step ${stepId}`;
    }

    return { basePrompt, expectJson, config };
};

export const runLiteratureReviewAgent = async ({ experiment, updateLog }) => {
    updateLog('Hypatia', 'Indexing global research nodes...');
    const context = await getStepContext(experiment, 2);
    const { basePrompt, config } = getPromptForStep(2, '', context, {});
    return await executeStepWorkflow('gemini-3-flash-preview', { contents: basePrompt, config }, context);
};

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }) => {
    updateLog('Hypatia', 'Commencing agentic statistical modeling...');
    const context = await getStepContext(experiment, 7);
    const { basePrompt, config } = getPromptForStep(7, csvData, context, {});
    const finalOutput = await executeStepWorkflow('gemini-3-flash-preview', { contents: basePrompt, config }, context, true, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA);
    return { finalOutput, logSummary: "Agentic statistical analysis complete. Visualization nodes synthesized from raw experimental data." };
};

export const runPeerReviewAgent = async ({ experiment, updateLog }) => {
    updateLog('Hypatia', 'Engaging adversary critique protocol...');
    const context = await getStepContext(experiment, 9);
    const { basePrompt, config } = getPromptForStep(9, '', context, {});
    return await executeStepWorkflow('gemini-3-pro-preview', { contents: basePrompt, config }, context);
};

export const runPublicationAgent = async ({ experiment, updateLog }) => {
    updateLog('Hypatia', 'Synthesizing technical manuscript draft...');
    const context = await getStepContext(experiment, 10);
    const { basePrompt, config } = getPromptForStep(10, '', context, {});
    return await executeStepWorkflow('gemini-3-pro-preview', { 
        contents: basePrompt, 
        config: { ...config, thinkingConfig: { thinkingBudget: 8000 }, maxOutputTokens: 16000 }
    }, context);
};

import React, { useState, useMemo } from 'react';
import { useExperiment } from '../../services';
import { Experiment } from '../../config';
import { ExperimentCard } from '../steps/ExperimentCard';
import { DeployModal } from './DeployModal';

export const Dashboard = ({ setView }) => {
    const { experiments, selectExperiment, deleteExperiment, updateExperiment, importExperiment, isAuthenticated } = useExperiment();
    const [showDeployModal, setShowDeployModal] = useState(false);
    const [selectedExperiment, setSelectedExperiment] = useState<Experiment | null>(null);

    const activeExperiments = useMemo(() => experiments.filter(e => !e.status || e.status === 'active'), [experiments]);
    const archivedExperiments = useMemo(() => experiments.filter(e => e.status === 'archived'), [experiments]);

    const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if(file) {
            const reader = new FileReader();
            reader.onload = (e) => {
                try {
                    const imported = JSON.parse(e.target.result as string);
                    importExperiment(imported);
                } catch (err) {
                    alert("Failed to parse experiment file. Is it a valid JSON export?");
                }
            };
            reader.readAsText(file);
        }
    };

    const handleExport = (experiment: Experiment) => {
        const dataStr = JSON.stringify(experiment, null, 2);
        const blob = new Blob([dataStr], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `hypatia_export_${experiment.id}.json`;
        link.click();
        URL.revokeObjectURL(url);
    };

    const handleDeployClick = (experiment: Experiment) => {
        setSelectedExperiment(experiment);
        setShowDeployModal(true);
    };

    const handleArchive = async (exp: Experiment) => {
        if (window.confirm("Move this project to saved storage? It will be accessible from the 'Saved Projects' section.")) {
            await updateExperiment({ ...exp, status: 'archived' });
        }
    };

    const handleUnarchive = async (exp: Experiment) => {
        await updateExperiment({ ...exp, status: 'active' });
    };

    return (
        <div className="container py-4">
            <div className="d-flex justify-content-between align-items-center mb-5">
                <div>
                    <h2 className="section-title mb-0 fw-bold">Research Dashboard</h2>
                    <p className="text-white-50 mb-0">Monitor and manage your active discovery nodes.</p>
                </div>
                <div className="d-flex gap-2">
                     <label className="btn btn-outline-secondary">
                        <i className="bi bi-upload me-1"></i> Import
                        <input type="file" accept=".json" onChange={handleFileImport} style={{display: 'none'}} />
                    </label>
                    <button className="btn btn-primary shadow" onClick={() => setView('landing')}>
                        <i className="bi bi-plus-lg me-1"></i> New Project
                    </button>
                </div>
            </div>

            {activeExperiments.length === 0 && archivedExperiments.length === 0 && (
                 <div className="text-center p-5 dashboard-empty-state card border-dashed">
                    <i className="bi bi-journal-plus text-primary-glow" style={{fontSize: '3rem'}}></i>
                    <h4 className="mt-3 fw-bold">Initialize Your First Study</h4>
                    <p className="text-white-50 mx-auto" style={{maxWidth: '400px'}}>No research projects detected in local archival storage. Start a new discovery journey to begin.</p>
                    <button className="btn btn-primary mt-3 px-4" onClick={() => setView('landing')}>Create Project</button>
                </div>
            )}

            {activeExperiments.length > 0 ? (
                <div className="row g-4 mb-5">
                    {activeExperiments.map(exp => (
                        <ExperimentCard 
                            key={exp.id} 
                            exp={exp} 
                            onArchive={handleArchive} 
                            onUnarchive={handleUnarchive} 
                            deleteExperiment={deleteExperiment} 
                            selectExperiment={selectExperiment} 
                            handleDeployClick={handleDeployClick} 
                            handleExport={handleExport} 
                        />
                    ))}
                </div>
            ) : experiments.length > 0 && (
                <div className="alert alert-dark border-secondary border-opacity-25 bg-black bg-opacity-20 text-center mb-5 p-4">
                    <i className="bi bi-info-circle me-2"></i> All projects are currently archived.
                </div>
            )}

            {archivedExperiments.length > 0 && (
                <div className="mt-5 pt-5 border-top border-secondary border-opacity-10">
                    <div className="d-flex align-items-center mb-4">
                        <i className="bi bi-archive-fill text-muted me-3 fs-4"></i>
                        <h3 className="section-title mb-0 text-white-50">Saved Projects</h3>
                    </div>
                    <div className="row g-4">
                        {archivedExperiments.map(exp => (
                            <ExperimentCard 
                                key={exp.id} 
                                exp={exp} 
                                isArchived={true} 
                                onArchive={handleArchive} 
                                onUnarchive={handleUnarchive} 
                                deleteExperiment={deleteExperiment} 
                                selectExperiment={selectExperiment} 
                                handleDeployClick={handleDeployClick} 
                                handleExport={handleExport} 
                            />
                        ))}
                    </div>
                </div>
            )}

            {showDeployModal && selectedExperiment && (
                <DeployModal
                    experiment={selectedExperiment}
                    onClose={() => setShowDeployModal(false)}
                    onUpdateExperiment={updateExperiment}
                    onExportExperiment={handleExport}
                    isAuthenticated={isAuthenticated}
                />
            )}
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { UniquenessMeter } from './UniquenessMeter';
import { DataAnalysisView } from './DataAnalysisView';
import { extractJson } from '../../services';

interface GeneratedOutputProps {
    stepId: number;
    onGenerate: (feedback?: string) => Promise<void>;
    isLoading: boolean;
    streamingText?: string | null;
}

export const GeneratedOutput: React.FC<GeneratedOutputProps> = ({ 
    stepId, 
    onGenerate, 
    isLoading, 
    streamingText 
}) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();

    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState('');
    const [showRegenInput, setShowRegenInput] = useState(false);
    const [regenFeedback, setRegenFeedback] = useState('');

    const stepData = activeExperiment.stepData[stepId] || {};
    const savedOutput = stepData.output || '';

    const currentText = streamingText !== null ? streamingText : savedOutput;

    useEffect(() => {
        setEditText(savedOutput);
    }, [savedOutput]);

    const handleSave = () => {
        updateExperiment({ 
            ...activeExperiment, 
            stepData: { 
                ...activeExperiment.stepData, 
                [stepId]: { ...stepData, output: editText } 
            } 
        });
        setIsEditing(false);
        addToast("Archive node updated.", "success");
    };

    const handleLaunch = () => {
        if (isLoading) return;
        onGenerate();
    };

    const handleRegenerate = () => {
        if (isLoading) return;
        onGenerate(regenFeedback);
        setShowRegenInput(false);
        setRegenFeedback('');
    };

    const renderedHtml = useMemo(() => {
        if (!currentText) return '';
        // Skip math rendering while loading to avoid thread blocking
        return renderMarkdown(currentText, !isLoading);
    }, [currentText, isLoading]);

    const renderJsonContent = (text: string) => {
        try {
            const clean = extractJson(text);
            const data = JSON.parse(clean);

            if (stepId === 1) {
                return (
                   <div>
                       <div className="mb-4" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.research_question || '', true) }} />
                       {data.uniqueness_score !== undefined && (
                           <UniquenessMeter 
                                score={data.uniqueness_score} 
                                justification={data.justification || ''} 
                           />
                       )}
                   </div>
               );
            }
            if (stepId === 7) return <DataAnalysisView analysisData={data} />;
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        } catch (e) {
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        }
    };

    if (isLoading && !currentText) {
        return (
            <div className="text-center p-5 border border-primary border-opacity-10 rounded-4 bg-black bg-opacity-10 mt-2">
                 <div className="spinner-border mb-3 text-primary-glow" role="status"></div>
                <h5 className="fw-bold text-primary-glow">Hypatia is calculating...</h5>
                <p className="text-white-50 small mb-0">Performing multi-agent synthesis and forensic verification.</p>
            </div>
        );
    }

    if (!currentText && !isLoading) {
        return (
            <div className="text-center p-5 border border-secondary border-opacity-10 rounded-4 mt-2">
                <i className="bi bi-cpu-fill mb-3 opacity-20" style={{ fontSize: '3rem' }}></i>
                <p className="text-white-50 mb-4 px-4">
                    {stepId === 1 
                        ? "Hypatia needs to refine your initial idea into a formal research question and uniqueness profile." 
                        : "Archive node idle. Data synthesis required."}
                </p>
                <button 
                    className="btn btn-primary btn-lg px-5 shadow" 
                    onClick={handleLaunch}
                    disabled={isLoading}
                >
                    <i className={`bi ${stepId === 1 ? 'bi-stars' : 'bi-rocket-takeoff-fill'} me-2`}></i> 
                    {stepId === 1 ? "Formulate Research Question" : "Launch AI Synthesis"}
                </button>
            </div>
        );
    }

    const isJsonStep = stepId === 1 || stepId === 7;

    return (
        <div className="generated-content-container position-relative mt-2">
            {!isLoading && !isEditing && (
                <div className="d-flex justify-content-end gap-2 mb-3">
                    <button className="btn btn-sm btn-outline-secondary" onClick={() => setShowRegenInput(p => !p)} title="Regenerate">
                        <i className="bi bi-arrow-clockwise"></i>
                    </button>
                    <button className="btn btn-sm btn-outline-secondary" onClick={() => { setIsEditing(true); setEditText(savedOutput); }} title="Edit">
                        <i className="bi bi-pencil-square"></i>
                    </button>
                </div>
            )}

            {showRegenInput && (
                <div className="input-group mb-4 shadow-sm">
                    <span className="input-group-text bg-dark border-secondary text-white-50"><i className="bi bi-chat-left-dots"></i></span>
                    <input 
                        type="text" 
                        className="form-control bg-dark text-white border-secondary" 
                        placeholder="Provide feedback for reconstruction..." 
                        value={regenFeedback} 
                        onChange={e => setRegenFeedback(e.target.value)} 
                    />
                    <button className="btn btn-primary px-4" onClick={handleRegenerate} disabled={isLoading}>REGENERATE</button>
                </div>
            )}

            {isEditing ? (
                <div className="edit-view card bg-black border-secondary p-3">
                    <textarea 
                        className="form-control font-monospace bg-dark text-white border-secondary mb-3" 
                        style={{ minHeight: '400px' }} 
                        value={editText} 
                        onChange={(e) => setEditText(e.target.value)} 
                    />
                    <div className="d-flex gap-2 justify-content-end">
                        <button className="btn btn-outline-secondary" onClick={() => setIsEditing(false)}>Cancel</button>
                        <button className="btn btn-success px-4" onClick={handleSave}><i className="bi bi-save me-2"></i>Save Changes</button>
                    </div>
                </div>
            ) : (
                <div className="rendered-view">
                    {isJsonStep && !isLoading ? renderJsonContent(currentText) : <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderedHtml }} />}

                    {isLoading && (
                        <div className="mt-5 pt-3 border-top border-secondary border-opacity-10 text-center">
                            <div className="spinner-grow spinner-grow-sm text-primary-glow me-2" role="status"></div>
                            <span className="small text-white-50 font-monospace">DECODING ARCHIVE STREAM...</span>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
