import React, { useState, useEffect, useMemo } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { 
    parseGeminiError, 
    getStepContext, 
    getPromptForStep, 
    executeStepWorkflow, 
    callGeminiStreamWithRetry,
    refineWithSubjectExpert
} from '../../services';
import { WORKFLOW_STEPS, RESEARCH_QUESTION_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, LITERATURE_REVIEW_SCHEMA } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();

    // Local UI State
    const [activeStep, setActiveStep] = useState(activeExperiment?.currentStep || 1);
    const [isLoading, setIsLoading] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);

    const [streamingText, setStreamingText] = useState<string | null>(null);

    // Sync activeStep with experiment progress if they diverge
    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading) {
            setActiveStep(activeExperiment.currentStep);
        }
    }, [activeExperiment?.currentStep, isLoading, activeStep]);

    if (!activeExperiment) return null;

    const handleStepChange = (stepId: number) => {
        if (stepId <= activeExperiment.currentStep && !isLoading) {
            setStreamingText(null);
            setActiveStep(stepId);
        }
    };

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading) return;

        setStreamingText(null);
        setIsLoading(true);

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            const fineTuneSettings = activeExperiment.fineTuneSettings[activeStep] || {};
            const input = activeExperiment.stepData[activeStep]?.input || '';

            const { basePrompt, expectJson, config } = getPromptForStep(
                activeStep,
                input,
                context,
                fineTuneSettings,
                regenerateFeedback
            );

            if (expectJson) {
                let schemaToUse = undefined;
                if (activeStep === 1) schemaToUse = RESEARCH_QUESTION_SCHEMA;
                if (activeStep === 2) schemaToUse = LITERATURE_REVIEW_SCHEMA;
                if (activeStep === 7) schemaToUse = DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;

                const modelToUse = activeStep === 1 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

                const finalOutput = await executeStepWorkflow(
                    modelToUse, 
                    { contents: basePrompt, config }, 
                    context, 
                    true, 
                    schemaToUse
                );

                await updateExperiment({ 
                    ...activeExperiment, 
                    stepData: { 
                        ...activeExperiment.stepData, 
                        [activeStep]: { ...(activeExperiment.stepData[activeStep] || {}), output: finalOutput } 
                    } 
                });
                setStreamingText(null);
            } else {
                let accumulated = '';
                let lastUiUpdate = Date.now();
                const UI_UPDATE_INTERVAL = 1000; 

                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });

                for await (const chunk of stream) {
                    accumulated += (chunk.text || '');
                    const now = Date.now();
                    if (now - lastUiUpdate > UI_UPDATE_INTERVAL) {
                        setStreamingText(accumulated);
                        lastUiUpdate = now;
                    }
                }

                const refinedOutput = await refineWithSubjectExpert(accumulated, context);

                await updateExperiment({
                    ...activeExperiment,
                    stepData: {
                        ...activeExperiment.stepData,
                        [activeStep]: { ...(activeExperiment.stepData[activeStep] || {}), output: refinedOutput }
                    }
                });
                setStreamingText(null);
            }
            addToast("Node synthesis successful.", "success");
        } catch (error) {
            console.error("Synthesis error:", error);
            addToast(parseGeminiError(error), 'danger');
            setStreamingText(null);
        } finally {
            setIsLoading(false);
        }
    };

    const handleCompleteStep = async () => {
        if (isLoading) return;

        setIsLoading(true);
        try {
            const nextStep = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : WORKFLOW_STEPS.length + 1;
            await updateExperiment({ 
                ...activeExperiment, 
                stepData: { 
                    ...activeExperiment.stepData, 
                    [activeStep]: { ...(activeExperiment.stepData[activeStep] || {}), summary: "Node verified." } 
                }, 
                currentStep: nextStep 
            });
            setActiveStep(nextStep);
            setStreamingText(null);
            addToast("Progress archived.", "success");
        } catch (error) {
            addToast("Archival link failed.", 'danger');
        } finally {
            setIsLoading(false);
        }
    };

    const renderStepContent = () => {
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;

        const stepInfo = WORKFLOW_STEPS[activeStep - 1];
        if (!stepInfo) return <div className="p-4 text-center">Node offline.</div>;

        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} />;
        }

        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={handleCompleteStep} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={handleCompleteStep} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={handleCompleteStep} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={handleCompleteStep} />;
        if (activeStep === 10) return <PublicationExporter />;

        return (
            <div className="discovery-view">
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    const isStepVerificationVisible = activeStep <= WORKFLOW_STEPS.length && activeExperiment.automationMode !== 'automated';
    const hasOutput = !!activeExperiment.stepData[activeStep]?.output;

    return (
        <div className="workspace-container">
            <aside className="sidebar-nav">
                <div className="card shadow-sm mb-4 overflow-hidden">
                    <div className="card-header fw-bold bg-dark py-3">
                        <i className="bi bi-cpu-fill text-primary-glow me-2"></i>
                        PROJECT TIMELINE
                    </div>
                    <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                            <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                                style={{ cursor: step.id <= activeExperiment.currentStep ? 'pointer' : 'default' }}
                            >
                                <span className="small">{step.id}. {step.title}</span>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                </div>
            </aside>

            <main className="content-area">
                <div className="card shadow-sm">
                    <div className="card-body p-4" style={{ minHeight: '65vh' }}>
                        <div className="mb-4">
                            <div className="badge bg-primary mb-2">Step {activeStep}</div>
                            <h3 className="fw-bold mb-1">
                                {activeStep <= WORKFLOW_STEPS.length ? WORKFLOW_STEPS[activeStep - 1].title : 'Project Conclusion'}
                            </h3>
                            {activeStep <= WORKFLOW_STEPS.length && (
                                <p className="text-white-50 small mb-0">{WORKFLOW_STEPS[activeStep - 1].description}</p>
                            )}
                        </div>
                        <hr className="border-secondary opacity-10 mb-4" />
                        {renderStepContent()}
                    </div>

                    {isStepVerificationVisible && (
                        <div className="card-footer d-flex justify-content-between align-items-center p-3 bg-dark bg-opacity-50 border-top border-secondary border-opacity-25">
                            <button className="btn btn-sm btn-outline-secondary" onClick={() => setFineTuneModalOpen(true)} disabled={isLoading}>
                                <i className="bi bi-sliders me-1"></i> Tuning
                            </button>
                            <div className="d-flex align-items-center gap-3">
                                {isLoading && (
                                    <span className="small text-white-50 font-monospace">
                                        <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                                        SYNTHESIZING...
                                    </span>
                                )}
                                <button 
                                    className="btn btn-success px-4" 
                                    onClick={handleCompleteStep} 
                                    disabled={isLoading || !hasOutput}
                                >
                                    <i className={`bi ${hasOutput ? 'bi-check-circle-fill' : 'bi-lock-fill'} me-1`}></i> 
                                    {activeStep === 10 ? "Verify & Finish Project" : "Verify Node & Continue"}
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </main>

            {fineTuneModalOpen && (
                <FineTuneModal stepId={activeStep} onClose={() => setFineTuneModalOpen(false)} />
            )}
        </div>
    );
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
    CHART_JS_SCHEMA,
    VISUALIZATION_PLAN_SCHEMA,
} from './config';

// --- UTILITIES ---

/**
 * Extracts JSON from potential markdown or conversational noise.
 */
export const extractJson = (text: string): string => {
    if (!text) return "";
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');
    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

/**
 * Validates a string against a JSON schema.
 */
export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = extractJson(jsonStr);
        if (!cleanStr) return false;
        const data = JSON.parse(cleanStr);
        if (schema && schema.required) {
            return schema.required.every((key: string) => key in data && data[key] !== undefined);
        }
        return true;
    } catch (e) {
        return false;
    }
};

// --- GEMINI API SERVICE ---

export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    if (msg.includes("Requested entity was not found") || status === 403 || status === 404) {
        const aistudio = (window as any).aistudio;
        if (aistudio?.openSelectKey) {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

/**
 * Agent: Subject Expert
 * Refines the generated content for scientific rigor.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false,
    schema?: any
): Promise<string> => {
    if (!content) return content;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

    const systemInstruction = `You are a Senior Scientific Editor in ${context.experimentField}. 
    Review the provided ${isJson ? 'JSON data' : 'research text'}.
    1. Standardize terminology for academic publication.
    2. Maintain the exact same core information and logic.
    3. ${isJson ? 'CRITICAL: Output ONLY the refined JSON. Do not add any text before or after.' : 'Output Markdown only.'}`;

    const config: any = { 
        systemInstruction,
        temperature: 0.1 
    };

    if (isJson && schema) {
        config.responseMimeType = "application/json";
        config.responseSchema = schema;
    }

    try {
        const response = await ai.models.generateContent({
            model,
            contents: `Refine the following archival node content:\n\n${content}`,
            config
        });
        const refinedText = response.text || content;

        if (isJson && !isValidJsonForSchema(refinedText, schema)) {
            return extractJson(content);
        }

        return isJson ? extractJson(refinedText) : refinedText;
    } catch (e) {
        return isJson ? extractJson(content) : content;
    }
};

/**
 * Agentic JSON Loop: Repair Agent fixes malformed output.
 */
const agenticJsonFixLoop = async (
    invalidJson: string, 
    schema: any, 
    errorMsg: string
): Promise<string | null> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    for (let cycle = 1; cycle <= 2; cycle++) {
        try {
            const expertResponse = await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: `REPAIR AGENT: The following input failed JSON schema validation.
                Schema: ${JSON.stringify(schema)}. 
                Error: ${errorMsg}. 
                Corrupt Input: ${invalidJson}. 
                Output valid JSON that adheres strictly to the schema.`,
                config: { responseMimeType: "application/json", responseSchema: schema }
            });
            const fixed = extractJson(expertResponse.text || "");
            if (isValidJsonForSchema(fixed, schema)) return fixed;
        } catch (e) {}
    }
    return null;
};

/**
 * Main Orchestration Workflow.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    let output = "";
    let success = false;
    let lastError = "";

    // 1. Primary Generation
    for (let attempt = 1; attempt <= 2; attempt++) {
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            });
            output = response.text || "";

            // Handle Grounding Citations if present (only if NOT expecting JSON, or we append it at the end)
            const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
            if (!expectJson && groundingChunks && Array.isArray(groundingChunks)) {
                let citations = "\n\n### Grounding Citations\n";
                groundingChunks.forEach((chunk: any) => {
                    if (chunk.web && chunk.web.uri) {
                        citations += `- [${chunk.web.title || chunk.web.uri}](${chunk.web.uri})\n`;
                    }
                });
                output += citations;
            }

            if (expectJson) {
                if (isValidJsonForSchema(output, schema)) {
                    output = extractJson(output);
                    success = true;
                    break;
                }
                lastError = "Schema validation failed.";
            } else if (output.trim()) {
                success = true;
                break;
            }
        } catch (e: any) {
            lastError = e.message;
            if (attempt === 2) throw e;
            await new Promise(r => setTimeout(r, 1000 * attempt));
        }
    }

    if (expectJson && !success) {
        const fixed = await agenticJsonFixLoop(output, schema, lastError);
        if (fixed) {
            output = fixed;
            success = true;
        } else {
            throw new Error(`Archival node corruption: ${lastError}`);
        }
    }

    if (expectJson && success) return output;

    return await refineWithSubjectExpert(output, context, expectJson, schema);
};

export const callGeminiWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const context = { experimentField: 'Scientific Research' };
    const text = (await executeStepWorkflow(model, params, context));
    return { text };
};

export const callGeminiStreamWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        return await ai.models.generateContentStream({
            model: model,
            contents: params.contents,
            config: params.config
        });
    } catch (error: any) {
        const err = await handleApiError(error);
        if (err === "AUTH_RETRY_REQUIRED") throw new Error("Authentication re-sync required.");
        throw error;
    }
};

export const parseGeminiError = (error: any, fallback = "Hypatia link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync')) return "Archive link unstable: Please re-verify your project key.";
    if (msg.includes('safety')) return "Archive protocol block: content violates safety filters.";
    if (msg.includes('corruption')) return error.message;
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 500) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) projectLog += `[Phase ${i}] ${stepInfo.title}: ${getSummary(i)}\n\n`;
        }
        context.full_project_summary_log = projectLog.trim();
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    const settings = fineTuneSettings || {};
    let systemInstruction = `You are Hypatia, an advanced AI Scientific Researcher. Field: ${context.experimentField}.`;
    let basePrompt = "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.7 };

    if (regenerateFeedback) basePrompt += `[SYSTEM OVERRIDE: PI FEEDBACK: "${regenerateFeedback}"]\n\n`;

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `REFINE RESEARCH QUESTION. 
            Initial input: "${userInput}". 
            Task: Output a formal research question and uniqueness assessment based on RESEARCH_QUESTION_SCHEMA. 
            Requirement: Output ONLY valid JSON.`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            expectJson = true;
            basePrompt += `LITERATURE REVIEW PROTOCOL.
            Research Question: "${context.question}". 
            Task:
            1. Use Google Search to find high-impact peer-reviewed papers related to this question.
            2. Synthesize a comprehensive summary of findings and identify critical research gaps.
            3. Assemble a list of the MOST RELEVANT scientific references found.
            Format output as JSON adhering to LITERATURE_REVIEW_SCHEMA.
            Each reference MUST include: title, authors (array), year, journal, and url.
            Include ONLY existing, real papers found via grounding.`;
            config.tools = [{ googleSearch: {} }];
            config.responseMimeType = "application/json";
            config.responseSchema = LITERATURE_REVIEW_SCHEMA;
            break;
        case 3:
            basePrompt += `Formulate 3 distinct hypotheses for the research question: "${context.question}". Use the Literature Review summary as a foundation: "${context.literature_review_summary}"`;
            break;
        case 4:
            basePrompt += `Design a technical methodology for testing: "${context.hypothesis}"`;
            break;
        case 5:
            basePrompt += `Create a detailed data collection protocol for: "${context.methodology_summary}"`;
            break;
        case 6:
            basePrompt += `Synthesize raw CSV data for methodology: "${context.methodology_summary}"`;
            break;
        case 7:
            expectJson = true;
            basePrompt += `Analyze the following CSV data: "${userInput}". Verify hypothesis "${context.hypothesis}". Return JSON summary and charts.`;
            config.responseMimeType = "application/json";
            config.responseSchema = DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
            break;
        case 8:
            basePrompt += `Draw interpretation and conclusions from the analysis summary: "${context.analysis_summary}"`;
            break;
        case 9:
            basePrompt += `Perform an adversarial peer review of the project archive:\n\n${context.full_project_summary_log}`;
            break;
        case 10:
            basePrompt += `Draft a comprehensive technical publication based on the project log:\n\n${context.full_project_summary_log}`;
            break;
        default:
            basePrompt += `Continue synthesis for Step ${stepId}`;
    }

    return { basePrompt, expectJson, config };
};

export const runLiteratureReviewAgent = async ({ experiment, updateLog }) => {
    updateLog('Hypatia', 'Initializing research link...');
    const context = await getStepContext(experiment, 2);
    const { basePrompt, config } = getPromptForStep(2, '', context, {});
    updateLog('Hypatia', 'Querying global research indices via Google Search...');
    const rawOutput = await executeStepWorkflow('gemini-3-flash-preview', { contents: basePrompt, config }, context, true, LITERATURE_REVIEW_SCHEMA);
    updateLog('Hypatia', 'Synthesizing findings and assembling bibliography...');
    return rawOutput;
};

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }) => {
    updateLog('Hypatia', 'Commencing agentic statistical modeling...');
    const context = await getStepContext(experiment, 7);
    const { basePrompt, config } = getPromptForStep(7, csvData, context, {});
    const finalOutput = await executeStepWorkflow('gemini-3-flash-preview', { contents: basePrompt, config }, context, true, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA);
    return { finalOutput, logSummary: "Statistical analysis complete." };
};

export const runPeerReviewAgent = async ({ experiment, updateLog }) => {
    updateLog('Hypatia', 'Engaging adversary critique protocol...');
    const context = await getStepContext(experiment, 9);
    const { basePrompt, config } = getPromptForStep(9, '', context, {});
    return await executeStepWorkflow('gemini-3-pro-preview', { contents: basePrompt, config }, context);
};

export const runPublicationAgent = async ({ experiment, updateLog }) => {
    updateLog('Hypatia', 'Synthesizing technical manuscript draft...');
    const context = await getStepContext(experiment, 10);
    const { basePrompt, config } = getPromptForStep(10, '', context, {});
    return await executeStepWorkflow('gemini-3-pro-preview', { 
