import React, { useState, useEffect } from 'react';
import { Experiment } from './config';
import { db } from './be_db';
import { testApiKey, parseGeminiError } from './services';
import { useToast } from './toast';
import { ExperimentContext } from './context/ExperimentContext';

import { Header } from './components/common/Header';
import { Footer } from './components/common/Footer';
import { LandingPage } from './components/landing/LandingPage';
import { Dashboard } from './components/dashboard/Dashboard';
import { ExperimentWorkspace } from './components/workspace/ExperimentWorkspace';
import { TestRunner } from './components/testing/TestRunner';
import { LabNotebook } from './components/workspace/LabNotebook';

/**
 * @component App
 * The root component that manages the overall application state and routing.
 */
export const App = () => {
    const [view, setView] = useState('landing'); 
    const [experiments, setExperiments] = useState<Experiment[]>([]);
    const [activeExperiment, setActiveExperiment] = useState<Experiment | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [isLabNotebookOpen, setLabNotebookOpen] = useState(false);

    const { addToast } = useToast();

    useEffect(() => {
        const loadData = async () => {
            try {
                const storedExperiments = await db.experiments.orderBy('createdAt').reverse().toArray();
                setExperiments(storedExperiments);
                if (storedExperiments.length > 0) {
                    setActiveExperiment(storedExperiments[0]);
                }
            } catch (error) {
                console.error("Failed to load data:", error);
                addToast("Could not load saved experiments.", 'danger');
            } finally {
                setIsLoading(false);
            }
        };
        loadData();
    }, [addToast]);

    useEffect(() => {
        if (isAuthenticated && view === 'landing') {
             setTimeout(() => window.scrollTo({ top: 0, behavior: 'smooth' }), 100);
        }
    }, [isAuthenticated, view]);

    const handleAuthentication = async (type: 'promo' | 'key', value: string) => {
        const aistudio = (window as any).aistudio;
        const validPromoCodes = ['MTI', 'HYPATIA-ALPHA', 'PRO-ACCESS', 'HYPATIA-2025'];

        if (type === 'promo' && validPromoCodes.includes(value.toUpperCase())) {
            // Priority: Force key rotation via AI Studio dialog if available
            if (aistudio) {
                try {
                    addToast("Rotating archival link. Please select an active project...", 'info');
                    await aistudio.openSelectKey();
                    // We assume success after the dialog closes to prevent race conditions
                    setIsAuthenticated(true);
                    addToast("Archive Link Synchronized. Welcome, Researcher.", 'success');
                    return;
                } catch (e) {
                    console.error("AI Studio key selection failed", e);
                    addToast("Key selection failed. Please try again.", 'danger');
                    return;
                }
            }

            // Fallback for environments where aistudio is not injected
            if (process.env.API_KEY) {
                setIsAuthenticated(true);
                addToast("Authentication successful via Environment Link.", 'success');
                return;
            } else {
                addToast("Access credentials missing in local environment. Please use a Personal API Key.", 'danger');
                return;
            }
        }

        if (type === 'key' && value) {
            try {
                const isValid = await testApiKey(value);
                if (isValid) {
                    setIsAuthenticated(true);
                    addToast("API Key Verified. Welcome back.", 'success');
                } else {
                    addToast("The provided API key is not valid or has expired.", 'danger');
                }
            } catch (error) {
                addToast(parseGeminiError(error, "Authentication failed. The key is not valid."), 'danger');
            }
            return;
        }

        addToast("Invalid credentials. Please check your key or promo code.", 'warning');
    };

    const createNewExperiment = async (title: string, description: string, field: string) => {
        const newId = `exp_${Date.now()}`;
        const newExperiment: Experiment = {
            id: newId,
            title,
            description,
            field,
            currentStep: 1,
            stepData: {
                1: {
                    input: `Title: ${title}\n\nDescription: ${description}`,
                    history: [],
                    provenance: [],
                }
            },
            fineTuneSettings: {},
            createdAt: new Date().toISOString(),
            labNotebook: '',
            automationMode: null,
            status: 'active',
        };
        try {
            await db.experiments.add(newExperiment);
            setExperiments(prev => [newExperiment, ...prev]);
            setActiveExperiment(newExperiment);
            setView('experiment');
            addToast("New research project created successfully!", 'success');
        } catch (error) {
            console.error("Failed to save new experiment:", error);
            addToast("Failed to create project.", 'danger');
        }
    };

    const importExperiment = async (experimentData: Experiment) => {
        try {
            if (!experimentData.id || !experimentData.title || !experimentData.createdAt) {
                throw new Error("Invalid experiment file format.");
            }
            const existing = await db.experiments.get(experimentData.id);
            if(existing) {
                if(!window.confirm("An experiment with this ID already exists. Overwrite it?")) {
                    return;
                }
                await db.experiments.put(experimentData);
            } else {
                await db.experiments.add(experimentData);
            }
            const storedExperiments = await db.experiments.orderBy('createdAt').reverse().toArray();
            setExperiments(storedExperiments);
            addToast(`Project "${experimentData.title}" imported successfully!`, 'success');

        } catch(error) {
             addToast(`Failed to import project: ${error.message}`, 'danger');
        }
    }

    const updateExperiment = async (updatedExperiment: Experiment): Promise<Experiment> => {
        try {
            const experimentWithTimestamp = { ...updatedExperiment, updatedAt: new Date().toISOString() };
            await db.experiments.put(experimentWithTimestamp);
            setExperiments(prev => prev.map(e => e.id === experimentWithTimestamp.id ? experimentWithTimestamp : e));
            if (activeExperiment?.id === experimentWithTimestamp.id) {
                setActiveExperiment(experimentWithTimestamp);
            }
            return experimentWithTimestamp;
        } catch (error) {
            console.error("Failed to update experiment:", error);
            addToast("Failed to save progress.", 'danger');
            throw error;
        }
    };

    const deleteExperiment = async (id: string) => {
        if (window.confirm("Are you sure you want to delete this project?")) {
            try {
                await db.experiments.delete(id);
                const updatedExperiments = experiments.filter(e => e.id !== id);
                setExperiments(updatedExperiments);
                if (activeExperiment?.id === id) {
                    setActiveExperiment(updatedExperiments.length > 0 ? updatedExperiments[0] : null);
                    if(updatedExperiments.length > 0) {
                        setView('dashboard');
                    } else {
                        setView('landing');
                    }
                }
                addToast("Project deleted.", 'success');
            } catch (error) {
                console.error("Failed to delete experiment:", error);
                addToast("Failed to delete project.", 'danger');
            }
        }
    };

    const selectExperiment = (id: string) => {
        const experiment = experiments.find(e => e.id === id);
        if (experiment) {
            setActiveExperiment(experiment);
            setView('experiment');
        }
    };

    const contextValue = {
        experiments,
        activeExperiment,
        isAuthenticated,
        createNewExperiment,
        updateExperiment,
        deleteExperiment,
        selectExperiment,
        setActiveExperiment,
        importExperiment,
        handleAuthentication,
    };

    if (isLoading) {
        return (
            <div className="d-flex flex-column justify-content-center align-items-center vh-100 bg-dark text-white">
                <div className="spinner-border text-primary mb-3" role="status"></div>
                <div className="font-monospace small">BOOTING HYPATIA CORE...</div>
            </div>
        );
    }

    return (
        <ExperimentContext.Provider value={contextValue}>
            <Header setView={setView} activeView={view} onToggleNotebook={() => setLabNotebookOpen(p => !p)} />
            <main className="container-fluid mt-4">
                {view === 'landing' && <LandingPage setView={setView} />}
                {view === 'dashboard' && <Dashboard setView={setView} />}
                {view === 'experiment' && activeExperiment && <ExperimentWorkspace key={activeExperiment.id} />}
                {view === 'testing' && <TestRunner />}
            </main>
            {activeExperiment && isAuthenticated && (
                <LabNotebook 
                    isOpen={isLabNotebookOpen} 
                    onClose={() => setLabNotebookOpen(false)}
                />
            )}
            <Footer />
        </ExperimentContext.Provider>
    );
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
    CHART_JS_SCHEMA,
    VISUALIZATION_PLAN_SCHEMA,
} from './config';

// --- UTILITIES ---

/**
 * Extracts JSON from potential markdown or conversational noise.
 */
export const extractJson = (text: string): string => {
    if (!text) return "";
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');
    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

/**
 * Validates a string against a JSON schema.
 */
export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = extractJson(jsonStr);
        if (!cleanStr) return false;
        const data = JSON.parse(cleanStr);
        if (schema && schema.required) {
            return schema.required.every((key: string) => key in data && data[key] !== undefined);
        }
        return true;
    } catch (e) {
        return false;
    }
};

// --- GEMINI API SERVICE ---

export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

/**
 * Diagnostic handler for API failures.
 * Triggers key rotation if the current project/key is invalid or has reached billing limits.
 */
const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    // Check for common permission/identity errors that require key rotation
    if (msg.includes("Requested entity was not found") || msg.includes("API_KEY_INVALID") || status === 403 || status === 404) {
        const aistudio = (window as any).aistudio;
        if (aistudio?.openSelectKey) {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

/**
 * Agent: Subject Expert
 * Refines the generated content for scientific rigor.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false,
    schema?: any
): Promise<string> => {
    if (!content) return content;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

    const systemInstruction = `You are a Senior Scientific Editor in ${context.experimentField}. 
    Review the provided ${isJson ? 'JSON data' : 'research text'}.
    1. Standardize terminology for academic publication.
    2. Maintain the exact same core information and logic.
    3. ${isJson ? 'CRITICAL: Output ONLY the refined JSON. Do not add any text before or after.' : 'Output Markdown only.'}`;

    const config: any = { 
        systemInstruction,
        temperature: 0.1 
    };

    if (isJson && schema) {
        config.responseMimeType = "application/json";
        config.responseSchema = schema;
    }

    try {
        const response = await ai.models.generateContent({
            model,
            contents: `Refine the following archival node content:\n\n${content}`,
            config
        });
        const refinedText = response.text || content;

        if (isJson && !isValidJsonForSchema(refinedText, schema)) {
            return extractJson(content);
        }

        return isJson ? extractJson(refinedText) : refinedText;
    } catch (e) {
        await handleApiError(e);
        return isJson ? extractJson(content) : content;
    }
};

/**
 * Agentic JSON Loop: Repair Agent fixes malformed output.
 */
const agenticJsonFixLoop = async (
    invalidJson: string, 
    schema: any, 
    errorMsg: string
): Promise<string | null> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    for (let cycle = 1; cycle <= 2; cycle++) {
        try {
            const expertResponse = await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: `REPAIR AGENT: The following input failed JSON schema validation.
                Schema: ${JSON.stringify(schema)}. 
                Error: ${errorMsg}. 
                Corrupt Input: ${invalidJson}. 
                Output valid JSON that adheres strictly to the schema.`,
                config: { responseMimeType: "application/json", responseSchema: schema }
            });
            const fixed = extractJson(expertResponse.text || "");
            if (isValidJsonForSchema(fixed, schema)) return fixed;
        } catch (e) {
            await handleApiError(e);
        }
    }
    return null;
};

/**
 * Main Orchestration Workflow.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    let output = "";
    let success = false;
    let lastError = "";

    // 1. Primary Generation
    for (let attempt = 1; attempt <= 2; attempt++) {
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            });
            output = response.text || "";

            // Handle Grounding Citations if present
            const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
            if (!expectJson && groundingChunks && Array.isArray(groundingChunks)) {
                let citations = "\n\n### Grounding Citations\n";
                groundingChunks.forEach((chunk: any) => {
                    if (chunk.web && chunk.web.uri) {
                        citations += `- [${chunk.web.title || chunk.web.uri}](${chunk.web.uri})\n`;
                    }
                });
                output += citations;
            }

            if (expectJson) {
                if (isValidJsonForSchema(output, schema)) {
                    output = extractJson(output);
                    success = true;
                    break;
                }
                lastError = "Schema validation failed.";
            } else if (output.trim()) {
                success = true;
                break;
            }
        } catch (e: any) {
            lastError = e.message;
            const errStatus = await handleApiError(e);
            if (errStatus === "AUTH_RETRY_REQUIRED") throw new Error("Authentication re-sync required.");
            if (attempt === 2) throw e;
            await new Promise(r => setTimeout(r, 1000 * attempt));
        }
    }

    if (expectJson && !success) {
        const fixed = await agenticJsonFixLoop(output, schema, lastError);
        if (fixed) {
            output = fixed;
            success = true;
        } else {
            throw new Error(`Archival node corruption: ${lastError}`);
        }
    }

    if (expectJson && success) return output;

    return await refineWithSubjectExpert(output, context, expectJson, schema);
};

export const callGeminiWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const context = { experimentField: 'Scientific Research' };
    const text = (await executeStepWorkflow(model, params, context));
    return { text };
};

export const callGeminiStreamWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        return await ai.models.generateContentStream({
            model: model,
            contents: params.contents,
            config: params.config
        });
    } catch (error: any) {
        const err = await handleApiError(error);
        if (err === "AUTH_RETRY_REQUIRED") throw new Error("Authentication re-sync required.");
        throw error;
    }
};

export const parseGeminiError = (error: any, fallback = "Hypatia link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync')) return "Archive link unstable: Please re-verify your project key via the system menu.";
    if (msg.includes('safety')) return "Archive protocol block: content violates safety filters.";
    if (msg.includes('corruption')) return error.message;
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 500) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) projectLog += `[Phase ${i}] ${stepInfo.title}: ${getSummary(i)}\n\n`;
        }
        context.full_project_summary_log = projectLog.trim();
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
