import React, { useState, useEffect, useMemo } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { UniquenessMeter } from './UniquenessMeter';
import { DataAnalysisView } from './DataAnalysisView';
import { extractJson } from '../../services';

interface GeneratedOutputProps {
    stepId: number;
    onGenerate: (feedback?: string) => Promise<void>;
    isLoading: boolean;
    streamingText?: string | null;
}

export const GeneratedOutput: React.FC<GeneratedOutputProps> = ({ 
    stepId, 
    onGenerate, 
    isLoading, 
    streamingText 
}) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();

    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState('');
    const [showRegenInput, setShowRegenInput] = useState(false);
    const [regenFeedback, setRegenFeedback] = useState('');

    const stepData = activeExperiment.stepData[stepId] || {};
    const savedOutput = stepData.output || '';

    const currentText = streamingText !== null ? streamingText : savedOutput;

    useEffect(() => {
        setEditText(savedOutput);
    }, [savedOutput]);

    const handleSave = () => {
        updateExperiment({ 
            ...activeExperiment, 
            stepData: { 
                ...activeExperiment.stepData, 
                [stepId]: { ...stepData, output: editText } 
            } 
        });
        setIsEditing(false);
        addToast("Archive node updated.", "success");
    };

    const handleLaunch = () => {
        if (isLoading) return;
        onGenerate();
    };

    const handleRegenerate = () => {
        if (isLoading) return;
        onGenerate(regenFeedback);
        setShowRegenInput(false);
        setRegenFeedback('');
    };

    const renderedHtml = useMemo(() => {
        if (!currentText) return '';
        return renderMarkdown(currentText, !isLoading);
    }, [currentText, isLoading]);

    const renderJsonContent = (text: string) => {
        try {
            const clean = extractJson(text);
            const data = JSON.parse(clean);

            if (stepId === 1) {
                return (
                   <div>
                       <div className="mb-4" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.research_question || '', true) }} />
                       {data.uniqueness_score !== undefined && (
                           <UniquenessMeter 
                                score={data.uniqueness_score} 
                                justification={data.justification || ''} 
                           />
                       )}
                   </div>
               );
            }

            if (stepId === 2) {
                return (
                    <div className="lit-review-output">
                        <section className="mb-4">
                            <h5 className="fw-bold text-primary-glow border-bottom border-secondary border-opacity-25 pb-2 mb-3">Synthesis of Findings</h5>
                            <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.summary || '', true) }} />
                        </section>

                        {data.research_gaps && (
                            <section className="mb-4">
                                <h5 className="fw-bold text-warning border-bottom border-secondary border-opacity-25 pb-2 mb-3">Identified Research Gaps</h5>
                                <div className="p-3 bg-dark bg-opacity-25 rounded-3 border border-warning border-opacity-10" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.research_gaps, true) }} />
                            </section>
                        )}

                        {data.references && Array.isArray(data.references) && data.references.length > 0 && (
                            <section>
                                <h5 className="fw-bold text-info border-bottom border-secondary border-opacity-25 pb-2 mb-3">Bibliography & Grounding Links</h5>
                                <div className="list-group list-group-flush bg-transparent">
                                    {data.references.map((ref: any, i: number) => (
                                        <div key={i} className="list-group-item bg-transparent border-secondary border-opacity-10 px-0 py-3">
                                            <div className="d-flex align-items-start">
                                                <div className="badge bg-secondary bg-opacity-10 text-secondary me-3 mt-1">[{i + 1}]</div>
                                                <div className="flex-grow-1">
                                                    <div className="fw-bold text-white mb-1">{ref.title}</div>
                                                    <div className="small text-white-50">
                                                        {ref.authors?.join(', ')} ({ref.year}). <em>{ref.journal || 'Research Publication'}</em>.
                                                    </div>
                                                    {ref.url && (
                                                        <a href={ref.url} target="_blank" rel="noopener noreferrer" className="btn btn-sm btn-link text-primary-glow p-0 mt-1">
                                                            <i className="bi bi-link-45deg me-1"></i> View Source Archive
                                                        </a>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </section>
                        )}
                    </div>
                );
            }

            if (stepId === 7) return <DataAnalysisView analysisData={data} />;
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        } catch (e) {
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        }
    };

    if (!currentText && !isLoading) {
        return (
            <div className="text-center p-4 border border-secondary border-opacity-10 rounded-3 mt-2 bg-dark bg-opacity-10">
                <i className="bi bi-cpu mb-3 opacity-20 d-block" style={{ fontSize: '2rem' }}></i>
                <p className="text-white-50 small mb-4 px-4">
                    {stepId === 1 
                        ? "Protocol ready to refine research question into a verifiable archival node." 
                        : "Archival node idle. Select synthesis protocol to proceed."}
                </p>
                <button 
                    className="btn btn-primary px-4 shadow-sm" 
                    onClick={handleLaunch}
                    disabled={isLoading}
                >
                    <i className={`bi ${stepId === 1 ? 'bi-stars' : 'bi-lightning-fill'} me-2`}></i> 
                    {stepId === 1 ? "Synthesize Research Question" : "Launch Archival Link"}
                </button>
            </div>
        );
    }

    if (isLoading && !currentText) {
        return (
            <div className="text-center p-5 mt-2">
                 <div className="spinner-border mb-3 text-primary-glow" role="status"></div>
                <h5 className="fw-bold text-primary-glow small text-uppercase ls-1">Decoding Archive...</h5>
                <p className="text-white-50 small mb-0">Bridging discovery nodes via frontier synthesis.</p>
            </div>
        );
    }

    const isJsonStep = stepId === 1 || stepId === 2 || stepId === 7;

    return (
        <div className="generated-content-container position-relative mt-2">
            {!isLoading && !isEditing && (
                <div className="d-flex justify-content-end gap-2 mb-3">
                    <button className="btn btn-sm btn-outline-secondary" onClick={() => setShowRegenInput(p => !p)} title="Regenerate">
                        <i className="bi bi-arrow-clockwise"></i>
                    </button>
                    <button className="btn btn-sm btn-outline-secondary" onClick={() => { setIsEditing(true); setEditText(savedOutput); }} title="Edit">
                        <i className="bi bi-pencil-square"></i>
                    </button>
                </div>
            )}

            {showRegenInput && (
                <div className="input-group mb-4 shadow-sm">
                    <span className="input-group-text bg-dark border-secondary text-white-50"><i className="bi bi-chat-left-dots"></i></span>
                    <input 
                        type="text" 
                        className="form-control bg-dark text-white border-secondary" 
                        placeholder="Provide feedback for reconstruction..." 
                        value={regenFeedback} 
                        onChange={e => setRegenFeedback(e.target.value)} 
                    />
                    <button className="btn btn-primary px-4" onClick={handleRegenerate} disabled={isLoading}>REGENERATE</button>
                </div>
            )}

            {isEditing ? (
                <div className="edit-view card bg-black border-secondary p-3">
                    <textarea 
                        className="form-control font-monospace bg-dark text-white border-secondary mb-3" 
                        style={{ minHeight: '400px' }} 
                        value={editText} 
                        onChange={(e) => setEditText(e.target.value)} 
                    />
                    <div className="d-flex gap-2 justify-content-end">
                        <button className="btn btn-outline-secondary" onClick={() => setIsEditing(false)}>Cancel</button>
                        <button className="btn btn-success px-4" onClick={handleSave}><i className="bi bi-save me-2"></i>Save Changes</button>
                    </div>
                </div>
            ) : (
                <div className="rendered-view">
                    {isJsonStep && !isLoading ? renderJsonContent(currentText) : <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderedHtml }} />}

                    {isLoading && (
                        <div className="mt-5 pt-3 border-top border-secondary border-opacity-10 text-center">
                            <div className="spinner-grow spinner-grow-sm text-primary-glow me-2" role="status"></div>
                            <span className="small text-white-50 font-monospace">DECODING ARCHIVE STREAM...</span>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { runLiteratureReviewAgent, parseGeminiError } from '../../services';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { AgenticAnalysisView } from '../common/AgenticAnalysisView';

export const LiteratureReviewWorkspace = ({ onStepComplete }) => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();
    const [agenticRun, setAgenticRun] = useState({
        status: 'idle', // 'idle', 'running', 'success', 'failed'
        iterations: 0,
        maxIterations: 5, 
        logs: [],
    });

    const isMounted = useRef(true);
    useEffect(() => () => { isMounted.current = false; }, []);

    const stepData = activeExperiment.stepData[2] || {};

    const performAgenticReview = useCallback(async () => {
        if (!isAuthenticated) {
            addToast("Gemini not available. Please check authentication.", "danger");
            return;
        }

        if (agenticRun.status === 'running') return;

        setAgenticRun(prev => ({ ...prev, status: 'running', logs: [], iterations: 0 }));

        try {
            const finalDoc = await runLiteratureReviewAgent({
                experiment: activeExperiment,
                updateLog: (agent, message) => {
                    if (isMounted.current) {
                        setAgenticRun(prev => ({ 
                            ...prev, 
                            logs: [...prev.logs, { agent, message }],
                            iterations: agent === 'Hypatia' && message.includes('indices') ? prev.iterations + 1 : prev.iterations
                        }));
                    }
                }
            });

            if (!isMounted.current) return;

            const finalStepData = { ...stepData, output: finalDoc };
            await updateExperiment({ ...activeExperiment, stepData: { ...activeExperiment.stepData, 2: finalStepData } });

            setAgenticRun(prev => ({ ...prev, status: 'success' }));
            addToast("Literature review complete!", "success");

            // Auto-advance in automated mode
            if (activeExperiment.automationMode === 'automated') {
                setTimeout(() => {
                    if (isMounted.current) onStepComplete();
                }, 1500);
            }

        } catch (error) {
            if (!isMounted.current) return;
            console.error("Literature Review error:", error);
            const errorMessage = parseGeminiError(error, "Agentic literature review failed.");
            addToast(errorMessage, 'danger');
            setAgenticRun(prev => ({ 
                ...prev, 
                status: 'failed',
                logs: [...prev.logs, { agent: 'System', message: `ERROR: ${errorMessage}` }]
            }));
        }

    }, [activeExperiment, isAuthenticated, addToast, updateExperiment, stepData, agenticRun.status, onStepComplete]);

    useEffect(() => {
        // Auto-trigger only if idle and no data
        if (!stepData.output && agenticRun.status === 'idle') {
            performAgenticReview();
        }
    }, [stepData.output, agenticRun.status, performAgenticReview]); 

    if (agenticRun.status === 'running') {
        return (
            <div className="p-2">
                <AgenticAnalysisView agenticRun={agenticRun} subtitle="Synthesizing archival research via Google Search grounding." />
                <div className="text-center mt-3">
                    <button className="btn btn-sm btn-outline-danger" onClick={() => setAgenticRun(prev => ({ ...prev, status: 'idle' }))}>
                        Abort & Reset Synthesis
                    </button>
                </div>
            </div>
        );
    }

    if (agenticRun.status === 'failed' && !stepData.output) {
        return (
            <div className="text-center p-5">
                <i className="bi bi-exclamation-triangle text-danger fs-1 mb-3 opacity-50"></i>
                <h5 className="fw-bold">Synthesis Failure</h5>
                <p className="text-white-50 small mb-4">The research link encountered a synchronization error.</p>
                <button className="btn btn-primary px-4" onClick={performAgenticReview}>
                    <i className="bi bi-arrow-clockwise me-2"></i> Retry Research Link
                </button>
                <div className="mt-4 text-start">
                    <AgenticAnalysisView agenticRun={agenticRun} title="Diagnostic Log" subtitle="Failure analysis." />
                </div>
            </div>
        );
    }

    return (
        <div className="lit-review-container">
            <GeneratedOutput 
                stepId={2} 
                onGenerate={performAgenticReview} 
                isLoading={agenticRun.status === 'running'} 
            />
        </div>
    );
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
    CHART_JS_SCHEMA,
    VISUALIZATION_PLAN_SCHEMA,
} from './config';

// --- UTILITIES ---

/**
 * Extracts JSON from potential markdown or conversational noise.
 */
export const extractJson = (text: string): string => {
    if (!text) return "";
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');
    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

/**
 * Validates a string against a JSON schema.
 */
export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = extractJson(jsonStr);
        if (!cleanStr) return false;
        const data = JSON.parse(cleanStr);
        if (schema && schema.required) {
            return schema.required.every((key: string) => key in data && data[key] !== undefined);
        }
        return true;
    } catch (e) {
        return false;
    }
};

// --- GEMINI API SERVICE ---

export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

/**
 * Diagnostic handler for API failures.
 * Triggers key rotation if the current project/key is invalid or has reached billing limits.
 */
const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    if (msg.includes("Requested entity was not found") || msg.includes("API_KEY_INVALID") || status === 403 || status === 404) {
        const aistudio = (window as any).aistudio;
        if (aistudio?.openSelectKey) {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

/**
 * Agent: Subject Expert
 * Refines the generated content for scientific rigor.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false,
    schema?: any
): Promise<string> => {
    if (!content) return content;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

    const systemInstruction = `You are a Senior Scientific Editor in ${context.experimentField}. 
    Review the provided ${isJson ? 'JSON data' : 'research text'}.
    1. Standardize terminology for academic publication.
    2. Maintain the exact same core information and logic.
    3. ${isJson ? 'CRITICAL: Output ONLY the refined JSON. Do not add any text before or after.' : 'Output Markdown only.'}`;

    const config: any = { 
        systemInstruction,
        temperature: 0.1 
    };

    if (isJson && schema) {
        config.responseMimeType = "application/json";
        config.responseSchema = schema;
    }

    try {
        const response = await ai.models.generateContent({
            model,
            contents: `Refine the following archival node content:\n\n${content}`,
            config
        });
        const refinedText = response.text || content;

        if (isJson && !isValidJsonForSchema(refinedText, schema)) {
            return extractJson(content);
        }

        return isJson ? extractJson(refinedText) : refinedText;
    } catch (e) {
        await handleApiError(e);
        return isJson ? extractJson(content) : content;
    }
};

/**
 * Agentic JSON Loop: Repair Agent fixes malformed output.
 */
const agenticJsonFixLoop = async (
    invalidJson: string, 
    schema: any, 
    errorMsg: string
): Promise<string | null> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    for (let cycle = 1; cycle <= 2; cycle++) {
        try {
            const expertResponse = await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: `REPAIR AGENT: The following input failed JSON schema validation.
                Schema: ${JSON.stringify(schema)}. 
                Error: ${errorMsg}. 
                Corrupt Input: ${invalidJson}. 
                Output valid JSON that adheres strictly to the schema.`,
                config: { responseMimeType: "application/json", responseSchema: schema }
            });
            const fixed = extractJson(expertResponse.text || "");
            if (isValidJsonForSchema(fixed, schema)) return fixed;
        } catch (e) {
            await handleApiError(e);
        }
    }
    return null;
};

/**
 * Main Orchestration Workflow.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    let output = "";
    let success = false;
    let lastError = "";

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // 1. Primary Generation
    for (let attempt = 1; attempt <= 2; attempt++) {
        try {
            // Added defensive timeout promise to prevent infinite hangs
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 60000); // 60s timeout

            const response = await ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            });

            clearTimeout(timeoutId);
            output = response.text || "";

            const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
            if (!expectJson && groundingChunks && Array.isArray(groundingChunks)) {
                let citations = "\n\n### Grounding Citations\n";
                groundingChunks.forEach((chunk: any) => {
                    if (chunk.web && chunk.web.uri) {
                        citations += `- [${chunk.web.title || chunk.web.uri}](${chunk.web.uri})\n`;
                    }
                });
                output += citations;
            }

            if (expectJson) {
                if (isValidJsonForSchema(output, schema)) {
                    output = extractJson(output);
                    success = true;
                    break;
                }
                lastError = "Schema validation failed.";
            } else if (output.trim()) {
                success = true;
                break;
            }
        } catch (e: any) {
            lastError = e.message;
            const errStatus = await handleApiError(e);
            if (errStatus === "AUTH_RETRY_REQUIRED") throw new Error("Authentication re-sync required.");
            if (attempt === 2) throw e;
            await new Promise(r => setTimeout(r, 1000 * attempt));
        }
    }

    if (expectJson && !success) {
        const fixed = await agenticJsonFixLoop(output, schema, lastError);
        if (fixed) {
            output = fixed;
            success = true;
        } else {
            throw new Error(`Archival node corruption: ${lastError}`);
        }
    }

    if (expectJson && success) return output;

    return await refineWithSubjectExpert(output, context, expectJson, schema);
};

export const callGeminiWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const context = { experimentField: 'Scientific Research' };
    const text = (await executeStepWorkflow(model, params, context));
    return { text };
};

export const callGeminiStreamWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        return await ai.models.generateContentStream({
            model: model,
            contents: params.contents,
            config: params.config
        });
    } catch (error: any) {
        const err = await handleApiError(error);
        if (err === "AUTH_RETRY_REQUIRED") throw new Error("Authentication re-sync required.");
        throw error;
    }
};

export const parseGeminiError = (error: any, fallback = "Hypatia link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync')) return "Archive link unstable: Please re-verify your project key via the system menu.";
    if (msg.includes('safety')) return "Archive protocol block: content violates safety filters.";
    if (msg.includes('corruption')) return error.message;
    if (msg.includes('abort')) return "Request timed out. Please retry synthesis.";
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};

    const getSummary = (sId: number) => {
        const step = data[sId];
        if (!step) return 'N/A';
        return step.summary || (step.output ? (step.output.slice(0, 500) + '...') : 'N/A');
    };
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 5) context.data_collection_plan_summary = getSummary(5);
    if (stepId > 6) context.experimental_data_summary = getSummary(6);
    if (stepId > 7) context.analysis_summary = getSummary(7);

    if (stepId === 10 || stepId === 13) {
        let projectLog = '';
        for (let i = 1; i < stepId; i++) {
            const stepInfo = WORKFLOW_STEPS.find(s => s.id === i);
            if (stepInfo) projectLog += `[Phase ${i}] ${stepInfo.title}: ${getSummary(i)}\n\n`;
        }
        context.full_project_summary_log = projectLog.trim();
    }
    return context;
};

