import { GoogleGenAI, Type, Modality, GenerateContentResponse } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
    CHART_JS_SCHEMA,
    VISUALIZATION_PLAN_SCHEMA,
} from './config';

// --- UTILITIES ---

export const extractJson = (text: string): string => {
    if (!text) return "";
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');
    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = extractJson(jsonStr);
        if (!cleanStr) return false;
        const data = JSON.parse(cleanStr);
        if (schema && schema.required) {
            return schema.required.every((key: string) => key in data && data[key] !== undefined);
        }
        return true;
    } catch (e) {
        return false;
    }
};

// --- GEMINI API SERVICE ---

export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    if (msg.includes("entity was not found") || msg.includes("API_KEY_INVALID") || status === 403 || status === 404) {
        const aistudio = (window as any).aistudio;
        if (aistudio?.openSelectKey) {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

const withTimeout = <T>(promise: Promise<T>, ms: number, message: string): Promise<T> => {
    let timeoutId: any;
    const timeoutPromise = new Promise<T>((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(message)), ms);
    });
    return Promise.race([
        promise.then(val => { clearTimeout(timeoutId); return val; }),
        timeoutPromise
    ]);
};

export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false,
    schema?: any
): Promise<string> => {
    if (!content) return content;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
    const systemInstruction = `You are a Senior Scientific Editor in ${context.experimentField}. Review output for academic rigor. Output ONLY ${isJson ? 'valid JSON' : 'Markdown'}.`;

    try {
        const response = await withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: `Refine the following archival node content:\n\n${content}`,
                config: { systemInstruction, temperature: 0.1 }
            }),
            30000,
            "Expert refinement timed out."
        );
        const refinedText = response.text || content;
        return isJson ? extractJson(refinedText) : refinedText;
    } catch (e) {
        console.warn("Refinement failed:", e);
        return isJson ? extractJson(content) : content;
    }
};

export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    let output = "";
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
        const response = await withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }),
            45000,
            "Archival synthesis timed out."
        );

        output = response.text || "";
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (!expectJson && groundingChunks && Array.isArray(groundingChunks)) {
            let citations = "\n\n### Grounding Citations\n";
            groundingChunks.forEach((chunk: any) => {
                if (chunk.web && chunk.web.uri) {
                    citations += `- [${chunk.web.title || chunk.web.uri}](${chunk.web.uri})\n`;
                }
            });
            output += citations;
        }

        if (expectJson && !isValidJsonForSchema(output, schema)) {
            const repairResponse = await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: `Repair this JSON to match schema ${JSON.stringify(schema)}:\n${output}`,
                config: { responseMimeType: "application/json" }
            });
            output = repairResponse.text || output;
        }

        return expectJson ? extractJson(output) : await refineWithSubjectExpert(output, context);
    } catch (e: any) {
        await handleApiError(e);
        throw e;
    }
};

export const callGeminiWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const context = { experimentField: 'Scientific Research' };
    const text = await executeStepWorkflow(model, params, context);
    return { text };
};

export const callGeminiStreamWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    return await ai.models.generateContentStream({
        model: model,
        contents: params.contents,
        config: params.config
    });
};

export const parseGeminiError = (error: any, fallback = "Hypatia link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync') || msg.includes('timed out')) return "Archive link unstable. Please retry synthesis.";
    if (msg.includes('safety')) return "Safety filter triggered by research content.";
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};
    const getSummary = (sId: number) => data[sId]?.summary || (data[sId]?.output ? (data[sId].output.slice(0, 300) + '...') : 'N/A');
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 7) context.analysis_summary = getSummary(7);

    if (stepId === 10) {
        let log = '';
        WORKFLOW_STEPS.forEach(s => { if(s.id < 10) log += `[${s.title}] ${getSummary(s.id)}\n\n`; });
        context.full_project_summary_log = log;
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    const settings = fineTuneSettings || {};
    let systemInstruction = `You are Hypatia, a professional AI Scientist. Research Field: ${context.experimentField}. Output academic, rigorous Markdown.`;
    let basePrompt = regenerateFeedback ? `[PI FEEDBACK: ${regenerateFeedback}]\n\n` : "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.7 };

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `REFINE RESEARCH QUESTION. Input: "${userInput}". Output valid JSON with "research_question", "uniqueness_score", "justification", "field".`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            expectJson = true;
            basePrompt += `Literature review for: "${context.question}". Use Google Search. Output JSON per LITERATURE_REVIEW_SCHEMA.`;
            config.tools = [{ googleSearch: {} }];
            config.responseMimeType = "application/json";
            config.responseSchema = LITERATURE_REVIEW_SCHEMA;
            break;
        case 3:
            basePrompt += `Formulate 3 hypotheses for: "${context.question}". Use context: "${context.literature_review_summary}".`;
            break;
        case 4:
            basePrompt += `Detailed experimental methodology for: "${context.hypothesis}".`;
            break;
        case 5:
            basePrompt += `Data collection plan for methodology: "${context.methodology_summary}".`;
            break;
        case 6:
            basePrompt += `Generate synthetic CSV data for: "${context.methodology_summary}".`;
            break;
        case 7:
            expectJson = true;
            basePrompt += `Analyze data: ${userInput}. Return JSON with "summary" and "charts" (imageData).`;
            config.responseMimeType = "application/json";
            config.responseSchema = DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
            break;
        case 8:
            basePrompt += `Draft conclusions from analysis summary: "${context.analysis_summary}".`;
            break;
        case 9:
            basePrompt += `Simulate a skeptical peer review for:\n${context.full_project_summary_log}`;
            break;
        case 10:
            basePrompt += `Draft a comprehensive scientific publication for:\n${context.full_project_summary_log}`;
            break;
        default:
            basePrompt += `Continue research on Step ${stepId}.`;
    }

    return { basePrompt, expectJson, config };
};

// --- BASE AGENT RUNNER HELPER ---
const runBaseAgent = async (
    experiment: Experiment,
    stepId: number,
    updateLog: (agent: string, message: string) => void,
    agentName: string,
    startMessage: string,
    model: string,
    expectJson: boolean = false,
    schema?: any,
    extraPromptData: string = '',
    extraConfig: any = {}
) => {
    const context = await getStepContext(experiment, stepId);
    const { basePrompt, config } = getPromptForStep(stepId, extraPromptData, context, {});
    updateLog(agentName, startMessage);

    return await executeStepWorkflow(model, { 
        contents: basePrompt, 
        config: { ...config, ...extraConfig } 
    }, context, expectJson, schema);
};

export const runLiteratureReviewAgent = async ({ experiment, updateLog }) => {
    return await runBaseAgent(
        experiment, 2, updateLog, 'Hypatia', 'Linking with global search indices...', 
        'gemini-3-flash-preview', true, LITERATURE_REVIEW_SCHEMA
    );
};

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }) => {
    const finalOutput = await runBaseAgent(
        experiment, 7, updateLog, 'Hypatia', 'Computing statistical models...', 
        'gemini-3-flash-preview', true, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, csvData
    );
    return { finalOutput, logSummary: "Analysis node synchronized." };
};

export const runPeerReviewAgent = async ({ experiment, updateLog }) => {
    return await runBaseAgent(
        experiment, 9, updateLog, 'Reviewer', 'Performing adversarial audit...', 
        'gemini-3-pro-preview'
    );
};

export const runPublicationAgent = async ({ experiment, updateLog }) => {
    return await runBaseAgent(
        experiment, 10, updateLog, 'Hypatia', 'Synthesizing final technical draft...', 
        'gemini-3-pro-preview', false, undefined, '', { thinkingConfig: { thinkingBudget: 8000 } }
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { UniquenessMeter } from './UniquenessMeter';
import { DataAnalysisView } from './DataAnalysisView';
import { extractJson } from '../../services';

interface GeneratedOutputProps {
    stepId: number;
    onGenerate: (feedback?: string) => Promise<void>;
    isLoading: boolean;
    streamingText?: string | null;
}

export const GeneratedOutput: React.FC<GeneratedOutputProps> = ({ 
    stepId, 
    onGenerate, 
    isLoading, 
    streamingText 
}) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();

    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState('');
    const [showRegenInput, setShowRegenInput] = useState(false);
    const [regenFeedback, setRegenFeedback] = useState('');

    const stepData = activeExperiment.stepData[stepId] || {};
    const savedOutput = stepData.output || '';
    const currentText = streamingText !== null ? streamingText : savedOutput;

    useEffect(() => {
        setEditText(savedOutput);
    }, [savedOutput]);

    const handleSave = () => {
        updateExperiment({ 
            ...activeExperiment, 
            stepData: { 
                ...activeExperiment.stepData, 
                [stepId]: { ...stepData, output: editText } 
            } 
        });
        setIsEditing(false);
        addToast("Archival node updated.", "success");
    };

    const handleRegenerate = () => {
        if (isLoading) return;
        onGenerate(regenFeedback);
        setShowRegenInput(false);
        setRegenFeedback('');
    };

    const renderedHtml = useMemo(() => {
        if (!currentText) return '';
        return renderMarkdown(currentText, !isLoading);
    }, [currentText, isLoading]);

    const renderJsonContent = (text: string) => {
        try {
            const clean = extractJson(text);
            const data = JSON.parse(clean);

            if (stepId === 1) {
                return (
                   <div className="animate-in">
                       <div className="mb-4" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.research_question || '', true) }} />
                       {data.uniqueness_score !== undefined && (
                           <UniquenessMeter 
                                score={data.uniqueness_score} 
                                justification={data.justification || ''} 
                           />
                       )}
                   </div>
               );
            }

            if (stepId === 2) {
                return (
                    <div className="lit-review-output animate-in">
                        <h5 className="fw-bold text-primary-glow border-bottom border-secondary border-opacity-25 pb-2 mb-3">Synthesis of Findings</h5>
                        <div className="generated-text-container mb-4" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.summary || '', true) }} />
                        {data.references && Array.isArray(data.references) && data.references.length > 0 && (
                            <section>
                                <h5 className="fw-bold text-info small text-uppercase ls-1 border-bottom border-secondary border-opacity-10 pb-2 mb-3">Grounding Links</h5>
                                <div className="list-group list-group-flush bg-transparent">
                                    {data.references.map((ref: any, i: number) => (
                                        <div key={i} className="list-group-item bg-transparent border-secondary border-opacity-10 px-0 py-2">
                                            <div className="fw-bold text-white small">{ref.title}</div>
                                            <div className="text-white-50" style={{fontSize: '0.75rem'}}>{ref.authors?.join(', ')} ({ref.year})</div>
                                            {ref.url && <a href={ref.url} target="_blank" rel="noopener noreferrer" className="small text-primary-glow">View Source &raquo;</a>}
                                        </div>
                                    ))}
                                </div>
                            </section>
                        )}
                    </div>
                );
            }

            if (stepId === 7) return <DataAnalysisView analysisData={data} />;
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        } catch (e) {
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        }
    };

    const isJsonStep = stepId === 1 || stepId === 2 || stepId === 7;

    return (
        <div className="generated-content-container">
            {/* Context remains visible always */}
            {!currentText && !isLoading ? (
                <div className="text-center p-5 border border-secondary border-opacity-10 rounded-4 bg-dark bg-opacity-10 my-3">
                    <i className="bi bi-cpu mb-3 text-primary-glow opacity-50 d-block" style={{ fontSize: '2.5rem' }}></i>
                    <h5 className="fw-bold mb-2">Initialize Archival Node</h5>
                    <p className="text-white-50 small mb-4 mx-auto" style={{maxWidth: '350px'}}>
                        Synthesize discovery data from previous steps into a verifiable research node.
                    </p>
                    <button 
                        className="btn btn-primary px-5 py-2 rounded-pill shadow-sm d-flex align-items-center justify-content-center mx-auto" 
                        onClick={() => onGenerate()} 
                    >
                        <i className="bi bi-stars me-2"></i> 
                        SYNTHESIZE NODE
                    </button>
                </div>
            ) : (
                <>
                    {/* Output Controls */}
                    {!isLoading && !isEditing && currentText && (
                        <div className="d-flex justify-content-end gap-2 mb-3">
                            <button className="btn btn-xs btn-outline-secondary py-1" onClick={() => setShowRegenInput(p => !p)}>
                                <i className="bi bi-arrow-clockwise me-1"></i> Regenerate
                            </button>
                            <button className="btn btn-xs btn-outline-secondary py-1" onClick={() => { setIsEditing(true); setEditText(savedOutput); }}>
                                <i className="bi bi-pencil-square me-1"></i> Edit
                            </button>
                        </div>
                    )}

                    {showRegenInput && (
                        <div className="input-group input-group-sm mb-4">
                            <input 
                                type="text" 
                                className="form-control bg-dark text-white border-secondary" 
                                placeholder="Feedback for refinement..." 
                                value={regenFeedback} 
                                onChange={e => setRegenFeedback(e.target.value)} 
                            />
                            <button className="btn btn-primary" onClick={handleRegenerate} disabled={isLoading}>Refine</button>
                        </div>
                    )}

                    {isEditing ? (
                        <div className="edit-view card bg-black border-secondary p-3">
                            <textarea 
                                className="form-control font-monospace bg-dark text-white border-secondary mb-3" 
                                style={{ minHeight: '300px' }} 
                                value={editText} 
                                onChange={(e) => setEditText(e.target.value)} 
                            />
                            <div className="d-flex gap-2 justify-content-end">
                                <button className="btn btn-sm btn-outline-secondary" onClick={() => setIsEditing(false)}>Cancel</button>
                                <button className="btn btn-sm btn-success px-3" onClick={handleSave}>Save Node</button>
                            </div>
                        </div>
                    ) : (
                        <div className={`rendered-view ${isLoading && !currentText ? 'opacity-25' : isLoading ? 'opacity-75' : ''}`}>
                            {isLoading && !currentText && (
                                <div className="text-center py-5">
                                     <div className="spinner-border text-primary-glow mb-3" role="status"></div>
                                     <div className="text-primary-glow small fw-bold text-uppercase ls-1">Archival Link Established...</div>
                                </div>
                            )}

                            {(currentText || streamingText) && (
                                <>
                                    {isJsonStep && !isLoading ? renderJsonContent(currentText) : <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderedHtml }} />}

                                    {isLoading && currentText && (
                                        <div className="mt-4 pt-3 border-top border-secondary border-opacity-10 text-center">
                                            <div className="spinner-grow spinner-grow-sm text-primary-glow me-2" role="status"></div>
                                            <span className="small text-primary-glow font-monospace text-uppercase ls-1">Decoding Archive Stream...</span>
                                        </div>
                                    )}
                                </>
                            )}
                        </div>
                    )}
                </>
            )}

            <style>{`
                .animate-pulse { animation: pulse 2s infinite ease-in-out; }
                @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
                .btn-xs { padding: 0.25rem 0.5rem; font-size: 0.75rem; }
                .ls-1 { letter-spacing: 0.05rem; }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import {
    Chart,
    LineController,
    BarController,
    LineElement,
    BarElement,
    PointElement,
    CategoryScale,
    LinearScale,
    Legend,
    Tooltip,
    Title
} from 'chart.js';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { runPublicationAgent, parseGeminiError } from '../../services';
import { AgenticAnalysisView } from '../common/AgenticAnalysisView';

// Register Chart.js components
Chart.register(
    LineController,
    BarController,
    LineElement,
    BarElement,
    PointElement,
    CategoryScale,
    LinearScale,
    Legend,
    Tooltip,
    Title
);

export const FinalPublicationView = ({ publicationText, onRegenerate, showRegenerate = true }) => {
    const { addToast } = useToast();
    const { activeExperiment } = useExperiment();
    const contentRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const renderContent = async () => {
            if (!publicationText || !contentRef.current) return;

            contentRef.current.innerHTML = `<div class="text-center p-3"><div class="spinner-border spinner-border-sm"></div> Rendering document...</div>`;

            let processedText = publicationText;
            const chartPlaceholders = publicationText.match(/\[CHART_(\d+):([\s\S]*?)\]/g) || [];

            if (chartPlaceholders.length > 0) {
                const analysisJson = activeExperiment.stepData[7]?.output || '{}';
                let analysisData: any = {};
                try {
                    analysisData = JSON.parse(analysisJson.replace(/```json/g, '').replace(/```/g, ''));
                } catch(e) {
                    console.error("Failed to parse analysis JSON for charts", e);
                }
                const charts = analysisData.charts || []; 

                for (const placeholder of chartPlaceholders) {
                    const match = placeholder.match(/\[CHART_(\d+):([\s\S]*?)\]/);
                    if (!match) continue;

                    const chartIndex = parseInt(match[1], 10) - 1;
                    const caption = match[2];

                    if (charts[chartIndex] && charts[chartIndex].imageData) {
                        const dataUrl = `data:image/png;base64,${charts[chartIndex].imageData}`;
                        const imgTag = `<figure style="text-align: center;"><img src="${dataUrl}" alt="${caption}" style="max-width: 80%; height: auto; display: block; margin: 1rem auto; border: 1px solid #444;" /><figcaption style="font-size: 0.9em; color: #aaa; margin-top: 0.5em;">${caption}</figcaption></figure>`;
                        processedText = processedText.replace(placeholder, imgTag);
                    } else {
                         processedText = processedText.replace(placeholder, `<p class="text-warning">[Chart data for placeholder not found.]</p>`);
                    }
                }
            }

            contentRef.current.innerHTML = renderMarkdown(processedText);
        };

        renderContent();
    }, [publicationText, activeExperiment]);


    const handleDownload = (format: 'md' | 'doc' | 'pdf' | 'txt') => {
        const { title, id } = activeExperiment;
        if (format === 'pdf') {
            addToast("Preparing a print-friendly view...", "info");
            const printContent = contentRef.current?.innerHTML || '';
            const printWindow = window.open('', '_blank');
            if (!printWindow) {
                addToast("Could not open a new window. Please check your browser's pop-up blocker.", 'warning');
                return;
            }
            printWindow.document.write(`
                <!DOCTYPE html>
                <html>
                <head>
                    <title>Print - ${title}</title>
                    <style>
                        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; line-height: 1.6; color: #333; max-width: 800px; margin: 20px auto; }
                        h1, h2, h3, h4 { color: #000; }
                        pre, code { background-color: #f4f4f4; padding: 2px 4px; border-radius: 4px; font-family: monospace; }
                        pre { padding: 1em; overflow: auto; }
                        img { max-width: 100%; height: auto; }
                        figure { page-break-inside: avoid; }
                    </style>
                </head>
                <body>
                    ${printContent}
                    <script>
                        setTimeout(() => {
                            window.print();
                            window.close();
                        }, 500);
                    </script>
                </body>
                </html>
            `);
            printWindow.document.close();
            return;
        }

        let blob;
        let filename = `${title.replace(/ /g, '_')}_${id}`;
        if (format === 'doc') {
            const htmlContent = `
                <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
                <head><meta charset='utf-8'><title>${title}</title></head>
                <body>${contentRef.current?.innerHTML}</body>
                </html>`;
            blob = new Blob(['\ufeff', htmlContent], { type: 'application/msword' });
            filename += '.doc';
        } else {
            const content = format === 'md' ? publicationText : contentRef.current?.innerText || publicationText;
            blob = new Blob([content], { type: 'text/plain' });
            filename += `.${format}`;
        }

        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        link.click();
        URL.revokeObjectURL(url);
    };

    return (
        <div>
            <div className="d-flex justify-content-end mb-2">
                {showRegenerate && 
                    <button className="btn btn-sm btn-outline-secondary me-auto" onClick={onRegenerate}>
                        <i className="bi bi-arrow-clockwise me-1"></i> Regenerate with Agents
                    </button>
                }
                <div className="btn-group">
                    <button type="button" className="btn btn-sm btn-secondary dropdown-toggle" data-bs-toggle="dropdown">
                       <i className="bi bi-download me-1"></i> Download As
                    </button>
                    <ul className="dropdown-menu dropdown-menu-end">
                        <li><a className="dropdown-item" href="#" onClick={() => handleDownload('md')}>Markdown (.md)</a></li>
                        <li><a className="dropdown-item" href="#" onClick={() => handleDownload('txt')}>Plain Text (.txt)</a></li>
                        <li><a className="dropdown-item" href="#" onClick={() => handleDownload('doc')}>Word Document (.doc)</a></li>
                         <li><a className="dropdown-item" href="#" onClick={() => handleDownload('pdf')}>PDF (Print)</a></li>
                    </ul>
                </div>
            </div>
            <div ref={contentRef} className="generated-text-container" style={{ minHeight: '50vh' }}>
                {/* Content is rendered here via useEffect */}
            </div>
        </div>
    );
};

export const PublicationExporter = () => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();
    const [agenticRun, setAgenticRun] = useState({ logs: [], status: 'idle', iterations: 0 });
    const stepData = activeExperiment?.stepData[10] || {};
    const publicationText = stepData.output || '';

    const experimentRef = useRef(activeExperiment);
    useEffect(() => {
        experimentRef.current = activeExperiment;
    }, [activeExperiment]);

    const startPublicationGeneration = async () => {
        if (!experimentRef.current || agenticRun.status === 'running') return;

        setAgenticRun({ logs: [], status: 'running', iterations: 0 });

        try {
            const finalDoc = await runPublicationAgent({
                experiment: experimentRef.current, 
                updateLog: (agent, message) => {
                    setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent, message }] }));
                }
            });
            const updatedExperiment = {
                ...experimentRef.current, 
                stepData: {
                    ...experimentRef.current.stepData,
                    10: { ...stepData, output: finalDoc }
                },
                currentStep: 11
            };
            await updateExperiment(updatedExperiment);
            setAgenticRun(prev => ({ ...prev, status: 'success' }));
            addToast("Publication generated successfully!", "success");

        } catch (error) {
            const errorMessage = parseGeminiError(error, "Agentic publication generation failed.");
            addToast(errorMessage, 'danger');
            setAgenticRun(prev => ({ ...prev, status: 'failed', logs: [...prev.logs, { agent: 'System', message: `ERROR: ${errorMessage}` }] }));
        }
    };

    return (
        <div className="publication-exporter-container">
            {/* Always show existing text or the start view, non-blocking */}
            {publicationText ? (
                <div className={agenticRun.status === 'running' ? 'opacity-50' : ''}>
                    <FinalPublicationView 
                        publicationText={publicationText}
                        onRegenerate={startPublicationGeneration}
                        showRegenerate={agenticRun.status !== 'running'}
                    />
                </div>
            ) : agenticRun.status === 'idle' && (
                <div className="text-center p-5">
                    <h5 className="fw-bold">Assemble Your Publication</h5>
                    <p className="text-white-50">Use the agentic workflow to build your final paper. The AI will outline, write, and format the entire document, including charts and references.</p>
                    <div className="alert alert-info small mt-4">
                        <i className="bi bi-info-circle-fill me-2"></i>
                        <strong>A Note on Context:</strong> The AI will synthesize your entire project archive into a formal manuscript.
                    </div>
                    <button className="btn btn-primary" onClick={startPublicationGeneration}>
                        <i className="bi bi-robot me-1"></i> Generate Publication with Agents
                    </button>
                </div>
            )}

            {/* Always show logs at the bottom if active or failed */}
            {(agenticRun.status === 'running' || (agenticRun.status === 'failed' && agenticRun.logs.length > 0)) && (
                <div className="mt-4 border-top border-secondary border-opacity-10 pt-4">
                    <AgenticAnalysisView 
                        agenticRun={{...agenticRun, maxIterations: 7}} 
                        title="Publication Agent Log" 
                        subtitle="The AI team is synthesizing the project dossier." 
                    />
                    {agenticRun.status === 'failed' && (
                        <div className="text-center mt-3">
                            <button className="btn btn-sm btn-primary px-4" onClick={startPublicationGeneration}>
                                <i className="bi bi-arrow-clockwise me-1"></i> Retry Generation
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

