import { GoogleGenAI, Type, Modality, GenerateContentResponse } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
} from './config';

// --- UTILITIES ---

export const extractJson = (text: string): string => {
    if (!text) return "";
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');
    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = extractJson(jsonStr);
        if (!cleanStr) return false;
        const data = JSON.parse(cleanStr);
        if (schema && schema.required) {
            return schema.required.every((key: string) => key in data && data[key] !== undefined);
        }
        return true;
    } catch (e) {
        return false;
    }
};

// --- GEMINI API SERVICE ---

export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    return apiKey.length >= 20; 
};

const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    if (msg.includes("entity was not found") || msg.includes("API_KEY_INVALID") || status === 403 || status === 404) {
        const aistudio = (window as any).aistudio;
        if (aistudio?.openSelectKey) {
            await aistudio.openSelectKey();
            return "AUTH_RETRY_REQUIRED";
        }
    }
    return null;
};

const withTimeout = <T>(promise: Promise<T>, ms: number, message: string): Promise<T> => {
    let timeoutId: any;
    const timeoutPromise = new Promise<T>((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(message)), ms);
    });
    return Promise.race([
        promise.then(val => { clearTimeout(timeoutId); return val; }),
        timeoutPromise
    ]);
};

/**
 * FAST REFINEMENT: Optional, non-blocking scientific polish.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false
): Promise<string> => {
    if (!content) return content;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
    const systemInstruction = `You are a Senior Scientific Editor. Review output for academic rigor. Output ONLY ${isJson ? 'valid JSON' : 'Markdown'}.`;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: `Refine the following archival node content:\n\n${content}`,
            config: { systemInstruction, temperature: 0.1 }
        });
        const refinedText = response.text || content;
        return isJson ? extractJson(refinedText) : refinedText;
    } catch (e) {
        return isJson ? extractJson(content) : content;
    }
};

/**
 * CORE WORKFLOW EXECUTION: Now performs exactly ONE archival call to minimize blocking.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
        const response = await withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }),
            30000,
            "Archival synthesis timed out."
        );

        let output = response.text || "";

        // Citations are added without triggering a new LLM call
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (!expectJson && groundingChunks && Array.isArray(groundingChunks)) {
            let citations = "\n\n### Grounding Citations\n";
            groundingChunks.forEach((chunk: any) => {
                if (chunk.web && chunk.web.uri) {
                    citations += `- [${chunk.web.title || chunk.web.uri}](${chunk.web.uri})\n`;
                }
            });
            output += citations;
        }

        // Return immediately. Repair/Refinement is now handled by the UI/Background as non-blocking tasks.
        return expectJson ? extractJson(output) : output;
    } catch (e: any) {
        await handleApiError(e);
        throw e;
    }
};

// Added callGeminiWithRetry to handle standard content generation requests with timeout and error handling.
// This function ensures that the latest API key is used by initializing the GoogleGenAI client on each call.
export const callGeminiWithRetry = async (model: string, params: { contents: string, config?: any }): Promise<GenerateContentResponse> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
        return await withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }),
            30000,
            "Archival link unstable. Please retry synthesis."
        );
    } catch (e: any) {
        await handleApiError(e);
        throw e;
    }
};

export const callGeminiStreamWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    return await ai.models.generateContentStream({
        model: model,
        contents: params.contents,
        config: params.config
    });
};

export const parseGeminiError = (error: any, fallback = "Hypatia link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync') || msg.includes('timed out')) return "Archive link unstable. Please retry synthesis.";
    if (msg.includes('safety')) return "Safety filter triggered by research content.";
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};
    const getSummary = (sId: number) => data[sId]?.summary || (data[sId]?.output ? (data[sId].output.slice(0, 300) + '...') : 'N/A');
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 7) context.analysis_summary = getSummary(7);

    if (stepId === 10) {
        let log = '';
        WORKFLOW_STEPS.forEach(s => { if(s.id < 10) log += `[${s.title}] ${getSummary(s.id)}\n\n`; });
        context.full_project_summary_log = log;
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    const settings = fineTuneSettings || {};
    let systemInstruction = `You are Hypatia, a professional AI Scientist. Research Field: ${context.experimentField}. Output academic, rigorous Markdown.`;
    let basePrompt = regenerateFeedback ? `[PI FEEDBACK: ${regenerateFeedback}]\n\n` : "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.7 };

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `REFINE RESEARCH QUESTION. Input: "${userInput}". Output valid JSON with "research_question", "uniqueness_score", "justification", "field".`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            expectJson = true;
            basePrompt += `Literature review for: "${context.question}". Use Google Search. Output JSON per LITERATURE_REVIEW_SCHEMA.`;
            config.tools = [{ googleSearch: {} }];
            config.responseMimeType = "application/json";
            config.responseSchema = LITERATURE_REVIEW_SCHEMA;
            break;
        case 3:
            basePrompt += `Formulate 3 hypotheses for: "${context.question}". Use context: "${context.literature_review_summary}".`;
            break;
        case 4:
            basePrompt += `Detailed experimental methodology for: "${context.hypothesis}".`;
