            break;
        case 8:
            basePrompt += `Draft conclusions from analysis summary: "${context.analysis_summary}".`;
            break;
        case 9:
            basePrompt += `Simulate a skeptical peer review for:\n${context.full_project_summary_log}`;
            break;
        case 10:
            basePrompt += `Draft a comprehensive scientific publication for:\n${context.full_project_summary_log}`;
            break;
        default:
            basePrompt += `Continue research on Step ${stepId}.`;
    }

    return { basePrompt, expectJson, config };
};

// --- AGENTIC WORKFLOW RUNNER ---
export const runAgenticWorkflow = async ({
    experiment,
    stepId,
    agentName,
    startMessage,
    updateLog,
    model = 'gemini-3-flash-preview',
    expectJson = false,
    schema = undefined,
    extraInput = '',
    extraConfig = {}
}: {
    experiment: Experiment;
    stepId: number;
    agentName: string;
    startMessage: string;
    updateLog: (agent: string, message: string) => void;
    model?: string;
    expectJson?: boolean;
    schema?: any;
    extraInput?: string;
    extraConfig?: any;
}) => {
    const context = await getStepContext(experiment, stepId);
    const { basePrompt, config } = getPromptForStep(stepId, extraInput, context, {});
    updateLog(agentName, startMessage);

    return await executeStepWorkflow(model, { 
        contents: basePrompt, 
        config: { ...config, ...extraConfig } 
    }, context, expectJson, schema);
};

export const runLiteratureReviewAgent = async ({ experiment, updateLog }) => {
    return await runAgenticWorkflow({
        experiment,
        stepId: 2,
        agentName: 'Hypatia',
        startMessage: 'Linking with global search indices...',
        updateLog,
        expectJson: true,
        schema: LITERATURE_REVIEW_SCHEMA
    });
};

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }) => {
    let finalOutput = "";
    let isValid = false;

    // 1. Initial Attempt with Simple Retries
    for (let attempt = 1; attempt <= 3; attempt++) {
        const msg = attempt === 1 ? 'Computing statistical models...' : `Computing statistical models (Attempt ${attempt})...`;
        try {
            finalOutput = await runAgenticWorkflow({
                experiment,
                stepId: 7,
                agentName: 'Hypatia',
                startMessage: msg,
                updateLog,
                extraInput: csvData,
                expectJson: true,
                schema: DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA
            });

            if (isValidJsonForSchema(finalOutput, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA)) {
                isValid = true;
                break;
            } else {
                updateLog('System', `Attempt ${attempt}: Output failed schema validation.`);
            }
        } catch (e: any) {
            updateLog('System', `Attempt ${attempt} error: ${e.message}`);
        }
    }

    if (isValid) {
        return { finalOutput, logSummary: "Analysis node synchronized." };
    }

    // 2. Agentic Recovery Loop
    updateLog('System', 'Standard synthesis failed. Initiating Agentic Repair Protocol...');

    // Recovery Context
    let currentCandidate = finalOutput;

    for (let cycle = 1; cycle <= 3; cycle++) {
        updateLog('System', `Recovery Cycle ${cycle}/3...`);

        // Agent: JSON Expert
        updateLog('JSON Expert', 'Analyzing structural integrity...');
        try {
            const repairContext = { experimentField: experiment.field }; // Minimal context
            const repairPrompt = `
                ACT AS: Senior Data Architect.
                TASK: Fix the following JSON output which failed validation against the Data Analysis Schema.

                REQUIREMENTS:
                1. Must be valid JSON.
                2. Must follow this schema structure:
                   {
                     "summary": "markdown string",
                     "charts": [ { "title": "string", "imageData": "base64_string" } ]
                   }
                3. Ensure 'imageData' contains the base64 string if charts exist. If broken, remove the chart.

                BROKEN JSON:
                ${currentCandidate}

                Output ONLY the fixed JSON.
            `;

            const expertResponse = await executeStepWorkflow(
                'gemini-3-flash-preview', 
                { 
                    contents: repairPrompt, 
                    config: { responseMimeType: 'application/json', responseSchema: DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA } 
                }, 
                repairContext, 
                true,
                DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA
            );

            currentCandidate = expertResponse;
            updateLog('JSON Expert', 'Patch applied.');

            // Agent: QA Agent
            updateLog('QA Agent', 'Verifying patch against schema...');
            if (isValidJsonForSchema(currentCandidate, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA)) {
                isValid = true;
                finalOutput = currentCandidate;
                updateLog('QA Agent', 'Validation successful. Node restored.');
                break;
            } else {
                updateLog('QA Agent', 'Validation failed. Escalating to next cycle.');
            }

        } catch (e: any) {
            updateLog('System', `Recovery logic error: ${e.message}`);
        }
    }

    if (isValid) {
        return { finalOutput, logSummary: "Analysis node repaired and synchronized." };
    }

    updateLog('System', 'Recovery failed. Proceeding with best available data.');
    return { finalOutput: currentCandidate, logSummary: "Analysis node synchronized (Schema Warnings present)." };
};

export const runPeerReviewAgent = async ({ experiment, updateLog }) => {
    return await runAgenticWorkflow({
        experiment,
        stepId: 9,
        agentName: 'Reviewer',
        startMessage: 'Performing adversarial audit...',
        updateLog,
        model: 'gemini-3-pro-preview'
    });
};

export const runPublicationAgent = async ({ experiment, updateLog }) => {
    return await runAgenticWorkflow({
        experiment,
        stepId: 10,
        agentName: 'Hypatia',
        startMessage: 'Synthesizing final technical draft...',
        updateLog,
        model: 'gemini-3-pro-preview',
        extraConfig: { thinkingConfig: { thinkingBudget: 8000 } }
    });
};

