export const runAgenticWorkflow = async ({
    experiment,
    stepId,
    agentName,
    startMessage,
    updateLog,
    model = 'gemini-3-flash-preview',
    expectJson = false,
    schema = undefined,
    extraInput = '',
    extraConfig = {}
}: {
    experiment: Experiment;
    stepId: number;
