                { 
                    contents: repairPrompt, 
                    config: { responseMimeType: 'application/json', responseSchema: DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA } 
                }, 
                repairContext, 
                true,
                DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA
            );

            currentCandidate = expertResponse;
