export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};
    const getSummary = (sId: number) => data[sId]?.summary || (data[sId]?.output ? (data[sId].output.slice(0, 300) + '...') : 'N/A');
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 7) context.analysis_summary = getSummary(7);

    if (stepId === 10) {
        let log = '';
        WORKFLOW_STEPS.forEach(s => { if(s.id < 10) log += `[${s.title}] ${getSummary(s.id)}\n\n`; });
        context.full_project_summary_log = log;
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    const settings = fineTuneSettings || {};
    let systemInstruction = `You are Hypatia, a professional AI Scientist. Research Field: ${context.experimentField}. Output academic, rigorous Markdown.`;
    let basePrompt = regenerateFeedback ? `[PI FEEDBACK: ${regenerateFeedback}]\n\n` : "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.7 };

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `CRITICAL: YOU MUST OUTPUT ONLY VALID JSON. REFINE RESEARCH QUESTION. Input: "${userInput}". Output valid JSON with "research_question", "uniqueness_score", "justification", "field".`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            expectJson = true;
            basePrompt += `Literature review for: "${context.question}". Use Google Search. Output JSON per LITERATURE_REVIEW_SCHEMA.`;
            config.tools = [{ googleSearch: {} }];
            config.responseMimeType = "application/json";
            config.responseSchema = LITERATURE_REVIEW_SCHEMA;
            break;
        case 3:
            basePrompt += `Formulate 3 distinct hypotheses for: "${context.question}". Use context: "${context.literature_review_summary}".`;
            break;
        case 4:
            basePrompt += `Detailed experimental methodology for: "${context.hypothesis}".`;
            break;
        case 5:
            basePrompt += `Data collection plan for methodology: "${context.methodology_summary}".`;
            break;
        case 6:
            basePrompt += `Generate synthetic CSV data for: "${context.methodology_summary}".`;
            break;
        case 7:
            expectJson = true;
            basePrompt += `Analyze data: ${userInput}. Return JSON with "summary" and "charts" (imageData).`;
            config.responseMimeType = "application/json";
            config.responseSchema = DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
            break;
        case 8:
            basePrompt += `Draft conclusions from analysis summary: "${context.analysis_summary}".`;
            break;
        case 9:
            basePrompt += `Simulate a skeptical peer review for:\n${context.full_project_summary_log}`;
            break;
        case 10:
            basePrompt += `Draft a comprehensive scientific publication for:\n${context.full_project_summary_log}`;
            break;
        default:
            basePrompt += `Continue research on Step ${stepId}.`;
    }

    return { basePrompt, expectJson, config };
};

