const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    console.warn("API Error intercepted:", msg, status);

    // CRITICAL FIX: Do not automatically trigger aistudio.openSelectKey() here.
    // It causes a blocking overlay ("Rocket Launch" screen) that prevents user interaction.
    // Instead, return a specific error code that the UI can handle gracefully (e.g. via Toast).
    if (msg.includes("entity was not found") || msg.includes("API_KEY_INVALID") || status === 403 || status === 404) {
        return "AUTH_ERROR";
    }
    return null;
};

const withTimeout = <T>(promise: Promise<T>, ms: number, message: string): Promise<T> => {
    let timeoutId: any;
    const timeoutPromise = new Promise<T>((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(message)), ms);
    });
    return Promise.race([
        promise.then(
            val => { clearTimeout(timeoutId); return val; },
            err => { clearTimeout(timeoutId); throw err; }
        ),
        timeoutPromise
    ]);
};

