import { GoogleGenAI, Type, Modality, GenerateContentResponse } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
} from './config';

// Re-export context hook for simplified imports in components
export { useExperiment } from './context/ExperimentContext';

// --- UTILITIES ---

export const extractJson = (text: any): string => {
    if (typeof text !== 'string') return "";
    if (!text) return "";
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');
    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = extractJson(jsonStr);
        if (!cleanStr) return false;
        const data = JSON.parse(cleanStr);
        if (schema && schema.properties) {
             const required = schema.required || [];
             return required.every((key: string) => key in data && data[key] !== undefined);
        }
        return true;
    } catch (e) {
        return false;
    }
};

// --- GEMINI API SERVICE ---

// Safe Environment Access
export const getSafeEnvApiKey = () => {
    try {
        // @ts-ignore
        if (typeof process !== 'undefined' && process && process.env) {
            return process.env.API_KEY;
        }
    } catch (e) {
        // Ignore reference errors
    }
    return undefined;
};

// Mutable storage for API key to support runtime updates via UI
// Default to 'demo-mode' if no env key is present to prevent blocking UI
let storedApiKey = getSafeEnvApiKey() || "demo-mode";

export const setStoredApiKey = (key: string) => {
    storedApiKey = key;
};

const getApiKey = () => storedApiKey;

/**
 * Performs a real connectivity test to ensure the API key is valid.
 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    if (apiKey === 'demo-mode') return true;
    const ai = new GoogleGenAI({ apiKey });
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: 'ping',
        });
        return !!response.text;
    } catch (e) {
        console.error("API Key validation failed:", e);
        return false;
    }
};

const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    console.warn("API Error intercepted:", msg, status);

    // Explicitly return a code, NEVER call external UI globals
    if (msg.includes("entity was not found") || msg.includes("API_KEY_INVALID") || status === 403 || status === 404) {
        return "AUTH_ERROR";
    }
    return null;
};

const withTimeout = <T>(promise: Promise<T>, ms: number, message: string): Promise<T> => {
    let timeoutId: any;
    const timeoutPromise = new Promise<T>((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(message)), ms);
    });
    return Promise.race([
        promise.then(
            val => { clearTimeout(timeoutId); return val; },
            err => { clearTimeout(timeoutId); throw err; }
        ),
        timeoutPromise
    ]);
};

/**
 * FAST REFINEMENT: Optional, non-blocking scientific polish.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false
): Promise<string> => {
    if (!content) return content;
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') return content;

    const ai = new GoogleGenAI({ apiKey });
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
    const systemInstruction = `You are a Senior Scientific Editor. Review output for academic rigor. Output ONLY ${isJson ? 'valid JSON' : 'Markdown'}.`;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: `Refine the following archival node content:\n\n${content}`,
            config: { systemInstruction, temperature: 0.1 }
        });
        const refinedText = response.text || content;
        return isJson ? extractJson(refinedText) : refinedText;
    } catch (e) {
        return isJson ? extractJson(content) : content;
    }
};

/**
 * CONTEXT OPTIMIZATION: Generates a concise summary of a completed step.
 */
export const generateNodeSummary = async (content: string, field: string): Promise<string> => {
    if (!content) return "";
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') return "Demo Mode: Simulated summary of the content.";

    const ai = new GoogleGenAI({ apiKey });
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Concisely summarize the following scientific discovery node in 2-3 sentences for a PI dashboard in the field of ${field}:\n\n${content}`,
            config: { temperature: 0.3 }
        });
        return response.text?.trim() || "Node summary unavailable.";
    } catch (e) {
        return content.slice(0, 200) + "...";
    }
};

/**
 * CORE WORKFLOW EXECUTION: Performs the primary archival call with robust timeout and grounding handling.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    const apiKey = getApiKey();

    // DEMO MODE SIMULATION
    if (apiKey === 'demo-mode') {
        await new Promise(r => setTimeout(r, 1500)); // Simulate latency
        if (expectJson) {
            if (params.contents.includes("RESEARCH QUESTION")) {
                return JSON.stringify({
                    research_question: "Simulated Question: How does simulated data affect demo environments?",
                    uniqueness_score: 0.95,
                    justification: "This is a high-fidelity simulation for demo purposes.",
                    field: context.experimentField || "Simulation Science"
                });
            }
            if (params.contents.includes("Literature review")) {
                return JSON.stringify({
                    summary: "This is a simulated literature review. In demo mode, real search grounding is disabled.",
                    research_gaps: "Lack of real API keys in demo environments.",
                    references: [{ title: "The Simulation Hypothesis", authors: ["Nick Bostrom"], year: "2003", url: "https://simulation-argument.com" }]
                });
            }
            // Default mock for other JSON steps
            return JSON.stringify({ summary: "Demo analysis complete.", charts: [] });
        }
        return "## Demo Mode Output\n\nThis is a simulated response generated because the application is running in **Demo Mode**. To see real AI-generated scientific content, please provide a valid API key.";
    }

    const ai = new GoogleGenAI({ apiKey });

    try {
        const response = await withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }),
            60000, // 60s timeout
            "Archival synthesis timed out."
        );

        let output = response.text || "";

        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (!expectJson && groundingChunks && Array.isArray(groundingChunks)) {
            let citations = "\n\n### Grounding Citations\n";
            groundingChunks.forEach((chunk: any) => {
                if (chunk.web && chunk.web.uri) {
                    citations += `- [${chunk.web.title || chunk.web.uri}](${chunk.web.uri})\n`;
                }
            });
            output += citations;
        }

        return expectJson ? extractJson(output) : output;
    } catch (e: any) {
        const authStatus = await handleApiError(e);
        if (authStatus === "AUTH_ERROR") {
             throw new Error("API Key Invalid or Model Not Found. Please check your settings.");
        }
        throw e;
    }
};

export const callGeminiWithRetry = async (model: string, params: { contents: string, config?: any }): Promise<GenerateContentResponse> => {
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') {
        return { 
            text: "Simulated response in Demo Mode.",
            candidates: [] 
        } as any;
    }

    const ai = new GoogleGenAI({ apiKey });
    try {
        return await withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }),
            60000,
            "Archive link unstable."
        );
    } catch (e: any) {
        const authStatus = await handleApiError(e);
        if (authStatus === "AUTH_ERROR") {
             throw new Error("API Key Invalid or Model Not Found.");
        }
        throw e;
    }
};

export const callGeminiStreamWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') {
        // Return a simulated async iterator for demo mode
        return (async function* () {
            yield { text: "Simulating streaming response..." };
            await new Promise(r => setTimeout(r, 500));
            yield { text: "\n\n**Demo Mode Active**\n\nGenerated content is simulated." };
        })();
    }

    const ai = new GoogleGenAI({ apiKey });
    try {
        return await ai.models.generateContentStream({
            model: model,
            contents: params.contents,
            config: params.config
        });
    } catch (e: any) {
        const authStatus = await handleApiError(e);
        if (authStatus === "AUTH_ERROR") {
             throw new Error("API Key Invalid or Model Not Found.");
        }
        throw e;
    }
};

export const parseGeminiError = (error: any, fallback = "Hypatia link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync') || msg.includes('timed out')) return "Archive link unstable. High traffic in the archival network. Please retry synthesis.";
    if (msg.includes('safety')) return "Safety filter triggered.";
    if (msg.includes('API Key Invalid')) return "Authentication Error: Please check your API key in Settings.";
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};
    const getSummary = (sId: number) => data[sId]?.summary || (data[sId]?.output ? (data[sId].output.slice(0, 300) + '...') : 'N/A');
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 7) context.analysis_summary = getSummary(7);

    if (stepId === 10) {
        let log = '';
        WORKFLOW_STEPS.forEach(s => { if(s.id < 10) log += `[${s.title}] ${getSummary(s.id)}\n\n`; });
        context.full_project_summary_log = log;
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    const settings = fineTuneSettings || {};
    let systemInstruction = `You are Hypatia, a professional AI Scientist. Research Field: ${context.experimentField}. Output academic, rigorous Markdown.`;
    let basePrompt = regenerateFeedback ? `[PI FEEDBACK: ${regenerateFeedback}]\n\n` : "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.7 };

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `CRITICAL: YOU MUST OUTPUT ONLY VALID JSON. REFINE RESEARCH QUESTION. Input: "${userInput}". Output valid JSON with "research_question", "uniqueness_score", "justification", "field".`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            expectJson = true;
            basePrompt += `Literature review for: "${context.question}". Use Google Search. Output JSON per LITERATURE_REVIEW_SCHEMA.`;
            config.tools = [{ googleSearch: {} }];
            config.responseMimeType = "application/json";
            config.responseSchema = LITERATURE_REVIEW_SCHEMA;
            break;
        case 3:
            basePrompt += `Formulate 3 distinct hypotheses for: "${context.question}". Use context: "${context.literature_review_summary}".`;
            break;
        case 4:
            basePrompt += `Detailed experimental methodology for: "${context.hypothesis}".`;
            break;
        case 5:
            basePrompt += `Data collection plan for methodology: "${context.methodology_summary}".`;
            break;
        case 6:
            basePrompt += `Generate synthetic CSV data for: "${context.methodology_summary}".`;
            break;
        case 7:
            expectJson = true;
            basePrompt += `Analyze data: ${userInput}. Return JSON with "summary" and "charts" (imageData).`;
            config.responseMimeType = "application/json";
            config.responseSchema = DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
            break;
        case 8:
            basePrompt += `Draft conclusions from analysis summary: "${context.analysis_summary}".`;
            break;
        case 9:
            basePrompt += `Simulate a skeptical peer review for:\n${context.full_project_summary_log}`;
            break;
        case 10:
            basePrompt += `Draft a comprehensive scientific publication for:\n${context.full_project_summary_log}`;
            break;
        default:
            basePrompt += `Continue research on Step ${stepId}.`;
    }

    return { basePrompt, expectJson, config };
};

// --- AGENTIC WORKFLOW RUNNER ---
export const runAgenticWorkflow = async ({
    experiment,
    stepId,
    agentName,
    startMessage,
    updateLog,
    model = 'gemini-3-flash-preview',
    expectJson = false,
    schema = undefined,
    extraInput = '',
    extraConfig = {}
}: {
    experiment: Experiment;
    stepId: number;
    agentName: string;
    startMessage: string;
    updateLog: (agent: string, message: string) => void;
    model?: string;
    expectJson?: boolean;
    schema?: any;
    extraInput?: string;
    extraConfig?: any;
}) => {
    const context = await getStepContext(experiment, stepId);
    const { basePrompt, config } = getPromptForStep(stepId, extraInput, context, {});
    updateLog(agentName, startMessage);

    return await executeStepWorkflow(model, { 
        contents: basePrompt, 
        config: { ...config, ...extraConfig } 
    }, context, expectJson, schema);
};

export const runLiteratureReviewAgent = async ({ experiment, updateLog }) => {
    return await runAgenticWorkflow({
        experiment,
        stepId: 2,
        agentName: 'Hypatia',
        startMessage: 'Linking with global search indices...',
        updateLog,
        expectJson: true,
        schema: LITERATURE_REVIEW_SCHEMA
    });
};

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }) => {
    const finalOutput = await runAgenticWorkflow({
        experiment,
        stepId: 7,
        agentName: 'Hypatia',
        startMessage: 'Computing statistical models...',
        updateLog,
        extraInput: csvData,
        expectJson: true,
        schema: DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA
    });
    return { finalOutput, logSummary: "Analysis node synchronized." };
};

export const runPeerReviewAgent = async ({ experiment, updateLog }) => {
    return await runAgenticWorkflow({
        experiment,
        stepId: 9,
        agentName: 'Reviewer',
        startMessage: 'Performing adversarial audit...',
        updateLog,
        model: 'gemini-3-pro-preview'
    });
};

export const runPublicationAgent = async ({ experiment, updateLog }) => {
    return await runAgenticWorkflow({
        experiment,
        stepId: 10,
        agentName: 'Hypatia',
        startMessage: 'Synthesizing final technical draft...',
        updateLog,
        model: 'gemini-3-pro-preview',
        extraConfig: { thinkingConfig: { thinkingBudget: 8000 } }
    });
};

import React, { useState, useEffect, useRef } from 'react';
import { Experiment } from './config';
import { db } from './be_db';
import { testApiKey, parseGeminiError, setStoredApiKey, getSafeEnvApiKey } from './services';
import { useToast } from './toast';
import { ExperimentContext } from './context/ExperimentContext';
import { ErrorBoundary } from './components/common/ErrorBoundary';

import { Header } from './components/common/Header';
import { Footer } from './components/common/Footer';
import { LandingPage } from './components/landing/LandingPage';
import { Dashboard } from './components/dashboard/Dashboard';
import { ExperimentWorkspace } from './components/workspace/ExperimentWorkspace';
import { TestRunner } from './components/testing/TestRunner';
import { LabNotebook } from './components/workspace/LabNotebook';

/**
 * @component App
 * The root component that manages the overall application state and routing.
 */
export const App = () => {
    const [view, setView] = useState('landing'); 
    const [experiments, setExperiments] = useState<Experiment[]>([]);
    const [activeExperiment, setActiveExperiment] = useState<Experiment | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [isLabNotebookOpen, setLabNotebookOpen] = useState(false);

    // Ref to track if we have already completed initialization to prevent re-triggering loader
    const isInitialized = useRef(false);

    const { addToast } = useToast();

    useEffect(() => {
        let mounted = true;
        const loadData = async () => {
            if (isInitialized.current) return;

            try {
                // Defensive check for DB
                if (!db || !db.experiments) {
                    throw new Error("Local database protocol failed.");
                }

                const dbPromise = db.experiments.orderBy('createdAt').reverse().toArray();
                const storedExperiments = await dbPromise as Experiment[];

                if (mounted) {
                    setExperiments(storedExperiments);
                    if (storedExperiments.length > 0) {
                        setActiveExperiment(storedExperiments[0]);
                    }

                    // Auto-detect environment key using safe accessor
                    const envKey = getSafeEnvApiKey();
                    if (envKey) {
                         setIsAuthenticated(true);
                    } else {
                        // Default to Demo Mode silently if no key is present to avoid blocking UI
                        setStoredApiKey('demo-mode');
                        setIsAuthenticated(true);
                    }
                }
            } catch (error) {
                console.warn("Data load warning:", error);
                if (mounted) addToast("Could not access local archives.", 'warning');
            } finally {
                if (mounted) {
                    setIsLoading(false);
                    isInitialized.current = true;
                }
            }
        };

        // Safety timeout to ensure app never hangs on loading screen
        const safetyTimeout = setTimeout(() => {
            if (mounted && isLoading) {
                console.warn("Initialization timed out, forcing render.");
                setIsLoading(false);
                isInitialized.current = true;
            }
        }, 2000);

        loadData().then(() => clearTimeout(safetyTimeout));

        return () => { mounted = false; clearTimeout(safetyTimeout); };
    }, []);

    useEffect(() => {
        if (isAuthenticated && view === 'landing') {
             setTimeout(() => window.scrollTo({ top: 0, behavior: 'smooth' }), 100);
        }
    }, [isAuthenticated, view]);

    const handleAuthentication = async (type: 'promo' | 'key' | 'demo', value: string) => {
        const validPromoCodes = ['MTI', 'HYPATIA-ALPHA', 'PRO-ACCESS', 'HYPATIA-2025'];

        if (type === 'demo') {
            setStoredApiKey('demo-mode');
            setIsAuthenticated(true);
            addToast("Demo Mode Active. AI features will be simulated.", 'info');
            return;
        }

        if (type === 'promo' && validPromoCodes.includes(value.toUpperCase())) {
            // Check safe env key
            if (getSafeEnvApiKey()) {
                setIsAuthenticated(true);
                addToast("Environment Link Active.", 'success');
                return;
            } else {
                addToast("Promo code accepted. Entering Demo Mode.", 'info');
                setStoredApiKey('demo-mode');
                setIsAuthenticated(true);
                return;
            }
        }

        if (type === 'key' && value) {
            try {
                const isValid = await testApiKey(value);
                if (isValid) {
                    setStoredApiKey(value);
                    setIsAuthenticated(true);
                    addToast("API Key Verified.", 'success');
                } else {
                    addToast("Invalid API Key.", 'danger');
                }
            } catch (error) {
                addToast("Authentication failed.", 'danger');
            }
            return;
        }
    };

    const createNewExperiment = async (title: string, description: string, field: string) => {
        const newId = `exp_${Date.now()}`;
        const newExperiment: Experiment = {
            id: newId,
            title,
            description,
            field,
            currentStep: 1,
            stepData: {
                1: {
                    input: `Title: ${title}\n\nDescription: ${description}`,
                    history: [],
                    provenance: [],
                }
            },
            fineTuneSettings: {},
            createdAt: new Date().toISOString(),
            labNotebook: '',
            automationMode: null,
            status: 'active',
        };
        try {
            await db.experiments.add(newExperiment);
            setExperiments(prev => [newExperiment, ...prev]);
            setActiveExperiment(newExperiment);
            setView('experiment');
            addToast("Project initialized.", 'success');
        } catch (error) {
            console.error("Failed to save new experiment:", error);
            addToast("Failed to create project.", 'danger');
        }
    };

    const importExperiment = async (experimentData: Experiment) => {
        try {
            if (!experimentData.id || !experimentData.title || !experimentData.createdAt) {
                throw new Error("Invalid experiment file format.");
            }
            const existing = await db.experiments.get(experimentData.id);
            if(existing) {
                if(!window.confirm("An experiment with this ID already exists. Overwrite it?")) {
                    return;
                }
                await db.experiments.put(experimentData);
            } else {
                await db.experiments.add(experimentData);
            }
            const storedExperiments = await db.experiments.orderBy('createdAt').reverse().toArray();
            setExperiments(storedExperiments);
            addToast(`Project imported.`, 'success');

        } catch(error) {
             addToast(`Failed to import project.`, 'danger');
        }
    }

    const updateExperiment = async (updatedExperiment: Experiment): Promise<Experiment> => {
        try {
            const experimentWithTimestamp = { ...updatedExperiment, updatedAt: new Date().toISOString() };
            await db.experiments.put(experimentWithTimestamp);
            setExperiments(prev => prev.map(e => e.id === experimentWithTimestamp.id ? experimentWithTimestamp : e));
            if (activeExperiment?.id === experimentWithTimestamp.id) {
                setActiveExperiment(experimentWithTimestamp);
            }
            return experimentWithTimestamp;
        } catch (error) {
            console.error("Failed to update experiment:", error);
            throw error;
        }
    };

    const deleteExperiment = async (id: string) => {
        if (window.confirm("Are you sure you want to delete this project?")) {
            try {
                await db.experiments.delete(id);
                const updatedExperiments = experiments.filter(e => e.id !== id);
                setExperiments(updatedExperiments);
                if (activeExperiment?.id === id) {
                    setActiveExperiment(updatedExperiments.length > 0 ? updatedExperiments[0] : null);
                    if(updatedExperiments.length > 0) {
                        setView('dashboard');
                    } else {
                        setView('landing');
                    }
                }
                addToast("Project deleted.", 'success');
            } catch (error) {
                addToast("Failed to delete project.", 'danger');
            }
        }
    };

    const selectExperiment = (id: string) => {
        const experiment = experiments.find(e => e.id === id);
        if (experiment) {
            setActiveExperiment(experiment);
            setView('experiment');
        }
    };

    const contextValue = {
        experiments,
        activeExperiment,
        isAuthenticated,
        createNewExperiment,
        updateExperiment,
        deleteExperiment,
        selectExperiment,
        setActiveExperiment,
        importExperiment,
        handleAuthentication,
    };

    if (isLoading) {
        return (
            <div className="d-flex align-items-center justify-content-center vh-100 bg-dark text-white">
                <div className="text-center">
                    <div className="spinner-border text-primary-glow mb-4" role="status" style={{width: '3rem', height: '3rem'}}></div>
                    <h5 className="fw-light ls-1 text-uppercase">Initializing Hypatia...</h5>
                    <p className="text-white-50 small mt-2">Establishing secure archival link</p>
                </div>
            </div>
        );
    }

    return (
        <ErrorBoundary>
            <ExperimentContext.Provider value={contextValue}>
                <Header setView={setView} activeView={view} onToggleNotebook={() => setLabNotebookOpen(p => !p)} />
                <main className="container-fluid mt-4">
                    {view === 'landing' && <LandingPage setView={setView} />}
                    {view === 'dashboard' && <Dashboard setView={setView} />}
                    {view === 'experiment' && activeExperiment && <ExperimentWorkspace key={activeExperiment.id} />}
                    {view === 'testing' && <TestRunner />}
                </main>
                {activeExperiment && isAuthenticated && (
                    <LabNotebook 
                        isOpen={isLabNotebookOpen} 
                        onClose={() => setLabNotebookOpen(false)}
                    />
                )}
                <Footer />
            </ExperimentContext.Provider>
        </ErrorBoundary>
    );
};

import React, { ReactNode, ErrorInfo } from 'react';

interface ErrorBoundaryProps {
    children?: ReactNode;
}

interface ErrorBoundaryState {
    hasError: boolean;
    error: any;
}

export class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
    public state: ErrorBoundaryState = {
        hasError: false,
        error: null
    };

    static getDerivedStateFromError(error: any): ErrorBoundaryState {
        return { hasError: true, error };
    }

    componentDidCatch(error: any, errorInfo: ErrorInfo) {
        console.error("Uncaught error:", error, errorInfo);
    }

    render() {
        if (this.state.hasError) {
            return (
                <div className="d-flex align-items-center justify-content-center vh-100 bg-dark" style={{position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', zIndex: 9999}}>
                    <div className="container text-center">
                        <div className="card border-danger bg-black text-white p-4 shadow-lg mx-auto" style={{maxWidth: '600px'}}>
                            <div className="card-body">
                                <i className="bi bi-exclamation-octagon-fill text-danger mb-3" style={{fontSize: '3rem'}}></i>
                                <h4 className="fw-bold text-danger mb-3">System Protocol Failure</h4>
                                <p className="text-white-50 mb-4">
                                    A critical rendering error occurred. The application state has been preserved safely in the database.
                                </p>
                                <div className="bg-dark border border-secondary border-opacity-25 rounded p-3 text-start mb-4 font-monospace small text-danger overflow-auto" style={{maxHeight: '150px'}}>
                                    {this.state.error?.message || "Unknown Error"}
                                </div>
                                <button className="btn btn-primary px-4" onClick={() => window.location.reload()}>
                                    <i className="bi bi-arrow-clockwise me-2"></i> Reboot Hypatia
                                </button>
