                    </div>
                </div>
            </div>
        </div>
    );

    return (
        <>
            {createPortal(menuOverlay, document.body)}
            {showHelp && <HelpModal onClose={() => { setShowHelp(false); onClose(); }} />}
            {showSettings && createPortal(settingsModal, document.body)}
        </>
    );
};

