import { GoogleGenAI, Type, Modality, GenerateContentResponse } from "@google/genai";
import {
    Experiment,
    FineTuneSettings,
    STEP_SPECIFIC_TUNING_PARAMETERS,
    DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
    LITERATURE_REVIEW_SCHEMA,
    RESEARCH_QUESTION_SCHEMA,
    WORKFLOW_STEPS,
} from './config';

// Re-export context hook for simplified imports in components
export { useExperiment } from './context/ExperimentContext';

// --- UTILITIES ---

export const extractJson = (text: any): string => {
    if (typeof text !== 'string') return "";
    if (!text) return "";
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');
    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

export const isValidJsonForSchema = (jsonStr: string, schema: any): boolean => {
    try {
        const cleanStr = extractJson(jsonStr);
        if (!cleanStr) return false;
        const data = JSON.parse(cleanStr);
        if (schema && schema.properties) {
             const required = schema.required || [];
             return required.every((key: string) => key in data && data[key] !== undefined);
        }
        return true;
    } catch (e) {
        return false;
    }
};

// --- GEMINI API SERVICE ---

// Safe Environment Access
export const getSafeEnvApiKey = () => {
    try {
        // @ts-ignore
        if (typeof process !== 'undefined' && process && process.env) {
            return process.env.API_KEY;
        }
    } catch (e) {
        // Ignore reference errors
    }
    return undefined;
};

// Mutable storage for API key to support runtime updates via UI
// Default to 'demo-mode' if no env key is present to prevent blocking UI
let storedApiKey = getSafeEnvApiKey() || "demo-mode";

export const setStoredApiKey = (key: string) => {
    storedApiKey = key;
};

export const getCurrentApiKey = () => storedApiKey;

const getApiKey = () => storedApiKey;

export const getKeyStatus = () => {
    const envKey = getSafeEnvApiKey();
    if (storedApiKey === 'demo-mode') return { type: 'demo', label: 'Demo Mode Active', color: 'bg-info' };
    // Check if the stored key matches the env key (if env key exists)
    if (envKey && storedApiKey === envKey) return { type: 'env', label: 'Environment Key Linked', color: 'bg-success' };
    return { type: 'manual', label: 'Manual Key Active', color: 'bg-warning' };
};

/**
 * Performs a real connectivity test to ensure the API key is valid.
 */
export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    if (apiKey === 'demo-mode') return true;
    const ai = new GoogleGenAI({ apiKey });
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: 'ping',
        });
        return !!response.text;
    } catch (e) {
        console.error("API Key validation failed:", e);
        return false;
    }
};

const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    console.warn("API Error intercepted:", msg, status);

    // Explicitly return a code, NEVER call external UI globals
    if (msg.includes("entity was not found") || msg.includes("API_KEY_INVALID") || status === 403 || status === 404) {
        return "AUTH_ERROR";
    }
    return null;
};

const withTimeout = <T>(promise: Promise<T>, ms: number, message: string): Promise<T> => {
    let timeoutId: any;
    const timeoutPromise = new Promise<T>((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(message)), ms);
    });
    return Promise.race([
        promise.then(
            val => { clearTimeout(timeoutId); return val; },
            err => { clearTimeout(timeoutId); throw err; }
        ),
        timeoutPromise
    ]);
};

/**
 * FAST REFINEMENT: Optional, non-blocking scientific polish.
 */
export const refineWithSubjectExpert = async (
    content: string, 
    context: any, 
    isJson: boolean = false
): Promise<string> => {
    if (!content) return content;
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') return content;

    const ai = new GoogleGenAI({ apiKey });
    const model = isJson ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
    const systemInstruction = `You are a Senior Scientific Editor. Review output for academic rigor. Output ONLY ${isJson ? 'valid JSON' : 'Markdown'}.`;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: `Refine the following archival node content:\n\n${content}`,
            config: { systemInstruction, temperature: 0.1 }
        });
        const refinedText = response.text || content;
        return isJson ? extractJson(refinedText) : refinedText;
    } catch (e) {
        return isJson ? extractJson(content) : content;
    }
};

/**
 * CONTEXT OPTIMIZATION: Generates a concise summary of a completed step.
 */
export const generateNodeSummary = async (content: string, field: string): Promise<string> => {
    if (!content) return "";
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') return "Demo Mode: Simulated summary of the content.";

    const ai = new GoogleGenAI({ apiKey });
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Concisely summarize the following scientific discovery node in 2-3 sentences for a PI dashboard in the field of ${field}:\n\n${content}`,
            config: { temperature: 0.3 }
        });
        return response.text?.trim() || "Node summary unavailable.";
    } catch (e) {
        return content.slice(0, 200) + "...";
    }
};

/**
 * CORE WORKFLOW EXECUTION: Performs the primary archival call with robust timeout and grounding handling.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    const apiKey = getApiKey();

    // DEMO MODE SIMULATION
    if (apiKey === 'demo-mode') {
        await new Promise(r => setTimeout(r, 1500)); // Simulate latency
        if (expectJson) {
            if (params.contents.includes("RESEARCH QUESTION")) {
                return JSON.stringify({
                    research_question: "Simulated Question: How does simulated data affect demo environments?",
                    uniqueness_score: 0.95,
                    justification: "This is a high-fidelity simulation for demo purposes.",
                    field: context.experimentField || "Simulation Science"
                });
            }
            if (params.contents.includes("Literature review")) {
                return JSON.stringify({
                    summary: "This is a simulated literature review. In demo mode, real search grounding is disabled.",
                    research_gaps: "Lack of real API keys in demo environments.",
                    references: [{ title: "The Simulation Hypothesis", authors: ["Nick Bostrom"], year: "2003", url: "https://simulation-argument.com" }]
                });
            }
            // Default mock for other JSON steps
            return JSON.stringify({ summary: "Demo analysis complete.", charts: [] });
        }
        return "## Demo Mode Output\n\nThis is a simulated response generated because the application is running in **Demo Mode**. To see real AI-generated scientific content, please provide a valid API key.";
    }

    const ai = new GoogleGenAI({ apiKey });

    try {
        const response = await withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }),
            60000, // 60s timeout
            "Archival synthesis timed out."
        );

        let output = response.text || "";

        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (!expectJson && groundingChunks && Array.isArray(groundingChunks)) {
            let citations = "\n\n### Grounding Citations\n";
            groundingChunks.forEach((chunk: any) => {
                if (chunk.web && chunk.web.uri) {
                    citations += `- [${chunk.web.title || chunk.web.uri}](${chunk.web.uri})\n`;
                }
            });
            output += citations;
        }

        return expectJson ? extractJson(output) : output;
    } catch (e: any) {
        const authStatus = await handleApiError(e);
        if (authStatus === "AUTH_ERROR") {
             throw new Error("API Key Invalid or Model Not Found. Please check your settings.");
        }
        throw e;
    }
};

export const callGeminiWithRetry = async (model: string, params: { contents: string, config?: any }): Promise<GenerateContentResponse> => {
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') {
        return { 
            text: "Simulated response in Demo Mode.",
            candidates: [] 
        } as any;
    }

    const ai = new GoogleGenAI({ apiKey });
    try {
        return await withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }),
            60000,
            "Archive link unstable."
        );
    } catch (e: any) {
        const authStatus = await handleApiError(e);
        if (authStatus === "AUTH_ERROR") {
             throw new Error("API Key Invalid or Model Not Found.");
        }
        throw e;
    }
};

export const callGeminiStreamWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') {
        // Return a simulated async iterator for demo mode
        return (async function* () {
            yield { text: "Simulating streaming response..." };
            await new Promise(r => setTimeout(r, 500));
            yield { text: "\n\n**Demo Mode Active**\n\nGenerated content is simulated." };
        })();
    }

    const ai = new GoogleGenAI({ apiKey });
    try {
        return await ai.models.generateContentStream({
            model: model,
            contents: params.contents,
            config: params.config
        });
    } catch (e: any) {
        const authStatus = await handleApiError(e);
        if (authStatus === "AUTH_ERROR") {
             throw new Error("API Key Invalid or Model Not Found.");
        }
        throw e;
    }
};

export const parseGeminiError = (error: any, fallback = "Hypatia link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync') || msg.includes('timed out')) return "Archive link unstable. High traffic in the archival network. Please retry synthesis.";
    if (msg.includes('safety')) return "Safety filter triggered.";
    if (msg.includes('API Key Invalid')) return "Authentication Error: Please check your API key in Settings.";
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { experimentField: experiment.field };
    const data = experiment.stepData || {};
    const getSummary = (sId: number) => data[sId]?.summary || (data[sId]?.output ? (data[sId].output.slice(0, 300) + '...') : 'N/A');
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) context.question = getFull(1);
    if (stepId > 2) context.literature_review_summary = getSummary(2);
    if (stepId > 3) context.hypothesis = getFull(3);
    if (stepId > 4) context.methodology_summary = getSummary(4);
    if (stepId > 7) context.analysis_summary = getSummary(7);

    if (stepId === 10) {
        let log = '';
        WORKFLOW_STEPS.forEach(s => { if(s.id < 10) log += `[${s.title}] ${getSummary(s.id)}\n\n`; });
        context.full_project_summary_log = log;
    }
    return context;
};

export const getPromptForStep = (
