                    <div className="modal-body">
                        {parameters.length > 0 ? parameters.map(param => (
                            <div className="mb-3" key={param.name}>
                                <label htmlFor={param.name} className="form-label fw-bold">{param.label}</label>
                                {param.type === 'select' && (
                                    <select
                                        id={param.name}
