/**
 * CORE WORKFLOW EXECUTION: Performs the primary archival call with robust timeout and grounding handling.
 */
export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    const apiKey = getApiKey();

    // DEMO MODE SIMULATION
    if (apiKey === 'demo-mode') {
        await new Promise(r => setTimeout(r, 1500)); // Simulate latency
        if (expectJson) {
            if (params.contents.includes("RESEARCH QUESTION")) {
                return JSON.stringify({
                    research_question: "Simulated Question: How does simulated data affect demo environments?",
                    uniqueness_score: 0.95,
                    justification: "This is a high-fidelity simulation for demo purposes.",
                    field: context.experimentField || "Simulation Science"
                });
            }
            if (params.contents.includes("Literature review")) {
                return JSON.stringify({
                    summary: "This is a simulated literature review. In demo mode, real search grounding is disabled.",
                    research_gaps: "Lack of real API keys in demo environments.",
                    references: [{ title: "The Simulation Hypothesis", authors: ["Nick Bostrom"], year: "2003", url: "https://simulation-argument.com" }]
                });
            }
            // Default mock for other JSON steps
            return JSON.stringify({ summary: "Demo analysis complete.", charts: [] });
        }
        return "## Demo Mode Output\n\nThis is a simulated response generated because the application is running in **Demo Mode**. To see real AI-generated scientific content, please provide a valid API key.";
    }

    try {
        const ai = new GoogleGenAI({ apiKey });
        const response = await withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }),
            60000, // 60s timeout
            "Archival synthesis timed out."
        );

        let output = response.text || "";

        // Defensive access for grounding chunks
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (!expectJson && groundingChunks && Array.isArray(groundingChunks)) {
            let citations = "\n\n### Grounding Citations\n";
            groundingChunks.forEach((chunk: any) => {
                if (chunk.web && chunk.web.uri) {
                    citations += `- [${chunk.web.title || chunk.web.uri}](${chunk.web.uri})\n`;
                }
            });
            output += citations;
        }

        return expectJson ? extractJson(output) : output;
    } catch (e: any) {
        const authStatus = await handleApiError(e);
        if (authStatus === "AUTH_ERROR") {
             throw new Error("API Key Invalid or Model Not Found. Please check your settings.");
        }
        throw e;
    }
};

