export const runAgenticWorkflow = async ({
    experiment,
    stepId,
    agentName,
    startMessage,
    updateLog,
    model = 'gemini-3-flash-preview',
    expectJson = false,
    schema = undefined,
    extraInput = '',
    extraConfig = {}
}: {
    experiment: Experiment;
    stepId: number;
    agentName: string;
    startMessage: string;
    updateLog: (agent: string, message: string) => void;
    model?: string;
    expectJson?: boolean;
    schema?: any;
    extraInput?: string;
