import React, { useState, useMemo, useCallback } from 'react';
import { useExperiment } from '../../services';
import { Experiment } from '../../config';
import { ExperimentCard } from '../steps/ExperimentCard';
import { DeployModal } from './DeployModal';
import { useToast } from '../../toast';

export const Dashboard = ({ setView }) => {
    const { experiments, selectExperiment, deleteExperiment, updateExperiment, importExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();
    const [showDeployModal, setShowDeployModal] = useState(false);
    const [selectedExperiment, setSelectedExperiment] = useState<Experiment | null>(null);

    const activeExperiments = useMemo(() => experiments.filter(e => !e.status || e.status === 'active'), [experiments]);
    const archivedExperiments = useMemo(() => experiments.filter(e => e.status === 'archived'), [experiments]);

    const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const result = e.target?.result;
                if (typeof result !== 'string') throw new Error("File read failed");

                const imported = JSON.parse(result);
                // Basic validation
                if (!imported.id || !imported.title) throw new Error("Missing required experiment fields");

                importExperiment(imported);
            } catch (err) {
                console.error(err);
                addToast("Failed to parse experiment file. Ensure it is a valid JSON export.", 'danger');
            }
        };
        reader.onerror = () => addToast("Error reading file.", 'danger');
        reader.readAsText(file);

        // Reset input
        event.target.value = '';
    };

    const handleExport = useCallback((experiment: Experiment) => {
        try {
            const dataStr = JSON.stringify(experiment, null, 2);
            const blob = new Blob([dataStr], { type: "application/json" });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = `hypatia_export_${experiment.title.replace(/\s+/g, '_')}_${experiment.id.slice(-4)}.json`;
            link.click();
            URL.revokeObjectURL(url);
            addToast("Export started.", 'success');
        } catch (e) {
            addToast("Export failed.", 'danger');
        }
    }, [addToast]);

    const handleDeployClick = useCallback((experiment: Experiment) => {
        setSelectedExperiment(experiment);
        setShowDeployModal(true);
    }, []);

    const handleArchive = useCallback(async (exp: Experiment) => {
        if (window.confirm("Move this project to saved storage? It will be accessible from the 'Saved Projects' section.")) {
            await updateExperiment({ ...exp, status: 'archived' });
            addToast("Project archived.", 'success');
        }
    }, [updateExperiment, addToast]);

    const handleUnarchive = useCallback(async (exp: Experiment) => {
        await updateExperiment({ ...exp, status: 'active' });
        addToast("Project restored to active dashboard.", 'success');
    }, [updateExperiment, addToast]);

    return (
        <div className="container py-4">
            <div className="d-flex justify-content-between align-items-center mb-5">
                <div>
                    <h2 className="section-title mb-0 fw-bold">Research Dashboard</h2>
                    <p className="text-white-50 mb-0">Monitor and manage your active discovery nodes.</p>
                </div>
                <div className="d-flex gap-2">
                     <label className="btn btn-outline-secondary btn-sm d-flex align-items-center" style={{cursor: 'pointer'}}>
                        <i className="bi bi-upload me-2"></i> Import JSON
                        <input type="file" accept=".json" onChange={handleFileImport} style={{display: 'none'}} />
                    </label>
                    <button className="btn btn-primary shadow" onClick={() => setView('landing')}>
                        <i className="bi bi-plus-lg me-1"></i> New Project
                    </button>
                </div>
            </div>

            {activeExperiments.length === 0 && archivedExperiments.length === 0 && (
                 <div className="text-center p-5 dashboard-empty-state card border-dashed bg-transparent">
                    <i className="bi bi-journal-plus text-primary-glow" style={{fontSize: '3rem'}}></i>
                    <h4 className="mt-3 fw-bold">Initialize Your First Study</h4>
                    <p className="text-white-50 mx-auto" style={{maxWidth: '400px'}}>No research projects detected in local archival storage. Start a new discovery journey to begin.</p>
                    <button className="btn btn-primary mt-3 px-4" onClick={() => setView('landing')}>Create Project</button>
                </div>
            )}

            {activeExperiments.length > 0 ? (
                <div className="row g-4 mb-5">
                    {activeExperiments.map(exp => (
                        <ExperimentCard 
                            key={exp.id} 
                            exp={exp} 
                            onArchive={handleArchive} 
                            onUnarchive={handleUnarchive} 
                            deleteExperiment={deleteExperiment} 
                            selectExperiment={selectExperiment} 
                            handleDeployClick={handleDeployClick} 
                            handleExport={handleExport} 
                        />
                    ))}
                </div>
            ) : experiments.length > 0 && (
                <div className="alert alert-dark border-secondary border-opacity-25 bg-black bg-opacity-20 text-center mb-5 p-4">
                    <i className="bi bi-info-circle me-2"></i> All projects are currently archived.
                </div>
            )}

            {archivedExperiments.length > 0 && (
                <div className="mt-5 pt-5 border-top border-secondary border-opacity-10">
                    <div className="d-flex align-items-center mb-4">
                        <i className="bi bi-archive-fill text-muted me-3 fs-4"></i>
                        <h3 className="section-title mb-0 text-white-50">Saved Projects</h3>
                    </div>
                    <div className="row g-4">
                        {archivedExperiments.map(exp => (
                            <ExperimentCard 
                                key={exp.id} 
                                exp={exp} 
                                isArchived={true} 
                                onArchive={handleArchive} 
                                onUnarchive={handleUnarchive} 
                                deleteExperiment={deleteExperiment} 
                                selectExperiment={selectExperiment} 
                                handleDeployClick={handleDeployClick} 
                                handleExport={handleExport} 
                            />
                        ))}
                    </div>
                </div>
            )}

            {showDeployModal && selectedExperiment && (
                <DeployModal
                    experiment={selectedExperiment}
                    onClose={() => setShowDeployModal(false)}
                    onUpdateExperiment={updateExperiment}
                    onExportExperiment={handleExport}
                    isAuthenticated={isAuthenticated}
                />
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useExperiment } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry } from '../../../services';
import { AgenticAnalysisView } from '../../common/AgenticAnalysisView';

export const CodeSimulator = ({ onComplete, context }) => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const [code, setCode] = useState(activeExperiment.stepData[6]?.input || '');
    const [isInitializing, setIsInitializing] = useState(false);
    const [initLogs, setInitLogs] = useState([]);
    const { addToast } = useToast();
    const workerRef = useRef<Worker | null>(null);
    const isMounted = useRef(true);

    const [agenticRun, setAgenticRun] = useState({
        status: 'idle', 
        logs: [],
        iterations: 0,
        maxIterations: 25,
    });

    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    useEffect(() => {
        const createWorker = () => {
            const workerCode = `
                self.onmessage = (event) => {
                    const { code } = event.data;
                    let finished = false;
                    const hypatia = {
                        finish: (data, summary) => {
                            self.postMessage({ type: 'finish', payload: { data, summary } });
                            finished = true;
                        }
                    };
                    const consoleProxy = {
                        log: (...args) => {
                            const logMsg = args.map(arg => String(arg)).join(' ');
                            self.postMessage({ type: 'log', payload: logMsg });
                        }
                    };
                    try {
                        new Function('console', 'hypatia', code)(consoleProxy, hypatia);
                        if (!finished) self.postMessage({ type: 'done' });
                    } catch (e) {
                        self.postMessage({ type: 'error', payload: \`[\${e.name}] \${e.message}\` });
                    }
                };
            `;
            const blob = new Blob([workerCode], { type: 'application/javascript' });
            return new Worker(URL.createObjectURL(blob));
        };
        workerRef.current = createWorker();
        return () => { if (workerRef.current) workerRef.current.terminate(); };
    }, []);

    useEffect(() => {
        if (!code && isAuthenticated) {
            const runInitializationAgent = async () => {
                if (!isMounted.current) return;
                setIsInitializing(true);
                const log = (agent, message) => {
                    if (isMounted.current) setInitLogs(prev => [...prev, { agent, message }]);
                };
                try {
                    log('Simplifier', 'Extracting experimental variables from methodology...');

                    const simplifierPrompt = `
                        ACT AS: Senior Research Data Scientist.
                        TASK: Translate the following Experimental Methodology into a logical simulation specification for a coder.

                        INPUT CONTEXT:
                        - Hypothesis: "${context.hypothesis}"
                        - Methodology: "${context.methodology_summary}" (e.g. "Apply caffeine solution to Arabidopsis seedlings")
                        - Data Plan: "${context.data_collection_plan_summary}"

                        OUTPUT SPECIFICATION:
                        1. Identify the **Independent Variable** (e.g., Caffeine Concentration, Time).
                        2. Identify the **Dependent Variable** (e.g., Stem Length, Root Growth, Reaction Rate).
                        3. Define a **plausible mathematical relationship** between them (e.g., as concentration increases, growth decreases logarithmically; or linear growth over time).
                        4. Specify **Sample Size** (target 30-50 points) and **Data Types** (float, integer).

                        Provide clear, step-by-step logic for the simulation code.
                    `;

                    const simplifierResponse = await callGeminiWithRetry('gemini-3-flash-preview', { 
                        contents: simplifierPrompt 
                    });
                    if (!isMounted.current) return;
                    const instructions = simplifierResponse.text;

                    log('Coder', 'Generating autonomous simulation script...');

                    const coderPrompt = `
                        ACT AS: Scientific JavaScript Developer.
                        TASK: Write a JavaScript Web Worker script to simulate the experiment described below.

                        SIMULATION LOGIC SPEC:
                        ${instructions}

                        CRITICAL REQUIREMENTS:
                        1. **Data Generation**: Use a loop to generate 20-50 data points.
                        2. **Mathematical Model**: Implement the logic defined in the spec above. 
                        3. **NOISE**: You MUST add \`Math.random()\` variance to *every* dependent variable calculation to simulate real-world biological/physical variability. Data should look organic, not perfect.
                        4. **CSV Format**: Generate a valid CSV string with a header row.
                        5. **Final Handoff**: You MUST call \`hypatia.finish(csvData, summary)\` at the end of the script.
                           - \`csvData\`: The generated CSV string.
                           - \`summary\`: A short string explaining the simulated trend (e.g., "Simulated negative correlation between caffeine and growth.").

                        RESTRICTIONS:
                        - NO DOM access (no window, document, alert).
                        - Use \`console.log\` for debugging.

                        EXAMPLE CODE STRUCTURE:
                        \`\`\`javascript
                        const header = "Concentration_mM,Growth_cm";
                        let csv = header + "\\n";
                        for (let i = 0; i < 30; i++) {
                            const x = i * 5; // Independent
                            const noise = (Math.random() - 0.5) * 2; // Random variance
                            const y = Math.max(0, 10 - (0.1 * x) + noise); // Dependent logic with noise
                            csv += \`\${x},\${y.toFixed(2)}\\n\`;
                        }
                        hypatia.finish(csv, "Simulated growth inhibition with random noise.");
                        \`\`\`

                        Output ONLY the raw JavaScript code. Do not wrap in markdown code blocks if possible, or I will strip them.`;

                    const coderResponse = await callGeminiWithRetry('gemini-3-flash-preview', { 
                        contents: coderPrompt 
                    });
                    if (!isMounted.current) return;
                    const initialCode = coderResponse.text.trim().replace(/```javascript/g, '').replace(/```/g, '');
                    setCode(initialCode);
                    log('Coder', 'Initial script ready for testing.');
                } catch (err) {
                    if (isMounted.current) addToast("Failed to initialize coder.", "danger");
                } finally { 
                    if (isMounted.current) setIsInitializing(false); 
                }
            };
            runInitializationAgent();
        }
    }, [isAuthenticated, context, code, addToast]);

    const executeCodeInWorker = (codeToRun: string): Promise<any> => {
        return new Promise((resolve, reject) => {
            let timeoutId: any;

            const messageHandler = (event) => {
                const { type, payload } = event.data;
                if (type === 'log' && isMounted.current) {
                    setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Simulator', message: payload }] }));
                }

                if (type === 'finish' || type === 'done' || type === 'error') {
                    clearTimeout(timeoutId);
                    workerRef.current?.removeEventListener('message', messageHandler);
                    if (type === 'error') reject(payload); else resolve({ type, payload });
                }
            };

            // Watchdog Timer: Protect against infinite loops or hangs
            timeoutId = setTimeout(() => {
                workerRef.current?.removeEventListener('message', messageHandler);
                workerRef.current?.terminate(); // Hard reset of the worker environment

                // Re-initialize worker for the next attempt if mounted
                if (isMounted.current) {
                    const workerCode = `
                        self.onmessage = (event) => {
                            const { code } = event.data;
                            let finished = false;
                            const hypatia = {
                                finish: (data, summary) => {
                                    self.postMessage({ type: 'finish', payload: { data, summary } });
                                    finished = true;
                                }
                            };
                            const consoleProxy = {
                                log: (...args) => {
                                    const logMsg = args.map(arg => String(arg)).join(' ');
                                    self.postMessage({ type: 'log', payload: logMsg });
                                }
                            };
                            try {
                                new Function('console', 'hypatia', code)(consoleProxy, hypatia);
                                if (!finished) self.postMessage({ type: 'done' });
                            } catch (e) {
                                self.postMessage({ type: 'error', payload: \`[\${e.name}] \${e.message}\` });
                            }
                        };
                    `;
                    const blob = new Blob([workerCode], { type: 'application/javascript' });
                    workerRef.current = new Worker(URL.createObjectURL(blob));
                }
                reject("Execution Timeout: Simulation hung for over 10 seconds.");
            }, 10000);

            workerRef.current?.addEventListener('message', messageHandler);
            workerRef.current?.postMessage({ code: codeToRun });
        });
    };

    const runAgenticSimulation = async () => {
        if (agenticRun.status === 'running') return;
        setAgenticRun(prev => ({ ...prev, status: 'running', logs: [], iterations: 0 }));

        let currentCode = code;
        for (let i = 0; i < agenticRun.maxIterations; i++) {
            if (!isMounted.current) return;
            setAgenticRun(prev => ({ 
                ...prev, 
                iterations: i + 1, 
                logs: [...prev.logs, { agent: 'System', message: `Attempt ${i + 1}: Running simulation...` }] 
            }));

            try {
                const result = await executeCodeInWorker(currentCode);
                if (!isMounted.current) return;

                if (result.type === 'finish') {
                    setAgenticRun(prev => ({ ...prev, status: 'success' }));
                    onComplete(result.payload.data, result.payload.summary);
                    return;
                }
                throw new Error("Simulation execution completed but hypatia.finish() was never invoked.");
            } catch (error) {
                if (!isMounted.current) return;
                setAgenticRun(prev => ({ 
                    ...prev, 
                    logs: [...prev.logs, { agent: 'Debugger', message: `Logic failure detected: ${error}. Triggering Self-Healing Loop.` }] 
                }));

                const debuggerPrompt = `DEBUGGER LOG: The following code failed. 
                ERROR: "${error}". 
                MISSION: Fix the logic and ensure hypatia.finish(csvData, summary) is called with plausible simulated data.

                CODE:
                ${currentCode}`;

                try {
                    const res = await callGeminiWithRetry('gemini-3-flash-preview', { 
                        contents: debuggerPrompt 
                    });
                    if (isMounted.current) {
                        currentCode = res.text.trim().replace(/```javascript/g, '').replace(/```/g, '');
                        setCode(currentCode);
                        await new Promise(r => setTimeout(r, 1000));
                    }
                } catch (e) {
                    if (isMounted.current) addToast("Self-healing link unstable.", "warning");
                }
            }
        }
        if (isMounted.current) setAgenticRun(prev => ({ ...prev, status: 'failed' }));
    };

    return (
        <div>
            <div className="doc-section mb-3">
                <h6 className="fw-bold">AI Agent Simulation Hub</h6>
                <p className="small text-white-50">Specialized agents are drafting and debugging a JavaScript simulation of your methodology. The <strong>Self-Healing Debugger</strong> will autonomously resolve any runtime errors or logical hangs.</p>
            </div>
            {isInitializing && <AgenticAnalysisView agenticRun={{logs: initLogs, iterations: 0, maxIterations: 0}} title="Coder Agent Initializing..." />}
            <textarea 
                id="code-editor" 
                className="form-control mb-3 font-monospace bg-black text-primary-glow border-secondary border-opacity-25" 
                style={{ height: '300px', fontSize: '0.85rem' }}
                value={code} 
                onChange={(e) => setCode(e.target.value)} 
            />
            <button className="btn btn-primary w-100" onClick={runAgenticSimulation} disabled={!code || agenticRun.status === 'running'}>
                {agenticRun.status === 'running' ? 'Self-Healing Loop Active...' : 'Start Agentic Simulation'}
            </button>
            {agenticRun.logs.length > 0 && <AgenticAnalysisView agenticRun={agenticRun} title="Self-Healing Debugger Log" subtitle="Adversarial debugging logic is active." />}
        </div>
    );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { runDataAnalysisAgent, parseGeminiError } from '../../services';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { AgenticAnalysisView } from '../common/AgenticAnalysisView';

export const DataAnalysisWorkspace = ({ onStepComplete }) => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();
    const [agenticRun, setAgenticRun] = useState({
        status: 'idle', // 'idle', 'running', 'success', 'failed'
        iterations: 0,
        maxIterations: 2, 
        logs: [],
    });

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    const stepData = activeExperiment.stepData[7] || {};

    const performAgenticAnalysis = useCallback(async () => {
        if (!isAuthenticated || !stepData.input || agenticRun.status === 'running') return;

        setAgenticRun({ status: 'running', logs: [], iterations: 0, maxIterations: 2 });

        try {
            const { finalOutput, logSummary } = await runDataAnalysisAgent({
                experiment: activeExperiment,
                csvData: stepData.input,
                updateLog: (agent, message) => {
                    if (isMounted.current) {
                        setAgenticRun(prev => ({
                            ...prev,
                            logs: [...prev.logs, { agent, message }],
                            iterations: Math.min(prev.maxIterations, prev.iterations + 1)
                        }));
                    }
                },
            });

            if (!isMounted.current) return;

            const finalStepData = { ...stepData, output: finalOutput, suggestedInput: logSummary };
            await updateExperiment({ ...activeExperiment, stepData: { ...activeExperiment.stepData, 7: finalStepData } });
            setAgenticRun(prev => ({ ...prev, status: 'success' }));
            addToast("Analysis complete!", "success");
        } catch (error) {
            if (!isMounted.current) return;
            const errorMessage = parseGeminiError(error, "An unknown error occurred during analysis.");
            addToast(errorMessage, "danger");
            setAgenticRun(prev => ({ 
                ...prev, 
                status: 'failed',
                logs: [...prev.logs, { agent: 'System', message: `ERROR: ${errorMessage}` }]
            }));
        }

    }, [activeExperiment, isAuthenticated, addToast, updateExperiment, stepData, agenticRun.status]);

    useEffect(() => {
        if (!stepData.output && agenticRun.status === 'idle') {
            performAgenticAnalysis();
        }
    }, [stepData.output, agenticRun.status, performAgenticAnalysis]);

    return (
        <div className="data-analysis-container">
            <GeneratedOutput 
                stepId={7} 
                onGenerate={performAgenticAnalysis} 
                isLoading={agenticRun.status === 'running'} 
            />

            {(agenticRun.logs.length > 0 || agenticRun.status === 'running') && (
                <div className="mt-4 border-top border-secondary border-opacity-10 pt-4">
                    <AgenticAnalysisView 
                        agenticRun={agenticRun} 
                        title="Statistical Analysis Progress"
                        subtitle="A multi-agent workflow is analyzing your data and generating visualizations." 
                    />
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useExperiment } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry } from '../../../services';
import { DYNAMIC_TABLE_SCHEMA } from '../../../config';
import * as XLSX from 'xlsx';

export const ManualDataEntry = ({ onComplete, context }) => {
    const { isAuthenticated } = useExperiment();
    const [columns, setColumns] = useState<string[]>([]);
    const [rows, setRows] = useState<Record<string, string>[]>([]);
    const [isInitializing, setIsInitializing] = useState(true);
    const { addToast } = useToast();
    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    // Helper to safely access XLSX methods
    const getXLSX = () => {
        // @ts-ignore
        return XLSX.default || XLSX;
    }

    useEffect(() => {
        let active = true;

        if (isAuthenticated) {
            const prompt = `Based on the data collection plan summary: "${context.data_collection_plan_summary}", generate a JSON array of objects. Each object should represent a column for a data entry table and have two keys: "columnName" (string) and "dataType" (string, e.g., 'number', 'string'). For example: [{"columnName": "time_seconds", "dataType": "number"}, {"columnName": "temperature_celsius", "dataType": "number"}]. Output only the raw JSON array.`;
            callGeminiWithRetry('gemini-3-flash-preview', { 
                contents: prompt, 
                config: { responseMimeType: "application/json", responseSchema: DYNAMIC_TABLE_SCHEMA } 
            })
                .then(response => {
                    if (!active || !isMounted.current) return;
                    const schemaArray = JSON.parse(response.text);
                    if (!Array.isArray(schemaArray)) throw new Error("AI response was not a JSON array.");
                    const newColumns = schemaArray.map(col => col.columnName);

                    setColumns(newColumns);
                    setRows([Object.fromEntries(newColumns.map(c => [c, '']))]);
                })
                .catch(err => {
                    if (!active || !isMounted.current) return;
                    addToast(parseGeminiError(err, "AI failed to create a data entry form."), "danger");
                    setColumns(['Column 1', 'Column 2']);
                    setRows([{'Column 1': '', 'Column 2': ''}]);
                })
                .finally(() => {
                    if (active && isMounted.current) setIsInitializing(false);
                });
        }

        return () => { active = false; };
    }, [isAuthenticated, context, addToast]);

    const handleRowChange = (index, col, value) => {
        const newRows = [...rows];
        newRows[index][col] = value;
        setRows(newRows);
    };

    const addRow = () => setRows([...rows, Object.fromEntries(columns.map(c => [c, '']))]);
    const removeRow = (index) => setRows(rows.filter((_, i) => i !== index));

    const handleSubmit = () => {
        const header = columns.join(',');
        const body = rows.map(row => columns.map(col => `"${(row[col] || '').replace(/"/g, '""')}"`).join(',')).join('\n');
        const csvData = `${header}\n${body}`;
        onComplete(csvData, "Manually entered data.");
    };

    const handleDownloadTemplate = () => {
        if (columns.length === 0) {
            addToast("Columns are still being generated by the AI.", "warning");
            return;
        }
        try {
            const Lib = getXLSX();
            const ws = Lib.utils.aoa_to_sheet([columns]);
            const wb = Lib.utils.book_new();
            Lib.utils.book_append_sheet(wb, ws, "Data Entry");

            const wscols = columns.map(col => ({ wch: col.length + 5 }));
            ws['!cols'] = wscols;

            Lib.writeFile(wb, "Data_Entry_Template.xlsx");
            addToast("Excel template downloaded.", "success");
        } catch (e) {
            console.error(e);
            addToast("Failed to generate Excel template.", "danger");
        }
    };

    if (isInitializing) return <div className="text-center p-4"><div className="spinner-border"></div><p className="mt-2">AI is building your data entry form...</p></div>;

    return (
        <div>
            <div className="card mb-4">
                <div className="card-body">
                    <h6 className="fw-bold">Option 1: Use the Web Form</h6>
                    <p className="small text-white-50 mb-3">Enter your data directly into the table below. The form was generated by the AI based on your data collection plan.</p>
                    <div className="table-responsive">
                        <table className="table table-bordered">
                            <thead><tr>{columns.map(c => <th key={c}>{c}</th>)}<th>Actions</th></tr></thead>
                            <tbody>
                                {rows.map((row, rowIndex) => (
                                    <tr key={rowIndex}>
                                        {columns.map(col => <td key={col}><input type="text" className="form-control form-control-sm" value={row[col] || ''} onChange={e => handleRowChange(rowIndex, col, e.target.value)} /></td>)}
                                        <td><button className="btn btn-sm btn-outline-danger" onClick={() => removeRow(rowIndex)} disabled={rows.length <= 1}><i className="bi bi-trash"></i></button></td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                    <button className="btn btn-secondary me-2" onClick={addRow}><i className="bi bi-plus-lg me-1"></i> Add Row</button>
                    <button className="btn btn-success" onClick={handleSubmit}><i className="bi bi-check-circle-fill me-1"></i> Submit Data from Form</button>
                </div>
            </div>

            <div className="card">
                <div className="card-body">
                     <h6 className="fw-bold">Option 2: Use an Excel Template</h6>
                     <p className="small text-white-50 mb-3">For larger datasets, download a pre-formatted Excel template. After filling it out, go back and use the "Upload Your Data" mode to submit it.</p>
                     <button className="btn btn-info" onClick={handleDownloadTemplate} disabled={columns.length === 0}>
                         <i className="bi bi-file-earmark-excel-fill me-1"></i> Download Data Entry Template (.xlsx)
                     </button>
                 </div>
            </div>
        </div>
    );
};

