import React, { useState, useEffect, useRef } from 'react';
import { useExperiment } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry } from '../../../services';

export const DataSynthesizer = ({ onComplete, context }) => {
    const { isAuthenticated } = useExperiment();
    const [result, setResult] = useState<{ summary: string, csv: string } | null>(null);
    const [isSynthesizing, setIsSynthesizing] = useState(false);
    const { addToast } = useToast();

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    const handleSynthesize = async () => {
        if (!isAuthenticated) return;
        setIsSynthesizing(true);
        const prompt = `DATA PROVENANCE REQUIREMENT: You are synthesizing synthetic data. 
        Based on Methodology: "${context.methodology_summary}" and Data Plan: "${context.data_collection_plan_summary}", generate a plausible estimated dataset in CSV format. 

        **CRITICAL**: You MUST explicitly state in the summary that: "This experimental data was synthesized by AI Generation for theoretical exploration." 

        Output ONLY the CSV data and a brief, one-sentence summary. Separate with '---'.`;

        try {
            const response = await callGeminiWithRetry('gemini-3-flash-preview', { 
                contents: prompt 
            });

            if (isMounted.current) {
                const parts = response.text.split('---');
                if (parts.length >= 2) {
                     const summary = parts[0].trim();
                     const csv = parts[1].trim();
                     setResult({ summary, csv });
                     addToast("AI synthesized the dataset.", "success");
                } else {
                     // Fallback if separator missing
                     const content = response.text;
                     setResult({ summary: "Data synthesized by AI.", csv: content });
                     addToast("AI synthesized the dataset (formatting adjusted).", "warning");
                }
            }
        } catch (err) {
            if (isMounted.current) {
                addToast(parseGeminiError(err), "danger");
            }
        } finally { 
            if (isMounted.current) {
                setIsSynthesizing(false); 
            }
        }
    };

    return (
        <div className="text-center p-4">
            <h6 className="fw-bold"><i className="bi bi-magic me-2"></i>AI Data Synthesis</h6>
            <p className="text-white-50">Generate a plausible theoretical dataset using AI synthesis. This data is labeled as <strong>AI-Synthesized</strong>.</p>
            <button className="btn btn-primary" onClick={handleSynthesize} disabled={isSynthesizing}>
                {isSynthesizing ? 'Synthesizing...' : 'Generate Synthetic Dataset'}
            </button>
            {result && (
                <div className="mt-4 text-start">
                    <p className="small"><strong>Disclosure:</strong> {result.summary}</p>
                    <textarea className="form-control font-monospace mb-3" readOnly rows={6} value={result.csv} />
                    <button className="btn btn-success w-100" onClick={() => onComplete(result.csv, result.summary)}>Use This Data</button>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { appTests } from '../../index.test';

export const TestRunner = () => {
    const [results, setResults] = useState([]);
    const [isRunning, setIsRunning] = useState(false);

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    const runTests = async () => {
        setIsRunning(true);
        const testResults = [];
        // Clear previous results
        setResults([]);

        for (const test of appTests) {
            if (!isMounted.current) return; // Cancel execution if unmounted

            try {
                await test.fn();
                testResults.push({ name: test.name, passed: true });
            } catch (error) {
                const errorMsg = error instanceof Error ? error.message : String(error);
                testResults.push({ name: test.name, passed: false, error: errorMsg });
            }
            // Update UI progressively
            if (isMounted.current) {
                setResults([...testResults]);
            }
        }
        if (isMounted.current) {
            setIsRunning(false);
        }
    };

    useEffect(() => {
        runTests();
    }, []);

    const passedCount = results.filter(r => r.passed).length;
    const failedCount = results.filter(r => !r.passed).length;

    return (
        <div className="container py-4">
            <div className="card shadow-lg bg-dark border-secondary">
                <div className="card-header d-flex justify-content-between align-items-center py-3">
                    <div>
                        <h4 className="mb-0 fw-bold"><i className="bi bi-shield-shaded me-2 text-primary-glow"></i>System Health Audit</h4>
                        <p className="small text-white-50 mb-0">Validating research logic, archival protocols, and agentic workflows.</p>
                    </div>
                    <button className="btn btn-primary" onClick={runTests} disabled={isRunning}>
                        {isRunning ? (
                            <>
                                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                Auditing...
                            </>
                        ) : (
                            <><i className="bi bi-play-fill me-1"></i> Run Full Audit</>
                        )}
                    </button>
                </div>
                <div className="card-body">
                    {results.length > 0 && (
                        <div className="d-flex gap-4 mb-4 p-3 bg-black rounded-3 border border-secondary border-opacity-25">
                            <div className="text-center">
                                <div className="h3 mb-0 text-success fw-bold">{passedCount}</div>
                                <div className="small text-white-50 text-uppercase ls-1">Passed</div>
                            </div>
                            <div className="text-center">
                                <div className="h3 mb-0 text-danger fw-bold">{failedCount}</div>
                                <div className="small text-white-50 text-uppercase ls-1">Failed</div>
                            </div>
                            <div className="text-center">
                                <div className="h3 mb-0 text-primary-glow fw-bold">{results.length}</div>
                                <div className="small text-white-50 text-uppercase ls-1">Total</div>
                            </div>
                        </div>
                    )}

                    <div className="test-results-list">
                        {results.length === 0 && !isRunning && (
                            <div className="text-center p-5 text-white-50">
                                <i className="bi bi-clipboard2-pulse mb-3 d-block" style={{fontSize: '3rem', opacity: 0.3}}></i>
                                <p>No audit results yet. Click "Run Full Audit" to begin.</p>
                            </div>
                        )}

                        {results.map((result, index) => (
                            <div key={index} className={`d-flex align-items-start p-3 mb-2 rounded-2 border ${result.passed ? 'border-success border-opacity-25 bg-success bg-opacity-10' : 'border-danger border-opacity-25 bg-danger bg-opacity-10'}`}>
                                <div className="me-3">
                                    {result.passed ? (
                                        <i className="bi bi-check-circle-fill text-success fs-5"></i>
                                    ) : (
                                        <i className="bi bi-exclamation-triangle-fill text-danger fs-5"></i>
                                    )}
                                </div>
                                <div className="flex-grow-1">
                                    <div className={`fw-semibold ${result.passed ? 'text-success' : 'text-danger'}`}>{result.name}</div>
                                    {!result.passed && (
                                        <div className="mt-1 p-2 bg-dark rounded font-monospace small text-danger border border-danger border-opacity-10">
                                            {result.error || "Unknown error occurred"}
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}

                        {isRunning && (
                            <div className="text-center p-4">
                                <div className="spinner-grow text-primary-glow" role="status"></div>
                                <p className="mt-2 text-white-50 animate-pulse">Scanning archival nodes...</p>
