import React, { useState, useEffect, useRef } from 'react';
import { useToast } from '../../toast';
import * as XLSX from 'xlsx';

export const DataUploader = ({ onComplete }) => {
    const [file, setFile] = useState<File | null>(null);
    const [fileContent, setFileContent] = useState('');
    const { addToast } = useToast();

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    // Helper to safely access XLSX methods regardless of import structure
    const getXLSX = () => {
        // @ts-ignore
        return XLSX.default || XLSX;
    }

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (selectedFile) {
            setFile(selectedFile);
            const reader = new FileReader();

            if (selectedFile.name.endsWith('.csv')) {
                reader.onload = (event) => {
                    if (isMounted.current) {
                        const content = event.target?.result as string;
                        setFileContent(content);
                    }
                };
                reader.readAsText(selectedFile);
            } else if (selectedFile.name.endsWith('.xlsx')) {
                reader.onload = (event) => {
                    if (!isMounted.current) return;
                    try {
                        const Lib = getXLSX();
                        const data = event.target?.result;
                        const workbook = Lib.read(data, { type: 'array' });
                        const sheetName = workbook.SheetNames[0];
                        const worksheet = workbook.Sheets[sheetName];
                        const csvContent = Lib.utils.sheet_to_csv(worksheet);
                        setFileContent(csvContent);
                        addToast("Excel file parsed successfully.", 'success');
                    } catch (error) {
                        console.error("Error parsing XLSX file:", error);
                        addToast('Error parsing .xlsx file.', 'danger');
                        setFile(null);
                        setFileContent('');
                        e.target.value = '';
                    }
                };
                reader.readAsArrayBuffer(selectedFile);
            } else {
                addToast('Please upload a valid .csv or .xlsx file.', 'warning');
                e.target.value = ''; // Reset file input
                setFile(null);
                setFileContent('');
            }
        }
    };

    const handleSubmit = () => {
        if (!file || !fileContent) {
            addToast('Please select a file to upload.', 'warning');
            return;
        }
        const summary = `Data uploaded from file: ${file.name}`;
        onComplete(fileContent, summary);
    };

    return (
        <div>
            <h6 className="fw-bold">Upload Your Dataset</h6>
            <p className="text-white-50 small">Please select a CSV or Excel (.xlsx) file from your computer.</p>
            <div className="mb-3">
                <input type="file" className="form-control" accept=".csv,.xlsx" onChange={handleFileChange} />
            </div>
            {fileContent && (
                <div className="mb-3">
                    <label className="form-label small">File Preview (as CSV):</label>
                    <textarea className="form-control" readOnly rows={8} value={fileContent} />
                </div>
            )}
            <button className="btn btn-success" onClick={handleSubmit} disabled={!fileContent}>
                <i className="bi bi-check-circle-fill me-1"></i> Submit Uploaded Data
            </button>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useExperiment } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry } from '../../../services';
import { AgenticAnalysisView } from '../../common/AgenticAnalysisView';

export const CodeSimulator = ({ onComplete, context }) => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const [code, setCode] = useState(activeExperiment.stepData[6]?.input || '');
    const [isInitializing, setIsInitializing] = useState(false);
    const [initLogs, setInitLogs] = useState([]);
    const { addToast } = useToast();
    const workerRef = useRef<Worker | null>(null);
    const workerUrlRef = useRef<string | null>(null);
    const isMounted = useRef(true);

    const [agenticRun, setAgenticRun] = useState({
        status: 'idle', 
        logs: [],
        iterations: 0,
        maxIterations: 25,
    });

    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    useEffect(() => {
        const createWorker = () => {
            const workerCode = `
                self.onmessage = (event) => {
                    const { code } = event.data;
                    let finished = false;
                    const hypatia = {
                        finish: (data, summary) => {
                            self.postMessage({ type: 'finish', payload: { data, summary } });
                            finished = true;
                        }
                    };
                    const consoleProxy = {
                        log: (...args) => {
                            const logMsg = args.map(arg => String(arg)).join(' ');
                            self.postMessage({ type: 'log', payload: logMsg });
                        }
                    };
                    try {
                        new Function('console', 'hypatia', code)(consoleProxy, hypatia);
                        if (!finished) self.postMessage({ type: 'done' });
                    } catch (e) {
                        self.postMessage({ type: 'error', payload: \`[\${e.name}] \${e.message}\` });
                    }
                };
            `;
            const blob = new Blob([workerCode], { type: 'application/javascript' });
            const url = URL.createObjectURL(blob);
            workerUrlRef.current = url;
            return new Worker(url);
        };
        workerRef.current = createWorker();
        return () => { 
            if (workerRef.current) workerRef.current.terminate(); 
            if (workerUrlRef.current) URL.revokeObjectURL(workerUrlRef.current);
        };
    }, []);

    useEffect(() => {
        if (!code && isAuthenticated) {
            const runInitializationAgent = async () => {
                if (!isMounted.current) return;
                setIsInitializing(true);
                const log = (agent, message) => {
                    if (isMounted.current) setInitLogs(prev => [...prev, { agent, message }]);
                };
                try {
                    log('Simplifier', 'Extracting experimental variables from methodology...');

                    const simplifierPrompt = `
                        ACT AS: Senior Research Data Scientist.
                        TASK: Translate the following Experimental Methodology into a logical simulation specification for a coder.

                        INPUT CONTEXT:
                        - Hypothesis: "${context.hypothesis}"
                        - Methodology: "${context.methodology_summary}" (e.g. "Apply caffeine solution to Arabidopsis seedlings")
                        - Data Plan: "${context.data_collection_plan_summary}"

                        OUTPUT SPECIFICATION:
                        1. Identify the **Independent Variable** (e.g., Caffeine Concentration, Time).
                        2. Identify the **Dependent Variable** (e.g., Stem Length, Root Growth, Reaction Rate).
                        3. Define a **plausible mathematical relationship** between them (e.g., as concentration increases, growth decreases logarithmically; or linear growth over time).
                        4. Specify **Sample Size** (target 30-50 points) and **Data Types** (float, integer).

                        Provide clear, step-by-step logic for the simulation code.
                    `;

                    const simplifierResponse = await callGeminiWithRetry('gemini-3-flash-preview', { 
                        contents: simplifierPrompt 
                    });
                    if (!isMounted.current) return;
                    const instructions = simplifierResponse.text;

                    log('Coder', 'Generating autonomous simulation script...');

                    const coderPrompt = `
                        ACT AS: Scientific JavaScript Developer.
                        TASK: Write a JavaScript Web Worker script to simulate the experiment described below.

                        SIMULATION LOGIC SPEC:
                        ${instructions}

                        CRITICAL REQUIREMENTS:
                        1. **Data Generation**: Use a loop to generate 20-50 data points.
                        2. **Mathematical Model**: Implement the logic defined in the spec above. 
                        3. **NOISE**: You MUST add \`Math.random()\` variance to *every* dependent variable calculation to simulate real-world biological/physical variability. Data should look organic, not perfect.
                        4. **CSV Format**: Generate a valid CSV string with a header row.
                        5. **Final Handoff**: You MUST call \`hypatia.finish(csvData, summary)\` at the end of the script.
                           - \`csvData\`: The generated CSV string.
                           - \`summary\`: A short string explaining the simulated trend (e.g., "Simulated negative correlation between caffeine and growth.").

                        RESTRICTIONS:
                        - NO DOM access (no window, document, alert).
                        - Use \`console.log\` for debugging.

                        EXAMPLE CODE STRUCTURE:
                        \`\`\`javascript
                        const header = "Concentration_mM,Growth_cm";
                        let csv = header + "\\n";
                        for (let i = 0; i < 30; i++) {
                            const x = i * 5; // Independent
                            const noise = (Math.random() - 0.5) * 2; // Random variance
                            const y = Math.max(0, 10 - (0.1 * x) + noise); // Dependent logic with noise
                            csv += \`\${x},\${y.toFixed(2)}\\n\`;
                        }
                        hypatia.finish(csv, "Simulated growth inhibition with random noise.");
                        \`\`\`

                        Output ONLY the raw JavaScript code. Do not wrap in markdown code blocks if possible, or I will strip them.`;

                    const coderResponse = await callGeminiWithRetry('gemini-3-flash-preview', { 
                        contents: coderPrompt 
                    });
                    if (!isMounted.current) return;
                    const initialCode = coderResponse.text.trim().replace(/```javascript/g, '').replace(/```/g, '');
                    setCode(initialCode);
                    log('Coder', 'Initial script ready for testing.');
                } catch (err) {
                    if (isMounted.current) addToast("Failed to initialize coder.", "danger");
                } finally { 
                    if (isMounted.current) setIsInitializing(false); 
                }
            };
            runInitializationAgent();
        }
    }, [isAuthenticated, context, code, addToast]);

    const executeCodeInWorker = (codeToRun: string): Promise<any> => {
        return new Promise((resolve, reject) => {
            let timeoutId: any;

            const messageHandler = (event) => {
                const { type, payload } = event.data;
                if (type === 'log' && isMounted.current) {
                    setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Simulator', message: payload }] }));
                }

                if (type === 'finish' || type === 'done' || type === 'error') {
                    clearTimeout(timeoutId);
                    workerRef.current?.removeEventListener('message', messageHandler);
                    if (type === 'error') reject(payload); else resolve({ type, payload });
                }
            };

            // Watchdog Timer: Protect against infinite loops or hangs
            timeoutId = setTimeout(() => {
                workerRef.current?.removeEventListener('message', messageHandler);
                workerRef.current?.terminate(); // Hard reset of the worker environment

                // Re-initialize worker for the next attempt if mounted
                if (isMounted.current) {
                    if (workerUrlRef.current) URL.revokeObjectURL(workerUrlRef.current);

                    const workerCode = `
                        self.onmessage = (event) => {
                            const { code } = event.data;
                            let finished = false;
                            const hypatia = {
                                finish: (data, summary) => {
                                    self.postMessage({ type: 'finish', payload: { data, summary } });
                                    finished = true;
                                }
                            };
                            const consoleProxy = {
                                log: (...args) => {
                                    const logMsg = args.map(arg => String(arg)).join(' ');
                                    self.postMessage({ type: 'log', payload: logMsg });
                                }
                            };
                            try {
                                new Function('console', 'hypatia', code)(consoleProxy, hypatia);
                                if (!finished) self.postMessage({ type: 'done' });
                            } catch (e) {
                                self.postMessage({ type: 'error', payload: \`[\${e.name}] \${e.message}\` });
                            }
                        };
                    `;
                    const blob = new Blob([workerCode], { type: 'application/javascript' });
                    const url = URL.createObjectURL(blob);
                    workerUrlRef.current = url;
                    workerRef.current = new Worker(url);
                }
                reject("Execution Timeout: Simulation hung for over 10 seconds.");
            }, 10000);

            workerRef.current?.addEventListener('message', messageHandler);
            workerRef.current?.postMessage({ code: codeToRun });
        });
    };

    const runAgenticSimulation = async () => {
        if (agenticRun.status === 'running') return;
        setAgenticRun(prev => ({ ...prev, status: 'running', logs: [], iterations: 0 }));

        let currentCode = code;
        for (let i = 0; i < agenticRun.maxIterations; i++) {
            if (!isMounted.current) return;
            setAgenticRun(prev => ({ 
                ...prev, 
                iterations: i + 1, 
                logs: [...prev.logs, { agent: 'System', message: `Attempt ${i + 1}: Running simulation...` }] 
            }));

            try {
                const result = await executeCodeInWorker(currentCode);
                if (!isMounted.current) return;

                if (result.type === 'finish') {
                    setAgenticRun(prev => ({ ...prev, status: 'success' }));
                    onComplete(result.payload.data, result.payload.summary);
                    return;
                }
                throw new Error("Simulation execution completed but hypatia.finish() was never invoked.");
            } catch (error) {
                if (!isMounted.current) return;
                setAgenticRun(prev => ({ 
                    ...prev, 
                    logs: [...prev.logs, { agent: 'Debugger', message: `Logic failure detected: ${error}. Triggering Self-Healing Loop.` }] 
                }));

                const debuggerPrompt = `DEBUGGER LOG: The following code failed. 
                ERROR: "${error}". 
                MISSION: Fix the logic and ensure hypatia.finish(csvData, summary) is called with plausible simulated data.

                CODE:
                ${currentCode}`;

                try {
                    const res = await callGeminiWithRetry('gemini-3-flash-preview', { 
                        contents: debuggerPrompt 
                    });
                    if (isMounted.current) {
                        currentCode = res.text.trim().replace(/```javascript/g, '').replace(/```/g, '');
                        setCode(currentCode);
                        await new Promise(r => setTimeout(r, 1000));
                    }
                } catch (e) {
                    if (isMounted.current) addToast("Self-healing link unstable.", "warning");
                }
            }
        }
        if (isMounted.current) setAgenticRun(prev => ({ ...prev, status: 'failed' }));
    };

    return (
        <div>
            <div className="doc-section mb-3">
                <h6 className="fw-bold">AI Agent Simulation Hub</h6>
                <p className="small text-white-50">Specialized agents are drafting and debugging a JavaScript simulation of your methodology. The <strong>Self-Healing Debugger</strong> will autonomously resolve any runtime errors or logical hangs.</p>
            </div>
            {isInitializing && <AgenticAnalysisView agenticRun={{logs: initLogs, iterations: 0, maxIterations: 0}} title="Coder Agent Initializing..." />}
            <textarea 
                id="code-editor" 
                className="form-control mb-3 font-monospace bg-black text-primary-glow border-secondary border-opacity-25" 
                style={{ height: '300px', fontSize: '0.85rem' }}
                value={code} 
                onChange={(e) => setCode(e.target.value)} 
            />
            <button className="btn btn-primary w-100" onClick={runAgenticSimulation} disabled={!code || agenticRun.status === 'running'}>
                {agenticRun.status === 'running' ? 'Self-Healing Loop Active...' : 'Start Agentic Simulation'}
            </button>
            {agenticRun.logs.length > 0 && <AgenticAnalysisView agenticRun={agenticRun} title="Self-Healing Debugger Log" subtitle="Adversarial debugging logic is active." />}
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { 
    parseGeminiError, 
    getStepContext, 
    getPromptForStep, 
    executeStepWorkflow, 
    callGeminiStreamWithRetry,
    generateNodeSummary
} from '../../services';
import { WORKFLOW_STEPS, RESEARCH_QUESTION_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, LITERATURE_REVIEW_SCHEMA } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();

    const [activeStep, setActiveStep] = useState(activeExperiment?.currentStep || 1);
    const [isLoading, setIsLoading] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const [streamingText, setStreamingText] = useState<string | null>(null);

    // Throttled streaming buffer to prevent UI blocking
    const streamBuffer = useRef("");
    const streamInterval = useRef<any>(null);
    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        return () => { 
            isMounted.current = false;
            if (streamInterval.current) {
                clearInterval(streamInterval.current);
            }
        };
    }, []);

    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading) {
            setActiveStep(activeExperiment.currentStep);
        }
    }, [activeExperiment?.currentStep, isLoading, activeStep]);

    /**
     * Automation Effect: Ensures the project continues if 'automated' mode is active.
     */
    useEffect(() => {
        if (!activeExperiment || !isAuthenticated || isLoading || isVerifying) return;

        const mode = activeExperiment.automationMode;
        if (mode === 'automated' && activeStep === activeExperiment.currentStep) {
            // Defensive access for automation logic
            const stepData = (activeExperiment.stepData && activeExperiment.stepData[activeStep]) || {};
            const isAgenticStep = [2, 7, 9, 10].includes(activeStep);

            // Trigger generation if no output exists
            if (!stepData?.output && !isAgenticStep) {
                handleGenerate();
            } else if (stepData?.output && !stepData?.summary) {
                // Auto-verify if output exists but summary doesn't (node not fully closed)
                handleCompleteStep();
            }
        }
    }, [activeExperiment, activeStep, isAuthenticated, isLoading, isVerifying]);

    const handleStepChange = useCallback((stepId: number) => {
        setStreamingText(null);
        setActiveStep(stepId);
    }, []);

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading) return;

        setStreamingText(null);
        setIsLoading(true);
        streamBuffer.current = "";

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            // Safe access to input
            const input = (activeExperiment.stepData && activeExperiment.stepData[activeStep]?.input) || '';

            // Safe access to fineTuneSettings with fallback to empty object
            // This prevents crashes if the experiment object is from an older schema version
            const stepSettings = activeExperiment.fineTuneSettings && activeExperiment.fineTuneSettings[activeStep] 
                ? activeExperiment.fineTuneSettings[activeStep] 
                : {};

            const { basePrompt, expectJson, config } = getPromptForStep(
                activeStep, input, context, stepSettings, regenerateFeedback
            );

            if (expectJson) {
                let schema = (activeStep === 1) ? RESEARCH_QUESTION_SCHEMA : (activeStep === 2) ? LITERATURE_REVIEW_SCHEMA : DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
                const model = activeStep === 1 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

                const output = await executeStepWorkflow(model, { contents: basePrompt, config }, context, true, schema);

                if (isMounted.current) {
                    await updateExperiment({ 
                        ...activeExperiment, 
                        stepData: { 
                            ...activeExperiment.stepData, 
                            [activeStep]: { 
                                ...(activeExperiment.stepData?.[activeStep] || {}), 
                                output 
                            } 
                        } 
                    });
                }
            } else {
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });

                // Start throttled update interval
                if (streamInterval.current) clearInterval(streamInterval.current);
                streamInterval.current = setInterval(() => {
                    if (isMounted.current) {
                        setStreamingText(streamBuffer.current);
                    }
                }, 100);

                for await (const chunk of stream) {
                    streamBuffer.current += (chunk.text || '');
                }

                if (streamInterval.current) {
                    clearInterval(streamInterval.current);
                    streamInterval.current = null;
                }

                if (isMounted.current) {
                    const finalOutput = streamBuffer.current;
                    setStreamingText(finalOutput);

                    await updateExperiment({
                        ...activeExperiment,
                        stepData: { 
                            ...activeExperiment.stepData, 
                            [activeStep]: { 
                                ...(activeExperiment.stepData?.[activeStep] || {}), 
                                output: finalOutput 
                            } 
                        }
                    });
                }
            }
            if (isMounted.current) addToast("Archival node synchronized.", "success");
        } catch (error) {
            if (isMounted.current) addToast(parseGeminiError(error), 'danger');
        } finally {
            if (isMounted.current) setIsLoading(false);
            if (streamInterval.current) {
                clearInterval(streamInterval.current);
                streamInterval.current = null;
            }
        }
    };

    const handleCompleteStep = async (stepDataOverride?: any) => {
        if (isVerifying || !activeExperiment) return;
        setIsVerifying(true);

        // Defensive access to current step data
        const currentStepData = { ...(activeExperiment.stepData?.[activeStep] || {}), ...stepDataOverride };
        const currentOutput = currentStepData.output || "";

        try {
            let summary = currentStepData.summary || "Node verified.";
            if (!currentStepData.summary && currentOutput.length > 50) {
                summary = await generateNodeSummary(currentOutput, activeExperiment.field);
            }

            const nextStep = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : activeStep;
            // Defensive clone of stepData
            const allStepData = { ...(activeExperiment.stepData || {}) };
            allStepData[activeStep] = { ...currentStepData, summary };

            if (activeStep === 6 && currentStepData.input) {
                allStepData[7] = { 
                    ...(allStepData[7] || {}), 
                    input: currentStepData.input,
                    output: undefined,
                    summary: undefined
                };
            }

            const updatedExp = { 
                ...activeExperiment, 
                stepData: allStepData, 
                currentStep: nextStep 
            };

            await updateExperiment(updatedExp);
            if (isMounted.current) {
                setActiveStep(nextStep);
                addToast("Node verified and compressed for archive.", "success");
            }
        } catch (error) {
            console.error("Verification error:", error);
            if (isMounted.current) addToast("Archive link unstable. Could not verify node.", 'danger');
        } finally {
            if (isMounted.current) setIsVerifying(false);
        }
    };

    const renderStepContent = () => {
        if (!activeExperiment) return null;
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} />;
        }

        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={handleCompleteStep} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 10) return <PublicationExporter />;

        return (
            <div className="discovery-view">
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    if (!activeExperiment) return null;

    // Defensive check to prevent render crashes if stepData is malformed
    const hasOutput = activeExperiment.stepData && activeExperiment.stepData[activeStep]?.output;

    return (
        <div className="workspace-container">
            <aside className="sidebar-nav">
                <div className="card shadow-sm border-secondary border-opacity-10 overflow-hidden">
                    <div className="card-header fw-bold bg-dark py-3 small ls-1 text-uppercase">
                        <i className="bi bi-cpu-fill text-primary-glow me-2"></i> Timeline
                    </div>
                    <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                            <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                                style={{ cursor: step.id <= activeExperiment.currentStep ? 'pointer' : 'default' }}
                            >
                                <span className="small">{step.id}. {step.title}</span>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                </div>
            </aside>

            <main className="content-area">
                <div className="card shadow-sm border-secondary border-opacity-25 position-relative overflow-hidden">
                    {(isLoading || isVerifying) && (
                        <div className="progress rounded-0" style={{ height: '3px', position: 'absolute', top: 0, left: 0, right: 0, zIndex: 100 }}>
                            <div className="progress-bar progress-bar-striped progress-bar-animated bg-primary-glow w-100"></div>
                        </div>
                    )}
                    <div className="card-body p-4" style={{ minHeight: '60vh' }}>
                        <div className="d-flex justify-content-between align-items-start mb-4">
                            <div>
                                <div className="badge bg-primary bg-opacity-10 text-primary-glow mb-2">Step {activeStep}</div>
                                <h4 className="fw-bold mb-1">{WORKFLOW_STEPS[activeStep - 1]?.title || 'Node Overview'}</h4>
                                <p className="text-white-50 small mb-0">{WORKFLOW_STEPS[activeStep - 1]?.description}</p>
                            </div>
                            {activeExperiment.automationMode === 'automated' && (
                                <span className="badge bg-warning text-dark px-3 py-2 rounded-pill shadow-sm">
                                    <i className="bi bi-cpu-fill me-1"></i> AGENTIC OVERRIDE ACTIVE
                                </span>
                            )}
                        </div>
                        <hr className="border-secondary opacity-10 mb-4" />
                        {renderStepContent()}
                    </div>

                    {activeStep <= WORKFLOW_STEPS.length && (
                        <div className="card-footer d-flex justify-content-between align-items-center p-3 bg-dark bg-opacity-25 border-top border-secondary border-opacity-10">
                            <button className="btn btn-sm btn-outline-secondary" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Tuning
                            </button>
                            <button 
                                className="btn btn-success px-4 shadow-sm" 
                                onClick={() => handleCompleteStep()} 
                                disabled={isVerifying || !hasOutput}
                            >
                                {isVerifying ? (
                                    <span className="spinner-border spinner-border-sm me-2"></span>
                                ) : (
                                    <i className={`bi ${hasOutput ? 'bi-check-circle-fill' : 'bi-lock-fill'} me-2`}></i> 
                                )}
                                {activeStep === 10 ? "Finish Project" : "Verify Node & Continue"}
                            </button>
                        </div>
                    )}
                </div>
            </main>

            {fineTuneModalOpen && (
                <FineTuneModal stepId={activeStep} onClose={() => setFineTuneModalOpen(false)} />
            )}
            <style>{`
                .bg-primary-glow { background-color: var(--primary-glow); box-shadow: 0 0 10px var(--primary-glow); }
                .ls-1 { letter-spacing: 0.05rem; }
            `}</style>
        </div>
    );
};

