export const getSafeEnvApiKey = () => {
    try {
        if (typeof process !== 'undefined' && process && process.env) {
            return process.env.API_KEY;
        }
    } catch (e) {}
    return undefined;
};

let storedApiKey = getSafeEnvApiKey() || "demo-mode";

export const setStoredApiKey = (key: string) => {
    storedApiKey = key;
};

export const getCurrentApiKey = () => storedApiKey;
const getApiKey = () => storedApiKey;

export const getKeyStatus = () => {
    const envKey = getSafeEnvApiKey();
    if (storedApiKey === 'demo-mode') return { type: 'demo', label: 'Demo Mode Active', color: 'bg-info' };
    if (envKey && storedApiKey === envKey) return { type: 'env', label: 'Environment Key Linked', color: 'bg-success' };
    return { type: 'manual', label: 'Manual Key Active', color: 'bg-warning' };
};

export const testApiKey = async (apiKey: string | undefined): Promise<boolean> => {
    if (!apiKey) return false;
    if (apiKey === 'demo-mode') return true;
    try {
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: 'ping',
        });
        return !!response.text;
    } catch (e) {
        console.error("API Key validation failed:", e);
        return false;
    }
};

const handleApiError = async (error: any) => {
    const msg = error?.message || "";
    const status = error?.status;
    if (msg.includes("entity was not found") || msg.includes("API_KEY_INVALID") || status === 403 || status === 404) {
        return "AUTH_ERROR";
    }
    if (status === 503 || msg.includes("overloaded") || msg.includes("timeout")) {
        return "RETRY";
    }
    return null;
};

const withTimeout = <T>(promise: Promise<T>, ms: number, message: string): Promise<T> => {
    let timeoutId: any;
    const timeoutPromise = new Promise<T>((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(message)), ms);
    });
    return Promise.race([
        promise.then(
            val => { clearTimeout(timeoutId); return val; },
            err => { clearTimeout(timeoutId); throw err; }
        ),
        timeoutPromise
    ]);
};

async function retryOperation<T>(operation: () => Promise<T>, retries: number = 2, delay: number = 1000): Promise<T> {
    try {
        return await operation();
    } catch (err: any) {
        const status = await handleApiError(err);
        if (retries > 0 && status === "RETRY") {
            await new Promise(resolve => setTimeout(resolve, delay));
            return retryOperation(operation, retries - 1, delay * 2);
        }
        throw err;
    }
}

export const generateNodeSummary = async (content: string, field: string): Promise<string> => {
    if (!content) return "";
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') return "Simulated summary.";
    try {
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Concisely summarize the following scientific discovery node in 2-3 sentences for a PI dashboard in the field of ${field}:\n\n${content}`,
            config: { temperature: 0.3 }
        });
        return response.text?.trim() || "Node summary unavailable.";
    } catch (e) {
        return content.slice(0, 200) + "...";
    }
};

export const executeStepWorkflow = async (
    model: string,
    params: { contents: string, config?: any },
    context: any,
    expectJson: boolean = false,
    schema?: any
): Promise<string> => {
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') {
        await new Promise(r => setTimeout(r, 1000));
        return expectJson ? JSON.stringify({ research_question: "Demo Question", study_type: "simulation", uniqueness_score: 0.9, justification: "Demo mode justification." }) : "Demo output.";
    }

    try {
        const ai = new GoogleGenAI({ apiKey });
        const operation = () => withTimeout<GenerateContentResponse>(
            ai.models.generateContent({
                model,
                contents: params.contents,
                config: params.config
            }),
            60000,
            "Archival synthesis timed out."
        );

        const response = await retryOperation(operation);
        let output = response.text || "";

        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (!expectJson && groundingChunks && Array.isArray(groundingChunks)) {
            let citations = "\n\n### Grounding Citations\n";
            groundingChunks.forEach((chunk: any) => {
                if (chunk.web && chunk.web.uri) {
                    citations += `- [${chunk.web.title || chunk.web.uri}](${chunk.web.uri})\n`;
                }
            });
            output += citations;
        }

        return expectJson ? extractJson(output) : output;
    } catch (e: any) {
        const authStatus = await handleApiError(e);
        if (authStatus === "AUTH_ERROR") throw new Error("API Key Invalid or Model Not Found.");
        throw e;
    }
};

export const callGeminiWithRetry = async (model: string, params: { contents: string, config?: any }): Promise<GenerateContentResponse> => {
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') return { text: "Simulated response.", candidates: [] } as any;
    try {
        const ai = new GoogleGenAI({ apiKey });
        const operation = () => withTimeout<GenerateContentResponse>(
            ai.models.generateContent({ model, contents: params.contents, config: params.config }),
            60000,
            "Archive link unstable."
        );
        return await retryOperation(operation);
    } catch (e: any) {
        if (await handleApiError(e) === "AUTH_ERROR") throw new Error("API Key Invalid.");
        throw e;
    }
};

export const callGeminiStreamWithRetry = async (model: string, params: { contents: string, config?: any }) => {
    const apiKey = getApiKey();
    if (apiKey === 'demo-mode') {
        return (async function* () {
            yield { text: "Simulating stream..." };
        })();
    }
    const ai = new GoogleGenAI({ apiKey });
    return await ai.models.generateContentStream({ model, contents: params.contents, config: params.config });
};

export const parseGeminiError = (error: any, fallback = "Hypatia link failed."): string => {
    const msg = error?.message || "";
    if (msg.includes('re-sync') || msg.includes('timed out')) return "Archive link unstable. Please retry synthesis.";
    if (msg.includes('safety')) return "Safety filter triggered.";
    if (msg.includes('API Key Invalid')) return "Authentication Error: Check API key.";
    return fallback;
};

export const getStepContext = async (experiment: Experiment, stepId: number): Promise<any> => {
    const context: any = { 
        experimentField: experiment.field, 
        studyType: experiment.studyType || 'controlled_experiment'
    };
    const data = experiment.stepData || {};
    const getSummary = (sId: number) => data[sId]?.summary || (data[sId]?.output ? (data[sId].output.slice(0, 300) + '...') : 'N/A');
    const getFull = (sId: number) => data[sId]?.output || 'N/A';

    if (stepId > 1) {
        context.researchQuestion = getFull(1);
        try {
            const rq = JSON.parse(extractJson(context.researchQuestion));
            context.studyType = rq.study_type || context.studyType;
        } catch(e) {}
    }
    if (stepId > 2) context.evidenceSummary = getSummary(2);
    if (stepId > 3) context.hypothesisSet = getFull(3);
    if (stepId > 4) context.protocol = getFull(4);
    if (stepId > 5) context.analysisPlan = getFull(5);
    if (stepId > 7) context.analysisResults = getSummary(7);

    if (stepId === 10) {
        let log = '';
        WORKFLOW_STEPS.forEach(s => { if(s.id < 10) log += `[STEP ${s.id}: ${s.title}]\n${getSummary(s.id)}\n\n`; });
        context.fullProjectContext = log;
    }
    return context;
};

export const getPromptForStep = (
    stepId: number, 
    userInput: string, 
    context: any, 
    fineTuneSettings: FineTuneSettings,
    regenerateFeedback: string = ''
) => {
    const settings = fineTuneSettings || {};
    const studyTypeLabel = context.studyType?.toUpperCase() || 'GENERAL';
    let systemInstruction = `PROJECT HYPATIA PRO (v2.5). Field: ${context.experimentField}. Study Mode: ${studyTypeLabel}. 
    Only APPROVED OUTPUTS flow forward. Maintain rigorous scientific tone. Use LaTeX for math.`;

    let basePrompt = regenerateFeedback ? `[PI INTERVENTION: ${regenerateFeedback}]\n\n` : "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.5 };

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `STEP 1: RESEARCH QUESTION & SCOPE. Turn this idea into a testable objective: "${userInput}". 
            Identify Study Type: observational | simulation | benchmarking | controlled_experiment.
            Identify Research Object (system, organism, artifact, etc.).
            Output valid JSON per RESEARCH_QUESTION_SCHEMA.`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            expectJson = true;
            const depth = settings.depth || 'standard';
            basePrompt += `STEP 2: EVIDENCE DISCOVERY (${depth}). Grounded review for: "${context.researchQuestion}". 
            Track what is known, contested, and unknown. Build Evidence Map with gaps and candidate mechanisms.
            Use Google Search grounding for external reality. Output JSON per EVIDENCE_BUNDLE_SCHEMA.`;
            config.tools = [{ googleSearch: {} }];
            config.responseMimeType = "application/json";
            config.responseSchema = EVIDENCE_BUNDLE_SCHEMA;
            break;
        case 3:
            basePrompt += `STEP 3: HYPOTHESIS SET. Based on Evidence: "${context.evidenceSummary}". 
            Generate falsifiable primary and secondary hypotheses. Include operational definitions and falsification criteria.`;
            break;
        case 4:
            basePrompt += `STEP 4: PROTOCOL DESIGN. For Hypothesis: "${context.hypothesisSet}". 
            Study Type: ${context.studyType}. Specify replicable steps, materials, and bias mitigation (e.g., STROBE for observational).`;
            break;
        case 5:
            basePrompt += `STEP 5: ANALYSIS PLAN (SAP). Based on Protocol: "${context.protocol}". 
            Define primary/secondary endpoints, variable dictionary, and statistical tests. Include stopping rules if applicable.`;
            break;
        case 6:
            basePrompt += `STEP 6: DATA ACQUISITION. Generate theoretical dataset description and schema for: "${context.protocol}".`;
            break;
        case 7:
            expectJson = true;
            basePrompt += `STEP 7: ANALYSIS & VISUALIZATION. Run contract-driven analysis on data: ${userInput}. 
            Adhere to SAP: "${context.analysisPlan}". Return JSON with summary, stats, assumption checks, and Chart.js configs.`;
            config.responseMimeType = "application/json";
            config.responseSchema = DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
            break;
        case 8:
            basePrompt += `STEP 8: INTERPRETATION. Evaluate Claims against Results: "${context.analysisResults}". 
            Include robustness checks and external validity assessment. Use Search Grounding for factual context.`;
            config.tools = [{ googleSearch: {} }];
            break;
        case 9:
            basePrompt += `STEP 9: PEER REVIEW SIMULATION. multi-persona audit (Methodologist, Statistician, Editor). 
            Review full project: \n${context.fullProjectContext}. Flag severity, evidence, and fix instructions.`;
            break;
        case 10:
            basePrompt += `STEP 10: PUBLICATION BUNDLE. Synthesize Reproducible Manuscript for:\n${context.fullProjectContext}. 
            Embed figures from Analysis results. Include metadata, provenance, and citations.`;
            break;
        default:
            basePrompt += `Archival synthesis Step ${stepId}.`;
    }

    return { basePrompt, expectJson, config };
};

export const runAgenticWorkflow = async ({
    experiment, stepId, agentName, startMessage, updateLog, model = 'gemini-3-flash-preview', 
    expectJson = false, schema = undefined, extraInput = '', extraConfig = {}
}: any) => {
    const context = await getStepContext(experiment, stepId);
    const { basePrompt, config } = getPromptForStep(stepId, extraInput, context, experiment.fineTuneSettings?.[stepId] || {});
    updateLog(agentName, startMessage);
    return await executeStepWorkflow(model, { contents: basePrompt, config: { ...config, ...extraConfig } }, context, expectJson, schema);
};

export const runLiteratureReviewAgent = async ({ experiment, updateLog }: any) => {
    return await runAgenticWorkflow({
        experiment, stepId: 2, agentName: 'EvidenceAgent', 
        startMessage: 'Mapping evidence saturation and mechanisms...',
        updateLog, expectJson: true, schema: EVIDENCE_BUNDLE_SCHEMA
    });
};

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }: any) => {
    const finalOutput = await runAgenticWorkflow({
        experiment, stepId: 7, agentName: 'StatAgent',
        startMessage: 'Validating SAP contracts and computing models...',
        updateLog, extraInput: csvData, expectJson: true, schema: DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA
    });
    return { finalOutput, logSummary: "Statistical contract verified." };
};

export const runPeerReviewAgent = async ({ experiment, updateLog }: any) => {
