export const parseBlockers = (text: string): Blocker[] => {
    try {
        const jsonStr = extractJson(text);
        if (!jsonStr) return [];
        const data = JSON.parse(jsonStr);

        // Handle case where output is ONLY the blocker alert or includes it
        const alert = data.BLOCKER_ALERT || (data.severity ? data : null);
        if (!alert) return [];

        const blockers = Array.isArray(alert) ? alert : [alert];
        return blockers.map((b: any, i: number) => ({
            id: `blk_${Date.now()}_${i}`,
            severity: b.severity || 'warning',
            msg: b.msg || b.message || "Logic inconsistency detected by PI Agent.",
            resolved: false
        }));
    } catch (e) {
        return [];
    }
};

