) => {
    const settings = fineTuneSettings || {};
    const studyType = context.studyType || 'controlled_experiment';
    const studyTypeLabel = studyType.toUpperCase();

    let systemInstruction = `PROJECT HYPATIA PRO (v2.5). Field: ${context.experimentField}. Study Mode: ${studyTypeLabel}. 
    Maintain rigorous scientific tone. Use LaTeX for math. Use grounding for factual verification.

    CRITICAL: If you detect a logic, safety, or ethical violation, you MUST include a "BLOCKER_ALERT" JSON object in your response:
    {"BLOCKER_ALERT": {"severity": "critical", "msg": "Detailed explanation of the blocker."}}`;

    let basePrompt = regenerateFeedback ? `[PI INTERVENTION: ${regenerateFeedback}]\n\n` : "";
    let expectJson = false;
    const config: any = { systemInstruction, temperature: settings.temperature || 0.5 };

    switch (stepId) {
        case 1:
            expectJson = true;
            basePrompt += `STEP 1: RESEARCH QUESTION & SCOPE. Refine this objective: "${userInput}". 
            Output JSON per RESEARCH_QUESTION_SCHEMA. Identify the most rigorous study type.`;
            config.responseMimeType = "application/json";
            config.responseSchema = RESEARCH_QUESTION_SCHEMA;
            break;
        case 2:
            expectJson = true;
            basePrompt += `STEP 2: EVIDENCE DISCOVERY. Grounded literature review for: "${context.researchQuestion}". 
            Map evidence gaps and candidate mechanisms. Output JSON per LITERATURE_REVIEW_SCHEMA. Use Google Search.`;
            config.tools = [{ googleSearch: {} }];
            config.responseMimeType = "application/json";
            config.responseSchema = LITERATURE_REVIEW_SCHEMA;
            break;
        case 3:
            basePrompt += `STEP 3: HYPOTHESIS SET. Based on Evidence: "${context.evidenceSummary}". 
            Generate falsifiable primary ($H_1$) and null ($H_0$) hypotheses for a ${studyTypeLabel} study. 
            Specify effect directions and measurable endpoints.`;
            break;
        case 4:
            basePrompt += `STEP 4: PROTOCOL DESIGN. For ${studyTypeLabel} study testing "${context.hypothesisSet}". 
            Draft a replicable methodology. Include controls, sampling frame, and bias mitigation.`;
            break;
        case 5:
            basePrompt += `STEP 5: ANALYSIS PLAN (SAP). Based on Protocol: "${context.protocol}". 
            Define endpoints, statistical models, and stopping rules. Ensure alignment with ${studyTypeLabel} rigor.`;
            break;
        case 6:
            basePrompt += `STEP 6: DATA ACQUISITION. Define the data structure and generate representative simulated CSV data for: "${context.protocol}". 
            Ensure data mirrors predicted effect sizes from hypothesis.`;
            break;
        case 7:
            expectJson = true;
            basePrompt += `STEP 7: ANALYSIS & VISUALIZATION. Adhere to SAP: "${context.analysisPlan}". 
            Analyze dataset: "${context.rawDataset}". 
            Return JSON per DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA including Chart.js configs.`;
            config.responseMimeType = "application/json";
            config.responseSchema = DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
            break;
        case 8:
            basePrompt += `STEP 8: INTERPRETATION & ROBUSTNESS. Evaluate claims against results: "${context.analysisResults}". 
            Check for p-hacking, effect size significance, and robustness to outliers. Use search grounding for external context.`;
            config.tools = [{ googleSearch: {} }];
            break;
        case 9:
            basePrompt += `STEP 9: PEER REVIEW SIMULATION. Conduct adversarial audit of full project context: \n${context.fullProjectContext}. 
            Roleplay methodologist and statistician. Identify critical blockers.`;
            break;
        case 10:
            basePrompt += `STEP 10: PUBLICATION BUNDLE. Synthesize FAIR-compliant manuscript for: \n${context.fullProjectContext}. 
            Embed figures from Step 7 results. Focus on reproducibility.`;
            break;
        default:
            basePrompt += `Archival synthesis Step ${stepId}.`;
    }

    return { basePrompt, expectJson, config };
};

export const runAgenticWorkflow = async ({
    experiment, stepId, agentName, startMessage, updateLog, model = 'gemini-3-flash-preview', 
    expectJson = false, schema = undefined, extraInput = '', extraConfig = {}
}: any) => {
    const context = await getStepContext(experiment, stepId);
    const { basePrompt, config } = getPromptForStep(stepId, extraInput, context, experiment.fineTuneSettings?.[stepId] || {});
    updateLog(agentName, startMessage);

    const output = await executeStepWorkflow(model, { contents: basePrompt, config: { ...config, ...extraConfig } }, context, expectJson, schema);

    // Check for blockers in output
    const blockers = parseBlockers(output);
    return { output, blockers };
};

