import { GoogleGenAI } from "@google/genai";
import { Blocker } from '../config';

// --- API KEY MANAGEMENT ---

const STORAGE_KEY = 'hypatia_api_key';

export const getSafeEnvApiKey = () => {
    // @ts-ignore - process is polyfilled in index.html
    if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
        // @ts-ignore
        return process.env.API_KEY;
    }
    return null;
};

export const getCurrentApiKey = () => {
    const envKey = getSafeEnvApiKey();
    if (envKey) return envKey;
    return localStorage.getItem(STORAGE_KEY) || '';
};

export const setStoredApiKey = (key: string) => {
    localStorage.setItem(STORAGE_KEY, key);
};

export const getKeyStatus = () => {
    const envKey = getSafeEnvApiKey();
    if (envKey) return { type: 'env', label: 'Environment Linked', color: 'bg-success' };

    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === 'demo-mode') return { type: 'demo', label: 'Demo Mode', color: 'bg-warning' };
    if (stored) return { type: 'manual', label: 'Key Stored', color: 'bg-success' };

    return { type: 'none', label: 'Disconnected', color: 'bg-danger' };
};

export const testApiKey = async (key: string): Promise<boolean> => {
    if (key === 'demo-mode') return true;
    try {
        const ai = new GoogleGenAI({ apiKey: key });
        // Simple fast call to test auth
        await ai.models.generateContent({
             model: 'gemini-3-flash-preview',
             contents: 'Test connection.',
        });
        return true;
    } catch (e) {
        console.warn("API Key Test Failed:", e);
        return false;
    }
};

// --- ERROR HANDLING ---

export const parseGeminiError = (error: any, defaultMsg = "An error occurred with the AI service."): string => {
    console.error("Gemini Error:", error);
    const msg = error?.message || error?.toString() || "";

    if (msg.includes("429") || msg.includes("quota")) return "Rate limit exceeded. Please wait a moment.";
    if (msg.includes("401") || msg.includes("API key")) return "Invalid API Key. Please re-authenticate.";
    if (msg.includes("503") || msg.includes("overloaded")) return "AI Service overloaded. Retrying usually fixes this.";
    if (msg.includes("SAFETY")) return "Content blocked by safety filters. Please refine your input.";

    return defaultMsg;
};

// --- UTILITIES ---

export const extractJson = (text: any): string => {
    if (typeof text !== 'string') return "";
    if (!text) return "";

    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match && match[1]) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');

    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

export const isValidJsonForSchema = (jsonString: string, schema: any): boolean => {
    try {
        const obj = JSON.parse(jsonString);
        if (!obj) return false;
        // Basic check: if schema requires certain properties, check existence
        if (schema && schema.required && Array.isArray(schema.required)) {
            for (const field of schema.required) {
                if (!(field in obj)) return false;
            }
        }
        return true;
    } catch (e) {
        return false;
    }
};

export const parseBlockers = (text: string): Blocker[] => {
    try {
        const jsonStr = extractJson(text);
        if (!jsonStr) return [];
        const data = JSON.parse(jsonStr);

        // Handle case where output is ONLY the blocker alert or includes it
        const alert = data.BLOCKER_ALERT || (data.severity ? data : null);
        if (!alert) return [];

        const blockersList = Array.isArray(alert) ? alert : [alert];
        return blockersList
            .filter((b: any) => b && (b.severity === 'critical' || b.severity === 'warning') && b.msg)
            .map((b: any, i: number) => ({
                id: `blk_${Date.now()}_${i}`,
                severity: b.severity,
                msg: b.msg,
                resolved: false
            }));
    } catch (e) {
        return [];
    }
};

// --- GEMINI WRAPPERS ---

const MODEL_CONFIGS: any = {
    'gemini-3-flash-preview': { temperature: 0.7, topK: 40, topP: 0.95 },
    'gemini-3-pro-preview': { temperature: 0.9, topK: 64, topP: 0.95, thinkingConfig: { thinkingBudget: 2048 } }
};

export const callGeminiWithRetry = async (modelName: string, params: any, retries = 2) => {
    const apiKey = getCurrentApiKey();
    if (apiKey === 'demo-mode') {
        return { text: "Demo Mode: AI simulation response. Connect a valid API key for real intelligence." };
    }
    if (!apiKey) throw new Error("No API Key available.");

    const ai = new GoogleGenAI({ apiKey });

    // Ensure config exists and merge defaults
    const defaults = MODEL_CONFIGS[modelName] || {};
    params.config = { ...defaults, ...(params.config || {}) };

    for (let i = 0; i <= retries; i++) {
        try {
            const response = await ai.models.generateContent({
                model: modelName,
                ...params
            });
            return response;
        } catch (error: any) {
            if (i === retries) throw error;
            if (error.message?.includes("429") || error.message?.includes("503")) {
                await new Promise(res => setTimeout(res, 1000 * (i + 1))); // Exponential backoff
            } else {
                throw error;
            }
        }
    }
    throw new Error("Failed after retries");
};

export const callGeminiStreamWithRetry = async (modelName: string, params: any) => {
    const apiKey = getCurrentApiKey();
    if (apiKey === 'demo-mode') {
        // Mock stream generator
        return (async function* mockStream() {
            const msg = "Demo Mode: Streaming simulated response... [Connect API Key for live models]";
            for (const char of msg) {
                yield { text: char };
                await new Promise(r => setTimeout(r, 20));
            }
        })();
    }
    if (!apiKey) throw new Error("No API Key available.");

    const ai = new GoogleGenAI({ apiKey });

    const defaults = MODEL_CONFIGS[modelName] || {};
    params.config = { ...defaults, ...(params.config || {}) };

    try {
        const stream = await ai.models.generateContentStream({
            model: modelName,
            ...params
        });
        return stream;
    } catch (error) {
        console.error("Stream Error", error);
        throw error;
    }
};

export const generateNodeSummary = async (content: string, field: string): Promise<string> => {
    if (!content || content.length < 50) return content;

    const prompt = `As a Research Archivist in ${field}, compress the following content into a concise, high-density summary (max 3 sentences) suitable for context in future steps. Preserve key variables, findings, and numbers.

    CONTENT:
    ${content.substring(0, 15000)}...`;

    try {
        const response = await callGeminiWithRetry('gemini-3-flash-preview', { contents: prompt });
        return response.text || content.substring(0, 200) + "...";
    } catch (e) {
        return content.substring(0, 200) + "...";
    }
};

import { Experiment, FineTuneSettings, RESEARCH_QUESTION_SCHEMA, LITERATURE_REVIEW_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA } from '../config';

/**
 * Retrieves context from previous steps to inform the current prompt.
 * Instead of passing massive full-text outputs, it favors the 'summary' field logic for efficiency.
 */
export const getStepContext = async (experiment: Experiment, currentStepId: number) => {
    const data = experiment.stepData || {};

    // Helper to get summary or output
    const getC = (step: number) => {
        if (!data[step]) return "Not yet generated.";
        return data[step].summary || data[step].output || "Not yet generated.";
    };

    return {
        experimentField: experiment.field,
        question: getC(1),
        literature_review_summary: getC(2),
        hypothesis: getC(3),
        methodology_summary: getC(4),
        data_collection_plan_summary: getC(5),
        experimental_data_summary: getC(6), // From Runner
        analysis_summary: getC(7),
        conclusion_summary: getC(8),
        full_project_summary_log: Object.entries(data)
            .filter(([k, v]) => parseInt(k) < currentStepId && (v.summary || v.output))
            .map(([k, v]) => `Step ${k}: ${v.summary || "Completed"}`)
            .join('\n')
    };
};

/**
 * Main prompt factory. Returns the prompt string, JSON expectation flag, and configuration constraints.
 */
export const getPromptForStep = (
    stepId: number, 
    input: string, 
    context: any, 
    fineTune: FineTuneSettings,
    feedback: string = ""
) => {
    let basePrompt = "";
    let expectJson = false;
    let config: any = {};

    const role = `You are Hypatia, an advanced Research Scientist AI specializing in ${context.experimentField}. You adhere to the Scientific Method rigorously.`;
    const tuning = Object.entries(fineTune).map(([k, v]) => `${k}: ${v}`).join(', ');
    const feedbackInstruction = feedback ? `\n\nUSER FEEDBACK ON PREVIOUS DRAFT (INCORPORATE THIS): "${feedback}"` : "";

    switch (stepId) {
        case 1: // Question
            expectJson = true;
            basePrompt = `${role}
            Analyze the user's initial research idea and formulate a rigorous, falsifiable Research Question.

            USER INPUT: "${input}"

            CRITICAL: YOU MUST OUTPUT ONLY VALID JSON matching the specified schema.
            The JSON must include:
            - "research_question": The refined question.
            - "study_type": One of ['observational', 'simulation', 'benchmarking', 'controlled_experiment', 'qualitative'].
            - "uniqueness_score": A float 0-1 (1 is highly novel).
            - "justification": Why is this unique?
            - "measurable_outcomes": Array of strings.

            ${feedbackInstruction}`;
            break;

        case 2: // Lit Review
            expectJson = true;
            basePrompt = `${role}
            Conduct a simulated literature review search and synthesis.

            RESEARCH QUESTION: "${context.question}"
            SEARCH DEPTH: ${fineTune.depth || 'standard'}

            Output JSON matching the schema with:
            - "synthesis_narrative": Markdown summary of state-of-the-art.
            - "evidence_gaps": List of missing knowledge this study addresses.
            - "candidate_mechanisms": Theoretical underpinnings.
            - "references": Array of citations (mock or grounded if search tool active).

            ${feedbackInstruction}`;
            break;

        case 3: // Hypothesis
            basePrompt = `${role}
            Formulate 3 distinct hypotheses based on the literature gaps.

            LIT REVIEW CONTEXT: ${context.literature_review_summary}
            RESEARCH QUESTION: ${context.question}

            Output Format:
            1. **Null Hypothesis ($H_0$)**: ...
            2. **Alternative Hypothesis 1 ($H_1$)**: ...
            3. **Alternative Hypothesis 2 ($H_2$)**: ...

            Provide a brief rationale for each.
            ${feedbackInstruction}`;
            break;

        case 4: // Methodology
            basePrompt = `${role}
            Draft a Detailed experimental methodology for:

            HYPOTHESIS: ${context.hypothesis}
            FIELD: ${context.experimentField}

            Include:
            - Study Design (e.g., Double-blind, Randomized Block).
            - Variables (Independent, Dependent, Control).
            - Materials/Equipment.
            - Step-by-step Procedure.

            Ensure the methodology is reproducible.
            ${feedbackInstruction}`;
            break;

        case 5: // Data Plan
            basePrompt = `${role}
            Create a Data collection plan for methodology:

            METHODOLOGY: ${context.methodology_summary}

            Define:
            - Data points to capture.
            - Format (CSV structure).
            - Frequency of measurement.
            - Statistical Power considerations.
            ${feedbackInstruction}`;
            break;

        case 6: // Runner (Used for synthesis prompts mostly)
            basePrompt = `${role}
            Generate synthetic CSV data representing the results of the experiment described below.

            METHODOLOGY: ${context.methodology_summary}

            The data should be realistic, containing some noise/variance, but generally trending to support or refute the hypothesis logically.
            Output ONLY raw CSV data.
            ${feedbackInstruction}`;
            break;

        case 7: // Analysis
            expectJson = true;
            basePrompt = `${role}
            Analyze data: csvData provided in system context.

            CONTEXT:
            - Question: ${context.question}
            - Hypothesis: ${context.hypothesis}

            Execute statistical tests appropriate for ${context.experimentField}.
            Output JSON with:
            - "summary": Markdown analysis.
            - "statistical_outputs": key-value pairs of stats.
            - "charts": Array of Chart.js configurations (type, data, options).
            - "imageData": Optional base64 if available (or use Chart.js config).

            ${feedbackInstruction}`;
            break;

        case 8: // Conclusion
