export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }: { experiment: Experiment, csvData: string, updateLog: (agent: string, msg: string) => void }) => {
    updateLog('Manager', 'Initializing Data Analysis Agent Swarm...');

    // 1. Data Profiler
    updateLog('Profiler', 'Scanning dataset structure and quality...');
    const context = await getStepContext(experiment, 7);
    const profilerPrompt = `Analyze the first 50 rows of this dataset: ${csvData.substring(0, 5000)}...
    Identify columns, data types, and potential quality issues.
    Research Question: ${context.question}
    Hypothesis: ${context.hypothesis}`;

    const profileRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: profilerPrompt });
    updateLog('Profiler', 'Data profile generated.');

    // 2. Statistician & Visualizer (Combined for speed/consistency)
    updateLog('Analyst', 'Executing statistical tests and generating visualization config...');
    const analysisPrompt = `
    ACT AS: Senior Data Scientist.
    TASK: Analyze the provided dataset to test the hypothesis.

    DATA PROFILE: ${profileRes.text}
    RAW DATA (First 100 rows): ${csvData.substring(0, 10000)}
    HYPOTHESIS: ${context.hypothesis}

    REQUIREMENTS:
    1. Perform appropriate statistical tests (t-test, correlation, regression, etc.).
    2. Generate a detailed Markdown summary of results.
    3. Generate 2-3 Chart.js configuration objects to visualize the key findings.

    CRITICAL: Output MUST be valid JSON matching the provided schema.
    `;

    const analysisRes = await callGeminiWithRetry('gemini-3-pro-preview', { 
        contents: analysisPrompt,
        config: { responseMimeType: "application/json", responseSchema: DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA }
    });

    let resultJson = extractJson(analysisRes.text);

    // Post-process charts to ensure visibility
    try {
        const parsed = JSON.parse(resultJson);
        if (parsed.charts && Array.isArray(parsed.charts)) {
            parsed.charts = parsed.charts.map((c: any) => ensureChartStyling(c));
            resultJson = JSON.stringify(parsed);
        }
        updateLog('Visualizer', 'Charts rendered and styled.');
    } catch (e) {
        updateLog('System', 'Warning: Chart styling post-processing failed.');
    }

    // 3. Blocker Check
    updateLog('Safety', 'Running blocker check on analysis results...');
    const blockerPrompt = `Analyze this analysis result for critical failures (e.g., p-value > 0.5 when significant effect claimed, insufficient sample size, obvious data fabrication).
    RESULT: ${resultJson}

    Output JSON: { "BLOCKER_ALERT": [ { "severity": "critical"|"warning", "msg": "..." } ] } or empty object.`;

    const blockerRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: blockerPrompt });
    const blockers = parseBlockers(blockerRes.text);

    return { finalOutput: resultJson, blockers, logSummary: profileRes.text };
};

