export const runPeerReviewAgent = async ({ experiment, updateLog }: { experiment: Experiment, updateLog: (agent: string, msg: string) => void }) => {
    const steps = [3, 4, 5, 7];
    let critiqueLog = "";

    for (const step of steps) {
        updateLog('Reviewer', `Analyzing Step ${step} logic...`);
        const stepContent = experiment.stepData[step]?.output || "";
        const critiquePrompt = `Critique this scientific step output for logic, bias, and rigor. Be harsh.
        STEP ${step} CONTENT: ${stepContent.substring(0, 5000)}`;

        const res = await callGeminiWithRetry('gemini-3-flash-preview', { contents: critiquePrompt });
        critiqueLog += `\n\nSTEP ${step} CRITIQUE:\n${res.text}`;
    }

    updateLog('Editor', 'Compiling final peer review report...');
    const finalReportPrompt = `Summarize these critiques into a formal Peer Review Report.

    CRITIQUES: ${critiqueLog}`;

    const finalRes = await callGeminiWithRetry('gemini-3-pro-preview', { contents: finalReportPrompt });
    return finalRes.text;
};

// Barrel file for services
export * from './services/api';
export * from './services/prompts';
export * from './services/agents';
export { useExperiment } from './context/ExperimentContext';

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { runDataAnalysisAgent, parseGeminiError } from '../../services';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { AgenticAnalysisView } from '../common/AgenticAnalysisView';

export const DataAnalysisWorkspace = ({ onStepComplete }) => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();
    const [agenticRun, setAgenticRun] = useState({
        status: 'idle', // 'idle', 'running', 'success', 'failed'
        iterations: 0,
        maxIterations: 2, 
        logs: [],
    });

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    const stepData = activeExperiment.stepData[7] || {};

    const performAgenticAnalysis = useCallback(async () => {
        if (!isAuthenticated || !stepData.input || agenticRun.status === 'running') return;

        setAgenticRun({ status: 'running', logs: [], iterations: 0, maxIterations: 2 });

        try {
            const { finalOutput, blockers, logSummary } = await runDataAnalysisAgent({
                experiment: activeExperiment,
                csvData: stepData.input,
                updateLog: (agent, message) => {
                    if (isMounted.current) {
                        setAgenticRun(prev => ({
                            ...prev,
                            logs: [...prev.logs, { agent, message }],
                            iterations: Math.min(prev.maxIterations, prev.iterations + 1)
                        }));
                    }
                },
            });

            if (!isMounted.current) return;

            // Merge blockers into step data
            const finalStepData = { 
                ...stepData, 
                output: finalOutput, 
                suggestedInput: logSummary,
                blockers: [...(stepData.blockers || []), ...blockers]
            };

            await updateExperiment({ ...activeExperiment, stepData: { ...activeExperiment.stepData, 7: finalStepData } });

            if (blockers.some(b => b.severity === 'critical')) {
                setAgenticRun(prev => ({ 
                    ...prev, 
                    status: 'failed',
                    logs: [...prev.logs, { agent: 'System', message: 'CRITICAL BLOCKER DETECTED. Analysis halted for PI review.' }]
                }));
                addToast("Critical blockers detected in analysis.", "warning");
            } else {
                setAgenticRun(prev => ({ ...prev, status: 'success' }));
                addToast("Analysis complete!", "success");

                 if (activeExperiment.automationMode === 'automated') {
                     setTimeout(() => { if (isMounted.current) onStepComplete(); }, 1500);
                }
            }
        } catch (error) {
            if (!isMounted.current) return;
            const errorMessage = parseGeminiError(error, "An unknown error occurred during analysis.");
            addToast(errorMessage, "danger");
            setAgenticRun(prev => ({ 
                ...prev, 
                status: 'failed',
                logs: [...prev.logs, { agent: 'System', message: `ERROR: ${errorMessage}` }]
            }));
        }
    }, [activeExperiment, isAuthenticated, addToast, updateExperiment, stepData, agenticRun.status, onStepComplete]);

    return (
        <div className="data-analysis-workspace">
             {!stepData.input ? (
                 <div className="alert alert-warning">
                     <i className="bi bi-exclamation-triangle me-2"></i>
                     No data available for analysis. Please complete the "Data Acquisition" step first.
                 </div>
             ) : (
                 <>
                    {agenticRun.status !== 'running' && stepData.output && (
                        <div className="d-flex justify-content-end mb-3">
                             <button className="btn btn-sm btn-outline-secondary" onClick={performAgenticAnalysis}>
                                <i className="bi bi-arrow-clockwise me-1"></i> Re-Run Analysis Agent
                            </button>
                        </div>
                    )}

                    {!stepData.output && agenticRun.status === 'idle' && (
                        <div className="text-center p-5 border border-secondary border-opacity-10 rounded-4 bg-dark bg-opacity-10 my-3">
                            <i className="bi bi-graph-up-arrow mb-3 text-primary-glow opacity-50 d-block" style={{ fontSize: '2.5rem' }}></i>
                            <h5 className="fw-bold mb-2">Initialize Analysis Agent</h5>
                            <p className="text-white-50 small mb-4 mx-auto" style={{maxWidth: '350px'}}>
                                Deploy the Data Scientist agent to perform statistical tests and generate visualizations.
                            </p>
                            <button className="btn btn-primary px-5 py-2 rounded-pill shadow-sm" onClick={performAgenticAnalysis}>
                                <i className="bi bi-play-fill me-2"></i> Start Analysis
                            </button>
                        </div>
                    )}

                    {agenticRun.status === 'running' ? (
                        <div className="mt-4 border-top border-secondary border-opacity-10 pt-4">
                            <AgenticAnalysisView 
                                agenticRun={agenticRun} 
                                title="Data Scientist Agent Active" 
                                subtitle="Performing statistical tests and rendering charts..." 
                            />
                        </div>
                    ) : (
                        <GeneratedOutput 
                            stepId={7} 
                            onGenerate={performAgenticAnalysis} 
                            isLoading={false} 
                        />
                    )}
                 </>
             )}
        </div>
    );
};

import { Experiment, FineTuneSettings } from '../config';

/**
 * Retrieves context from previous steps to inform the current prompt.
 * Instead of passing massive full-text outputs, it favors the 'summary' field logic for efficiency.
 */
export const getStepContext = async (experiment: Experiment, currentStepId: number) => {
    const data = experiment.stepData || {};

    // Helper to get summary or output
    const getC = (step: number) => {
        if (!data[step]) return "Not yet generated.";
        return data[step].summary || data[step].output || "Not yet generated.";
    };

    return {
        experimentField: experiment.field,
        question: getC(1),
        literature_review_summary: getC(2),
        hypothesis: getC(3),
        methodology_summary: getC(4),
        data_collection_plan_summary: getC(5),
        experimental_data_summary: getC(6), // From Runner
        analysis_summary: getC(7),
        conclusion_summary: getC(8),
        full_project_summary_log: Object.entries(data)
            .filter(([k, v]) => parseInt(k) < currentStepId && (v.summary || v.output))
            .map(([k, v]) => `Step ${k}: ${v.summary || "Completed"}`)
            .join('\n')
    };
};

/**
 * Main prompt factory. Returns the prompt string, JSON expectation flag, and configuration constraints.
 */
export const getPromptForStep = (
    stepId: number, 
    input: string, 
    context: any, 
    fineTune: FineTuneSettings,
    feedback: string = ""
) => {
    let basePrompt = "";
    let expectJson = false;
    let config: any = {};

    const role = `You are Hypatia, an advanced Research Scientist AI specializing in ${context.experimentField}. You adhere to the Scientific Method rigorously.`;
    // const tuning = Object.entries(fineTune).map(([k, v]) => `${k}: ${v}`).join(', ');
    const feedbackInstruction = feedback ? `\n\nUSER FEEDBACK ON PREVIOUS DRAFT (INCORPORATE THIS): "${feedback}"` : "";

    switch (stepId) {
        case 1: // Question
            expectJson = true;
            basePrompt = `${role}
            Analyze the user's initial research idea and formulate a rigorous, falsifiable Research Question.

            USER INPUT: "${input}"

            CRITICAL: YOU MUST OUTPUT ONLY VALID JSON matching the specified schema.
            The JSON must include:
            - "research_question": The refined question.
            - "study_type": One of ['observational', 'simulation', 'benchmarking', 'controlled_experiment', 'qualitative'].
            - "uniqueness_score": A float 0-1 (1 is highly novel).
            - "justification": Why is this unique?
            - "measurable_outcomes": Array of strings.

            ${feedbackInstruction}`;
            break;

        case 2: // Lit Review
            expectJson = true;
            basePrompt = `${role}
            Conduct a simulated literature review search and synthesis.

            RESEARCH QUESTION: "${context.question}"
            SEARCH DEPTH: ${fineTune.depth || 'standard'}

            Output JSON matching the schema with:
            - "synthesis_narrative": Markdown summary of state-of-the-art.
            - "evidence_gaps": List of missing knowledge this study addresses.
            - "candidate_mechanisms": Theoretical underpinnings.
            - "references": Array of citations (mock or grounded if search tool active).

            ${feedbackInstruction}`;
            break;

        case 3: // Hypothesis
            basePrompt = `${role}
            Formulate 3 distinct hypotheses based on the literature gaps.

            LIT REVIEW CONTEXT: ${context.literature_review_summary}
            RESEARCH QUESTION: ${context.question}

            Output Format:
            1. **Null Hypothesis ($H_0$)**: ...
            2. **Alternative Hypothesis 1 ($H_1$)**: ...
            3. **Alternative Hypothesis 2 ($H_2$)**: ...

            Provide a brief rationale for each.
            ${feedbackInstruction}`;
            break;

        case 4: // Methodology
            basePrompt = `${role}
            Draft a Detailed experimental methodology for:

            HYPOTHESIS: ${context.hypothesis}
            FIELD: ${context.experimentField}

            Include:
            - Study Design (e.g., Double-blind, Randomized Block).
            - Variables (Independent, Dependent, Control).
            - Materials/Equipment.
            - Step-by-step Procedure.

            Ensure the methodology is reproducible.
            ${feedbackInstruction}`;
            break;

        case 5: // Data Plan
            basePrompt = `${role}
            Create a Data collection plan for methodology:

            METHODOLOGY: ${context.methodology_summary}

            Define:
            - Data points to capture.
            - Format (CSV structure).
            - Frequency of measurement.
            - Statistical Power considerations.
            ${feedbackInstruction}`;
            break;

        case 6: // Runner (Used for synthesis prompts mostly)
            basePrompt = `${role}
            Generate synthetic CSV data representing the results of the experiment described below.

            METHODOLOGY: ${context.methodology_summary}

            The data should be realistic, containing some noise/variance, but generally trending to support or refute the hypothesis logically.
            Output ONLY raw CSV data.
            ${feedbackInstruction}`;
            break;

        case 7: // Analysis
            expectJson = true;
            basePrompt = `${role}
            Analyze data: csvData provided in system context.

            CONTEXT:
            - Question: ${context.question}
            - Hypothesis: ${context.hypothesis}

            Execute statistical tests appropriate for ${context.experimentField}.
            Output JSON with:
            - "summary": Markdown analysis.
            - "statistical_outputs": key-value pairs of stats.
            - "charts": Array of Chart.js configurations (type, data, options).
            - "imageData": Optional base64 if available (or use Chart.js config).

            ${feedbackInstruction}`;
            break;

        case 8: // Conclusion
            basePrompt = `${role}
            Draft conclusions from analysis summary:
            ${context.analysis_summary}

            Did the data support $H_1$?
            Discuss limitations, implications, and future work.
            ${feedbackInstruction}`;
            break;

        case 9: // Peer Review
            basePrompt = `${role}
            Simulate a skeptical peer review of this project.

            PROJECT LOG:
            ${context.full_project_summary_log}

            Persona: Strict Academic Reviewer.
            Focus on: ${fineTune.reviewerPersona || 'Methodological Flaws'}.

            Provide a report evaluating rigor, logic, and validity.
            ${feedbackInstruction}`;
            break;

        case 10: // Publication
            basePrompt = `${role}
            Draft a comprehensive scientific publication based on the entire project log.

            PROJECT LOG:
            ${context.full_project_summary_log}

            Structure: Abstract, Introduction, Methods, Results, Discussion, References.
            Use Academic Tone.
            ${feedbackInstruction}`;
            break;

        case 13: // Explanation
             basePrompt = `${role}
             Explain the findings of this research paper in simple terms for a general audience.

             PROJECT CONTEXT:
             ${context.conclusion_summary}

             Focus on the "So What?" and real-world impact.
             `;
             break;

        default:
            basePrompt = `${role} Generate content for step ${stepId}. input: ${input}`;
    }

    return { basePrompt, expectJson, config };
};

