import { GoogleGenAI } from "@google/genai";
import { Blocker } from '../config';

// --- API KEY MANAGEMENT ---

export const getSafeEnvApiKey = () => {
    // @ts-ignore - process is polyfilled in index.html
    if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
        // @ts-ignore
        return process.env.API_KEY;
    }
    return '';
};

export const getCurrentApiKey = () => {
    return getSafeEnvApiKey();
};

export const setStoredApiKey = (key: string) => {
    // No-op: Keys must be managed via environment variables.
    console.warn("Attempted to store API key via client-side storage, which is prohibited.");
};

export const getKeyStatus = () => {
    const envKey = getSafeEnvApiKey();
    if (envKey) return { type: 'env', label: 'Environment Linked', color: 'bg-success' };
    return { type: 'none', label: 'Disconnected', color: 'bg-danger' };
};

export const testApiKey = async (key: string): Promise<boolean> => {
    if (!key) return false;
    try {
        const ai = new GoogleGenAI({ apiKey: key });
        // Simple fast call to test auth
        await ai.models.generateContent({
             model: 'gemini-3-flash-preview',
             contents: 'Test connection.',
        });
        return true;
    } catch (e) {
        console.warn("API Key Test Failed:", e);
        return false;
    }
};

// --- ERROR HANDLING ---

export const parseGeminiError = (error: any, defaultMsg = "An error occurred with the AI service."): string => {
    console.error("Gemini Error:", error);
    const msg = error?.message || error?.toString() || "";

    if (msg.includes("429") || msg.includes("quota")) return "Rate limit exceeded. Please wait a moment.";
    if (msg.includes("401") || msg.includes("API key")) return "Invalid API Key. Please re-authenticate.";
    if (msg.includes("503") || msg.includes("overloaded")) return "AI Service overloaded. Retrying usually fixes this.";
    if (msg.includes("SAFETY")) return "Content blocked by safety filters. Please refine your input.";

    return defaultMsg;
};

// --- UTILITIES ---

export const extractJson = (text: any): string => {
    if (typeof text !== 'string') return "";
    if (!text) return "";

    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match && match[1]) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');

    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

export const isValidJsonForSchema = (jsonString: string, schema: any): boolean => {
    try {
        const obj = JSON.parse(jsonString);
        if (!obj) return false;
        // Basic check: if schema requires certain properties, check existence
        if (schema && schema.required && Array.isArray(schema.required)) {
            for (const field of schema.required) {
                if (!(field in obj)) return false;
            }
        }
        return true;
    } catch (e) {
        return false;
    }
};

export const parseBlockers = (text: string): Blocker[] => {
    try {
        const jsonStr = extractJson(text);
        if (!jsonStr) return [];
        const data = JSON.parse(jsonStr);

        // Handle case where output is ONLY the blocker alert or includes it
        const alert = data.BLOCKER_ALERT || (data.severity ? data : null);
        if (!alert) return [];

        const blockersList = Array.isArray(alert) ? alert : [alert];
        return blockersList
            .filter((b: any) => b && (b.severity === 'critical' || b.severity === 'warning') && b.msg)
            .map((b: any, i: number) => ({
                id: `blk_${Date.now()}_${i}`,
                severity: b.severity,
                msg: b.msg,
                resolved: false
            }));
    } catch (e) {
        return [];
    }
};

// --- GEMINI WRAPPERS ---

const MODEL_CONFIGS: any = {
    'gemini-3-flash-preview': { temperature: 0.7, topK: 40, topP: 0.95 },
    'gemini-3-pro-preview': { temperature: 0.9, topK: 64, topP: 0.95, thinkingConfig: { thinkingBudget: 2048 } }
};

export const callGeminiWithRetry = async (modelName: string, params: any, retries = 2) => {
    // @ts-ignore
    const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("No API Key available in environment variables.");

    const ai = new GoogleGenAI({ apiKey });

    // Ensure config exists and merge defaults
    const defaults = MODEL_CONFIGS[modelName] || {};
    params.config = { ...defaults, ...(params.config || {}) };

    for (let i = 0; i <= retries; i++) {
        try {
            const response = await ai.models.generateContent({
                model: modelName,
                ...params
            });
            return response;
        } catch (error: any) {
            if (i === retries) throw error;
            if (error.message?.includes("429") || error.message?.includes("503")) {
                await new Promise(res => setTimeout(res, 1000 * (i + 1))); // Exponential backoff
            } else {
                throw error;
            }
        }
    }
    throw new Error("Failed after retries");
};

export const callGeminiStreamWithRetry = async (modelName: string, params: any) => {
    // @ts-ignore
    const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("No API Key available in environment variables.");

    const ai = new GoogleGenAI({ apiKey });

    const defaults = MODEL_CONFIGS[modelName] || {};
    params.config = { ...defaults, ...(params.config || {}) };

    try {
        const stream = await ai.models.generateContentStream({
            model: modelName,
            ...params
        });
        return stream;
    } catch (error) {
        console.error("Stream Error", error);
        throw error;
    }
};

export const generateNodeSummary = async (content: string, field: string): Promise<string> => {
    if (!content || content.length < 50) return content;

    const prompt = `As a Research Archivist in ${field}, compress the following content into a concise, high-density summary (max 3 sentences) suitable for context in future steps. Preserve key variables, findings, and numbers.

    CONTENT:
    ${content.substring(0, 15000)}...`;

    try {
        const response = await callGeminiWithRetry('gemini-3-flash-preview', { contents: prompt });
        return response.text || content.substring(0, 200) + "...";
    } catch (e) {
        return content.substring(0, 200) + "...";
    }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Experiment } from './config';
import { db } from './be_db';
import { testApiKey, getSafeEnvApiKey } from './services';
import { useToast } from './toast';
import { ExperimentContext } from './context/ExperimentContext';
import { ErrorBoundary } from './components/common/ErrorBoundary';

import { Header } from './components/common/Header';
import { Footer } from './components/common/Footer';
import { LandingPage } from './components/landing/LandingPage';
import { Dashboard } from './components/dashboard/Dashboard';
import { ExperimentWorkspace } from './components/workspace/ExperimentWorkspace';
import { TestRunner } from './components/testing/TestRunner';
import { LabNotebook } from './components/workspace/LabNotebook';

/**
 * @component App
 * The root component that manages the overall application state, routing, and global context.
 */
export const App = () => {
    const [view, setView] = useState('landing'); 
    const [experiments, setExperiments] = useState<Experiment[]>([]);
    const [activeExperiment, setActiveExperiment] = useState<Experiment | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [isLabNotebookOpen, setLabNotebookOpen] = useState(false);

    const { addToast } = useToast();
    const isInitialized = useRef(false);

    // Initial Data Load
    useEffect(() => {
        let mounted = true;

        const loadData = async () => {
            if (isInitialized.current) return;

            try {
                if (!db || !db.experiments) {
                    throw new Error("Database schema missing.");
                }

                const storedExperiments = await db.experiments.orderBy('createdAt').reverse().toArray();

                if (mounted) {
                    setExperiments(storedExperiments || []);
                }

                // Auto-detect environment key
                const envKey = getSafeEnvApiKey();
                if (envKey) {
                     if (mounted) setIsAuthenticated(true);
                } else {
                    console.warn("No environment API key detected.");
                }
            } catch (error) {
                console.warn("Data load warning:", error);
                if (mounted) addToast("Could not access local archives.", 'warning');
            } finally {
                if (mounted) {
                    setIsLoading(false);
                    isInitialized.current = true;
                }
            }
        };

        loadData();

        return () => { mounted = false; };
    }, [addToast]);

    // Scroll to top on view change
    useEffect(() => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }, [view]);

    // Context Methods - Wrapped in useCallback for referential stability

    const handleAuthentication = useCallback(async (type: 'promo' | 'key' | 'demo', value: string) => {
       // Legacy handler maintained for interface compatibility but effectively deprecated
       // Authentication is now exclusively handled via process.env.API_KEY
       if (getSafeEnvApiKey()) {
            setIsAuthenticated(true);
       }
    }, []);

    const createNewExperiment = useCallback(async (title: string, description: string, field: string) => {
        const newId = `exp_${Date.now()}`;
        const newExperiment: Experiment = {
            id: newId,
            title,
            description,
            field,
            currentStep: 1,
            stepData: {
                1: {
                    input: `Title: ${title}\n\nDescription: ${description}`,
                    history: [],
                    provenance: [],
                }
            },
            fineTuneSettings: {},
            createdAt: new Date().toISOString(),
            labNotebook: '',
            automationMode: null,
            status: 'active',
        };

        try {
            await db.experiments.add(newExperiment);
            setExperiments(prev => [newExperiment, ...prev]);
            setActiveExperiment(newExperiment);
            setView('experiment');
            addToast("Project initialized.", 'success');
        } catch (error) {
            console.error("Failed to save new experiment:", error);
            addToast("Failed to create project database entry.", 'danger');
        }
    }, [addToast]);

    const importExperiment = useCallback(async (experimentData: Experiment) => {
        try {
            if (!experimentData.id || !experimentData.title || !experimentData.createdAt) {
                throw new Error("Invalid experiment file format.");
            }

            // Check for duplicate ID
            const existing = await db.experiments.get(experimentData.id);
            if (existing) {
                // If ID exists, regenerate ID to avoid overwriting unless explicitly desired (safer default)
                experimentData.id = `exp_${Date.now()}_imported`;
                experimentData.title = `${experimentData.title} (Imported)`;
            }

            await db.experiments.add(experimentData);
            const storedExperiments = await db.experiments.orderBy('createdAt').reverse().toArray();
            setExperiments(storedExperiments);
            addToast(`Project imported successfully.`, 'success');
        } catch(error) {
             console.error(error);
             addToast(`Failed to import project. File may be corrupted.`, 'danger');
        }
    }, [addToast]);

    const updateExperiment = useCallback(async (updatedExperiment: Experiment): Promise<Experiment> => {
        try {
            const experimentWithTimestamp = { ...updatedExperiment, updatedAt: new Date().toISOString() };
            await db.experiments.put(experimentWithTimestamp);

            setExperiments(prev => prev.map(e => e.id === experimentWithTimestamp.id ? experimentWithTimestamp : e));

            if (activeExperiment?.id === experimentWithTimestamp.id) {
                setActiveExperiment(experimentWithTimestamp);
            }
            return experimentWithTimestamp;
        } catch (error) {
            console.error("Failed to update experiment:", error);
            addToast("Failed to save changes.", "danger");
            throw error;
        }
    }, [activeExperiment, addToast]);

    const deleteExperiment = useCallback(async (id: string) => {
        if (window.confirm("Are you sure you want to delete this project? This cannot be undone.")) {
            try {
                await db.experiments.delete(id);
                setExperiments(prev => {
                    const updated = prev.filter(e => e.id !== id);
                    // If we deleted the active experiment, kick user to dashboard
                    if (activeExperiment?.id === id) {
                        setActiveExperiment(null);
                        setView(updated.length > 0 ? 'dashboard' : 'landing');
                    }
                    return updated;
                });
                addToast("Project deleted.", 'success');
            } catch (error) {
                addToast("Failed to delete project.", 'danger');
            }
        }
    }, [activeExperiment, addToast]);

    const selectExperiment = useCallback((id: string) => {
        const experiment = experiments.find(e => e.id === id);
        if (experiment) {
            setActiveExperiment(experiment);
            setView('experiment');
        }
    }, [experiments]);

    // Construct context value
    const contextValue = {
        experiments,
        activeExperiment,
        isAuthenticated,
        createNewExperiment,
        updateExperiment,
        deleteExperiment,
        selectExperiment,
        setActiveExperiment,
        importExperiment,
        handleAuthentication,
    };

    if (isLoading) {
        return (
            <div className="d-flex align-items-center justify-content-center vh-100 bg-dark text-white">
                <div className="text-center">
                    <div className="spinner-border text-primary-glow mb-4" role="status" style={{width: '3rem', height: '3rem'}}></div>
                    <h5 className="fw-light ls-1 text-uppercase">Initializing Hypatia...</h5>
                    <p className="text-white-50 small mt-2">Establishing secure archival link</p>
                </div>
            </div>
        );
    }

    return (
        <ErrorBoundary>
            <ExperimentContext.Provider value={contextValue}>
                <Header setView={setView} activeView={view} onToggleNotebook={() => setLabNotebookOpen(p => !p)} />
                <main className="container-fluid mt-4" style={{ minHeight: '80vh' }}>
                    {view === 'landing' && <LandingPage setView={setView} />}
                    {view === 'dashboard' && <Dashboard setView={setView} />}
                    {view === 'experiment' && activeExperiment && <ExperimentWorkspace key={activeExperiment.id} />}
                    {view === 'testing' && <TestRunner />}
                </main>
                {activeExperiment && isAuthenticated && (
                    <LabNotebook 
                        isOpen={isLabNotebookOpen} 
                        onClose={() => setLabNotebookOpen(false)}
                    />
                )}
                <Footer />
            </ExperimentContext.Provider>
        </ErrorBoundary>
    );
};

