import React, { useEffect, useRef } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { Chart } from 'chart.js';

/**
 * @component DataAnalysisView
 * A robust component for rendering the output of the data analysis step,
 * which includes a summary and dynamic Chart.js visualizations.
 */
export const DataAnalysisView = ({ analysisData }) => {
    const chartRefs = useRef<Array<HTMLCanvasElement | null>>([]);

    useEffect(() => {
        const charts: any[] = [];

        if (analysisData?.charts && Array.isArray(analysisData.charts)) {
            analysisData.charts.forEach((chartData, index) => {
                const canvas = chartRefs.current[index];
                if (canvas && chartData.chartConfig) {
                    try {
                        const config = typeof chartData.chartConfig === 'string' 
                            ? JSON.parse(chartData.chartConfig) 
                            : chartData.chartConfig;

                        // Ensure context exists
                        const ctx = canvas.getContext('2d');
                        if (ctx) {
                            const newChart = new Chart(ctx, config);
                            charts.push(newChart);
                        }
                    } catch (e) {
                        console.error("Failed to render chart:", chartData.title, e);
                    }
                }
            });
        }

        return () => {
            charts.forEach(chart => chart.destroy());
        };
    }, [analysisData]);

    if (!analysisData || analysisData.summary === undefined) {
        return <div className="alert alert-info">Awaiting analysis results...</div>;
    }

    const hasCharts = Array.isArray(analysisData.charts) && analysisData.charts.length > 0;

    return (
        <div>
            {analysisData.summary && (
                <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderMarkdown(analysisData.summary) }} />
            )}

            {hasCharts && (
                <div className="mt-4">
                    <h5 className="fw-bold mb-3"><i className="bi bi-bar-chart-fill me-2 text-primary-glow"></i>Experimental Visualizations</h5>
                    <div className="row g-4">
                        {analysisData.charts.map((chart, index) => (
                            <div className="col-lg-6" key={index}>
                                <div className="card h-100 bg-black border-secondary border-opacity-10 shadow-sm">
                                    <div className="card-header border-secondary border-opacity-10 bg-dark bg-opacity-25 fw-bold small text-uppercase ls-1">
                                        {chart.title || `Visual Node ${index + 1}`}
                                    </div>
                                    <div className="card-body p-3" style={{ minHeight: '350px', position: 'relative' }}>
                                        <canvas 
                                            ref={el => chartRefs.current[index] = el}
                                            style={{ width: '100%', height: '100%' }}
                                        ></canvas>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { 
    parseGeminiError, 
    getStepContext, 
    getPromptForStep, 
    executeStepWorkflow, 
    callGeminiStreamWithRetry,
    generateNodeSummary
} from '../../services';
import { WORKFLOW_STEPS, RESEARCH_QUESTION_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, LITERATURE_REVIEW_SCHEMA } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';
import { BlockerDisplay } from './BlockerDisplay';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();

    const [activeStep, setActiveStep] = useState(activeExperiment?.currentStep || 1);
    const [isLoading, setIsLoading] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const [streamingText, setStreamingText] = useState<string | null>(null);
    const [automationPaused, setAutomationPaused] = useState(false);

    const streamBuffer = useRef("");
    const streamInterval = useRef<any>(null);
    const isMounted = useRef(true);
    const lastAutomationTick = useRef<number>(0);

    useEffect(() => {
        isMounted.current = true;
        return () => { 
            isMounted.current = false;
            if (streamInterval.current) {
                clearInterval(streamInterval.current);
            }
        };
    }, []);

    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading && !isVerifying) {
            setActiveStep(activeExperiment.currentStep);
            setAutomationPaused(false); 
        }
    }, [activeExperiment?.currentStep, isLoading, isVerifying, activeStep]);

    // Main Automation Loop
    useEffect(() => {
        if (!activeExperiment || !isAuthenticated || isLoading || isVerifying || automationPaused) return;

        const mode = activeExperiment.automationMode;
        if (mode === 'automated' && activeStep === activeExperiment.currentStep) {
            const now = Date.now();
            if (now - lastAutomationTick.current < 2000) return;
            lastAutomationTick.current = now;

            const stepData = (activeExperiment.stepData && activeExperiment.stepData[activeStep]) || {};
            // Agentic steps handle their own internal generation triggers usually, 
            // but we need to ensure the wrapper doesn't skip them.
            const isAgenticStep = [2, 6, 7, 9, 10].includes(activeStep);

            const hasBlockers = stepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);
            if (hasBlockers) {
                setAutomationPaused(true);
                addToast("Automation paused: Critical protocol blockers detected.", "warning");
                return;
            }

            if (!stepData?.output && !isAgenticStep) {
                handleGenerate();
            } else if (stepData?.output && !stepData?.summary && !isAgenticStep) {
                handleCompleteStep();
            }
        }
    }, [activeExperiment, activeStep, isAuthenticated, isLoading, isVerifying, automationPaused, addToast]);

    const handleStepChange = useCallback((stepId: number) => {
        if (isLoading || isVerifying) return;
        setStreamingText(null);
        setActiveStep(stepId);
        setAutomationPaused(false);
    }, [isLoading, isVerifying]);

    const handleResolveBlocker = async (blockerId: string) => {
        if (!activeExperiment) return;
        const stepData = { ...(activeExperiment.stepData || {}) };
        const currentStepData = { ...(stepData[activeStep] || {}) };
        const blockers = (currentStepData.blockers || []).map(b => 
            b.id === blockerId ? { ...b, resolved: true } : b
        );

        stepData[activeStep] = { ...currentStepData, blockers };
        await updateExperiment({ ...activeExperiment, stepData });
        addToast("Blocker mitigation logged.", "success");
    };

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading || isVerifying) return;

        setStreamingText(null);
        setIsLoading(true);
        streamBuffer.current = "";

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            const input = (activeExperiment.stepData && activeExperiment.stepData[activeStep]?.input) || '';
            const stepSettings = activeExperiment.fineTuneSettings && activeExperiment.fineTuneSettings[activeStep] 
                ? activeExperiment.fineTuneSettings[activeStep] 
                : {};

            const { basePrompt, expectJson, config } = getPromptForStep(
                activeStep, input, context, stepSettings, regenerateFeedback
            );

            if (expectJson) {
                const schema = (activeStep === 1) ? RESEARCH_QUESTION_SCHEMA : (activeStep === 2) ? LITERATURE_REVIEW_SCHEMA : DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
                const model = activeStep === 1 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

                const output = await executeStepWorkflow(model, { contents: basePrompt, config }, context, true, schema);

                if (isMounted.current) {
                    await updateExperiment({ 
                        ...activeExperiment, 
                        stepData: { 
                            ...activeExperiment.stepData, 
                            [activeStep]: { 
                                ...(activeExperiment.stepData?.[activeStep] || {}), 
                                output 
                            } 
                        } 
                    });
                }
            } else {
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });

                if (streamInterval.current) clearInterval(streamInterval.current);
                streamInterval.current = setInterval(() => {
                    if (isMounted.current) {
                        setStreamingText(streamBuffer.current);
                    }
                }, 100);

                for await (const chunk of stream) {
                    streamBuffer.current += (chunk.text || '');
                }

                if (streamInterval.current) {
                    clearInterval(streamInterval.current);
                    streamInterval.current = null;
                }

                if (isMounted.current) {
                    const finalOutput = streamBuffer.current;
                    setStreamingText(finalOutput);

                    await updateExperiment({
                        ...activeExperiment,
                        stepData: { 
                            ...activeExperiment.stepData, 
                            [activeStep]: { 
                                ...(activeExperiment.stepData?.[activeStep] || {}), 
                                output: finalOutput 
                            } 
                        }
                    });
                }
            }
            if (isMounted.current) {
                addToast("Archival node synchronized.", "success");
            }
        } catch (error) {
            if (isMounted.current) {
                addToast(parseGeminiError(error), 'danger');
                if (activeExperiment?.automationMode === 'automated') {
                    setAutomationPaused(true);
                    addToast("Automation paused due to error.", 'warning');
                }
            }
        } finally {
            if (isMounted.current) setIsLoading(false);
            if (streamInterval.current) {
                clearInterval(streamInterval.current);
                streamInterval.current = null;
            }
        }
    };

    const handleCompleteStep = async (stepDataOverride?: any) => {
        if (isVerifying || !activeExperiment) return;

        setIsVerifying(true);
        const currentStepData = { ...(activeExperiment.stepData?.[activeStep] || {}), ...stepDataOverride };
        const currentOutput = currentStepData.output || "";

        // Block progression if unresolved critical blockers exist
        const hasCriticalBlockers = currentStepData.blockers?.some(b => b.severity === 'critical' && !b.resolved);
        if (hasCriticalBlockers) {
            addToast("Resolve critical protocol blockers before proceeding.", "warning");
            setAutomationPaused(true);
            setIsVerifying(false);
            return;
        }

        try {
            let summary = currentStepData.summary;
            if (!summary && currentOutput.length > 50) {
                try {
                    summary = await generateNodeSummary(currentOutput, activeExperiment.field);
                } catch (e) {
                    summary = "Node verified.";
                }
            } else if (!summary) {
                summary = "Node verified.";
            }

            const nextStepId = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : activeStep;
            const updatedStepDataMap = { ...(activeExperiment.stepData || {}) };
            updatedStepDataMap[activeStep] = { ...currentStepData, summary };

            // ENSURE STEP 6 -> 7 DATA FLOW IS ATOMIC
            if (activeStep === 6) {
                const csvData = currentStepData.input || currentOutput; 
                updatedStepDataMap[7] = { 
                    ...(updatedStepDataMap[7] || {}), 
                    input: csvData,
                    output: undefined,
                    summary: undefined 
                };
            }

            const updatedExp = { 
                ...activeExperiment, 
                stepData: updatedStepDataMap, 
                currentStep: nextStepId 
            };

            // Wait for DB write before state change
            await updateExperiment(updatedExp);

            if (isMounted.current) {
                addToast(`Step ${activeStep} verified. Initiating Step ${nextStepId}.`, "success");
                setActiveStep(nextStepId);
            }
        } catch (error) {
            console.error("Verification error:", error);
            if (isMounted.current) {
                addToast("Archive link unstable. Could not verify node.", 'danger');
                if (activeExperiment?.automationMode === 'automated') {
                    setAutomationPaused(true);
                }
            }
        } finally {
            if (isMounted.current) setIsVerifying(false);
        }
    };

    const renderStepContent = () => {
        if (!activeExperiment) return null;
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} />;
        }

        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={handleCompleteStep} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 10) return <PublicationExporter />;

        return (
            <div className="discovery-view">
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    if (!activeExperiment) return null;

    const currentStepData = activeExperiment.stepData?.[activeStep];
    const hasOutput = currentStepData?.output;
    const hasCriticalBlocker = currentStepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);

    return (
        <div className="workspace-container">
            <aside className="sidebar-nav">
                <div className="card shadow-sm border-secondary border-opacity-10 overflow-hidden">
                    <div className="card-header fw-bold bg-dark py-3 small ls-1 text-uppercase">
                        <i className="bi bi-cpu-fill text-primary-glow me-2"></i> Timeline
                    </div>
                    <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                            <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                                style={{ cursor: step.id <= activeExperiment.currentStep ? 'pointer' : 'default' }}
                            >
                                <span className="small">{step.id}. {step.title}</span>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                </div>
            </aside>

            <main className="content-area">
                <div className="card shadow-sm border-secondary border-opacity-25 position-relative overflow-hidden">
                    {(isLoading || isVerifying) && (
                        <div className="progress rounded-0" style={{ height: '3px', position: 'absolute', top: 0, left: 0, right: 0, zIndex: 100 }}>
                            <div className="progress-bar progress-bar-striped progress-bar-animated bg-primary-glow w-100"></div>
                        </div>
                    )}
                    <div className="card-body p-4" style={{ minHeight: '60vh' }}>
                        <div className="d-flex justify-content-between align-items-start mb-4">
                            <div>
                                <div className="badge bg-primary bg-opacity-10 text-primary-glow mb-2">Step {activeStep}</div>
                                <h4 className="fw-bold mb-1">{WORKFLOW_STEPS[activeStep - 1]?.title || 'Node Overview'}</h4>
                                <p className="text-white-50 small mb-0">{WORKFLOW_STEPS[activeStep - 1]?.description}</p>
                            </div>
                            {activeExperiment.automationMode === 'automated' && (
                                <div className="d-flex flex-column align-items-end">
                                    <span className={`badge ${automationPaused ? 'bg-warning text-dark' : 'bg-primary'} px-3 py-2 rounded-pill shadow-sm mb-2`}>
                                        <i className={`bi ${automationPaused ? 'bi-pause-circle-fill' : 'bi-cpu-fill'} me-1`}></i> 
                                        {automationPaused ? 'AUTOMATION PAUSED' : 'AGENTIC OVERRIDE ACTIVE'}
                                    </span>
                                    {automationPaused && (
                                        <button className="btn btn-xs btn-outline-warning" onClick={() => setAutomationPaused(false)}>
                                            <i className="bi bi-play-fill me-1"></i> RESUME
                                        </button>
                                    )}
                                </div>
                            )}
                        </div>
                        <hr className="border-secondary opacity-10 mb-4" />

                        {currentStepData?.blockers && (
                            <BlockerDisplay 
                                blockers={currentStepData.blockers} 
                                onResolve={handleResolveBlocker} 
                            />
                        )}

                        {renderStepContent()}
                    </div>

                    {activeStep <= WORKFLOW_STEPS.length && (
                        <div className="card-footer d-flex justify-content-between align-items-center p-3 bg-dark bg-opacity-25 border-top border-secondary border-opacity-10">
                            <button className="btn btn-sm btn-outline-secondary" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Tuning
                            </button>
                            <button 
                                className={`btn btn-${hasCriticalBlocker ? 'outline-danger' : 'success'} px-4 shadow-sm`} 
                                onClick={() => handleCompleteStep()} 
                                disabled={isVerifying || !hasOutput || hasCriticalBlocker}
                            >
                                {isVerifying ? (
                                    <span className="spinner-border spinner-border-sm me-2"></span>
                                ) : (
                                    <i className={`bi ${hasCriticalBlocker ? 'bi-lock-fill' : (hasOutput ? 'bi-check-circle-fill' : 'bi-lock-fill')} me-2`}></i> 
                                )}
                                {hasCriticalBlocker ? 'PROTOCOL BLOCKED' : (activeStep === 10 ? "Finish Project" : "Verify Node & Continue")}
                            </button>
                        </div>
                    )}
                </div>
            </main>

            {fineTuneModalOpen && (
                <FineTuneModal stepId={activeStep} onClose={() => setFineTuneModalOpen(false)} />
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useExperiment } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry } from '../../../services';
import { DYNAMIC_TABLE_SCHEMA } from '../../../config';
import * as XLSX from 'xlsx';

export const ManualDataEntry = ({ onComplete, context }) => {
    const { isAuthenticated, activeExperiment, updateExperiment } = useExperiment();
    const [columns, setColumns] = useState<string[]>([]);
    const [rows, setRows] = useState<Record<string, string>[]>([]);
    const [isInitializing, setIsInitializing] = useState(true);
    const { addToast } = useToast();
    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;

        // Pause automation if we are in manual entry mode to allow user input
        if (activeExperiment?.automationMode === 'automated') {
             addToast("Manual Data Entry required. Automation paused.", "info");
        }

        return () => { isMounted.current = false; };
    }, []);

    const getXLSX = () => {
        // @ts-ignore
        return XLSX.default || XLSX;
    }

    useEffect(() => {
        let active = true;

        if (isAuthenticated) {
            const prompt = `Based on the data collection plan summary: "${context.data_collection_plan_summary}", generate a JSON array of objects. Each object should represent a column for a data entry table and have two keys: "columnName" (string) and "dataType" (string, e.g., 'number', 'string'). For example: [{"columnName": "time_seconds", "dataType": "number"}, {"columnName": "temperature_celsius", "dataType": "number"}]. Output only the raw JSON array.`;
            callGeminiWithRetry('gemini-3-flash-preview', { 
                contents: prompt, 
                config: { responseMimeType: "application/json", responseSchema: DYNAMIC_TABLE_SCHEMA } 
            })
                .then(response => {
                    if (!active || !isMounted.current) return;
                    const schemaArray = JSON.parse(response.text);
                    if (!Array.isArray(schemaArray)) throw new Error("AI response was not a JSON array.");
                    const newColumns = schemaArray.map(col => col.columnName);

                    setColumns(newColumns);
                    setRows([Object.fromEntries(newColumns.map(c => [c, '']))]);
                })
                .catch(err => {
                    if (!active || !isMounted.current) return;
                    addToast(parseGeminiError(err, "AI failed to create a data entry form."), "danger");
                    setColumns(['Column 1', 'Column 2']);
                    setRows([{'Column 1': '', 'Column 2': ''}]);
                })
                .finally(() => {
                    if (active && isMounted.current) setIsInitializing(false);
                });
        }

        return () => { active = false; };
    }, [isAuthenticated, context, addToast]);

    const handleRowChange = (index, col, value) => {
        const newRows = [...rows];
        newRows[index][col] = value;
        setRows(newRows);
    };

    const addRow = () => setRows([...rows, Object.fromEntries(columns.map(c => [c, '']))]);
    const removeRow = (index) => setRows(rows.filter((_, i) => i !== index));

    const handleSubmit = () => {
        const header = columns.join(',');
        const body = rows.map(row => columns.map(col => `"${(row[col] || '').replace(/"/g, '""')}"`).join(',')).join('\n');
        const csvData = `${header}\n${body}`;
        onComplete(csvData, "Manually entered data.");
    };

    const handleDownloadTemplate = () => {
        if (columns.length === 0) {
            addToast("Columns are still being generated by the AI.", "warning");
            return;
        }
        try {
            const Lib = getXLSX();
            const ws = Lib.utils.aoa_to_sheet([columns]);
            const wb = Lib.utils.book_new();
            Lib.utils.book_append_sheet(wb, ws, "Data Entry");

            const wscols = columns.map(col => ({ wch: col.length + 5 }));
            ws['!cols'] = wscols;

            Lib.writeFile(wb, "Data_Entry_Template.xlsx");
            addToast("Excel template downloaded.", "success");
        } catch (e) {
            console.error(e);
            addToast("Failed to generate Excel template.", "danger");
        }
    };

    if (isInitializing) return <div className="text-center p-4"><div className="spinner-border"></div><p className="mt-2">AI is building your data entry form...</p></div>;

    return (
        <div className="animate-in">
            <div className="card mb-4">
                <div className="card-body">
                    <h6 className="fw-bold">Step 6: Forensic Data Entry</h6>
                    <p className="small text-white-50 mb-3">Manually reconstruct the archival record by populating the table below.</p>
                    <div className="table-responsive">
                        <table className="table table-bordered border-secondary border-opacity-10 mb-3">
                            <thead className="bg-dark bg-opacity-50">
                                <tr>{columns.map(c => <th key={c} className="small text-uppercase ls-1">{c}</th>)}<th style={{ width: '50px' }}></th></tr>
                            </thead>
                            <tbody>
                                {rows.map((row, rowIndex) => (
                                    <tr key={rowIndex}>
                                        {columns.map(col => <td key={col} className="p-1"><input type="text" className="form-control form-control-sm border-0 bg-transparent text-white" value={row[col] || ''} onChange={e => handleRowChange(rowIndex, col, e.target.value)} /></td>)}
                                        <td className="p-1 text-center"><button className="btn btn-sm text-danger" onClick={() => removeRow(rowIndex)} disabled={rows.length <= 1}><i className="bi bi-x-lg"></i></button></td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                    <div className="d-flex justify-content-between">
                        <button className="btn btn-sm btn-outline-secondary" onClick={addRow}><i className="bi bi-plus-lg me-1"></i> Add Record</button>
                        <button className="btn btn-success px-4" onClick={handleSubmit}><i className="bi bi-check-circle-fill me-1"></i> Finalize Manual Entry</button>
                    </div>
                </div>
            </div>

            <div className="card bg-dark bg-opacity-25 border-secondary border-opacity-10">
                <div className="card-body">
                     <h6 className="fw-bold small text-uppercase ls-1">Archival Alternative: Spreadsheet Link</h6>
                     <p className="small text-white-50 mb-3">Download a pre-formatted template if you prefer offline reconstruction.</p>
                     <button className="btn btn-sm btn-outline-info" onClick={handleDownloadTemplate} disabled={columns.length === 0}>
                         <i className="bi bi-file-earmark-excel-fill me-1"></i> DOWNLOAD TEMPLATE (.XLSX)
                     </button>
                 </div>
            </div>
        </div>
    );
};

import { Experiment, LITERATURE_REVIEW_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA } from '../config';
import { callGeminiWithRetry, extractJson, isValidJsonForSchema, parseBlockers } from './api';
import { getStepContext } from './prompts';
import { ensureChartStyling } from '../utils/chartUtils';

export const executeStepWorkflow = async (
    modelName: string, 
    params: any, 
    context: any, 
    isJsonMode: boolean, 
    schema: any
): Promise<string> => {
    if (isJsonMode && schema) {
        params.config = { 
            ...params.config, 
            responseMimeType: "application/json", 
            responseSchema: schema 
        };
    }

    const response = await callGeminiWithRetry(modelName, params);
    let output = response.text;

    if (isJsonMode) {
        output = extractJson(output);
        if (!isValidJsonForSchema(output, schema)) {
            // Self-Correction Loop
            console.warn("Schema validation failed, attempting self-correction...");
            const repairPrompt = `The previous output did not match the required JSON schema. 
            ERROR: Invalid Schema. 
            REQUIRED SCHEMA: ${JSON.stringify(schema)}
            PREVIOUS OUTPUT: ${output}

            Fix the JSON structure.`;

            const repairResponse = await callGeminiWithRetry('gemini-3-flash-preview', { contents: repairPrompt, config: { responseMimeType: "application/json", responseSchema: schema } });
            output = extractJson(repairResponse.text);
        }
    }
    return output;
};


// --- AGENTIC WORKFLOWS ---

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }: { experiment: Experiment, csvData: string, updateLog: (agent: string, msg: string) => void }) => {
    updateLog('Manager', 'Initializing Data Analysis Agent Swarm...');

    const context = await getStepContext(experiment, 7);

    // 1. Data Profiler
    updateLog('Profiler', 'Scanning dataset structure and quality...');
    const profilerPrompt = `
    Analyze this dataset to identify its structure, variables, and potential anomalies.

    DATASET (First 5000 chars):
    ${csvData.substring(0, 5000)}

    RESEARCH CONTEXT:
    - Question: ${context.question}
    - Hypothesis: ${context.hypothesis}

    Identify:
    - Independent/Dependent variables.
    - Presence of noise/outliers.
    - Appropriate statistical tests for this data distribution.
    `;

    const profileRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: profilerPrompt });
    updateLog('Profiler', 'Data profile and statistical mapping generated.');

    // 2. Statistician & Visualizer (Combined for speed/consistency)
    updateLog('Analyst', 'Executing statistical tests and generating high-fidelity visualizations...');
    const analysisPrompt = `
    ACT AS: Senior Data Scientist & Research Statistician.
    TASK: Perform a rigorous statistical analysis on the provided dataset to test the hypothesis.

    DATA PROFILE: ${profileRes.text}
    RAW DATA: ${csvData}

    HYPOTHESIS TO TEST: ${context.hypothesis}
    RESEARCH QUESTION: ${context.question}
    FIELD: ${experiment.field}

    REQUIREMENTS:
    1. Perform appropriate tests (e.g., ANOVA, t-test, Linear Regression, Correlation coefficients).
    2. Identify p-values and confidence intervals.
    3. Generate a detailed Markdown summary of the results including a discussion on whether the null hypothesis is rejected.
    4. Generate AT LEAST TWO (2) distinct Chart.js configuration objects (as JSON strings) to visualize key trends/comparisons.
       - Use diverse chart types (e.g., Scatter plot, Bar/Box plot, Line chart).
       - Ensure titles and labels are descriptive.
       - The output must fit the schema's 'chartConfig' string field.

    CRITICAL: Output MUST be valid JSON matching the provided schema.
    `;

    const analysisRes = await callGeminiWithRetry('gemini-3-pro-preview', { 
        contents: analysisPrompt,
        config: { 
            responseMimeType: "application/json", 
            responseSchema: DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
            thinkingConfig: { thinkingBudget: 4096 }
        }
    });

    let resultJson = extractJson(analysisRes.text);

    // Post-process charts to ensure visibility in dark mode
    try {
        const parsed = JSON.parse(resultJson);
        if (parsed.charts && Array.isArray(parsed.charts)) {
            parsed.charts = parsed.charts.map((c: any) => {
                const config = typeof c.chartConfig === 'string' ? JSON.parse(c.chartConfig) : c.chartConfig;
                const styledConfig = ensureChartStyling(config);
                return { ...c, chartConfig: JSON.stringify(styledConfig) };
            });
            resultJson = JSON.stringify(parsed);
        }
        updateLog('Visualizer', 'Visual assets synthesized and optimized for display.');
    } catch (e) {
        console.error("Analysis post-processing error:", e);
        updateLog('System', 'Warning: visualization post-processing encountered a minor logic error.');
    }

    // 3. Blocker Check
    updateLog('Safety', 'Verifying integrity of the analysis results...');
    const blockerPrompt = `Analyze the analysis results for any scientific integrity blockers or logical contradictions.
    RESULTS: ${resultJson}

    Output JSON: { "BLOCKER_ALERT": [ { "severity": "critical"|"warning", "msg": "..." } ] } or an empty object if no issues found.`;

    const blockerRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: blockerPrompt });
    const blockers = parseBlockers(blockerRes.text);

    return { finalOutput: resultJson, blockers, logSummary: profileRes.text };
};

export const runPublicationAgent = async ({ experiment, updateLog }: { experiment: Experiment, updateLog: (agent: string, msg: string) => void }) => {
    updateLog('Manager', 'Compiling project dossier...');
    const context = await getStepContext(experiment, 10);

    updateLog('Writer', 'Drafting manuscript structure...');
    const outlinePrompt = `Create a detailed outline for a scientific paper based on this log:
    ${context.full_project_summary_log}
    `;
    const outlineRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: outlinePrompt });

    updateLog('Writer', 'Writing full content (this may take a moment)...');
    const fullDraftPrompt = `
    ACT AS: Academic Author.
    TASK: Write the full scientific paper based on the Outline and Project Log.

    OUTLINE: ${outlineRes.text}
    PROJECT LOG: ${context.full_project_summary_log}
    DETAILS:
    - Hypothesis: ${context.hypothesis}
    - Results: ${context.analysis_summary}

    IMPORTANT:
    - Insert [CHART_X: Caption] placeholders where charts from the analysis should appear.
    - Use Markdown formatting.
    - Be rigorous and formal.
    `;

    const draftRes = await callGeminiWithRetry('gemini-3-pro-preview', { contents: fullDraftPrompt });
