export const runPeerReviewAgent = async ({ experiment, updateLog }: { experiment: Experiment, updateLog: (agent: string, msg: string) => void }) => {
    const steps = [3, 4, 5, 7];
    let critiqueLog = "";

    for (const step of steps) {
        updateLog('Reviewer', `Analyzing Step ${step} logic...`);
        const stepContent = experiment.stepData[step]?.output || "";
        const critiquePrompt = `Critique this scientific step output for logic, bias, and rigor. Be harsh.
        STEP ${step} CONTENT: ${stepContent.substring(0, 5000)}`;

        const res = await callGeminiWithRetry('gemini-3-flash-preview', { contents: critiquePrompt });
        critiqueLog += `\n\nSTEP ${step} CRITIQUE:\n${res.text}`;
    }

    updateLog('Editor', 'Compiling final peer review report...');
    const finalReportPrompt = `Summarize these critiques into a formal Peer Review Report.

    CRITIQUES: ${critiqueLog}`;

    const finalRes = await callGeminiWithRetry('gemini-3-pro-preview', { contents: finalReportPrompt });
    return finalRes.text;
};

import React, { useState, useEffect, useRef } from 'react';
import { useExperiment, runDataQA } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry } from '../../../services';
import { AgenticAnalysisView } from '../../common/AgenticAnalysisView';

export const CodeSimulator = ({ onComplete, context }) => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const [code, setCode] = useState(activeExperiment.stepData[6]?.input || '');
    const [isInitializing, setIsInitializing] = useState(false);
    const [initLogs, setInitLogs] = useState([]);
    const { addToast } = useToast();
    const workerRef = useRef<Worker | null>(null);
    const workerUrlRef = useRef<string | null>(null);
    const isMounted = useRef(true);

    const [agenticRun, setAgenticRun] = useState({
        status: 'idle', 
        logs: [],
        iterations: 0,
        maxIterations: 25,
    });

    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    useEffect(() => {
        const createWorker = () => {
            const workerCode = `
                self.onmessage = (event) => {
                    const { code } = event.data;
                    let finished = false;
                    const hypatia = {
                        finish: (data, summary) => {
                            self.postMessage({ type: 'finish', payload: { data, summary } });
                            finished = true;
                        }
                    };
                    const consoleProxy = {
                        log: (...args) => {
                            const logMsg = args.map(arg => String(arg)).join(' ');
                            self.postMessage({ type: 'log', payload: logMsg });
                        }
                    };
                    try {
                        new Function('console', 'hypatia', code)(consoleProxy, hypatia);
                        if (!finished) self.postMessage({ type: 'done' });
                    } catch (e) {
                        self.postMessage({ type: 'error', payload: \`[\${e.name}] \${e.message}\` });
                    }
                };
            `;
            const blob = new Blob([workerCode], { type: 'application/javascript' });
            const url = URL.createObjectURL(blob);
            workerUrlRef.current = url;
            return new Worker(url);
        };
        workerRef.current = createWorker();
        return () => { 
            if (workerRef.current) workerRef.current.terminate(); 
            if (workerUrlRef.current) URL.revokeObjectURL(workerUrlRef.current);
        };
    }, []);

    useEffect(() => {
        if (!code && isAuthenticated) {
            const runInitializationAgent = async () => {
                if (!isMounted.current) return;
                setIsInitializing(true);
                const log = (agent, message) => {
                    if (isMounted.current) setInitLogs(prev => [...prev, { agent, message }]);
                };
                try {
                    log('Simplifier', 'Extracting experimental variables from methodology...');

                    const simplifierPrompt = `
                        ACT AS: Senior Research Data Scientist.
                        TASK: Translate the following Experimental Methodology into a logical simulation specification for a coder.

                        INPUT CONTEXT:
                        - Hypothesis: "${context.hypothesis}"
                        - Methodology: "${context.methodology_summary}" (e.g. "Apply caffeine solution to Arabidopsis seedlings")
                        - Data Plan: "${context.data_collection_plan_summary}"

                        OUTPUT SPECIFICATION:
                        1. Identify the **Independent Variable** (e.g., Caffeine Concentration, Time).
                        2. Identify the **Dependent Variable** (e.g., Stem Length, Root Growth, Reaction Rate).
                        3. Define a **plausible mathematical relationship** between them (e.g., as concentration increases, growth decreases logarithmically; or linear growth over time).
                        4. Specify **Sample Size** (target 30-50 points) and **Data Types** (float, integer).

                        Provide clear, step-by-step logic for the simulation code.
                    `;

                    const simplifierResponse = await callGeminiWithRetry('gemini-3-flash-preview', { 
                        contents: simplifierPrompt 
                    });
                    if (!isMounted.current) return;
                    const instructions = simplifierResponse.text;

                    log('Coder', 'Generating autonomous simulation script...');

                    const coderPrompt = `
                        ACT AS: Scientific JavaScript Developer.
                        TASK: Write a JavaScript Web Worker script to simulate the experiment described below.

                        SIMULATION LOGIC SPEC:
                        ${instructions}

                        CRITICAL REQUIREMENTS:
                        1. **Data Generation**: Use a loop to generate 20-50 data points.
                        2. **Mathematical Model**: Implement the logic defined in the spec above. 
                        3. **NOISE**: You MUST add \`Math.random()\` variance to *every* dependent variable calculation to simulate real-world biological/physical variability. Data should look organic, not perfect.
                        4. **CSV Format**: Generate a valid CSV string with a header row.
                        5. **Final Handoff**: You MUST call \`hypatia.finish(csvData, summary)\` at the end of the script.
                           - \`csvData\`: The generated CSV string.
                           - \`summary\`: A short string explaining the simulated trend (e.g., "Simulated negative correlation between caffeine and growth.").

                        RESTRICTIONS:
                        - NO DOM access (no window, document, alert).
                        - Use \`console.log\` for debugging.

                        EXAMPLE CODE STRUCTURE:
                        \`\`\`javascript
                        const header = "Concentration_mM,Growth_cm";
                        let csv = header + "\\n";
                        for (let i = 0; i < 30; i++) {
                            const x = i * 5; // Independent
                            const noise = (Math.random() - 0.5) * 2; // Random variance
                            const y = Math.max(0, 10 - (0.1 * x) + noise); // Dependent logic with noise
                            csv += \`\${x},\${y.toFixed(2)}\\n\`;
                        }
                        hypatia.finish(csv, "Simulated growth inhibition with random noise.");
                        \`\`\`

                        Output ONLY the raw JavaScript code. Do not wrap in markdown code blocks if possible, or I will strip them.`;

                    const coderResponse = await callGeminiWithRetry('gemini-3-flash-preview', { 
                        contents: coderPrompt 
                    });
                    if (!isMounted.current) return;
                    const initialCode = coderResponse.text.trim().replace(/```javascript/g, '').replace(/```/g, '');
                    setCode(initialCode);
                    log('Coder', 'Initial script ready for testing.');
                } catch (err) {
                    if (isMounted.current) addToast("Failed to initialize coder.", "danger");
                } finally { 
                    if (isMounted.current) setIsInitializing(false); 
                }
            };
            runInitializationAgent();
        }
    }, [isAuthenticated, context, code, addToast]);

    const executeCodeInWorker = (codeToRun: string): Promise<any> => {
        return new Promise((resolve, reject) => {
            let timeoutId: any;

            const messageHandler = (event) => {
                const { type, payload } = event.data;
                if (type === 'log' && isMounted.current) {
                    setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Simulator', message: payload }] }));
                }

                if (type === 'finish' || type === 'done' || type === 'error') {
                    clearTimeout(timeoutId);
                    workerRef.current?.removeEventListener('message', messageHandler);
                    if (type === 'error') reject(payload); else resolve({ type, payload });
                }
            };

            // Watchdog Timer: Protect against infinite loops or hangs
            timeoutId = setTimeout(() => {
                workerRef.current?.removeEventListener('message', messageHandler);
                workerRef.current?.terminate(); // Hard reset of the worker environment

                // Re-initialize worker for the next attempt if mounted
                if (isMounted.current) {
                    if (workerUrlRef.current) URL.revokeObjectURL(workerUrlRef.current);

                    const workerCode = `
                        self.onmessage = (event) => {
                            const { code } = event.data;
                            let finished = false;
                            const hypatia = {
                                finish: (data, summary) => {
                                    self.postMessage({ type: 'finish', payload: { data, summary } });
                                    finished = true;
                                }
                            };
                            const consoleProxy = {
                                log: (...args) => {
                                    const logMsg = args.map(arg => String(arg)).join(' ');
                                    self.postMessage({ type: 'log', payload: logMsg });
                                }
                            };
                            try {
                                new Function('console', 'hypatia', code)(consoleProxy, hypatia);
                                if (!finished) self.postMessage({ type: 'done' });
                            } catch (e) {
                                self.postMessage({ type: 'error', payload: \`[\${e.name}] \${e.message}\` });
                            }
                        };
                    `;
                    const blob = new Blob([workerCode], { type: 'application/javascript' });
                    const url = URL.createObjectURL(blob);
                    workerUrlRef.current = url;
                    workerRef.current = new Worker(url);
                }
                reject("Execution Timeout: Simulation hung for over 10 seconds.");
            }, 10000);

            workerRef.current?.addEventListener('message', messageHandler);
            workerRef.current?.postMessage({ code: codeToRun });
        });
    };

    const runAgenticSimulation = async () => {
        if (agenticRun.status === 'running') return;
        setAgenticRun(prev => ({ ...prev, status: 'running', logs: [], iterations: 0 }));

        let currentCode = code;
        for (let i = 0; i < agenticRun.maxIterations; i++) {
            if (!isMounted.current) return;
            setAgenticRun(prev => ({ 
                ...prev, 
                iterations: i + 1, 
                logs: [...prev.logs, { agent: 'System', message: `Attempt ${i + 1}: Running simulation...` }] 
            }));

            try {
                const result = await executeCodeInWorker(currentCode);
                if (!isMounted.current) return;

                if (result.type === 'finish') {
                    // Perform Data QA
                    setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'QA Auditor', message: 'Analyzing generated dataset for fidelity...' }] }));
                    const qaResult = await runDataQA(result.payload.data, context);

                    if (qaResult.is_valid && qaResult.quality_score > 0.6) {
                        setAgenticRun(prev => ({ ...prev, status: 'success' }));
                        onComplete(result.payload.data, result.payload.summary);
                        return;
                    } else {
                        throw new Error(`QA Failure: ${qaResult.issues.join(', ')}. ${qaResult.recommendation}`);
                    }
                }
                throw new Error("Simulation execution completed but hypatia.finish() was never invoked.");
            } catch (error) {
                if (!isMounted.current) return;
                setAgenticRun(prev => ({ 
                    ...prev, 
                    logs: [...prev.logs, { agent: 'Debugger', message: `Issue detected: ${error}. Triggering Self-Healing Loop.` }] 
                }));

                const debuggerPrompt = `DEBUGGER LOG: The following code or its output failed quality checks. 
                ISSUE: "${error}". 
                MISSION: Fix the logic and ensure hypatia.finish(csvData, summary) is called with plausible, high-fidelity simulated data that passes auditor checks.

                CODE:
                ${currentCode}`;

                try {
                    const res = await callGeminiWithRetry('gemini-3-flash-preview', { 
                        contents: debuggerPrompt 
                    });
                    if (isMounted.current) {
                        currentCode = res.text.trim().replace(/```javascript/g, '').replace(/```/g, '');
                        setCode(currentCode);
                        await new Promise(r => setTimeout(r, 1000));
                    }
                } catch (e) {
                    if (isMounted.current) addToast("Self-healing link unstable.", "warning");
                }
            }
        }
        if (isMounted.current) setAgenticRun(prev => ({ ...prev, status: 'failed' }));
    };

    return (
        <div>
            <div className="doc-section mb-3">
                <h6 className="fw-bold">AI Agent Simulation Hub</h6>
                <p className="small text-white-50">Specialized agents are drafting and debugging a JavaScript simulation of your methodology. The <strong>Self-Healing Debugger</strong> will autonomously resolve any runtime errors or logical hangs.</p>
            </div>
            {isInitializing && <AgenticAnalysisView agenticRun={{logs: initLogs, iterations: 0, maxIterations: 0}} title="Coder Agent Initializing..." />}
            <textarea 
                id="code-editor" 
                className="form-control mb-3 font-monospace bg-black text-primary-glow border-secondary border-opacity-25" 
                style={{ height: '300px', fontSize: '0.85rem' }}
                value={code} 
                onChange={(e) => setCode(e.target.value)} 
            />
            <button className="btn btn-primary w-100" onClick={runAgenticSimulation} disabled={!code || agenticRun.status === 'running'}>
                {agenticRun.status === 'running' ? 'Self-Healing Loop Active...' : 'Start Agentic Simulation'}
            </button>
            {agenticRun.logs.length > 0 && <AgenticAnalysisView agenticRun={agenticRun} title="Self-Healing Debugger Log" subtitle="Adversarial debugging logic is active." />}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useExperiment, runDataQA } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry } from '../../../services';

export const DataSynthesizer = ({ onComplete, context }) => {
    const { isAuthenticated } = useExperiment();
    const [result, setResult] = useState<{ summary: string, csv: string } | null>(null);
    const [isSynthesizing, setIsSynthesizing] = useState(false);
    const { addToast } = useToast();

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    const handleSynthesize = async (retryFeedback = '') => {
        if (!isAuthenticated) return;
        setIsSynthesizing(true);
        const prompt = `DATA PROVENANCE REQUIREMENT: You are synthesizing synthetic data. 
        Based on Methodology: "${context.methodology_summary}" and Data Plan: "${context.data_collection_plan_summary}", generate a plausible estimated dataset in CSV format. 

        ${retryFeedback ? `PREVIOUS ATTEMPT FAILED QA: ${retryFeedback}. Fix these issues.` : ''}

        **CRITICAL**: You MUST explicitly state in the summary that: "This experimental data was synthesized by AI Generation for theoretical exploration." 

        Output ONLY the CSV data and a brief, one-sentence summary. Separate with '---'.`;

        try {
            const response = await callGeminiWithRetry('gemini-3-flash-preview', { 
                contents: prompt 
            });

            if (isMounted.current) {
                const parts = response.text.split('---');
                let summary = "";
                let csv = "";

                if (parts.length >= 2) {
                     summary = parts[0].trim();
                     csv = parts[1].trim();
                } else {
                     csv = response.text;
                     summary = "Data synthesized by AI.";
                }

                // QA Step
                addToast("Auditing synthesized dataset...", "info");
                const qa = await runDataQA(csv, context);

                if (qa.is_valid && qa.quality_score > 0.5) {
                    setResult({ summary, csv });
                    addToast("AI synthesized and verified the dataset.", "success");
                } else {
                    addToast(`Dataset failed QA audit: ${qa.issues[0]}. Retrying...`, "warning");
                    handleSynthesize(qa.recommendation || qa.issues.join('; '));
                }
            }
        } catch (err) {
            if (isMounted.current) {
                addToast(parseGeminiError(err), "danger");
            }
        } finally { 
            if (isMounted.current) {
                setIsSynthesizing(false); 
            }
        }
    };

    return (
        <div className="text-center p-4">
            <h6 className="fw-bold"><i className="bi bi-magic me-2"></i>AI Data Synthesis</h6>
            <p className="text-white-50">Generate a plausible theoretical dataset using AI synthesis. This data is labeled as <strong>AI-Synthesized</strong>.</p>
            <button className="btn btn-primary" onClick={() => handleSynthesize()} disabled={isSynthesizing}>
                {isSynthesizing ? 'Synthesizing...' : 'Generate Synthetic Dataset'}
            </button>
            {result && (
                <div className="mt-4 text-start">
                    <p className="small"><strong>Disclosure:</strong> {result.summary}</p>
                    <textarea className="form-control font-monospace mb-3" readOnly rows={6} value={result.csv} />
                    <button className="btn btn-success w-100" onClick={() => onComplete(result.csv, result.summary)}>Use This Data</button>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { 
    parseGeminiError, 
    getStepContext, 
    getPromptForStep, 
    executeStepWorkflow, 
    callGeminiStreamWithRetry,
    generateNodeSummary
} from '../../services';
import { WORKFLOW_STEPS, RESEARCH_QUESTION_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, LITERATURE_REVIEW_SCHEMA } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';
import { BlockerDisplay } from './BlockerDisplay';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();

    const [activeStep, setActiveStep] = useState(activeExperiment?.currentStep || 1);
    const [isLoading, setIsLoading] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const [streamingText, setStreamingText] = useState<string | null>(null);
    const [automationPaused, setAutomationPaused] = useState(false);

    const streamBuffer = useRef("");
    const streamInterval = useRef<any>(null);
    const isMounted = useRef(true);
    const lastAutomationTick = useRef<number>(0);

    useEffect(() => {
        isMounted.current = true;
        return () => { 
            isMounted.current = false;
            if (streamInterval.current) {
                clearInterval(streamInterval.current);
            }
        };
    }, []);

    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading && !isVerifying) {
            setActiveStep(activeExperiment.currentStep);
            setAutomationPaused(false); 
        }
    }, [activeExperiment?.currentStep, isLoading, isVerifying, activeStep]);

    // Main Automation Loop
    useEffect(() => {
        if (!activeExperiment || !isAuthenticated || isLoading || isVerifying || automationPaused) return;

        const mode = activeExperiment.automationMode;
        if (mode === 'automated' && activeStep === activeExperiment.currentStep) {
            const now = Date.now();
            if (now - lastAutomationTick.current < 2000) return;
            lastAutomationTick.current = now;

            const stepData = (activeExperiment.stepData && activeExperiment.stepData[activeStep]) || {};
            // Agentic steps handle their own internal generation triggers usually, 
            // but we need to ensure the wrapper doesn't skip them.
            const isAgenticStep = [2, 6, 7, 9, 10].includes(activeStep);

            const hasBlockers = stepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);
            if (hasBlockers) {
                setAutomationPaused(true);
                addToast("Automation paused: Critical protocol blockers detected.", "warning");
                return;
            }

            if (!stepData?.output && !isAgenticStep) {
                handleGenerate();
            } else if (stepData?.output && !stepData?.summary && !isAgenticStep) {
                handleCompleteStep();
            }
        }
    }, [activeExperiment, activeStep, isAuthenticated, isLoading, isVerifying, automationPaused, addToast]);

    const handleStepChange = useCallback((stepId: number) => {
        if (isLoading || isVerifying) return;
        setStreamingText(null);
        setActiveStep(stepId);
        setAutomationPaused(false);
    }, [isLoading, isVerifying]);

    const handleResolveBlocker = async (blockerId: string) => {
        if (!activeExperiment) return;
        const stepData = { ...(activeExperiment.stepData || {}) };
        const currentStepData = { ...(stepData[activeStep] || {}) };
        const blockers = (currentStepData.blockers || []).map(b => 
            b.id === blockerId ? { ...b, resolved: true } : b
        );

        stepData[activeStep] = { ...currentStepData, blockers };
        await updateExperiment({ ...activeExperiment, stepData });
        addToast("Blocker mitigation logged.", "success");
    };

    /**
     * Fallback mechanism to return to Step 6 if data analysis fails QA.
     */
    const handleAnalysisFailure = useCallback(async (errorMsg: string) => {
        if (!activeExperiment) return;
        addToast(`Analysis Error: ${errorMsg}. Re-routing to Acquisition for correction.`, "warning");

        const updatedStepData = { ...activeExperiment.stepData };
        // Clear failed analysis but keep the input for reference
        updatedStepData[7] = { ...updatedStepData[7], output: undefined, summary: undefined };

        await updateExperiment({
            ...activeExperiment,
            currentStep: 6,
            stepData: updatedStepData
        });
        setActiveStep(6);
    }, [activeExperiment, updateExperiment, addToast]);

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading || isVerifying) return;

        setStreamingText(null);
        setIsLoading(true);
        streamBuffer.current = "";

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            const input = (activeExperiment.stepData && activeExperiment.stepData[activeStep]?.input) || '';
            const stepSettings = activeExperiment.fineTuneSettings && activeExperiment.fineTuneSettings[activeStep] 
                ? activeExperiment.fineTuneSettings[activeStep] 
                : {};

            const { basePrompt, expectJson, config } = getPromptForStep(
                activeStep, input, context, stepSettings, regenerateFeedback
            );

            if (expectJson) {
                const schema = (activeStep === 1) ? RESEARCH_QUESTION_SCHEMA : (activeStep === 2) ? LITERATURE_REVIEW_SCHEMA : DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
                const model = activeStep === 1 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

                const output = await executeStepWorkflow(model, { contents: basePrompt, config }, context, true, schema);

                if (isMounted.current) {
                    await updateExperiment({ 
                        ...activeExperiment, 
                        stepData: { 
                            ...activeExperiment.stepData, 
                            [activeStep]: { 
                                ...(activeExperiment.stepData?.[activeStep] || {}), 
                                output 
                            } 
                        } 
                    });
                }
            } else {
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });

                if (streamInterval.current) clearInterval(streamInterval.current);
                streamInterval.current = setInterval(() => {
                    if (isMounted.current) {
                        setStreamingText(streamBuffer.current);
                    }
                }, 100);

                for await (const chunk of stream) {
                    streamBuffer.current += (chunk.text || '');
                }

                if (streamInterval.current) {
                    clearInterval(streamInterval.current);
                    streamInterval.current = null;
                }

                if (isMounted.current) {
                    const finalOutput = streamBuffer.current;
                    setStreamingText(finalOutput);

                    await updateExperiment({
                        ...activeExperiment,
                        stepData: { 
                            ...activeExperiment.stepData, 
                            [activeStep]: { 
                                ...(activeExperiment.stepData?.[activeStep] || {}), 
                                output: finalOutput 
                            } 
                        }
                    });
                }
            }
            if (isMounted.current) {
                addToast("Archival node synchronized.", "success");
            }
        } catch (error) {
            if (isMounted.current) {
                addToast(parseGeminiError(error), 'danger');
                if (activeExperiment?.automationMode === 'automated') {
                    setAutomationPaused(true);
                    addToast("Automation paused due to error.", 'warning');
                }
            }
        } finally {
            if (isMounted.current) setIsLoading(false);
            if (streamInterval.current) {
                clearInterval(streamInterval.current);
                streamInterval.current = null;
            }
        }
    };

    const handleCompleteStep = async (stepDataOverride?: any) => {
        if (isVerifying || !activeExperiment) return;

        setIsVerifying(true);
        const currentStepData = { ...(activeExperiment.stepData?.[activeStep] || {}), ...stepDataOverride };
        const currentOutput = currentStepData.output || "";

        // Block progression if unresolved critical blockers exist
        const hasCriticalBlockers = currentStepData.blockers?.some(b => b.severity === 'critical' && !b.resolved);
        if (hasCriticalBlockers) {
            addToast("Resolve critical protocol blockers before proceeding.", "warning");
            setAutomationPaused(true);
            setIsVerifying(false);
            return;
        }

        try {
            let summary = currentStepData.summary;
            if (!summary && currentOutput.length > 50) {
                try {
                    summary = await generateNodeSummary(currentOutput, activeExperiment.field);
                } catch (e) {
                    summary = "Node verified.";
                }
            } else if (!summary) {
                summary = "Node verified.";
            }

            const nextStepId = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : activeStep;
            const updatedStepDataMap = { ...(activeExperiment.stepData || {}) };
            updatedStepDataMap[activeStep] = { ...currentStepData, summary };

            // ENSURE STEP 6 -> 7 DATA FLOW IS ATOMIC
            if (activeStep === 6) {
                const csvData = currentStepData.input || currentOutput; 
                updatedStepDataMap[7] = { 
                    ...(updatedStepDataMap[7] || {}), 
                    input: csvData,
                    output: undefined,
                    summary: undefined 
                };
            }

            const updatedExp = { 
                ...activeExperiment, 
                stepData: updatedStepDataMap, 
                currentStep: nextStepId 
            };

            // Wait for DB write before state change
            await updateExperiment(updatedExp);

            if (isMounted.current) {
                addToast(`Step ${activeStep} verified. Initiating Step ${nextStepId}.`, "success");
                setActiveStep(nextStepId);
            }
        } catch (error) {
            console.error("Verification error:", error);
            if (isMounted.current) {
                addToast("Archive link unstable. Could not verify node.", 'danger');
                if (activeExperiment?.automationMode === 'automated') {
                    setAutomationPaused(true);
                }
            }
        } finally {
            if (isMounted.current) setIsVerifying(false);
        }
    };

    const renderStepContent = () => {
        if (!activeExperiment) return null;
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} />;
        }

        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={handleCompleteStep} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={() => handleCompleteStep()} onAnalysisFailure={handleAnalysisFailure} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 10) return <PublicationExporter />;

        return (
            <div className="discovery-view">
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    if (!activeExperiment) return null;

    const currentStepData = activeExperiment.stepData?.[activeStep];
    const hasOutput = currentStepData?.output;
    const hasCriticalBlocker = currentStepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);

    return (
        <div className="workspace-container">
            <aside className="sidebar-nav">
                <div className="card shadow-sm border-secondary border-opacity-10 overflow-hidden">
                    <div className="card-header fw-bold bg-dark py-3 small ls-1 text-uppercase">
                        <i className="bi bi-cpu-fill text-primary-glow me-2"></i> Timeline
                    </div>
                    <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                            <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                                style={{ cursor: step.id <= activeExperiment.currentStep ? 'pointer' : 'default' }}
                            >
                                <span className="small">{step.id}. {step.title}</span>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                </div>
            </aside>

            <main className="content-area">
                <div className="card shadow-sm border-secondary border-opacity-25 position-relative overflow-hidden">
                    {(isLoading || isVerifying) && (
                        <div className="progress rounded-0" style={{ height: '3px', position: 'absolute', top: 0, left: 0, right: 0, zIndex: 100 }}>
                            <div className="progress-bar progress-bar-striped progress-bar-animated bg-primary-glow w-100"></div>
                        </div>
                    )}
                    <div className="card-body p-4" style={{ minHeight: '60vh' }}>
                        <div className="d-flex justify-content-between align-items-start mb-4">
                            <div>
                                <div className="badge bg-primary bg-opacity-10 text-primary-glow mb-2">Step {activeStep}</div>
                                <h4 className="fw-bold mb-1">{WORKFLOW_STEPS[activeStep - 1]?.title || 'Node Overview'}</h4>
                                <p className="text-white-50 small mb-0">{WORKFLOW_STEPS[activeStep - 1]?.description}</p>
                            </div>
                            {activeExperiment.automationMode === 'automated' && (
                                <div className="d-flex flex-column align-items-end">
                                    <span className={`badge ${automationPaused ? 'bg-warning text-dark' : 'bg-primary'} px-3 py-2 rounded-pill shadow-sm mb-2`}>
                                        <i className={`bi ${automationPaused ? 'bi-pause-circle-fill' : 'bi-cpu-fill'} me-1`}></i> 
                                        {automationPaused ? 'AUTOMATION PAUSED' : 'AGENTIC OVERRIDE ACTIVE'}
                                    </span>
                                    {automationPaused && (
                                        <button className="btn btn-xs btn-outline-warning" onClick={() => setAutomationPaused(false)}>
                                            <i className="bi bi-play-fill me-1"></i> RESUME
                                        </button>
                                    )}
                                </div>
                            )}
                        </div>
                        <hr className="border-secondary opacity-10 mb-4" />

                        {currentStepData?.blockers && (
                            <BlockerDisplay 
                                blockers={currentStepData.blockers} 
                                onResolve={handleResolveBlocker} 
                            />
                        )}

                        {renderStepContent()}
                    </div>

                    {activeStep <= WORKFLOW_STEPS.length && (
                        <div className="card-footer d-flex justify-content-between align-items-center p-3 bg-dark bg-opacity-25 border-top border-secondary border-opacity-10">
                            <button className="btn btn-sm btn-outline-secondary" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Tuning
                            </button>
                            <button 
                                className={`btn btn-${hasCriticalBlocker ? 'outline-danger' : 'success'} px-4 shadow-sm`} 
                                onClick={() => handleCompleteStep()} 
                                disabled={isVerifying || !hasOutput || hasCriticalBlocker}
                            >
                                {isVerifying ? (
                                    <span className="spinner-border spinner-border-sm me-2"></span>
                                ) : (
                                    <i className={`bi ${hasCriticalBlocker ? 'bi-lock-fill' : (hasOutput ? 'bi-check-circle-fill' : 'bi-lock-fill')} me-2`}></i> 
                                )}
                                {hasCriticalBlocker ? 'PROTOCOL BLOCKED' : (activeStep === 10 ? "Finish Project" : "Verify Node & Continue")}
                            </button>
                        </div>
                    )}
                </div>
            </main>

            {fineTuneModalOpen && (
                <FineTuneModal stepId={activeStep} onClose={() => setFineTuneModalOpen(false)} />
            )}
        </div>
    );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { runDataAnalysisAgent, parseGeminiError } from '../../services';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { AgenticAnalysisView } from '../common/AgenticAnalysisView';

export const DataAnalysisWorkspace = ({ onStepComplete, onAnalysisFailure }) => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();
    const [agenticRun, setAgenticRun] = useState({
        status: 'idle', // 'idle', 'running', 'success', 'failed'
        iterations: 0,
        maxIterations: 2, 
        logs: [],
    });

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    const stepData = activeExperiment.stepData[7] || {};

    const performAgenticAnalysis = useCallback(async () => {
        if (!isAuthenticated || !stepData.input || agenticRun.status === 'running') return;

        setAgenticRun({ status: 'running', logs: [], iterations: 0, maxIterations: 2 });

        try {
            const { finalOutput, blockers, logSummary } = await runDataAnalysisAgent({
                experiment: activeExperiment,
                csvData: stepData.input,
                updateLog: (agent, message) => {
                    if (isMounted.current) {
                        setAgenticRun(prev => ({
                            ...prev,
                            logs: [...prev.logs, { agent, message }],
                            iterations: Math.min(prev.maxIterations, prev.iterations + 1)
                        }));
                    }
                },
            });

            if (!isMounted.current) return;

            // Merge blockers into step data
            const finalStepData = { 
                ...stepData, 
                output: finalOutput, 
                suggestedInput: logSummary,
                blockers: [...(stepData.blockers || []), ...blockers]
            };

            await updateExperiment({ ...activeExperiment, stepData: { ...activeExperiment.stepData, 7: finalStepData } });

            if (blockers.some(b => b.severity === 'critical')) {
                setAgenticRun(prev => ({ 
                    ...prev, 
                    status: 'failed',
                    logs: [...prev.logs, { agent: 'System', message: 'CRITICAL BLOCKER DETECTED. Analysis halted for PI review.' }]
                }));
                addToast("Critical blockers detected in analysis.", "warning");
            } else {
                setAgenticRun(prev => ({ ...prev, status: 'success' }));
                addToast("Analysis complete!", "success");

                 if (activeExperiment.automationMode === 'automated') {
                     setTimeout(() => { if (isMounted.current) onStepComplete(); }, 1500);
                }
            }
        } catch (error) {
            if (!isMounted.current) return;
            const errorMessage = error instanceof Error ? error.message : parseGeminiError(error);

            setAgenticRun(prev => ({ 
                ...prev, 
                status: 'failed',
                logs: [...prev.logs, { agent: 'System', message: `ERROR: ${errorMessage}` }]
            }));

            // If it's a data quality error, trigger the failure handler (returns to step 6)
            if (errorMessage.includes("Data Quality Check Failed")) {
                setTimeout(() => onAnalysisFailure(errorMessage), 3000);
            } else {
                addToast(errorMessage, "danger");
            }
        }
    }, [activeExperiment, isAuthenticated, addToast, updateExperiment, stepData, agenticRun.status, onStepComplete, onAnalysisFailure]);

    // Auto-run effect for automated workflows
    useEffect(() => {
        if (activeExperiment.automationMode === 'automated' && 
            !stepData.output && 
            stepData.input && 
            agenticRun.status === 'idle') {
            performAgenticAnalysis();
        }
    }, [activeExperiment.automationMode, stepData.output, stepData.input, agenticRun.status, performAgenticAnalysis]);

    return (
        <div className="data-analysis-workspace">
             {!stepData.input ? (
                 <div className="alert alert-warning">
                     <i className="bi bi-exclamation-triangle me-2"></i>
                     No data available for analysis. Please complete the "Data Acquisition" step first.
                 </div>
             ) : (
                 <>
                    {agenticRun.status !== 'running' && stepData.output && (
                        <div className="d-flex justify-content-end mb-3">
                             <button className="btn btn-sm btn-outline-secondary" onClick={performAgenticAnalysis}>
                                <i className="bi bi-arrow-clockwise me-1"></i> Re-Run Analysis Agent
                            </button>
                        </div>
                    )}

                    {!stepData.output && agenticRun.status === 'idle' && (
                        <div className="text-center p-5 border border-secondary border-opacity-10 rounded-4 bg-dark bg-opacity-10 my-3">
                            <i className="bi bi-graph-up-arrow mb-3 text-primary-glow opacity-50 d-block" style={{ fontSize: '2.5rem' }}></i>
                            <h5 className="fw-bold mb-2">Initialize Analysis Agent</h5>
                            <p className="text-white-50 small mb-4 mx-auto" style={{maxWidth: '350px'}}>
                                Deploy the Data Scientist agent to perform statistical tests and generate visualizations.
                            </p>
                            <button className="btn btn-primary px-5 py-2 rounded-pill shadow-sm" onClick={performAgenticAnalysis}>
                                <i className="bi bi-play-fill me-2"></i> Start Analysis
                            </button>
                        </div>
                    )}

                    {agenticRun.status === 'running' ? (
                        <div className="mt-4 border-top border-secondary border-opacity-10 pt-4">
                            <AgenticAnalysisView 
                                agenticRun={agenticRun} 
                                title="Data Scientist Agent Active" 
                                subtitle="Performing statistical tests and rendering charts..." 
                            />
                        </div>
                    ) : (
                        <GeneratedOutput 
                            stepId={7} 
                            onGenerate={performAgenticAnalysis} 
                            isLoading={false} 
                        />
                    )}
                 </>
             )}
        </div>
    );
};

import { Experiment, LITERATURE_REVIEW_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, DATA_QA_SCHEMA } from '../config';
import { callGeminiWithRetry, extractJson, isValidJsonForSchema, parseBlockers } from './api';
import { getStepContext } from './prompts';
import { ensureChartStyling } from '../utils/chartUtils';

export const executeStepWorkflow = async (
    modelName: string, 
    params: any, 
    context: any, 
    isJsonMode: boolean, 
    schema: any
): Promise<string> => {
    if (isJsonMode && schema) {
        params.config = { 
            ...params.config, 
            responseMimeType: "application/json", 
            responseSchema: schema 
        };
    }

    const response = await callGeminiWithRetry(modelName, params);
    let output = response.text;

    if (isJsonMode) {
        output = extractJson(output);
        if (!isValidJsonForSchema(output, schema)) {
            // Self-Correction Loop
            console.warn("Schema validation failed, attempting self-correction...");
            const repairPrompt = `The previous output did not match the required JSON schema. 
            ERROR: Invalid Schema. 
            REQUIRED SCHEMA: ${JSON.stringify(schema)}
            PREVIOUS OUTPUT: ${output}

            Fix the JSON structure and return only the valid JSON object.`;

            const repairResponse = await callGeminiWithRetry('gemini-3-flash-preview', { contents: repairPrompt, config: { responseMimeType: "application/json", responseSchema: schema } });
            output = extractJson(repairResponse.text);
        }
    }
    return output;
};


