/**
 * QA Agent to verify experimental data quality before analysis.
 * Enforces strict formatting and "actual data in all columns".
 */
export const runDataQA = async (csvData: string, context: any) => {
    const prompt = `
    ACT AS: Scientific Data Quality Assurance (QA) Auditor.
    TASK: Audit the following CSV dataset for "Perfect Formatting" and "Complete Data Capture".

    DATASET:
    ${csvData.substring(0, 5000)}

    RESEARCH CONTEXT:
    - Hypothesis: ${context.hypothesis}
    - Methodology: ${context.methodology_summary}

    CRITICAL AUDIT RULES:
    1. Perfect CSV Structure: Must have a header row and consistent column counts.
    2. Zero Nulls: EVERY column in EVERY row MUST have data. No empty cells.
    3. Scientific Plausibility: While the data doesn't need to be "perfect" real-world data, it must actually represent the variables defined in the methodology.

    Output ONLY valid JSON matching the QA schema.
    `;

    const response = await callGeminiWithRetry('gemini-3-flash-preview', { 
        contents: prompt,
        config: { responseMimeType: "application/json", responseSchema: DATA_QA_SCHEMA }
    });

    return JSON.parse(extractJson(response.text));
};

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }: { experiment: Experiment, csvData: string, updateLog: (agent: string, msg: string) => void }) => {
    updateLog('Manager', 'Initiating statistical engine...');

    const context = await getStepContext(experiment, 7);

    // 0. Data QA First
    updateLog('Auditor', 'Running strict protocol-level QA on dataset formatting...');
    const qaResult = await runDataQA(csvData, context);
    if (!qaResult.is_valid || qaResult.quality_score < 0.4) {
        updateLog('Auditor', `DATA QA FAILURE: ${qaResult.issues.join('; ')}`);
        // We throw a specific string that the workspace can catch to trigger a rerun of Step 6.
        throw new Error(`DATA_QUALITY_FAILURE: ${qaResult.recommendation || "The dataset is unsuitable for analysis."}`);
    }
    updateLog('Auditor', `Data integrity verified (Quality Score: ${qaResult.quality_score}).`);

    // 1. Data Profiler
    updateLog('Profiler', 'Identifying independent/dependent variable relationships...');
    const profilerPrompt = `
    Analyze this dataset structure for variables and outliers.

    DATASET (First 5000 chars):
    ${csvData.substring(0, 5000)}

    CONTEXT:
    - Question: ${context.question}
    - Hypothesis: ${context.hypothesis}
    `;

    const profileRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: profilerPrompt });
    updateLog('Profiler', 'Variable mapping complete.');

    // 2. Statistician & Visualizer
    updateLog('Analyst', 'Calculating p-values and regression models...');
    const analysisPrompt = `
    ACT AS: Senior Data Scientist.
    TASK: Perform rigorous statistical analysis on the provided dataset.

    DATA PROFILE: ${profileRes.text}
    RAW DATA: ${csvData}
    HYPOTHESIS: ${context.hypothesis}

    REQUIREMENTS:
    1. Perform tests (ANOVA, t-test, or Pearson correlation) and provide p-values.
    2. Generate AT LEAST TWO (2) Chart.js JSON configs.
    3. CRITICAL: For type: "scatter", the 'data' array MUST be objects with 'x' and 'y' properties.
       Example structure for scatter: 
       { 
         "type": "scatter", 
         "data": { 
           "datasets": [{ 
             "label": "Observed Data", 
             "data": [{"x": 1, "y": 2.5}, {"x": 2, "y": 4.1}] 
           }] 
         },
         "options": { "scales": { "x": { "title": { "display": true, "text": "X Var" } }, "y": { "title": { "display": true, "text": "Y Var" } } } }
       }
    4. Write a detailed Markdown summary interpreting results.

    CRITICAL: Output MUST be valid JSON matching the schema.
    `;

    const analysisRes = await callGeminiWithRetry('gemini-3-pro-preview', { 
        contents: analysisPrompt,
        config: { 
            responseMimeType: "application/json", 
            responseSchema: DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA,
            thinkingConfig: { thinkingBudget: 4096 }
        }
    });

    let resultJson = extractJson(analysisRes.text);

    // Post-process charts
    try {
        const parsed = JSON.parse(resultJson);
        if (parsed.charts && Array.isArray(parsed.charts)) {
            parsed.charts = parsed.charts.map((c: any) => {
                try {
                    const config = typeof c.chartConfig === 'string' ? JSON.parse(c.chartConfig) : c.chartConfig;
                    const styledConfig = ensureChartStyling(config);
                    return { ...c, chartConfig: JSON.stringify(styledConfig) };
                } catch (e) {
                    console.error("Failed to parse individual chart config", e);
                    return c;
                }
            });
            resultJson = JSON.stringify(parsed);
        }
        updateLog('Visualizer', 'Visual assets synchronized with dark mode theme.');
    } catch (e) {
        updateLog('System', 'Visualization post-processing bypassed.');
    }

    // 3. Blocker Check
    updateLog('Safety', 'Verifying scientific integrity...');
    const blockerPrompt = `Check these analysis results for logical fallacies or data-hypothesis mismatches.
    RESULTS: ${resultJson}
    Output JSON: { "BLOCKER_ALERT": [ { "severity": "critical"|"warning", "msg": "..." } ] } or empty.`;

    const blockerRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: blockerPrompt });
    const blockers = parseBlockers(blockerRes.text);

    return { finalOutput: resultJson, blockers, logSummary: profileRes.text };
};

