             addToast("Manual Data Entry required. Automation paused for user input.", "info");
        }
        return () => { isMounted.current = false; };
    }, [activeExperiment?.automationMode, addToast]);

    const initializeForm = useCallback(async () => {
        if (!isAuthenticated || agenticRun.status === 'running') return;

        setAgenticRun(prev => ({ ...prev, status: 'running', logs: [], iterations: 0 }));
        let currentSchema = "";

        for (let i = 0; i < agenticRun.maxIterations; i++) {
            if (!isMounted.current) return;

            try {
                const attempt = i + 1;
                setAgenticRun(prev => ({ 
                    ...prev, 
                    iterations: attempt,
                    logs: [...prev.logs, { agent: 'Architect', message: `Attempt ${attempt}: Generating data entry schema...` }] 
                }));

                const prompt = `Based on the data collection plan: "${context.data_collection_plan_summary}", generate a JSON array of column objects for a data table. Keys: "columnName" and "dataType". 
                ${currentSchema ? `PREVIOUS ATTEMPT FAILED. REVISE THIS SCHEMA: ${currentSchema}` : ''}
                Output ONLY raw JSON array.`;

                const response = await callGeminiWithRetry('gemini-3-flash-preview', { 
                    contents: prompt, 
                    config: { responseMimeType: "application/json", responseSchema: DYNAMIC_TABLE_SCHEMA } 
                });

                const schemaText = extractJson(response.text);
                currentSchema = schemaText;

                setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Auditor', message: 'Verifying schema integrity...' }] }));
                const qa = await runManualFormQA(schemaText, context);

                if (qa.is_valid && qa.quality_score > 0.6) {
                    const schemaArray = JSON.parse(schemaText);
                    const newColumns = schemaArray.map((col: any) => col.columnName);
                    setColumns(newColumns);
                    setRows([Object.fromEntries(newColumns.map((c: string) => [c, '']))]);
                    setAgenticRun(prev => ({ ...prev, status: 'success' }));
                    addToast("Data entry form initialized and verified.", "success");
                    return;
                } else {
                    setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Auditor', message: `QA Failure: ${qa.issues.join('; ')}` }] }));
                }
            } catch (err) {
                const msg = parseGeminiError(err);
                setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'System', message: `ERROR: ${msg}` }] }));
            }
        }
        setAgenticRun(prev => ({ ...prev, status: 'failed' }));
    }, [isAuthenticated, context, agenticRun.status, agenticRun.maxIterations, addToast]);

    useEffect(() => {
        if (columns.length === 0 && agenticRun.status === 'idle') {
            initializeForm();
        }
    }, [columns.length, agenticRun.status, initializeForm]);

    const handleRowChange = (index, col, value) => {
        const newRows = [...rows];
        newRows[index][col] = value;
        setRows(newRows);
    };

    const addRow = () => setRows([...rows, Object.fromEntries(columns.map(c => [c, '']))]);
    const removeRow = (index) => setRows(rows.filter((_, i) => i !== index));

    const handleSubmit = () => {
        // Fix: Explicitly cast v to string to resolve 'trim' does not exist on type 'unknown' error
        if (rows.some(r => Object.values(r).some(v => !(v as string).trim()))) {
            if (!window.confirm("Some fields are empty. Proceed anyway?")) return;
        }
        const header = columns.join(',');
        const body = rows.map(row => columns.map(col => `"${(row[col] || '').replace(/"/g, '""')}"`).join(',')).join('\n');
        onComplete(`${header}\n${body}`, "Manually entered forensic data.");
    };

    if (agenticRun.status === 'running') return <AgenticAnalysisView agenticRun={agenticRun} title="Building Data Entry Portal" subtitle="Agents are negotiating table structure and variable mapping." />;

    return (
        <div className="animate-in">
            {agenticRun.status === 'failed' ? (
                <div className="alert alert-danger">
                    <h6 className="fw-bold">Form Generation Protocol Failed</h6>
                    <p className="small mb-2">The AI Architect could not produce a stable schema for your methodology.</p>
                    <button className="btn btn-sm btn-outline-danger" onClick={() => { setAgenticRun(p => ({...p, status: 'idle'})); setColumns([]); }}>Retry Initialization</button>
                </div>
            ) : (
                <div className="card mb-4">
                    <div className="card-body">
                        <h6 className="fw-bold">Step 6: Forensic Data Entry</h6>
                        <div className="table-responsive">
                            <table className="table table-bordered border-secondary border-opacity-10 mb-3">
                                <thead className="bg-dark bg-opacity-50">
                                    <tr>{columns.map(c => <th key={c} className="small text-uppercase ls-1">{c}</th>)}<th style={{ width: '50px' }}></th></tr>
                                </thead>
                                <tbody>
                                    {rows.map((row, rowIndex) => (
                                        <tr key={rowIndex}>
                                            {columns.map(col => <td key={col} className="p-1"><input type="text" className="form-control form-control-sm border-0 bg-transparent text-white" value={row[col] || ''} onChange={e => handleRowChange(rowIndex, col, e.target.value)} /></td>)}
                                            <td className="p-1 text-center"><button className="btn btn-sm text-danger" onClick={() => removeRow(rowIndex)} disabled={rows.length <= 1}><i className="bi bi-x-lg"></i></button></td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="d-flex justify-content-between">
                            <button className="btn btn-sm btn-outline-secondary" onClick={addRow}><i className="bi bi-plus-lg me-1"></i> Add Record</button>
                            <button className="btn btn-success px-4" onClick={handleSubmit}><i className="bi bi-check-circle-fill me-1"></i> Finalize Entry</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import { GoogleGenAI } from "@google/genai";
import { Blocker } from '../config';

// --- API KEY MANAGEMENT ---

export const getSafeEnvApiKey = () => {
    // @ts-ignore - process is polyfilled in index.html
    if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
        // @ts-ignore
        return process.env.API_KEY;
    }
    return '';
};

export const getCurrentApiKey = () => {
    return getSafeEnvApiKey();
};

export const setStoredApiKey = (key: string) => {
    // No-op: Keys must be managed via environment variables.
    console.warn("Attempted to store API key via client-side storage, which is prohibited.");
};

export const getKeyStatus = () => {
    const envKey = getSafeEnvApiKey();
    if (envKey) return { type: 'env', label: 'Environment Linked', color: 'bg-success' };
    return { type: 'none', label: 'Disconnected', color: 'bg-danger' };
};

export const testApiKey = async (key: string): Promise<boolean> => {
    if (!key) return false;
    try {
        const ai = new GoogleGenAI({ apiKey: key });
        // Simple fast call to test auth
        await ai.models.generateContent({
             model: 'gemini-3-flash-preview',
             contents: 'Test connection.',
        });
        return true;
    } catch (e) {
        console.warn("API Key Test Failed:", e);
        return false;
    }
};

// --- ERROR HANDLING ---

export const parseGeminiError = (error: any, defaultMsg = "An error occurred with the AI service."): string => {
    console.error("Gemini Error:", error);
    const msg = error?.message || error?.toString() || "";

    // Explicit 429 Handling
    if (msg.includes("429") || msg.includes("quota") || msg.includes("RESOURCE_EXHAUSTED")) {
        return "API Quota Exceeded (429). The system is applying backoff. Please wait 10-15 seconds.";
    }
    if (msg.includes("401") || msg.includes("API key")) return "Invalid API Key. Please re-authenticate.";
    if (msg.includes("503") || msg.includes("overloaded")) return "AI Service overloaded. Retrying usually fixes this.";
    if (msg.includes("SAFETY")) return "Content blocked by safety filters. Please refine your input.";

    return defaultMsg;
};

// --- UTILITIES ---

export const extractJson = (text: any): string => {
    if (typeof text !== 'string') return "";
    if (!text) return "";

    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match && match[1]) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');

    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

export const isValidJsonForSchema = (jsonString: string, schema: any): boolean => {
    try {
        const obj = JSON.parse(jsonString);
        if (!obj) return false;
        // Basic check: if schema requires certain properties, check existence
        if (schema && schema.required && Array.isArray(schema.required)) {
            for (const field of schema.required) {
                if (!(field in obj)) return false;
            }
        }
        return true;
    } catch (e) {
        return false;
    }
};

export const parseBlockers = (text: string): Blocker[] => {
    try {
        const jsonStr = extractJson(text);
        if (!jsonStr) return [];
        const data = JSON.parse(jsonStr);

        const alert = data.BLOCKER_ALERT || (data.severity ? data : null);
        if (!alert) return [];

        const blockersList = Array.isArray(alert) ? alert : [alert];
        return blockersList
            .filter((b: any) => b && (b.severity === 'critical' || b.severity === 'warning') && b.msg)
            .map((b: any, i: number) => ({
                id: `blk_${Date.now()}_${i}`,
                severity: b.severity,
                msg: b.msg,
                resolved: false
            }));
    } catch (e) {
        return [];
    }
};

// --- GEMINI WRAPPERS ---

const MODEL_CONFIGS: any = {
    'gemini-3-flash-preview': { temperature: 0.7, topK: 40, topP: 0.95 },
    'gemini-3-pro-preview': { temperature: 0.9, topK: 64, topP: 0.95 }
};

export const callGeminiWithRetry = async (modelName: string, params: any, retries = 3) => {
    // @ts-ignore
    const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("No API Key available in environment variables.");

    const ai = new GoogleGenAI({ apiKey });

    const defaults = MODEL_CONFIGS[modelName] || {};
    params.config = { ...defaults, ...(params.config || {}) };

    for (let i = 0; i <= retries; i++) {
        try {
            const response = await ai.models.generateContent({
                model: modelName,
                ...params
            });
            return response;
        } catch (error: any) {
            const msg = error.message || "";
            const isRateLimit = msg.includes("429") || msg.includes("quota") || msg.includes("RESOURCE_EXHAUSTED");

            if (i === retries) throw error;

            if (isRateLimit || msg.includes("503") || msg.includes("500") || msg.includes("400")) {
                // Aggressive exponential backoff for rate limits: 2s, 4s, 8s...
                const waitTime = isRateLimit ? 2500 * Math.pow(2, i) : 1000 * (i + 1);
                console.warn(`Retry ${i + 1}/${retries} after ${waitTime}ms...`);
                await new Promise(res => setTimeout(res, waitTime));
            } else {
                throw error;
            }
        }
    }
    throw new Error("Maximum retries reached.");
};

export const callGeminiStreamWithRetry = async (modelName: string, params: any) => {
    // @ts-ignore
    const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("No API Key available in environment variables.");

    const ai = new GoogleGenAI({ apiKey });

    const defaults = MODEL_CONFIGS[modelName] || {};
    params.config = { ...defaults, ...(params.config || {}) };

    try {
        const stream = await ai.models.generateContentStream({
            model: modelName,
            ...params
        });
        return stream;
    } catch (error) {
        console.error("Stream Error", error);
        throw error;
    }
};

export const generateNodeSummary = async (content: string, field: string): Promise<string> => {
    if (!content || content.length < 50) return content;

    const prompt = `As a Research Archivist in ${field}, compress the following content into a concise, high-density summary (max 3 sentences) suitable for context in future steps. Preserve key variables, findings, and numbers.

    CONTENT:
    ${content.substring(0, 15000)}...`;

    try {
        const response = await callGeminiWithRetry('gemini-3-flash-preview', { contents: prompt });
        return response.text || content.substring(0, 200) + "...";
    } catch (e) {
        return content.substring(0, 200) + "...";
    }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { 
    parseGeminiError, 
    getStepContext, 
    getPromptForStep, 
    executeStepWorkflow, 
    callGeminiStreamWithRetry,
    generateNodeSummary
} from '../../services';
import { WORKFLOW_STEPS, RESEARCH_QUESTION_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, LITERATURE_REVIEW_SCHEMA } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';
import { InterpretationWorkspace } from '../steps/InterpretationWorkspace';
import { BlockerDisplay } from './BlockerDisplay';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();

    const [activeStep, setActiveStep] = useState(activeExperiment?.currentStep || 1);
    const [isLoading, setIsLoading] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const [streamingText, setStreamingText] = useState<string | null>(null);
    const [automationPaused, setAutomationPaused] = useState(false);

    const streamBuffer = useRef("");
    const streamInterval = useRef<any>(null);
    const isMounted = useRef(true);
    const lastAutomationTick = useRef<number>(0);

    useEffect(() => {
        isMounted.current = true;
        return () => { 
            isMounted.current = false;
            if (streamInterval.current) {
                clearInterval(streamInterval.current);
            }
        };
    }, []);

    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading && !isVerifying) {
            setActiveStep(activeExperiment.currentStep);
            setAutomationPaused(false); 
        }
    }, [activeExperiment?.currentStep, isLoading, isVerifying, activeStep]);

    // Main Automation Loop
    useEffect(() => {
        if (!activeExperiment || !isAuthenticated || isLoading || isVerifying || automationPaused) return;

        const mode = activeExperiment.automationMode;
        if (mode === 'automated' && activeStep === activeExperiment.currentStep) {
            const now = Date.now();
            // Increased delay to 3000ms to reduce likelihood of 429 quota exhaustion in bursts
            if (now - lastAutomationTick.current < 3000) return;
            lastAutomationTick.current = now;

            const stepData = (activeExperiment.stepData && activeExperiment.stepData[activeStep]) || {};
            // steps that handle their own logic triggers
            const isAgenticStep = [2, 6, 7, 8, 9, 10].includes(activeStep);

            const hasCriticalBlockers = stepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);
            if (hasCriticalBlockers) {
                setAutomationPaused(true);
                addToast("Automation paused: Critical blockers detected.", "warning");
                return;
            }

            if (!stepData?.output && !isAgenticStep) {
                handleGenerate();
            } else if (stepData?.output && !stepData?.summary && !isAgenticStep) {
                handleCompleteStep();
            }
        }
    }, [activeExperiment, activeStep, isAuthenticated, isLoading, isVerifying, automationPaused, addToast]);

    const handleStepChange = useCallback((stepId: number) => {
        if (isLoading || isVerifying) return;
        setStreamingText(null);
        setActiveStep(stepId);
        setAutomationPaused(false);
    }, [isLoading, isVerifying]);

    const handleResolveBlocker = async (blockerId: string) => {
        if (!activeExperiment) return;
        const stepData = { ...(activeExperiment.stepData || {}) };
        const currentStepData = { ...(stepData[activeStep] || {}) };
        const blockers = (currentStepData.blockers || []).map(b => 
            b.id === blockerId ? { ...b, resolved: true } : b
        );

        stepData[activeStep] = { ...currentStepData, blockers };
        await updateExperiment({ ...activeExperiment, stepData });
        addToast("Blocker mitigation logged.", "success");
    };

    /**
     * Re-routing logic for data quality failure.
     */
    const handleAnalysisFailure = useCallback(async (errorMsg: string) => {
        if (!activeExperiment) return;

        // If the error indicates a data quality issue, we must return to Step 6
        if (errorMsg.includes("DATA_QUALITY_FAILURE") || errorMsg.includes("Data Quality Check Failed")) {
            addToast(`Data quality failed: Re-routing to Acquisition for correction.`, "warning");

            const updatedStepData = { ...activeExperiment.stepData };
            // Reset Step 7 metadata to force re-run when we eventually return
            updatedStepData[7] = { ...updatedStepData[7], output: undefined, summary: undefined };
            // Reset Step 6 output to force the automation loop to re-generate/simulate data
            updatedStepData[6] = { ...updatedStepData[6], output: undefined, summary: undefined };

            await updateExperiment({
                ...activeExperiment,
                currentStep: 6,
                stepData: updatedStepData
            });
            setActiveStep(6);
        } else {
             addToast(`Analysis error: ${errorMsg}`, "danger");
             if (activeExperiment.automationMode === 'automated') {
                 setAutomationPaused(true);
             }
        }
    }, [activeExperiment, updateExperiment, addToast]);

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading || isVerifying) return;

        setStreamingText(null);
        setIsLoading(true);
        streamBuffer.current = "";

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            const input = (activeExperiment.stepData && activeExperiment.stepData[activeStep]?.input) || '';
            const stepSettings = activeExperiment.fineTuneSettings && activeExperiment.fineTuneSettings[activeStep] 
                ? activeExperiment.fineTuneSettings[activeStep] 
                : {};

            const { basePrompt, expectJson, config } = getPromptForStep(
                activeStep, input, context, stepSettings, regenerateFeedback
            );

            if (expectJson) {
                const schema = (activeStep === 1) ? RESEARCH_QUESTION_SCHEMA : (activeStep === 2) ? LITERATURE_REVIEW_SCHEMA : DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
                const model = activeStep === 1 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

                const output = await executeStepWorkflow(model, { contents: basePrompt, config }, context, true, schema);

                if (isMounted.current) {
                    await updateExperiment({ 
                        ...activeExperiment, 
                        stepData: { 
                            ...activeExperiment.stepData, 
                            [activeStep]: { 
                                ...(activeExperiment.stepData?.[activeStep] || {}), 
                                output 
                            } 
                        } 
                    });
                }
            } else {
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });

                if (streamInterval.current) clearInterval(streamInterval.current);
                streamInterval.current = setInterval(() => {
                    if (isMounted.current) {
                        setStreamingText(streamBuffer.current);
                    }
                }, 100);

                for await (const chunk of stream) {
                    streamBuffer.current += (chunk.text || '');
                }

                if (streamInterval.current) {
                    clearInterval(streamInterval.current);
                    streamInterval.current = null;
                }

                if (isMounted.current) {
                    const finalOutput = streamBuffer.current;
                    setStreamingText(finalOutput);

                    await updateExperiment({
                        ...activeExperiment,
                        stepData: { 
                            ...activeExperiment.stepData, 
                            [activeStep]: { 
                                ...(activeExperiment.stepData?.[activeStep] || {}), 
                                output: finalOutput 
                            } 
                        }
                    });
                }
            }
            if (isMounted.current) {
                addToast("Archival node synchronized.", "success");
            }
        } catch (error) {
            if (isMounted.current) {
                addToast(parseGeminiError(error), 'danger');
                if (activeExperiment?.automationMode === 'automated') {
                    setAutomationPaused(true);
                }
            }
        } finally {
            if (isMounted.current) setIsLoading(false);
            if (streamInterval.current) {
                clearInterval(streamInterval.current);
                streamInterval.current = null;
            }
        }
    };

    const handleCompleteStep = async (stepDataOverride?: any) => {
        if (isVerifying || !activeExperiment) return;

        setIsVerifying(true);
        const currentStepData = { ...(activeExperiment.stepData?.[activeStep] || {}), ...stepDataOverride };
        const currentOutput = currentStepData.output || "";

        const hasCriticalBlockers = currentStepData.blockers?.some(b => b.severity === 'critical' && !b.resolved);
        if (hasCriticalBlockers) {
            addToast("Resolve critical blockers before proceeding.", "warning");
            setAutomationPaused(true);
            setIsVerifying(false);
            return;
        }

        try {
            let summary = currentStepData.summary;
            if (!summary && currentOutput.length > 50) {
                try {
                    summary = await generateNodeSummary(currentOutput, activeExperiment.field);
                } catch (e) {
                    summary = "Node verified.";
                }
            } else if (!summary) {
                summary = "Node verified.";
            }

            const nextStepId = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : activeStep;
            const updatedStepDataMap = { ...(activeExperiment.stepData || {}) };
            updatedStepDataMap[activeStep] = { ...currentStepData, summary };

            if (activeStep === 6) {
                const csvData = currentStepData.input || currentOutput; 
                updatedStepDataMap[7] = { 
                    ...(updatedStepDataMap[7] || {}), 
                    input: csvData,
                    output: undefined,
                    summary: undefined 
                };
            }

            const updatedExp = { 
                ...activeExperiment, 
                stepData: updatedStepDataMap, 
                currentStep: nextStepId 
            };

            await updateExperiment(updatedExp);

            if (isMounted.current) {
                addToast(`Step ${activeStep} complete. Moving to Step ${nextStepId}.`, "success");
                setActiveStep(nextStepId);
            }
        } catch (error) {
            console.error("Verification error:", error);
            if (isMounted.current) {
                addToast("Archival link unstable.", 'danger');
            }
        } finally {
            if (isMounted.current) setIsVerifying(false);
        }
    };

    const renderStepContent = () => {
        if (!activeExperiment) return null;
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} />;
        }

        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={handleCompleteStep} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={() => handleCompleteStep()} onAnalysisFailure={handleAnalysisFailure} />;
        if (activeStep === 8) return <InterpretationWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={() => handleCompleteStep()} />;
        if (activeStep === 10) return <PublicationExporter />;

        return (
            <div className="discovery-view">
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    if (!activeExperiment) return null;

    const currentStepData = activeExperiment.stepData?.[activeStep];
    const hasOutput = currentStepData?.output;
    const hasCriticalBlocker = currentStepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);

    return (
        <div className="workspace-container">
            <aside className="sidebar-nav">
                <div className="card shadow-sm border-secondary border-opacity-10 overflow-hidden">
                    <div className="card-header fw-bold bg-dark py-3 small ls-1 text-uppercase">
                        <i className="bi bi-cpu-fill text-primary-glow me-2"></i> Timeline
                    </div>
                    <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                            <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                                style={{ cursor: (step.id <= activeExperiment.currentStep && !isLoading && !isVerifying) ? 'pointer' : 'default' }}
                            >
                                <span className="small">{step.id}. {step.title}</span>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                </div>
            </aside>

            <main className="content-area">
                <div className="card shadow-sm border-secondary border-opacity-25 position-relative overflow-hidden">
                    {(isLoading || isVerifying) && (
                        <div className="progress rounded-0" style={{ height: '3px', position: 'absolute', top: 0, left: 0, right: 0, zIndex: 100 }}>
                            <div className="progress-bar progress-bar-striped progress-bar-animated bg-primary-glow w-100"></div>
                        </div>
                    )}
                    <div className="card-body p-4" style={{ minHeight: '60vh' }}>
                        <div className="d-flex justify-content-between align-items-start mb-4">
                            <div>
                                <div className="badge bg-primary bg-opacity-10 text-primary-glow mb-2">Step {activeStep}</div>
                                <h4 className="fw-bold mb-1">{WORKFLOW_STEPS[activeStep - 1]?.title || 'Node Overview'}</h4>
                                <p className="text-white-50 small mb-0">{WORKFLOW_STEPS[activeStep - 1]?.description}</p>
                            </div>
                            {activeExperiment.automationMode === 'automated' && (
                                <div className="d-flex flex-column align-items-end">
                                    <span className={`badge ${automationPaused ? 'bg-warning text-dark' : 'bg-primary'} px-3 py-2 rounded-pill shadow-sm mb-2`}>
                                        <i className={`bi ${automationPaused ? 'bi-pause-circle-fill' : 'bi-cpu-fill'} me-1`}></i> 
                                        {automationPaused ? 'AUTOMATION PAUSED' : 'AGENTIC OVERRIDE ACTIVE'}
                                    </span>
                                    {automationPaused && (
                                        <button className="btn btn-xs btn-outline-warning" onClick={() => setAutomationPaused(false)}>
                                            <i className="bi bi-play-fill me-1"></i> RESUME
                                        </button>
                                    )}
                                </div>
                            )}
                        </div>
                        <hr className="border-secondary opacity-10 mb-4" />

                        {currentStepData?.blockers && (
                            <BlockerDisplay 
                                blockers={currentStepData.blockers} 
                                onResolve={handleResolveBlocker} 
                            />
                        )}

                        {renderStepContent()}
                    </div>

                    {activeStep <= WORKFLOW_STEPS.length && (
                        <div className="card-footer d-flex justify-content-between align-items-center p-3 bg-dark bg-opacity-25 border-top border-secondary border-opacity-10">
                            <button className="btn btn-sm btn-outline-secondary" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Tuning
                            </button>
                            <button 
                                className={`btn btn-${hasCriticalBlocker ? 'outline-danger' : 'success'} px-4 shadow-sm`} 
                                onClick={() => handleCompleteStep()} 
                                disabled={isVerifying || !hasOutput || hasCriticalBlocker}
                            >
                                {isVerifying ? (
                                    <span className="spinner-border spinner-border-sm me-2"></span>
                                ) : (
                                    <i className={`bi ${hasCriticalBlocker ? 'bi-lock-fill' : (hasOutput ? 'bi-check-circle-fill' : 'bi-lock-fill')} me-2`}></i> 
                                )}
                                {hasCriticalBlocker ? 'PROTOCOL BLOCKED' : (activeStep === 10 ? "Finish Project" : "Verify Node & Continue")}
                            </button>
                        </div>
                    )}
                </div>
            </main>

            {fineTuneModalOpen && (
                <FineTuneModal stepId={activeStep} onClose={() => setFineTuneModalOpen(false)} />
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useExperiment, runManualFormQA } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry, extractJson } from '../../../services';
import { DYNAMIC_TABLE_SCHEMA } from '../../../config';
import { AgenticAnalysisView } from '../../common/AgenticAnalysisView';
import * as XLSX from 'xlsx';

export const ManualDataEntry = ({ onComplete, context }) => {
    const { isAuthenticated, activeExperiment } = useExperiment();
    const [columns, setColumns] = useState<string[]>([]);
    const [rows, setRows] = useState<Record<string, string>[]>([]);
    const [agenticRun, setAgenticRun] = useState({
        status: 'idle',
        logs: [],
        iterations: 0,
        maxIterations: 5,
    });
    const { addToast } = useToast();
    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        if (activeExperiment?.automationMode === 'automated') {
             addToast("Manual Data Entry required. Automation paused for user input.", "info");
        }
        return () => { isMounted.current = false; };
    }, [activeExperiment?.automationMode, addToast]);

    const initializeForm = useCallback(async () => {
        if (!isAuthenticated || agenticRun.status === 'running') return;

        setAgenticRun(prev => ({ ...prev, status: 'running', logs: [], iterations: 0 }));
        let lastFeedback = "";

        for (let i = 0; i < agenticRun.maxIterations; i++) {
            if (!isMounted.current) return;

            try {
                const attempt = i + 1;
                setAgenticRun(prev => ({ 
                    ...prev, 
                    iterations: attempt,
                    logs: [...prev.logs, { agent: 'Architect', message: `Attempt ${attempt}: Generating data entry schema...` }] 
                }));

                const prompt = `ACT AS: Scientific Database Architect.
                Based on the data collection plan: "${context.data_collection_plan_summary}", generate a JSON array of column objects for a data table.

                ${lastFeedback ? `CRITICAL FAILURE IN PREVIOUS ATTEMPT: ${lastFeedback}. You MUST fix these structural issues.` : ''}

                REQUIREMENTS:
                1. Output a JSON array where each object has "columnName" and "dataType".
                2. Columns MUST map directly to the variables in the methodology.

                Output ONLY raw JSON array.`;

                const response = await callGeminiWithRetry('gemini-3-flash-preview', { 
                    contents: prompt, 
                    config: { responseMimeType: "application/json", responseSchema: DYNAMIC_TABLE_SCHEMA } 
                });

                const schemaText = extractJson(response.text);

                setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Auditor', message: 'Analyzing schema integrity against methodology...' }] }));
                const qa = await runManualFormQA(schemaText, context);

                if (qa.is_valid && qa.quality_score > 0.6) {
                    const schemaArray = JSON.parse(schemaText);
                    const newColumns = schemaArray.map((col: any) => col.columnName);
                    if (newColumns.length === 0) throw new Error("Architect returned zero columns.");

                    setColumns(newColumns);
                    setRows([Object.fromEntries(newColumns.map((c: string) => [c, '']))]);
                    setAgenticRun(prev => ({ ...prev, status: 'success' }));
                    addToast("Data entry portal initialized and verified.", "success");
                    return;
                } else {
                    lastFeedback = qa.issues.join('; ');
                    setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Auditor', message: `SCHEMA REJECTED: ${lastFeedback}. Retrying...` }] }));
                    // Small delay to prevent tight-loop 429s during self-healing
                    await new Promise(r => setTimeout(r, 2000));
                }
            } catch (err) {
                const msg = parseGeminiError(err);
                setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'System', message: `RECOVERY MODE: ${msg}` }] }));
                await new Promise(r => setTimeout(r, 3000));
            }
        }
        setAgenticRun(prev => ({ ...prev, status: 'failed' }));
    }, [isAuthenticated, context, agenticRun.status, agenticRun.maxIterations, addToast]);

    useEffect(() => {
        if (columns.length === 0 && agenticRun.status === 'idle') {
            initializeForm();
        }
    }, [columns.length, agenticRun.status, initializeForm]);

    const handleRowChange = (index, col, value) => {
        const newRows = [...rows];
        newRows[index][col] = value;
        setRows(newRows);
    };

    const addRow = () => setRows([...rows, Object.fromEntries(columns.map(c => [c, '']))]);
    const removeRow = (index) => setRows(rows.filter((_, i) => i !== index));

    const handleSubmit = () => {
        if (rows.some(r => Object.values(r).some(v => !(v as string).trim()))) {
            if (!window.confirm("PROTOCOL WARNING: Some fields are empty. This may degrade analysis quality. Proceed anyway?")) return;
        }
        const header = columns.join(',');
        const body = rows.map(row => columns.map(col => `"${(row[col] || '').replace(/"/g, '""')}"`).join(',')).join('\n');
        onComplete(`${header}\n${body}`, "Manually entered forensic data.");
    };

    if (agenticRun.status === 'running') return <AgenticAnalysisView agenticRun={agenticRun} title="Building Data Entry Portal" subtitle="Agents are negotiating table structure and variable mapping." />;

    return (
        <div className="animate-in">
            {agenticRun.status === 'failed' ? (
                <div className="alert alert-danger">
                    <h6 className="fw-bold">Form Generation Protocol Failed</h6>
                    <p className="small mb-2">The AI Architect could not produce a stable schema. This is usually due to an underspecified methodology.</p>
                    <button className="btn btn-sm btn-outline-danger" onClick={() => { setAgenticRun(p => ({...p, status: 'idle'})); setColumns([]); }}>Retry Initialization</button>
                </div>
            ) : (
                <div className="card mb-4 border-secondary border-opacity-25 bg-black bg-opacity-20 shadow-sm">
                    <div className="card-body">
                        <div className="d-flex justify-content-between align-items-center mb-3">
                            <h6 className="fw-bold mb-0">Step 6: Forensic Data Entry</h6>
                            <button className="btn btn-xs btn-outline-secondary" onClick={() => { if(window.confirm("Reset table structure?")) { setColumns([]); setAgenticRun(p=>({...p, status:'idle'})); }}} title="Re-initialize Architect Agents">
                                <i className="bi bi-gear-wide-connected"></i>
                            </button>
                        </div>
                        <div className="table-responsive">
                            <table className="table table-bordered border-secondary border-opacity-10 mb-3">
                                <thead className="bg-dark bg-opacity-50">
                                    <tr>{columns.map(c => <th key={c} className="small text-uppercase ls-1">{c}</th>)}<th style={{ width: '50px' }}></th></tr>
                                </thead>
                                <tbody>
                                    {rows.map((row, rowIndex) => (
                                        <tr key={rowIndex}>
                                            {columns.map(col => <td key={col} className="p-1"><input type="text" className="form-control form-control-sm border-0 bg-transparent text-white" value={row[col] || ''} onChange={e => handleRowChange(rowIndex, col, e.target.value)} /></td>)}
                                            <td className="p-1 text-center"><button className="btn btn-sm text-danger" onClick={() => removeRow(rowIndex)} disabled={rows.length <= 1}><i className="bi bi-x-lg"></i></button></td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="d-flex justify-content-between">
                            <button className="btn btn-sm btn-outline-secondary" onClick={addRow}><i className="bi bi-plus-lg me-1"></i> Add Record</button>
                            <button className="btn btn-success px-4" onClick={handleSubmit}><i className="bi bi-check-circle-fill me-1"></i> Finalize Entry</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { 
    parseGeminiError, 
    getStepContext, 
    getPromptForStep, 
    executeStepWorkflow, 
    callGeminiStreamWithRetry,
    generateNodeSummary
} from '../../services';
import { WORKFLOW_STEPS, RESEARCH_QUESTION_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, LITERATURE_REVIEW_SCHEMA } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';
import { InterpretationWorkspace } from '../steps/InterpretationWorkspace';
import { BlockerDisplay } from './BlockerDisplay';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();

    const [activeStep, setActiveStep] = useState(activeExperiment?.currentStep || 1);
    const [isLoading, setIsLoading] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const [streamingText, setStreamingText] = useState<string | null>(null);
    const [automationPaused, setAutomationPaused] = useState(false);
    const [reviewCountdown, setReviewCountdown] = useState<number | null>(null);

    const streamBuffer = useRef("");
    const streamInterval = useRef<any>(null);
    const isMounted = useRef(true);
    const lastAutomationTick = useRef<number>(0);
    const countdownInterval = useRef<any>(null);

    useEffect(() => {
        isMounted.current = true;
        return () => { 
            isMounted.current = false;
            if (streamInterval.current) clearInterval(streamInterval.current);
            if (countdownInterval.current) clearInterval(countdownInterval.current);
        };
    }, []);

    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading && !isVerifying) {
            setActiveStep(activeExperiment.currentStep);
            setAutomationPaused(false); 
            setReviewCountdown(null);
        }
    }, [activeExperiment?.currentStep, isLoading, isVerifying, activeStep]);

    // Countdown Timer Logic
    useEffect(() => {
        if (reviewCountdown !== null && reviewCountdown > 0) {
            if (countdownInterval.current) clearInterval(countdownInterval.current);
            countdownInterval.current = setInterval(() => {
                setReviewCountdown(prev => (prev !== null && prev > 0) ? prev - 1 : null);
            }, 1000);
        } else if (reviewCountdown === 0) {
            setReviewCountdown(null);
            if (countdownInterval.current) clearInterval(countdownInterval.current);
            handleCompleteStep();
        }
        return () => { if (countdownInterval.current) clearInterval(countdownInterval.current); };
    }, [reviewCountdown]);

    // Main Automation Loop
    useEffect(() => {
        if (!activeExperiment || !isAuthenticated || isLoading || isVerifying || automationPaused || reviewCountdown !== null) return;

        const mode = activeExperiment.automationMode;
        if (mode === 'automated' && activeStep === activeExperiment.currentStep) {
            const now = Date.now();
            if (now - lastAutomationTick.current < 3000) return;
            lastAutomationTick.current = now;

            const stepData = (activeExperiment.stepData && activeExperiment.stepData[activeStep]) || {};
            const isAgenticStep = [2, 6, 7, 8, 9, 10].includes(activeStep);

            const hasCriticalBlockers = stepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);
            if (hasCriticalBlockers) {
                setAutomationPaused(true);
                addToast("Automation paused: Critical blockers detected.", "warning");
                return;
            }

            if (!stepData?.output && !isAgenticStep) {
                handleGenerate();
            } else if (stepData?.output && !stepData?.summary && !isAgenticStep) {
                // Initiating 15-second review delay
                setReviewCountdown(15);
            }
        }
    }, [activeExperiment, activeStep, isAuthenticated, isLoading, isVerifying, automationPaused, reviewCountdown, addToast]);

    const handleStepChange = useCallback((stepId: number) => {
        if (isLoading || isVerifying) return;
        setStreamingText(null);
        setActiveStep(stepId);
        setAutomationPaused(false);
        setReviewCountdown(null);
    }, [isLoading, isVerifying]);

    const handleResolveBlocker = async (blockerId: string) => {
        if (!activeExperiment) return;
        const stepData = { ...(activeExperiment.stepData || {}) };
        const currentStepData = { ...(stepData[activeStep] || {}) };
        const blockers = (currentStepData.blockers || []).map(b => 
            b.id === blockerId ? { ...b, resolved: true } : b
        );

        stepData[activeStep] = { ...currentStepData, blockers };
        await updateExperiment({ ...activeExperiment, stepData });
        addToast("Blocker mitigation logged.", "success");
    };

    const handleAnalysisFailure = useCallback(async (errorMsg: string) => {
        if (!activeExperiment) return;
        if (errorMsg.includes("DATA_QUALITY_FAILURE") || errorMsg.includes("Data Quality Check Failed")) {
            addToast(`Data quality failed: Re-routing to Acquisition for correction.`, "warning");
            const updatedStepData = { ...activeExperiment.stepData };
            updatedStepData[7] = { ...updatedStepData[7], output: undefined, summary: undefined };
            updatedStepData[6] = { ...updatedStepData[6], output: undefined, summary: undefined };
            await updateExperiment({ ...activeExperiment, currentStep: 6, stepData: updatedStepData });
            setActiveStep(6);
        } else {
             addToast(`Analysis error: ${errorMsg}`, "danger");
             if (activeExperiment.automationMode === 'automated') setAutomationPaused(true);
        }
    }, [activeExperiment, updateExperiment, addToast]);

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading || isVerifying) return;
        setStreamingText(null);
        setIsLoading(true);
        setReviewCountdown(null);
        streamBuffer.current = "";

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            const input = (activeExperiment.stepData && activeExperiment.stepData[activeStep]?.input) || '';
            const stepSettings = activeExperiment.fineTuneSettings?.[activeStep] || {};
            const { basePrompt, expectJson, config } = getPromptForStep(activeStep, input, context, stepSettings, regenerateFeedback);

            if (expectJson) {
                const schema = (activeStep === 1) ? RESEARCH_QUESTION_SCHEMA : (activeStep === 2) ? LITERATURE_REVIEW_SCHEMA : DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
                const model = activeStep === 1 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
                const output = await executeStepWorkflow(model, { contents: basePrompt, config }, context, true, schema);
                if (isMounted.current) {
                    await updateExperiment({ 
                        ...activeExperiment, 
                        stepData: { ...activeExperiment.stepData, [activeStep]: { ...(activeExperiment.stepData?.[activeStep] || {}), output } } 
                    });
                }
            } else {
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });
                if (streamInterval.current) clearInterval(streamInterval.current);
                streamInterval.current = setInterval(() => { if (isMounted.current) setStreamingText(streamBuffer.current); }, 100);
                for await (const chunk of stream) { streamBuffer.current += (chunk.text || ''); }
                if (streamInterval.current) { clearInterval(streamInterval.current); streamInterval.current = null; }
                if (isMounted.current) {
                    const finalOutput = streamBuffer.current;
                    setStreamingText(finalOutput);
                    await updateExperiment({
                        ...activeExperiment,
                        stepData: { ...activeExperiment.stepData, [activeStep]: { ...(activeExperiment.stepData?.[activeStep] || {}), output: finalOutput } }
                    });
                }
            }
            if (isMounted.current) addToast("Archival node synchronized.", "success");
        } catch (error) {
            if (isMounted.current) {
                addToast(parseGeminiError(error), 'danger');
                if (activeExperiment?.automationMode === 'automated') setAutomationPaused(true);
            }
        } finally {
            if (isMounted.current) setIsLoading(false);
        }
    };

    const handleCompleteStep = async (stepDataOverride?: any) => {
        if (isVerifying || !activeExperiment) return;
        setIsVerifying(true);
        setReviewCountdown(null);
        const currentStepData = { ...(activeExperiment.stepData?.[activeStep] || {}), ...stepDataOverride };
        const currentOutput = currentStepData.output || "";

        const hasCriticalBlockers = currentStepData.blockers?.some(b => b.severity === 'critical' && !b.resolved);
        if (hasCriticalBlockers) {
            addToast("Resolve critical blockers before proceeding.", "warning");
            setAutomationPaused(true);
            setIsVerifying(false);
            return;
        }

        try {
            let summary = currentStepData.summary;
            if (!summary && currentOutput.length > 50) {
                try { summary = await generateNodeSummary(currentOutput, activeExperiment.field); } catch (e) { summary = "Node verified."; }
            } else if (!summary) { summary = "Node verified."; }

            const nextStepId = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : activeStep;
            const updatedStepDataMap = { ...(activeExperiment.stepData || {}) };
            updatedStepDataMap[activeStep] = { ...currentStepData, summary };

            if (activeStep === 6) {
                const csvData = currentStepData.input || currentOutput; 
                updatedStepDataMap[7] = { ...(updatedStepDataMap[7] || {}), input: csvData, output: undefined, summary: undefined };
            }

            const updatedExp = { ...activeExperiment, stepData: updatedStepDataMap, currentStep: nextStepId };
            await updateExperiment(updatedExp);
            if (isMounted.current) {
                addToast(`Step ${activeStep} complete. Moving to Step ${nextStepId}.`, "success");
                setActiveStep(nextStepId);
            }
        } catch (error) {
            console.error("Verification error:", error);
            if (isMounted.current) addToast("Archival link unstable.", 'danger');
        } finally {
            if (isMounted.current) setIsVerifying(false);
        }
    };

    const renderStepContent = () => {
        if (!activeExperiment) return null;
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} />;
        }

        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={(data: any) => { handleCompleteStep(data); }} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={() => setReviewCountdown(15)} onAnalysisFailure={handleAnalysisFailure} />;
        if (activeStep === 8) return <InterpretationWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 10) return <PublicationExporter />;

        return (
            <div className="discovery-view">
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    if (!activeExperiment) return null;

    const currentStepData = activeExperiment.stepData?.[activeStep];
    const hasOutput = currentStepData?.output;
    const hasCriticalBlocker = currentStepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);

    return (
        <div className="workspace-container">
            <aside className="sidebar-nav">
                <div className="card shadow-sm border-secondary border-opacity-10 overflow-hidden">
                    <div className="card-header fw-bold bg-dark py-3 small ls-1 text-uppercase">
                        <i className="bi bi-cpu-fill text-primary-glow me-2"></i> Timeline
                    </div>
                    <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                            <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                                style={{ cursor: (step.id <= activeExperiment.currentStep && !isLoading && !isVerifying) ? 'pointer' : 'default' }}
                            >
                                <div className="d-flex align-items-center gap-2 flex-grow-1">
                                    <span className="small">{step.id}. {step.title}</span>
                                    {((isLoading || isVerifying) && activeStep === step.id) && (
                                        <div className="spinner-border spinner-border-sm text-primary-glow" role="status"></div>
                                    )}
                                </div>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                </div>
            </aside>

            <main className="content-area">
                <div className="card shadow-sm border-secondary border-opacity-25 position-relative overflow-hidden">
                    {(isLoading || isVerifying || reviewCountdown !== null) && (
                        <div className="progress rounded-0" style={{ height: '4px', position: 'absolute', top: 0, left: 0, right: 0, zIndex: 100 }}>
                            <div className={`progress-bar progress-bar-striped progress-bar-animated ${reviewCountdown !== null ? 'bg-info' : 'bg-primary-glow'}`} 
                                 style={{ width: reviewCountdown !== null ? `${(reviewCountdown / 15) * 100}%` : '100%' }}></div>
