// --- ERROR HANDLING ---

export const parseGeminiError = (error: any, defaultMsg = "An error occurred with the AI service."): string => {
    console.error("Gemini Error:", error);
    const msg = error?.message || error?.toString() || "";

    // Explicit 429 Handling
    if (msg.includes("429") || msg.includes("quota") || msg.includes("RESOURCE_EXHAUSTED")) {
        return "API Quota Exceeded (429). The system is applying a cooling-off period. Please wait 15-30 seconds.";
    }
    if (msg.includes("401") || msg.includes("API key")) return "Invalid API Key. Please re-authenticate.";
    if (msg.includes("503") || msg.includes("overloaded")) return "AI Service overloaded. Retrying usually fixes this.";
    if (msg.includes("SAFETY")) return "Content blocked by safety filters. Please refine your input.";

    return defaultMsg;
};

// --- UTILITIES ---

export const extractJson = (text: any): string => {
    if (typeof text !== 'string') return "";
    if (!text) return "";

    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    if (match && match[1]) return match[1].trim();

    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');

    let startIdx = -1;
    let endIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIdx = firstBrace;
        endIdx = text.lastIndexOf('}');
    } else if (firstBracket !== -1) {
        startIdx = firstBracket;
        endIdx = text.lastIndexOf(']');
    }

    if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
        return text.substring(startIdx, endIdx + 1).trim();
    }

    return text.trim();
};

export const isValidJsonForSchema = (jsonString: string, schema: any): boolean => {
    try {
        const obj = JSON.parse(jsonString);
        if (!obj) return false;
        // Basic check: if schema requires certain properties, check existence
        if (schema && schema.required && Array.isArray(schema.required)) {
            for (const field of schema.required) {
                if (!(field in obj)) return false;
            }
        }
        return true;
    } catch (e) {
        return false;
    }
};

export const parseBlockers = (text: string): Blocker[] => {
    try {
        const jsonStr = extractJson(text);
        if (!jsonStr) return [];
        const data = JSON.parse(jsonStr);

        const alert = data.BLOCKER_ALERT || (data.severity ? data : null);
        if (!alert) return [];

        const blockersList = Array.isArray(alert) ? alert : [alert];
        return blockersList
            .filter((b: any) => b && (b.severity === 'critical' || b.severity === 'warning') && b.msg)
            .map((b: any, i: number) => ({
                id: `blk_${Date.now()}_${i}`,
                severity: b.severity,
                msg: b.msg,
                resolved: false
            }));
    } catch (e) {
        return [];
    }
};

// --- GEMINI WRAPPERS ---

const MODEL_CONFIGS: any = {
    'gemini-3-flash-preview': { temperature: 0.7, topK: 40, topP: 0.95 },
    'gemini-3-pro-preview': { temperature: 0.9, topK: 64, topP: 0.95 }
};

export const callGeminiWithRetry = async (modelName: string, params: any, retries = 3) => {
    const apiKey = getSafeEnvApiKey();
    if (!apiKey) throw new Error("No API Key available in environment variables.");

    const ai = new GoogleGenAI({ apiKey });

    const defaults = MODEL_CONFIGS[modelName] || {};
    params.config = { ...defaults, ...(params.config || {}) };

    for (let i = 0; i <= retries; i++) {
        try {
            const response = await ai.models.generateContent({
                model: modelName,
                ...params
            });
            return response;
        } catch (error: any) {
            const msg = error.message || "";
            const isRateLimit = msg.includes("429") || msg.includes("quota") || msg.includes("RESOURCE_EXHAUSTED");

            if (i === retries) throw error;

            if (isRateLimit || msg.includes("503") || msg.includes("500") || msg.includes("400")) {
                // Aggressive exponential backoff for rate limits: 5s, 10s, 20s...
                const waitTime = isRateLimit ? 5000 * Math.pow(2, i) : 1000 * (i + 1);
                console.warn(`Retry ${i + 1}/${retries} after ${waitTime}ms...`);
                await new Promise(res => setTimeout(res, waitTime));
            } else {
                throw error;
            }
        }
    }
    throw new Error("Maximum retries reached.");
};

export const callGeminiStreamWithRetry = async (modelName: string, params: any) => {
    const apiKey = getSafeEnvApiKey();
    if (!apiKey) throw new Error("No API Key available in environment variables.");

    const ai = new GoogleGenAI({ apiKey });

    const defaults = MODEL_CONFIGS[modelName] || {};
    params.config = { ...defaults, ...(params.config || {}) };

    try {
        const stream = await ai.models.generateContentStream({
            model: modelName,
            ...params
        });
        return stream;
    } catch (error) {
        console.error("Stream Error", error);
        throw error;
    }
};

export const generateNodeSummary = async (content: string, field: string): Promise<string> => {
    if (!content || content.length < 50) return content;

    const prompt = `As a Research Archivist in ${field}, compress the following content into a concise, high-density summary (max 3 sentences) suitable for context in future steps. Preserve key variables, findings, and numbers.

    CONTENT:
    ${content.substring(0, 15000)}...`;

    try {
        const response = await callGeminiWithRetry('gemini-3-flash-preview', { contents: prompt });
        return response.text || content.substring(0, 200) + "...";
    } catch (e) {
        return content.substring(0, 200) + "...";
    }
};

