        isMounted.current = true;
        return () => { 
            isMounted.current = false;
            if (streamInterval.current) clearInterval(streamInterval.current);
            if (countdownInterval.current) clearInterval(countdownInterval.current);
        };
    }, []);

    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading && !isVerifying) {
            setActiveStep(activeExperiment.currentStep);
            setAutomationPaused(false); 
            setReviewCountdown(null);
        }
    }, [activeExperiment?.currentStep, isLoading, isVerifying, activeStep]);

    // Countdown Timer Logic for Automation
    useEffect(() => {
        if (reviewCountdown !== null && reviewCountdown > 0) {
            if (countdownInterval.current) clearInterval(countdownInterval.current);
            countdownInterval.current = setInterval(() => {
                setReviewCountdown(prev => (prev !== null && prev > 0) ? prev - 1 : null);
            }, 1000);
        } else if (reviewCountdown === 0) {
            setReviewCountdown(null);
            if (countdownInterval.current) clearInterval(countdownInterval.current);
            handleCompleteStep();
        }
        return () => { if (countdownInterval.current) clearInterval(countdownInterval.current); };
    }, [reviewCountdown]);

    // Main Automation Loop
    useEffect(() => {
        if (!activeExperiment || !isAuthenticated || isLoading || isVerifying || automationPaused || reviewCountdown !== null) return;

        const mode = activeExperiment.automationMode;
        if (mode === 'automated' && activeStep === activeExperiment.currentStep) {
            const now = Date.now();
            // Minimum delay between autonomous actions to avoid burst 429s
            if (now - lastAutomationTick.current < 5000) return;
            lastAutomationTick.current = now;

            const stepData = (activeExperiment.stepData && activeExperiment.stepData[activeStep]) || {};
            const isAgenticStep = [2, 6, 7, 8, 9, 10].includes(activeStep);

            const hasCriticalBlockers = stepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);
            if (hasCriticalBlockers) {
                setAutomationPaused(true);
                addToast("Automation paused: Critical blockers detected.", "warning");
                return;
            }

            if (!stepData?.output && !isAgenticStep) {
                handleGenerate();
            } else if (stepData?.output && !stepData?.summary && !isAgenticStep) {
                // Initiate the 15-second review delay before completing the step
                setReviewCountdown(15);
            }
        }
    }, [activeExperiment, activeStep, isAuthenticated, isLoading, isVerifying, automationPaused, reviewCountdown, addToast]);

    const handleStepChange = useCallback((stepId: number) => {
        if (isLoading || isVerifying) return;
        setStreamingText(null);
        setActiveStep(stepId);
        setAutomationPaused(false);
        setReviewCountdown(null);
    }, [isLoading, isVerifying]);

    const handleResolveBlocker = async (blockerId: string) => {
        if (!activeExperiment) return;
        const stepData = { ...(activeExperiment.stepData || {}) };
        const currentStepData = { ...(stepData[activeStep] || {}) };
        const blockers = (currentStepData.blockers || []).map(b => 
            b.id === blockerId ? { ...b, resolved: true } : b
        );

        stepData[activeStep] = { ...currentStepData, blockers };
        await updateExperiment({ ...activeExperiment, stepData });
        addToast("Blocker mitigation logged.", "success");
    };

    const handleAnalysisFailure = useCallback(async (errorMsg: string) => {
        if (!activeExperiment) return;
        if (errorMsg.includes("DATA_QUALITY_FAILURE") || errorMsg.includes("Data Quality Check Failed")) {
            addToast(`Data quality failed: Re-routing to Acquisition for correction.`, "warning");
            const updatedStepData = { ...activeExperiment.stepData };
            updatedStepData[7] = { ...updatedStepData[7], output: undefined, summary: undefined };
            updatedStepData[6] = { ...updatedStepData[6], output: undefined, summary: undefined };
            await updateExperiment({ ...activeExperiment, currentStep: 6, stepData: updatedStepData });
            setActiveStep(6);
        } else {
             addToast(`Analysis error: ${errorMsg}`, "danger");
             if (activeExperiment.automationMode === 'automated') setAutomationPaused(true);
        }
    }, [activeExperiment, updateExperiment, addToast]);

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading || isVerifying) return;
        setStreamingText(null);
        setIsLoading(true);
        setReviewCountdown(null);
        streamBuffer.current = "";

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            const input = (activeExperiment.stepData && activeExperiment.stepData[activeStep]?.input) || '';
            const stepSettings = activeExperiment.fineTuneSettings?.[activeStep] || {};
            const { basePrompt, expectJson, config } = getPromptForStep(activeStep, input, context, stepSettings, regenerateFeedback);

            if (expectJson) {
                const schema = (activeStep === 1) ? RESEARCH_QUESTION_SCHEMA : (activeStep === 2) ? LITERATURE_REVIEW_SCHEMA : DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
                const model = activeStep === 1 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
                const output = await executeStepWorkflow(model, { contents: basePrompt, config }, context, true, schema);
                if (isMounted.current) {
                    await updateExperiment({ 
                        ...activeExperiment, 
                        stepData: { ...activeExperiment.stepData, [activeStep]: { ...(activeExperiment.stepData?.[activeStep] || {}), output } } 
                    });
                }
            } else {
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });
                if (streamInterval.current) clearInterval(streamInterval.current);
                streamInterval.current = setInterval(() => { if (isMounted.current) setStreamingText(streamBuffer.current); }, 100);
                for await (const chunk of stream) { streamBuffer.current += (chunk.text || ''); }
                if (streamInterval.current) { clearInterval(streamInterval.current); streamInterval.current = null; }
                if (isMounted.current) {
                    const finalOutput = streamBuffer.current;
                    setStreamingText(finalOutput);
                    await updateExperiment({
                        ...activeExperiment,
                        stepData: { ...activeExperiment.stepData, [activeStep]: { ...(activeExperiment.stepData?.[activeStep] || {}), output: finalOutput } }
                    });
                }
            }
            if (isMounted.current) addToast("Archival node synchronized.", "success");
        } catch (error) {
            if (isMounted.current) {
                addToast(parseGeminiError(error), 'danger');
                if (activeExperiment?.automationMode === 'automated') setAutomationPaused(true);
            }
        } finally {
            if (isMounted.current) setIsLoading(false);
        }
    };

    const handleCompleteStep = async (stepDataOverride?: any) => {
        if (isVerifying || !activeExperiment) return;
        setIsVerifying(true);
        setReviewCountdown(null);
        const currentStepData = { ...(activeExperiment.stepData?.[activeStep] || {}), ...stepDataOverride };
        const currentOutput = currentStepData.output || "";

        const hasCriticalBlockers = currentStepData.blockers?.some(b => b.severity === 'critical' && !b.resolved);
        if (hasCriticalBlockers) {
            addToast("Resolve critical blockers before proceeding.", "warning");
            setAutomationPaused(true);
            setIsVerifying(false);
            return;
        }

        try {
            let summary = currentStepData.summary;
            if (!summary && currentOutput.length > 50) {
                try { summary = await generateNodeSummary(currentOutput, activeExperiment.field); } catch (e) { summary = "Node verified."; }
            } else if (!summary) { summary = "Node verified."; }

            const nextStepId = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : activeStep;
            const updatedStepDataMap = { ...(activeExperiment.stepData || {}) };
            updatedStepDataMap[activeStep] = { ...currentStepData, summary };

            if (activeStep === 6) {
                const csvData = currentStepData.input || currentOutput; 
                updatedStepDataMap[7] = { ...(updatedStepDataMap[7] || {}), input: csvData, output: undefined, summary: undefined };
            }

            const updatedExp = { ...activeExperiment, stepData: updatedStepDataMap, currentStep: nextStepId };
            await updateExperiment(updatedExp);
            if (isMounted.current) {
                addToast(`Step ${activeStep} complete. Moving to Step ${nextStepId}.`, "success");
                setActiveStep(nextStepId);
            }
        } catch (error) {
            console.error("Verification error:", error);
            if (isMounted.current) addToast("Archival link unstable.", 'danger');
        } finally {
            if (isMounted.current) setIsVerifying(false);
        }
    };

    const renderStepContent = () => {
        if (!activeExperiment) return null;
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} />;
        }

        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={(data: any) => { handleCompleteStep(data); }} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={() => setReviewCountdown(15)} onAnalysisFailure={handleAnalysisFailure} />;
        if (activeStep === 8) return <InterpretationWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 10) return <PublicationExporter />;

        return (
            <div className="discovery-view">
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    if (!activeExperiment) return null;

    const currentStepData = activeExperiment.stepData?.[activeStep];
    const hasOutput = currentStepData?.output;
    const hasCriticalBlocker = currentStepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);

    return (
        <div className="workspace-container">
            <aside className="sidebar-nav">
                <div className="card shadow-sm border-secondary border-opacity-10 overflow-hidden">
                    <div className="card-header fw-bold bg-dark py-3 small ls-1 text-uppercase">
                        <i className="bi bi-cpu-fill text-primary-glow me-2"></i> Timeline
                    </div>
                    <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                            <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                                style={{ cursor: (step.id <= activeExperiment.currentStep && !isLoading && !isVerifying) ? 'pointer' : 'default' }}
                            >
                                <div className="d-flex align-items-center gap-2 flex-grow-1">
                                    <span className="small">{step.id}. {step.title}</span>
                                    {((isLoading || isVerifying) && activeStep === step.id) && (
                                        <div className="spinner-border spinner-border-sm text-primary-glow" role="status"></div>
                                    )}
                                </div>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                </div>
            </aside>

            <main className="content-area">
                <div className="card shadow-sm border-secondary border-opacity-25 position-relative overflow-hidden">
                    {(isLoading || isVerifying || reviewCountdown !== null) && (
                        <div className="progress rounded-0" style={{ height: '4px', position: 'absolute', top: 0, left: 0, right: 0, zIndex: 100 }}>
                            <div className={`progress-bar progress-bar-striped progress-bar-animated ${reviewCountdown !== null ? 'bg-info' : 'bg-primary-glow'}`} 
                                 style={{ width: reviewCountdown !== null ? `${(reviewCountdown / 15) * 100}%` : '100%' }}></div>
                        </div>
                    )}
                    <div className="card-body p-4" style={{ minHeight: '60vh' }}>
                        <div className="d-flex justify-content-between align-items-start mb-4">
                            <div>
                                <div className="badge bg-primary bg-opacity-10 text-primary-glow mb-2">Step {activeStep}</div>
                                <h4 className="fw-bold mb-1">{WORKFLOW_STEPS[activeStep - 1]?.title || 'Node Overview'}</h4>
                                <p className="text-white-50 small mb-0">{WORKFLOW_STEPS[activeStep - 1]?.description}</p>
                            </div>
                            <div className="d-flex flex-column align-items-end">
                                {activeExperiment.automationMode === 'automated' && (
                                    <>
                                        <span className={`badge ${automationPaused ? 'bg-warning text-dark' : 'bg-primary'} px-3 py-2 rounded-pill shadow-sm mb-2`}>
                                            <i className={`bi ${automationPaused ? 'bi-pause-circle-fill' : 'bi-cpu-fill'} me-1`}></i> 
                                            {automationPaused ? 'AUTOMATION PAUSED' : 'AGENTIC OVERRIDE ACTIVE'}
                                        </span>
                                        {automationPaused && (
                                            <button className="btn btn-xs btn-outline-warning" onClick={() => setAutomationPaused(false)}>
                                                <i className="bi bi-play-fill me-1"></i> RESUME
                                            </button>
                                        )}
                                        {reviewCountdown !== null && (
                                            <div className="text-info small fw-bold mt-1">
                                                <i className="bi bi-eye-fill me-1"></i> AUTO-ADVANCING IN {reviewCountdown}s...
                                                <button className="btn btn-link btn-xs text-info p-0 ms-2" onClick={() => handleCompleteStep()}>SKIP</button>
                                            </div>
                                        )}
                                    </>
                                )}
                            </div>
                        </div>
                        <hr className="border-secondary opacity-10 mb-4" />

                        {currentStepData?.blockers && (
                            <BlockerDisplay 
                                blockers={currentStepData.blockers} 
                                onResolve={handleResolveBlocker} 
                            />
                        )}

                        {renderStepContent()}
                    </div>

                    {activeStep <= WORKFLOW_STEPS.length && (
                        <div className="card-footer d-flex justify-content-between align-items-center p-3 bg-dark bg-opacity-25 border-top border-secondary border-opacity-10">
                            <button className="btn btn-sm btn-outline-secondary" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Tuning
                            </button>
                            <button 
                                className={`btn btn-${hasCriticalBlocker ? 'outline-danger' : 'success'} px-4 shadow-sm`} 
                                onClick={() => handleCompleteStep()} 
                                disabled={isVerifying || !hasOutput || hasCriticalBlocker}
                            >
                                {isVerifying ? (
                                    <span className="spinner-border spinner-border-sm me-2"></span>
                                ) : (
                                    <i className={`bi ${hasCriticalBlocker ? 'bi-lock-fill' : (hasOutput ? 'bi-check-circle-fill' : 'bi-lock-fill')} me-2`}></i> 
                                )}
                                {hasCriticalBlocker ? 'PROTOCOL BLOCKED' : (activeStep === 10 ? "Finish Project" : "Verify Node & Continue")}
                            </button>
                        </div>
                    )}
                </div>
            </main>

            {fineTuneModalOpen && (
                <FineTuneModal stepId={activeStep} onClose={() => setFineTuneModalOpen(false)} />
            )}
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { UniquenessMeter } from './UniquenessMeter';
import { DataAnalysisView } from './DataAnalysisView';
import { extractJson } from '../../services';

interface GeneratedOutputProps {
    stepId: number;
    onGenerate: (feedback?: string) => Promise<void>;
    isLoading: boolean;
    streamingText?: string | null;
}

export const GeneratedOutput: React.FC<GeneratedOutputProps> = ({ 
    stepId, 
    onGenerate, 
    isLoading, 
    streamingText 
}) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();

    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState('');
    const [showRegenInput, setShowRegenInput] = useState(false);
    const [regenFeedback, setRegenFeedback] = useState('');

    const stepData = (activeExperiment.stepData && activeExperiment.stepData[stepId]) || {};
    const savedOutput = typeof stepData.output === 'string' ? stepData.output : '';
    const currentText = typeof streamingText === 'string' ? streamingText : savedOutput;

    useEffect(() => {
        setEditText(savedOutput);
    }, [savedOutput]);

    const handleSave = () => {
        updateExperiment({ 
            ...activeExperiment, 
            stepData: { 
                ...activeExperiment.stepData, 
                [stepId]: { ...stepData, output: editText } 
            } 
        });
        setIsEditing(false);
        addToast("Archival node updated.", "success");
    };

    const handleRegenerate = () => {
        if (isLoading) return;
        onGenerate(regenFeedback);
        setShowRegenInput(false);
        setRegenFeedback('');
    };

    const renderedHtml = useMemo(() => {
        if (!currentText) return '';
        try {
            return renderMarkdown(currentText, !isLoading);
        } catch (e) {
            console.error("Critical rendering error detected:", e);
            return `<div class="alert alert-danger">Rendering Error: Content Stream Interrupted.</div><pre class="text-white-50 small">${currentText.slice(0, 500)}...</pre>`;
        }
    }, [currentText, isLoading]);

    const renderJsonContent = (text: string) => {
        try {
            const clean = extractJson(text);
            if (!clean) throw new Error("No JSON found");
            const data = JSON.parse(clean);

            if (stepId === 1) {
                return (
                   <div className="animate-in">
                       <div className="mb-4" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.research_question || '', true) }} />
                       {data.uniqueness_score !== undefined && (
                           <UniquenessMeter 
                                score={data.uniqueness_score} 
                                justification={data.justification || ''} 
                           />
                       )}
                   </div>
               );
            }

            if (stepId === 2) {
                return (
                    <div className="lit-review-output animate-in">
                        <h5 className="fw-bold text-primary-glow border-bottom border-secondary border-opacity-25 pb-2 mb-3">Synthesis of Findings</h5>
                        <div className="generated-text-container mb-4" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.summary || '', true) }} />
                        {data.references && Array.isArray(data.references) && data.references.length > 0 && (
                            <section>
                                <h5 className="fw-bold text-info small text-uppercase ls-1 border-bottom border-secondary border-opacity-10 pb-2 mb-3">Grounding Links</h5>
                                <div className="list-group list-group-flush bg-transparent">
                                    {data.references.map((ref: any, i: number) => (
                                        <div key={i} className="list-group-item bg-transparent border-secondary border-opacity-10 px-0 py-2">
                                            <div className="fw-bold text-white small">{ref.title}</div>
                                            <div className="text-white-50" style={{fontSize: '0.75rem'}}>{ref.authors?.join(', ')} ({ref.year})</div>
                                            {ref.url && <a href={ref.url} target="_blank" rel="noopener noreferrer" className="small text-primary-glow">View Source &raquo;</a>}
                                        </div>
                                    ))}
                                </div>
                            </section>
                        )}
                    </div>
                );
            }

            if (stepId === 7) return <DataAnalysisView analysisData={data} />;
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        } catch (e) {
            return (
                <div>
                     <div className="alert alert-warning small">
                        <i className="bi bi-exclamation-triangle me-2"></i>
                        Visual rendering failed due to malformed data. Raw output displayed below.
                    </div>
                    <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />
                </div>
            );
        }
    };

    const isJsonStep = stepId === 1 || stepId === 2 || stepId === 7;

    return (
        <div className="generated-content-container">
            {isLoading && (
                <div className="archive-status-line mb-4 px-3 py-2 rounded d-flex flex-column gap-2">
                    <div className="d-flex align-items-center justify-content-between">
                         <div className="d-flex align-items-center">
                              <div className="spinner-border spinner-border-sm text-primary-glow me-2" role="status"></div>
                              <span className="small text-uppercase fw-bold ls-1 text-primary-glow">Archival Link Established: Synthesizing Research Node...</span>
                         </div>
                         <div className="spinner-grow spinner-grow-sm text-primary-glow opacity-50" role="status"></div>
                    </div>
                    <div className="progress bg-dark" style={{height: '2px'}}>
                         <div className="progress-bar progress-bar-striped progress-bar-animated bg-primary-glow w-100"></div>
                    </div>
                </div>
            )}

            {!currentText && !isLoading ? (
                <div className="text-center p-5 border border-secondary border-opacity-10 rounded-4 bg-dark bg-opacity-10 my-3">
                    <i className="bi bi-cpu mb-3 text-primary-glow opacity-50 d-block" style={{ fontSize: '2.5rem' }}></i>
                    <h5 className="fw-bold mb-2">Initialize Archival Node</h5>
                    <p className="text-white-50 small mb-4 mx-auto" style={{maxWidth: '350px'}}>
                        Synthesize discovery data from previous steps into a verifiable research node.
                    </p>
                    <button 
                        className={`btn ${isLoading ? 'btn-secondary' : 'btn-primary'} px-5 py-2 rounded-pill shadow-sm d-flex align-items-center justify-content-center mx-auto`} 
                        onClick={() => onGenerate()} 
                        disabled={isLoading}
                    >
                        {isLoading ? (
                            <>
                                <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                                INITIALIZING ARCHIVE...
                            </>
                        ) : (
                            <>
                                <i className="bi bi-stars me-2"></i> 
                                SYNTHESIZE NODE
                            </>
                        )}
                    </button>
                </div>
            ) : (
                <>
                    {!isLoading && !isEditing && currentText && (
                        <div className="d-flex justify-content-end gap-2 mb-3">
                            <button className="btn btn-xs btn-outline-secondary py-1" onClick={() => setShowRegenInput(p => !p)}>
                                <i className="bi bi-arrow-clockwise me-1"></i> Regenerate
                            </button>
                            <button className="btn btn-xs btn-outline-secondary py-1" onClick={() => { setIsEditing(true); setEditText(savedOutput); }}>
                                <i className="bi bi-pencil-square me-1"></i> Edit
                            </button>
                        </div>
                    )}

                    {showRegenInput && (
                        <div className="input-group input-group-sm mb-4">
                            <input 
                                type="text" 
                                className="form-control bg-dark text-white border-secondary" 
                                placeholder="Feedback for refinement..." 
                                value={regenFeedback} 
                                onChange={e => setRegenFeedback(e.target.value)} 
                            />
                            <button className="btn btn-primary" onClick={handleRegenerate} disabled={isLoading}>Refine</button>
                        </div>
                    )}

                    {isEditing ? (
                        <div className="edit-view card bg-black border-secondary p-3">
                            <textarea 
                                className="form-control font-monospace bg-dark text-white border-secondary mb-3" 
                                style={{ minHeight: '300px' }} 
                                value={editText} 
                                onChange={(e) => setEditText(e.target.value)} 
                            />
                            <div className="d-flex gap-2 justify-content-end">
                                <button className="btn btn-sm btn-outline-secondary" onClick={() => setIsEditing(false)}>Cancel</button>
                                <button className="btn btn-sm btn-success px-3" onClick={handleSave}>Save Node</button>
                            </div>
                        </div>
                    ) : (
                        <div className={`rendered-view ${isLoading && !currentText ? 'opacity-25' : isLoading ? 'opacity-75' : ''}`}>
                            {isJsonStep && !isLoading ? renderJsonContent(currentText) : <div className="generated-text-container" dangerouslySetInnerHTML={{ __html: renderedHtml }} />}

                            {isLoading && currentText && (
                                <div className="mt-4 pt-3 border-top border-secondary border-opacity-10 d-flex flex-column align-items-center justify-content-center gap-2">
                                    <div className="d-flex align-items-center">
                                         <div className="spinner-grow spinner-grow-sm text-primary-glow me-2" role="status"></div>
                                         <span className="small text-primary-glow font-monospace text-uppercase ls-1">Decoding Archive Stream...</span>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </>
            )}

            <style>{`
                .archive-status-line {
                    background: rgba(0, 242, 254, 0.05);
                    border: 1px solid rgba(0, 242, 254, 0.1);
                }
                .btn-xs { padding: 0.25rem 0.5rem; font-size: 0.75rem; }
            `}</style>
        </div>
    );
};

import React, { useRef, useEffect } from 'react';

export const AgenticAnalysisView = ({ agenticRun, title = "AI Agents at Work...", subtitle = "A multi-agent workflow is running." }) => {
    const logsEndRef = useRef(null);

    useEffect(() => {
        logsEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [agenticRun.logs]);

    return (
        <div className="agentic-analysis-view border border-secondary border-opacity-10 rounded-3 bg-black bg-opacity-20 p-4 mb-4">
            <div className="text-center mb-4">
                <h5 className="fw-bold mb-1 text-primary-glow">{title}</h5>
