export const FinalPublicationView = ({ publicationText, onRegenerate, showRegenerate = true }) => {
    const { addToast } = useToast();
    const { activeExperiment } = useExperiment();
    const contentRef = useRef<HTMLDivElement>(null);

    // Determine the nature of the data source for the disclaimer
    const step6Output = activeExperiment.stepData[6]?.summary || activeExperiment.stepData[6]?.output || '';
    const isManualData = step6Output.toLowerCase().includes('manually entered');

    // Construct the Disclaimer Blocks
    const disclaimerHTML = `
        <div style="background-color: #fff3cd; color: #856404; padding: 20px; border: 1px solid #ffeeba; border-radius: 8px; margin-bottom: 30px; font-family: sans-serif; line-height: 1.5;">
            <div style="font-weight: bold; margin-bottom: 8px; text-transform: uppercase; font-size: 0.9em;">
                ⚠️ AI Generation Disclaimer
            </div>
            <div style="font-size: 0.95em;">
                This research paper was generated by an Artificial Intelligence system. Consequently, it may contain errors, hallucinations, or inaccuracies.
                ${!isManualData ? '<br/><br/><strong>NOTE:</strong> No physical experiments were performed. The results presented here are derived from AI-generated data, code-based simulations, or synthetic datasets. This document is intended strictly for theoretical investigation and ideation.' : ''}
            </div>
        </div>
        <hr style="margin-bottom: 30px; border-top: 1px solid #444;" />
    `;

    const disclaimerText = `⚠️ AI GENERATION DISCLAIMER: This research paper was generated by an Artificial Intelligence system. Consequently, it may contain errors, hallucinations, or inaccuracies.\n${!isManualData ? 'NOTE: No physical experiments were performed. The results presented here are derived from AI-generated data, code-based simulations, or synthetic datasets. This document is intended strictly for theoretical investigation and ideation.\n' : ''}\n---\n\n`;

    useEffect(() => {
        const renderContent = async () => {
            if (!publicationText || !contentRef.current) return;

            contentRef.current.innerHTML = `<div class="text-center p-3"><div class="spinner-border spinner-border-sm"></div> Rendering document...</div>`;

            let processedText = publicationText;
            const chartPlaceholders = publicationText.match(/\[CHART_(\d+):([\s\S]*?)\]/g) || [];

            if (chartPlaceholders.length > 0) {
                const analysisJson = activeExperiment.stepData[7]?.output || '{}';
                let analysisData: any = {};
                try {
                    analysisData = JSON.parse(analysisJson.replace(/```json/g, '').replace(/```/g, ''));
                } catch(e) {
                    console.error("Failed to parse analysis JSON for charts", e);
                }
                const charts = analysisData.charts || []; 

                for (const placeholder of chartPlaceholders) {
                    const match = placeholder.match(/\[CHART_(\d+):([\s\S]*?)\]/);
                    if (!match) continue;

                    const chartIndex = parseInt(match[1], 10) - 1;
                    const caption = match[2];

                    if (charts[chartIndex] && charts[chartIndex].imageData) {
                        const dataUrl = `data:image/png;base64,${charts[chartIndex].imageData}`;
                        const imgTag = `<figure style="text-align: center;"><img src="${dataUrl}" alt="${caption}" style="max-width: 80%; height: auto; display: block; margin: 1rem auto; border: 1px solid #444;" /><figcaption style="font-size: 0.9em; color: #aaa; margin-top: 0.5em;">${caption}</figcaption></figure>`;
                        processedText = processedText.replace(placeholder, imgTag);
                    } else {
                         processedText = processedText.replace(placeholder, `<p class="text-warning small border border-warning p-2 rounded">[Chart placeholder found but data unavailable for Index ${chartIndex + 1}]</p>`);
                    }
                }
            }

            // Render Markdown and prepend the disclaimer
            if (contentRef.current) {
                const renderedBody = renderMarkdown(processedText);
                contentRef.current.innerHTML = disclaimerHTML + renderedBody;
            }
        };

        renderContent();
    }, [publicationText, activeExperiment, disclaimerHTML]);


    const handleDownload = (format: 'md' | 'doc' | 'pdf' | 'txt') => {
        const { title, id } = activeExperiment;
        if (format === 'pdf') {
            addToast("Preparing a print-friendly view...", "info");
            const printContent = contentRef.current?.innerHTML || '';
            const printWindow = window.open('', '_blank');
            if (!printWindow) {
                addToast("Could not open a new window. Please check your browser's pop-up blocker.", 'warning');
                return;
            }
            printWindow.document.write(`
                <!DOCTYPE html>
                <html>
                <head>
                    <title>Print - ${title}</title>
                    <style>
                        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; line-height: 1.6; color: #333; max-width: 800px; margin: 20px auto; }
                        h1, h2, h3, h4 { color: #000; }
                        pre, code { background-color: #f4f4f4; padding: 2px 4px; border-radius: 4px; font-family: monospace; }
                        pre { padding: 1em; overflow: auto; }
                        img { max-width: 100%; height: auto; }
                        figure { page-break-inside: avoid; }
                    </style>
                </head>
                <body>
                    ${printContent}
                    <script>
                        setTimeout(() => {
                            window.print();
                            window.close();
                        }, 500);
                    </script>
                </body>
                </html>
            `);
            printWindow.document.close();
            return;
        }

        let blob;
        let filename = `${title.replace(/ /g, '_')}_${id}`;

        if (format === 'doc') {
            // For Word, we use the HTML content with the disclaimer already injected
            const htmlContent = `
                <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
                <head><meta charset='utf-8'><title>${title}</title></head>
                <body>${contentRef.current?.innerHTML}</body>
                </html>`;
            blob = new Blob(['\ufeff', htmlContent], { type: 'application/msword' });
            filename += '.doc';
        } else {
            // For Text/Markdown, we prepend the plain text disclaimer
            const rawContent = format === 'md' ? publicationText : (contentRef.current?.innerText || publicationText);
            const contentWithDisclaimer = disclaimerText + rawContent;
            blob = new Blob([contentWithDisclaimer], { type: 'text/plain' });
            filename += `.${format}`;
        }

        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        link.click();
        URL.revokeObjectURL(url);
    };

    return (
        <div>
            <div className="d-flex justify-content-end mb-2">
                {showRegenerate && 
                    <button className="btn btn-sm btn-outline-secondary me-auto" onClick={onRegenerate}>
                        <i className="bi bi-arrow-clockwise me-1"></i> Regenerate with Agents
                    </button>
                }
                <div className="btn-group">
                    <button type="button" className="btn btn-sm btn-secondary dropdown-toggle" data-bs-toggle="dropdown">
                       <i className="bi bi-download me-1"></i> Download As
                    </button>
                    <ul className="dropdown-menu dropdown-menu-end">
                        <li><a className="dropdown-item" href="#" onClick={() => handleDownload('md')}>Markdown (.md)</a></li>
                        <li><a className="dropdown-item" href="#" onClick={() => handleDownload('txt')}>Plain Text (.txt)</a></li>
                        <li><a className="dropdown-item" href="#" onClick={() => handleDownload('doc')}>Word Document (.doc)</a></li>
                         <li><a className="dropdown-item" href="#" onClick={() => handleDownload('pdf')}>PDF (Print)</a></li>
                    </ul>
                </div>
            </div>
            <div ref={contentRef} className="generated-text-container" style={{ minHeight: '50vh' }}>
                {/* Content is rendered here via useEffect */}
            </div>
        </div>
    );
};

export const PublicationExporter = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();
    const [agenticRun, setAgenticRun] = useState({
        status: 'idle',
        iterations: 0,
        maxIterations: 5,
        logs: [],
    });

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    const stepData = activeExperiment.stepData[10] || {};

    const performAgenticDraft = async () => {
        if (!isAuthenticated || agenticRun.status === 'running') return;
        setAgenticRun({ status: 'running', logs: [], iterations: 0, maxIterations: 5 });

        try {
            const finalDoc = await runPublicationAgent({
                experiment: activeExperiment,
                updateLog: (agent, message) => {
                    if (isMounted.current) {
                        setAgenticRun(prev => ({
                            ...prev,
                            logs: [...prev.logs, { agent, message }],
                            iterations: prev.iterations + 1
                        }));
                    }
                }
            });

            if (!isMounted.current) return;

            const finalStepData = { ...stepData, output: finalDoc };
            await updateExperiment({ ...activeExperiment, stepData: { ...activeExperiment.stepData, 10: finalStepData } });
            setAgenticRun(prev => ({ ...prev, status: 'success' }));
            addToast("Publication draft generated.", "success");
        } catch (error) {
             if (!isMounted.current) return;
             const errorMessage = parseGeminiError(error, "Draft generation failed.");
             addToast(errorMessage, 'danger');
             setAgenticRun(prev => ({
                ...prev,
                status: 'failed',
                logs: [...prev.logs, { agent: 'System', message: `ERROR: ${errorMessage}` }]
             }));
        }
    };

    if (stepData.output) {
        return (
            <FinalPublicationView 
                publicationText={stepData.output} 
                onRegenerate={performAgenticDraft} 
                showRegenerate={true}
            />
        );
    }

    return (
        <div className="publication-exporter-container">
            <div className="text-center p-5 border border-secondary border-opacity-10 rounded-4 bg-dark bg-opacity-10 my-3">
                    <i className="bi bi-file-earmark-text mb-3 text-primary-glow opacity-50 d-block" style={{ fontSize: '2.5rem' }}></i>
                <h5 className="fw-bold mb-2">Draft Publication</h5>
                <p className="text-white-50 small mb-4 mx-auto" style={{maxWidth: '350px'}}>
                    Synthesize all research nodes into a comprehensive scientific manuscript.
                </p>
                <button
                    className="btn btn-primary px-5 py-2 rounded-pill shadow-sm"
                    onClick={performAgenticDraft}
                    disabled={agenticRun.status === 'running'}
                >
                    {agenticRun.status === 'running' ? 'Drafting...' : 'Start Agentic Drafter'}
                </button>
            </div>
                {(agenticRun.logs.length > 0 || agenticRun.status === 'running') && (
                <div className="mt-4 border-top border-secondary border-opacity-10 pt-4">
                    <AgenticAnalysisView
                        agenticRun={agenticRun}
                        title="Publication Agent Progress"
                        subtitle="Synthesizing final manuscript from experiment data."
                    />
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Experiment } from './config';
import { db } from './be_db';
import { testApiKey, getSafeEnvApiKey } from './services';
import { useToast } from './toast';
import { ExperimentContext } from './context/ExperimentContext';
import { ErrorBoundary } from './components/common/ErrorBoundary';

import { Header } from './components/common/Header';
import { Footer } from './components/common/Footer';
import { LandingPage } from './components/landing/LandingPage';
import { Dashboard } from './components/dashboard/Dashboard';
import { ExperimentWorkspace } from './components/workspace/ExperimentWorkspace';
import { TestRunner } from './components/testing/TestRunner';
import { LabNotebook } from './components/workspace/LabNotebook';

// --- MEMORY OPTIMIZATION HELPER ---
// Strips heavy data (CSVs, long markdown) from the dashboard list to prevent
// iOS/iPadOS browser crashes due to memory limits.
const lightenExperiment = (exp: Experiment): Experiment => {
    const lightExp = { ...exp };
    const lightStepData: { [key: number]: any } = {};

    if (exp.stepData) {
        Object.keys(exp.stepData).forEach(key => {
            const k = Number(key);
            const data = exp.stepData[k];
            lightStepData[k] = {
                ...data,
                // Truncate heavy fields for the list view
                input: data.input ? (data.input.length > 50 ? data.input.substring(0, 50) + '...' : data.input) : undefined,
                output: data.output ? (data.output.length > 50 ? data.output.substring(0, 50) + '...' : data.output) : undefined,
                // Keep summary and blockers as they are essential for UI badges
                summary: data.summary,
                blockers: data.blockers
            };
        });
    }
    lightExp.stepData = lightStepData;
    lightExp.labNotebook = ''; // Clear notebook text from list view
    return lightExp;
};

/**
 * @component App
 * The root component that manages the overall application state, routing, and global context.
 */
export const App = () => {
    const [view, setView] = useState('landing'); 
    const [experiments, setExperiments] = useState<Experiment[]>([]);
    const [activeExperiment, setActiveExperiment] = useState<Experiment | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [isLabNotebookOpen, setLabNotebookOpen] = useState(false);

    const { addToast } = useToast();
    const isInitialized = useRef(false);

    // Initial Data Load
    useEffect(() => {
        let mounted = true;

        const loadData = async () => {
            if (isInitialized.current) return;

            try {
                if (!db || !db.experiments) {
                    throw new Error("Database schema missing.");
                }

                // Load all experiments but strip heavy data immediately
                const storedExperiments = await db.experiments.orderBy('createdAt').reverse().toArray();

                if (mounted) {
                    setExperiments(storedExperiments ? storedExperiments.map(lightenExperiment) : []);
                }

                // Auto-detect environment key
                const envKey = getSafeEnvApiKey();
                if (envKey) {
                     if (mounted) setIsAuthenticated(true);
                } else {
                    console.warn("No environment API key detected.");
                }
            } catch (error) {
                console.warn("Data load warning:", error);
                if (mounted) addToast("Could not access local archives.", 'warning');
            } finally {
                if (mounted) {
                    setIsLoading(false);
                    isInitialized.current = true;
                }
            }
        };

        loadData();

        return () => { mounted = false; };
    }, [addToast]);

    // Scroll to top on view change
    useEffect(() => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }, [view]);

    // Context Methods - Wrapped in useCallback for referential stability

    const handleAuthentication = useCallback(async (type: 'promo' | 'key' | 'demo', value: string) => {
       if (getSafeEnvApiKey()) {
            setIsAuthenticated(true);
       }
    }, []);

    const createNewExperiment = useCallback(async (title: string, description: string, field: string) => {
        const newId = `exp_${Date.now()}`;
        const newExperiment: Experiment = {
            id: newId,
            title,
            description,
            field,
            currentStep: 1,
            stepData: {
                1: {
                    input: `Title: ${title}\n\nDescription: ${description}`,
                    history: [],
                    provenance: [],
                }
            },
            fineTuneSettings: {},
            createdAt: new Date().toISOString(),
            labNotebook: '',
            automationMode: null,
            status: 'active',
        };

        try {
            await db.experiments.add(newExperiment);
            // Update list with lightweight version to save memory
            setExperiments(prev => [lightenExperiment(newExperiment), ...prev]);
            // Set active with full version
            setActiveExperiment(newExperiment);
            setView('experiment');
            addToast("Project initialized.", 'success');
        } catch (error) {
            console.error("Failed to save new experiment:", error);
            addToast("Failed to create project database entry.", 'danger');
        }
    }, [addToast]);

    const importExperiment = useCallback(async (experimentData: Experiment) => {
        try {
            if (!experimentData.id || !experimentData.title || !experimentData.createdAt) {
                throw new Error("Invalid experiment file format.");
            }

            // Check for duplicate ID
            const existing = await db.experiments.get(experimentData.id);
            if (existing) {
                experimentData.id = `exp_${Date.now()}_imported`;
                experimentData.title = `${experimentData.title} (Imported)`;
            }

            await db.experiments.add(experimentData);

            // Reload list with memory optimization
            const storedExperiments = await db.experiments.orderBy('createdAt').reverse().toArray();
            setExperiments(storedExperiments.map(lightenExperiment));

            addToast(`Project imported successfully.`, 'success');
        } catch(error) {
             console.error(error);
             addToast(`Failed to import project. File may be corrupted.`, 'danger');
        }
    }, [addToast]);

    const updateExperiment = useCallback(async (updatedExperiment: Experiment): Promise<Experiment> => {
        try {
            const experimentWithTimestamp = { ...updatedExperiment, updatedAt: new Date().toISOString() };

            // 1. Save FULL data to persistent storage (IndexedDB)
            await db.experiments.put(experimentWithTimestamp);

            // 2. Update the LIST state with LIGHTWEIGHT version (Memory Protection)
            setExperiments(prev => prev.map(e => e.id === experimentWithTimestamp.id ? lightenExperiment(experimentWithTimestamp) : e));

            // 3. Update the ACTIVE state with FULL version (so user sees their data)
            if (activeExperiment?.id === experimentWithTimestamp.id) {
                setActiveExperiment(experimentWithTimestamp);
            }
            return experimentWithTimestamp;
        } catch (error) {
            console.error("Failed to update experiment:", error);
            addToast("Failed to save changes.", "danger");
            throw error;
        }
    }, [activeExperiment, addToast]);

    const deleteExperiment = useCallback(async (id: string) => {
        if (window.confirm("Are you sure you want to delete this project? This cannot be undone.")) {
            try {
                await db.experiments.delete(id);
                setExperiments(prev => {
                    const updated = prev.filter(e => e.id !== id);
                    if (activeExperiment?.id === id) {
                        setActiveExperiment(null);
                        setView(updated.length > 0 ? 'dashboard' : 'landing');
                    }
                    return updated;
                });
                addToast("Project deleted.", 'success');
            } catch (error) {
                addToast("Failed to delete project.", 'danger');
            }
        }
    }, [activeExperiment, addToast]);

    const selectExperiment = useCallback(async (id: string) => {
        setIsLoading(true); // Show loading UI while fetching heavy data
        try {
            const fullExperiment = await db.experiments.get(id);
            if (fullExperiment) {
                setActiveExperiment(fullExperiment);
                setView('experiment');
            } else {
                addToast("Error: Experiment data not found.", 'danger');
            }
        } catch (error) {
            console.error("Fetch error:", error);
            addToast("Failed to retrieve project from database.", 'danger');
        } finally {
            setIsLoading(false);
        }
    }, [addToast]);

    // Construct context value
    const contextValue = {
        experiments,
        activeExperiment,
        isAuthenticated,
        createNewExperiment,
        updateExperiment,
        deleteExperiment,
        selectExperiment,
        setActiveExperiment,
        importExperiment,
        handleAuthentication,
    };

    if (isLoading) {
        return (
            <div className="d-flex align-items-center justify-content-center vh-100 bg-dark text-white">
                <div className="text-center">
                    <div className="spinner-border text-primary-glow mb-4" role="status" style={{width: '3rem', height: '3rem'}}></div>
                    <h5 className="fw-light ls-1 text-uppercase">Initializing Hypatia...</h5>
                    <p className="text-white-50 small mt-2">Establishing secure archival link</p>
                </div>
            </div>
        );
    }

    return (
        <ErrorBoundary>
            <ExperimentContext.Provider value={contextValue}>
                <Header setView={setView} activeView={view} onToggleNotebook={() => setLabNotebookOpen(p => !p)} />
                <main className="container-fluid mt-4" style={{ minHeight: '80vh' }}>
                    {view === 'landing' && <LandingPage setView={setView} />}
                    {view === 'dashboard' && <Dashboard setView={setView} />}
                    {view === 'experiment' && activeExperiment && <ExperimentWorkspace key={activeExperiment.id} />}
                    {view === 'testing' && <TestRunner />}
                </main>
                {activeExperiment && isAuthenticated && (
                    <LabNotebook 
                        isOpen={isLabNotebookOpen} 
                        onClose={() => setLabNotebookOpen(false)}
                    />
                )}
                <Footer />
            </ExperimentContext.Provider>
        </ErrorBoundary>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { 
    parseGeminiError, 
    getStepContext, 
    getPromptForStep, 
    executeStepWorkflow, 
    callGeminiStreamWithRetry,
    generateNodeSummary
} from '../../services';
import { WORKFLOW_STEPS, RESEARCH_QUESTION_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, LITERATURE_REVIEW_SCHEMA } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';
import { InterpretationWorkspace } from '../steps/InterpretationWorkspace';
import { BlockerDisplay } from './BlockerDisplay';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();

    const [activeStep, setActiveStep] = useState(activeExperiment?.currentStep || 1);
    const [isLoading, setIsLoading] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const [streamingText, setStreamingText] = useState<string | null>(null);
    const [automationPaused, setAutomationPaused] = useState(false);
    const [reviewCountdown, setReviewCountdown] = useState<number | null>(null);

    const streamBuffer = useRef("");
    const streamInterval = useRef<any>(null);
    const isMounted = useRef(true);
    const lastAutomationTick = useRef<number>(0);
    const countdownInterval = useRef<any>(null);

    useEffect(() => {
        isMounted.current = true;
        return () => { 
            isMounted.current = false;
            if (streamInterval.current) clearInterval(streamInterval.current);
            if (countdownInterval.current) clearInterval(countdownInterval.current);
        };
    }, []);

    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading && !isVerifying) {
            setActiveStep(activeExperiment.currentStep);
            setAutomationPaused(false); 
            setReviewCountdown(null);
        }
    }, [activeExperiment?.currentStep, isLoading, isVerifying, activeStep]);

    // Countdown Timer Logic for Automation
    useEffect(() => {
        if (reviewCountdown !== null && reviewCountdown > 0) {
            if (countdownInterval.current) clearInterval(countdownInterval.current);
            countdownInterval.current = setInterval(() => {
                setReviewCountdown(prev => (prev !== null && prev > 0) ? prev - 1 : null);
            }, 1000);
        } else if (reviewCountdown === 0) {
            setReviewCountdown(null);
            if (countdownInterval.current) clearInterval(countdownInterval.current);
            handleCompleteStep();
        }
        return () => { if (countdownInterval.current) clearInterval(countdownInterval.current); };
    }, [reviewCountdown]);

    // Main Automation Loop
    useEffect(() => {
        if (!activeExperiment || !isAuthenticated || isLoading || isVerifying || automationPaused || reviewCountdown !== null) return;

        const mode = activeExperiment.automationMode;
        if (mode === 'automated' && activeStep === activeExperiment.currentStep) {
            const now = Date.now();
            // Minimum delay between autonomous actions to avoid burst 429s
            if (now - lastAutomationTick.current < 5000) return;
            lastAutomationTick.current = now;

            const stepData = (activeExperiment.stepData && activeExperiment.stepData[activeStep]) || {};
            const isAgenticStep = [2, 6, 7, 8, 9, 10].includes(activeStep);

            const hasCriticalBlockers = stepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);
            if (hasCriticalBlockers) {
                setAutomationPaused(true);
                addToast("Automation paused: Critical blockers detected.", "warning");
                return;
            }

            if (!stepData?.output && !isAgenticStep) {
                handleGenerate();
            } else if (stepData?.output && !stepData?.summary && !isAgenticStep) {
                // Initiate the 15-second review delay before completing the step
                setReviewCountdown(15);
            }
        }
    }, [activeExperiment, activeStep, isAuthenticated, isLoading, isVerifying, automationPaused, reviewCountdown, addToast]);

    const handleStepChange = useCallback((stepId: number) => {
        if (isLoading || isVerifying) return;
        setStreamingText(null);
        setActiveStep(stepId);
        setAutomationPaused(false);
        setReviewCountdown(null);
    }, [isLoading, isVerifying]);

    const handleResolveBlocker = async (blockerId: string) => {
        if (!activeExperiment) return;
        const stepData = { ...(activeExperiment.stepData || {}) };
        const currentStepData = { ...(stepData[activeStep] || {}) };
        const blockers = (currentStepData.blockers || []).map(b => 
            b.id === blockerId ? { ...b, resolved: true } : b
        );

        stepData[activeStep] = { ...currentStepData, blockers };
        await updateExperiment({ ...activeExperiment, stepData });
        addToast("Blocker mitigation logged.", "success");
    };

    const handleAnalysisFailure = useCallback(async (errorMsg: string) => {
        if (!activeExperiment) return;
        if (errorMsg.includes("DATA_QUALITY_FAILURE") || errorMsg.includes("Data Quality Check Failed")) {
            addToast(`Data quality failed: Re-routing to Acquisition for correction.`, "warning");
            const updatedStepData = { ...activeExperiment.stepData };
            updatedStepData[7] = { ...updatedStepData[7], output: undefined, summary: undefined };
            updatedStepData[6] = { ...updatedStepData[6], output: undefined, summary: undefined };
            await updateExperiment({ ...activeExperiment, currentStep: 6, stepData: updatedStepData });
            setActiveStep(6);
        } else {
             addToast(`Analysis error: ${errorMsg}`, "danger");
             if (activeExperiment.automationMode === 'automated') setAutomationPaused(true);
        }
    }, [activeExperiment, updateExperiment, addToast]);

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading || isVerifying) return;
        setStreamingText(null);
        setIsLoading(true);
        setReviewCountdown(null);
        streamBuffer.current = "";

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            const input = (activeExperiment.stepData && activeExperiment.stepData[activeStep]?.input) || '';
            const stepSettings = activeExperiment.fineTuneSettings?.[activeStep] || {};
            const { basePrompt, expectJson, config } = getPromptForStep(activeStep, input, context, stepSettings, regenerateFeedback);

            if (expectJson) {
                const schema = (activeStep === 1) ? RESEARCH_QUESTION_SCHEMA : (activeStep === 2) ? LITERATURE_REVIEW_SCHEMA : DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
                const model = activeStep === 1 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
                const output = await executeStepWorkflow(model, { contents: basePrompt, config }, context, true, schema);
                if (isMounted.current) {
                    await updateExperiment({ 
                        ...activeExperiment, 
                        stepData: { ...activeExperiment.stepData, [activeStep]: { ...(activeExperiment.stepData?.[activeStep] || {}), output } } 
                    });
                }
            } else {
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });
                if (streamInterval.current) clearInterval(streamInterval.current);
                // Throttled update to 250ms to prevent render thrashing on mobile
                streamInterval.current = setInterval(() => { if (isMounted.current) setStreamingText(streamBuffer.current); }, 250);
                for await (const chunk of stream) { streamBuffer.current += (chunk.text || ''); }
                if (streamInterval.current) { clearInterval(streamInterval.current); streamInterval.current = null; }
                if (isMounted.current) {
                    const finalOutput = streamBuffer.current;
                    setStreamingText(finalOutput);
                    await updateExperiment({
                        ...activeExperiment,
                        stepData: { ...activeExperiment.stepData, [activeStep]: { ...(activeExperiment.stepData?.[activeStep] || {}), output: finalOutput } }
                    });
                }
            }
            if (isMounted.current) addToast("Archival node synchronized.", "success");
        } catch (error) {
            if (isMounted.current) {
                addToast(parseGeminiError(error), 'danger');
                if (activeExperiment?.automationMode === 'automated') setAutomationPaused(true);
            }
        } finally {
            if (isMounted.current) setIsLoading(false);
        }
    };

    const handleCompleteStep = async (stepDataOverride?: any) => {
        if (isVerifying || !activeExperiment) return;
        setIsVerifying(true);
        setReviewCountdown(null);
        const currentStepData = { ...(activeExperiment.stepData?.[activeStep] || {}), ...stepDataOverride };
        const currentOutput = currentStepData.output || "";

        const hasCriticalBlockers = currentStepData.blockers?.some(b => b.severity === 'critical' && !b.resolved);
        if (hasCriticalBlockers) {
            addToast("Resolve critical blockers before proceeding.", "warning");
            setAutomationPaused(true);
            setIsVerifying(false);
            return;
        }

        try {
            let summary = currentStepData.summary;
            if (!summary && currentOutput.length > 50) {
                try { summary = await generateNodeSummary(currentOutput, activeExperiment.field); } catch (e) { summary = "Node verified."; }
            } else if (!summary) { summary = "Node verified."; }

            const nextStepId = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : activeStep;
            const updatedStepDataMap = { ...(activeExperiment.stepData || {}) };
            updatedStepDataMap[activeStep] = { ...currentStepData, summary };

            if (activeStep === 6) {
                const csvData = currentStepData.input || currentOutput; 
                updatedStepDataMap[7] = { ...(updatedStepDataMap[7] || {}), input: csvData, output: undefined, summary: undefined };
            }

            const updatedExp = { ...activeExperiment, stepData: updatedStepDataMap, currentStep: nextStepId };
            await updateExperiment(updatedExp);
            if (isMounted.current) {
                addToast(`Step ${activeStep} complete. Moving to Step ${nextStepId}.`, "success");
                setActiveStep(nextStepId);
            }
        } catch (error) {
            console.error("Verification error:", error);
            if (isMounted.current) addToast("Archival link unstable.", 'danger');
        } finally {
            if (isMounted.current) setIsVerifying(false);
        }
    };

    const renderStepContent = () => {
        if (!activeExperiment) return null;
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} />;
        }

        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={(data: any) => { handleCompleteStep(data); }} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={() => setReviewCountdown(15)} onAnalysisFailure={handleAnalysisFailure} />;
        if (activeStep === 8) return <InterpretationWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 10) return <PublicationExporter />;

        return (
            <div className="discovery-view">
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    if (!activeExperiment) return null;

    const currentStepData = activeExperiment.stepData?.[activeStep];
    const hasOutput = currentStepData?.output;
    const hasCriticalBlocker = currentStepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);

    return (
        <div className="workspace-container">
            <aside className="sidebar-nav">
                <div className="card shadow-sm border-secondary border-opacity-10 overflow-hidden">
                    <div className="card-header fw-bold bg-dark py-3 small ls-1 text-uppercase">
                        <i className="bi bi-cpu-fill text-primary-glow me-2"></i> Timeline
                    </div>
                    <ul className="list-group list-group-flush">
                        {WORKFLOW_STEPS.map(step => (
                            <li
                                key={step.id}
                                className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                onClick={() => handleStepChange(step.id)}
                                style={{ cursor: (step.id <= activeExperiment.currentStep && !isLoading && !isVerifying) ? 'pointer' : 'default' }}
                            >
                                <div className="d-flex align-items-center gap-2 flex-grow-1">
                                    <span className="small">{step.id}. {step.title}</span>
                                    {((isLoading || isVerifying) && activeStep === step.id) && (
                                        <div className="spinner-border spinner-border-sm text-primary-glow" role="status"></div>
                                    )}
                                </div>
                                {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                            </li>
                        ))}
                    </ul>
                </div>
            </aside>

            <main className="content-area">
                <div className="card shadow-sm border-secondary border-opacity-25 position-relative overflow-hidden">
                    {(isLoading || isVerifying || reviewCountdown !== null) && (
                        <div className="progress rounded-0" style={{ height: '4px', position: 'absolute', top: 0, left: 0, right: 0, zIndex: 100 }}>
                            <div className={`progress-bar progress-bar-striped progress-bar-animated ${reviewCountdown !== null ? 'bg-info' : 'bg-primary-glow'}`} 
                                 style={{ width: reviewCountdown !== null ? `${(reviewCountdown / 15) * 100}%` : '100%' }}></div>
                        </div>
                    )}
                    <div className="card-body p-4" style={{ minHeight: '60vh' }}>
                        <div className="d-flex justify-content-between align-items-start mb-4">
                            <div>
                                <div className="badge bg-primary bg-opacity-10 text-primary-glow mb-2">Step {activeStep}</div>
                                <h4 className="fw-bold mb-1">{WORKFLOW_STEPS[activeStep - 1]?.title || 'Node Overview'}</h4>
                                <p className="text-white-50 small mb-0">{WORKFLOW_STEPS[activeStep - 1]?.description}</p>
                            </div>
                            <div className="d-flex flex-column align-items-end">
                                {activeExperiment.automationMode === 'automated' && (
                                    <>
                                        <span className={`badge ${automationPaused ? 'bg-warning text-dark' : 'bg-primary'} px-3 py-2 rounded-pill shadow-sm mb-2`}>
                                            <i className={`bi ${automationPaused ? 'bi-pause-circle-fill' : 'bi-cpu-fill'} me-1`}></i> 
                                            {automationPaused ? 'AUTOMATION PAUSED' : 'AGENTIC OVERRIDE ACTIVE'}
                                        </span>
                                        {automationPaused && (
                                            <button className="btn btn-xs btn-outline-warning" onClick={() => setAutomationPaused(false)}>
                                                <i className="bi bi-play-fill me-1"></i> RESUME
                                            </button>
                                        )}
                                        {reviewCountdown !== null && (
                                            <div className="text-info small fw-bold mt-1">
                                                <i className="bi bi-eye-fill me-1"></i> AUTO-ADVANCING IN {reviewCountdown}s...
                                                <button className="btn btn-link btn-xs text-info p-0 ms-2" onClick={() => handleCompleteStep()}>SKIP</button>
                                            </div>
                                        )}
                                    </>
                                )}
                            </div>
                        </div>
                        <hr className="border-secondary opacity-10 mb-4" />

                        {currentStepData?.blockers && (
                            <BlockerDisplay 
                                blockers={currentStepData.blockers} 
                                onResolve={handleResolveBlocker} 
                            />
                        )}

                        {renderStepContent()}
                    </div>

                    {activeStep <= WORKFLOW_STEPS.length && (
                        <div className="card-footer d-flex justify-content-between align-items-center p-3 bg-dark bg-opacity-25 border-top border-secondary border-opacity-10">
                            <button className="btn btn-sm btn-outline-secondary" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Tuning
                            </button>
                            <button 
                                className={`btn btn-${hasCriticalBlocker ? 'outline-danger' : 'success'} px-4 shadow-sm`} 
                                onClick={() => handleCompleteStep()} 
                                disabled={isVerifying || !hasOutput || hasCriticalBlocker}
                            >
                                {isVerifying ? (
                                    <span className="spinner-border spinner-border-sm me-2"></span>
                                ) : (
                                    <i className={`bi ${hasCriticalBlocker ? 'bi-lock-fill' : (hasOutput ? 'bi-check-circle-fill' : 'bi-lock-fill')} me-2`}></i> 
                                )}
                                {hasCriticalBlocker ? 'PROTOCOL BLOCKED' : (activeStep === 10 ? "Finish Project" : "Verify Node & Continue")}
                            </button>
                        </div>
                    )}
                </div>
            </main>

            {fineTuneModalOpen && (
                <FineTuneModal stepId={activeStep} onClose={() => setFineTuneModalOpen(false)} />
            )}
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useExperiment } from '../../services';
import { useToast } from '../../toast';
import { 
    parseGeminiError, 
    getStepContext, 
    getPromptForStep, 
    executeStepWorkflow, 
    callGeminiStreamWithRetry,
    generateNodeSummary
} from '../../services';
import { WORKFLOW_STEPS, RESEARCH_QUESTION_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, LITERATURE_REVIEW_SCHEMA } from '../../config';

import { ExperimentRunner } from '../steps/runner/ExperimentRunner';
import { DataAnalysisWorkspace } from '../steps/DataAnalysisWorkspace';
import { PublicationExporter } from '../steps/PublicationExporter';
import { EditableStepInput } from '../steps/EditableStepInput';
import { GeneratedOutput } from '../common/GeneratedOutput';
import { ProjectCompletionView } from './ProjectCompletionView';
import { AutomationModeSelector } from './AutomationModeSelector';
import { FineTuneModal } from './FineTuneModal';
import { LiteratureReviewWorkspace } from '../steps/LiteratureReviewWorkspace';
import { PeerReviewWorkspace } from '../steps/PeerReviewWorkspace';
import { InterpretationWorkspace } from '../steps/InterpretationWorkspace';
import { BlockerDisplay } from './BlockerDisplay';

export const ExperimentWorkspace = () => {
    const { activeExperiment, updateExperiment, isAuthenticated } = useExperiment();
    const { addToast } = useToast();

    const [activeStep, setActiveStep] = useState(activeExperiment?.currentStep || 1);
    const [isLoading, setIsLoading] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);
    const [fineTuneModalOpen, setFineTuneModalOpen] = useState(false);
    const [streamingText, setStreamingText] = useState<string | null>(null);
    const [automationPaused, setAutomationPaused] = useState(false);
    const [reviewCountdown, setReviewCountdown] = useState<number | null>(null);

    // Mobile Responsive State
    const [isSidebarExpanded, setIsSidebarExpanded] = useState(true);
    const [isMobile, setIsMobile] = useState(false);

    const streamBuffer = useRef("");
    const streamInterval = useRef<any>(null);
    const isMounted = useRef(true);
    const lastAutomationTick = useRef<number>(0);
    const countdownInterval = useRef<any>(null);

    useEffect(() => {
        isMounted.current = true;
        const checkMobile = () => {
            const mobile = window.innerWidth < 992;
            setIsMobile(mobile);
            // Default to collapsed on mobile, expanded on desktop
            if (mobile) {
                setIsSidebarExpanded(false);
            } else {
                setIsSidebarExpanded(true);
            }
        };
        checkMobile();
        window.addEventListener('resize', checkMobile);

        return () => { 
            isMounted.current = false;
            window.removeEventListener('resize', checkMobile);
            if (streamInterval.current) clearInterval(streamInterval.current);
            if (countdownInterval.current) clearInterval(countdownInterval.current);
        };
    }, []);

    useEffect(() => {
        if (activeExperiment && activeExperiment.currentStep !== activeStep && !isLoading && !isVerifying) {
            setActiveStep(activeExperiment.currentStep);
            setAutomationPaused(false); 
            setReviewCountdown(null);
        }
    }, [activeExperiment?.currentStep, isLoading, isVerifying, activeStep]);

    // Countdown Timer Logic for Automation
    useEffect(() => {
        if (reviewCountdown !== null && reviewCountdown > 0) {
            if (countdownInterval.current) clearInterval(countdownInterval.current);
            countdownInterval.current = setInterval(() => {
                setReviewCountdown(prev => (prev !== null && prev > 0) ? prev - 1 : null);
            }, 1000);
        } else if (reviewCountdown === 0) {
            setReviewCountdown(null);
            if (countdownInterval.current) clearInterval(countdownInterval.current);
            handleCompleteStep();
        }
        return () => { if (countdownInterval.current) clearInterval(countdownInterval.current); };
    }, [reviewCountdown]);

    // Main Automation Loop
    useEffect(() => {
        if (!activeExperiment || !isAuthenticated || isLoading || isVerifying || automationPaused || reviewCountdown !== null) return;

        const mode = activeExperiment.automationMode;
        if (mode === 'automated' && activeStep === activeExperiment.currentStep) {
            const now = Date.now();
            // Minimum delay between autonomous actions to avoid burst 429s
            if (now - lastAutomationTick.current < 5000) return;
            lastAutomationTick.current = now;

            const stepData = (activeExperiment.stepData && activeExperiment.stepData[activeStep]) || {};
            const isAgenticStep = [2, 6, 7, 8, 9, 10].includes(activeStep);

            const hasCriticalBlockers = stepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);
            if (hasCriticalBlockers) {
                setAutomationPaused(true);
                addToast("Automation paused: Critical blockers detected.", "warning");
                return;
            }

            if (!stepData?.output && !isAgenticStep) {
                handleGenerate();
            } else if (stepData?.output && !stepData?.summary && !isAgenticStep) {
                // Initiate the 15-second review delay before completing the step
                setReviewCountdown(15);
            }
        }
    }, [activeExperiment, activeStep, isAuthenticated, isLoading, isVerifying, automationPaused, reviewCountdown, addToast]);

    const handleStepChange = useCallback((stepId: number) => {
        if (isLoading || isVerifying) return;
        setStreamingText(null);
        setActiveStep(stepId);
        setAutomationPaused(false);
        setReviewCountdown(null);
        // On mobile, collapse sidebar after selection to show content
        if (isMobile) setIsSidebarExpanded(false);
    }, [isLoading, isVerifying, isMobile]);

    const handleResolveBlocker = async (blockerId: string) => {
        if (!activeExperiment) return;
        const stepData = { ...(activeExperiment.stepData || {}) };
        const currentStepData = { ...(stepData[activeStep] || {}) };
        const blockers = (currentStepData.blockers || []).map(b => 
            b.id === blockerId ? { ...b, resolved: true } : b
        );

        stepData[activeStep] = { ...currentStepData, blockers };
        await updateExperiment({ ...activeExperiment, stepData });
        addToast("Blocker mitigation logged.", "success");
    };

    const handleAnalysisFailure = useCallback(async (errorMsg: string) => {
        if (!activeExperiment) return;
        if (errorMsg.includes("DATA_QUALITY_FAILURE") || errorMsg.includes("Data Quality Check Failed")) {
            addToast(`Data quality failed: Re-routing to Acquisition for correction.`, "warning");
            const updatedStepData = { ...activeExperiment.stepData };
            updatedStepData[7] = { ...updatedStepData[7], output: undefined, summary: undefined };
            updatedStepData[6] = { ...updatedStepData[6], output: undefined, summary: undefined };
            await updateExperiment({ ...activeExperiment, currentStep: 6, stepData: updatedStepData });
            setActiveStep(6);
        } else {
             addToast(`Analysis error: ${errorMsg}`, "danger");
             if (activeExperiment.automationMode === 'automated') setAutomationPaused(true);
        }
    }, [activeExperiment, updateExperiment, addToast]);

    const handleGenerate = async (regenerateFeedback = '') => {
        if (!isAuthenticated || isLoading || isVerifying) return;
        setStreamingText(null);
        setIsLoading(true);
        setReviewCountdown(null);
        streamBuffer.current = "";

        try {
            const context = await getStepContext(activeExperiment, activeStep);
            const input = (activeExperiment.stepData && activeExperiment.stepData[activeStep]?.input) || '';
            const stepSettings = activeExperiment.fineTuneSettings?.[activeStep] || {};
            const { basePrompt, expectJson, config } = getPromptForStep(activeStep, input, context, stepSettings, regenerateFeedback);

            if (expectJson) {
                const schema = (activeStep === 1) ? RESEARCH_QUESTION_SCHEMA : (activeStep === 2) ? LITERATURE_REVIEW_SCHEMA : DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA;
                const model = activeStep === 1 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
                const output = await executeStepWorkflow(model, { contents: basePrompt, config }, context, true, schema);
                if (isMounted.current) {
                    await updateExperiment({ 
                        ...activeExperiment, 
                        stepData: { ...activeExperiment.stepData, [activeStep]: { ...(activeExperiment.stepData?.[activeStep] || {}), output } } 
                    });
                }
            } else {
                const stream = await callGeminiStreamWithRetry('gemini-3-flash-preview', { contents: basePrompt, config });
                if (streamInterval.current) clearInterval(streamInterval.current);
                // Throttled update to 250ms to prevent render thrashing on mobile
                streamInterval.current = setInterval(() => { if (isMounted.current) setStreamingText(streamBuffer.current); }, 250);
                for await (const chunk of stream) { streamBuffer.current += (chunk.text || ''); }
                if (streamInterval.current) { clearInterval(streamInterval.current); streamInterval.current = null; }
                if (isMounted.current) {
                    const finalOutput = streamBuffer.current;
                    setStreamingText(finalOutput);
                    await updateExperiment({
                        ...activeExperiment,
                        stepData: { ...activeExperiment.stepData, [activeStep]: { ...(activeExperiment.stepData?.[activeStep] || {}), output: finalOutput } }
                    });
                }
            }
            if (isMounted.current) addToast("Archival node synchronized.", "success");
        } catch (error) {
            if (isMounted.current) {
                addToast(parseGeminiError(error), 'danger');
                if (activeExperiment?.automationMode === 'automated') setAutomationPaused(true);
            }
        } finally {
            if (isMounted.current) setIsLoading(false);
        }
    };

    const handleCompleteStep = async (stepDataOverride?: any) => {
        if (isVerifying || !activeExperiment) return;
        setIsVerifying(true);
        setReviewCountdown(null);
        const currentStepData = { ...(activeExperiment.stepData?.[activeStep] || {}), ...stepDataOverride };
        const currentOutput = currentStepData.output || "";

        const hasCriticalBlockers = currentStepData.blockers?.some(b => b.severity === 'critical' && !b.resolved);
        if (hasCriticalBlockers) {
            addToast("Resolve critical blockers before proceeding.", "warning");
            setAutomationPaused(true);
            setIsVerifying(false);
            return;
        }

        try {
            let summary = currentStepData.summary;
            if (!summary && currentOutput.length > 50) {
                try { summary = await generateNodeSummary(currentOutput, activeExperiment.field); } catch (e) { summary = "Node verified."; }
            } else if (!summary) { summary = "Node verified."; }

            const nextStepId = activeStep < WORKFLOW_STEPS.length ? activeStep + 1 : activeStep;
            const updatedStepDataMap = { ...(activeExperiment.stepData || {}) };
            updatedStepDataMap[activeStep] = { ...currentStepData, summary };

            if (activeStep === 6) {
                const csvData = currentStepData.input || currentOutput; 
                updatedStepDataMap[7] = { ...(updatedStepDataMap[7] || {}), input: csvData, output: undefined, summary: undefined };
            }

            const updatedExp = { ...activeExperiment, stepData: updatedStepDataMap, currentStep: nextStepId };
            await updateExperiment(updatedExp);
            if (isMounted.current) {
                addToast(`Step ${activeStep} complete. Moving to Step ${nextStepId}.`, "success");
                setActiveStep(nextStepId);
            }
        } catch (error) {
            console.error("Verification error:", error);
            if (isMounted.current) addToast("Archival link unstable.", 'danger');
        } finally {
            if (isMounted.current) setIsVerifying(false);
        }
    };

    const renderStepContent = () => {
        if (!activeExperiment) return null;
        if (activeStep > WORKFLOW_STEPS.length) return <ProjectCompletionView />;
        if (activeExperiment.currentStep === 2 && activeExperiment.automationMode === null) {
            return <AutomationModeSelector onSelect={(mode) => updateExperiment({...activeExperiment, automationMode: mode})} />;
        }

        if (activeStep === 2) return <LiteratureReviewWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 6) return <ExperimentRunner onStepComplete={(data: any) => { handleCompleteStep(data); }} />;
        if (activeStep === 7) return <DataAnalysisWorkspace onStepComplete={() => setReviewCountdown(15)} onAnalysisFailure={handleAnalysisFailure} />;
        if (activeStep === 8) return <InterpretationWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 9) return <PeerReviewWorkspace onStepComplete={() => setReviewCountdown(15)} />;
        if (activeStep === 10) return <PublicationExporter />;

        return (
            <div className="discovery-view">
                {activeStep === 1 && <EditableStepInput stepId={1} />}
                <GeneratedOutput
                    key={`${activeExperiment.id}-${activeStep}`}
                    stepId={activeStep}
                    onGenerate={handleGenerate}
                    isLoading={isLoading}
                    streamingText={streamingText}
                />
            </div>
        );
    };

    if (!activeExperiment) return null;

    const currentStepData = activeExperiment.stepData?.[activeStep];
    const hasOutput = currentStepData?.output;
    const hasCriticalBlocker = currentStepData?.blockers?.some(b => b.severity === 'critical' && !b.resolved);

    return (
        <div className="workspace-container">
            <aside className="sidebar-nav">
                <div className="card shadow-sm border-secondary border-opacity-10 overflow-hidden">
                    <div 
                        className="card-header fw-bold bg-dark py-3 small ls-1 text-uppercase d-flex justify-content-between align-items-center"
                        onClick={() => setIsSidebarExpanded(!isSidebarExpanded)}
                        style={{ cursor: 'pointer' }}
                    >
                        <span><i className="bi bi-cpu-fill text-primary-glow me-2"></i> Timeline</span>
                        {isMobile && (
                            <i className={`bi bi-chevron-${isSidebarExpanded ? 'up' : 'down'}`}></i>
                        )}
                    </div>
                    {isSidebarExpanded && (
                        <ul className="list-group list-group-flush">
                            {WORKFLOW_STEPS.map(step => (
                                <li
                                    key={step.id}
                                    className={`list-group-item list-group-item-action d-flex justify-content-between align-items-center py-3 ${activeStep === step.id ? 'active' : ''} ${step.id > activeExperiment.currentStep ? 'disabled' : ''}`}
                                    onClick={() => handleStepChange(step.id)}
                                    style={{ cursor: (step.id <= activeExperiment.currentStep && !isLoading && !isVerifying) ? 'pointer' : 'default' }}
                                >
                                    <div className="d-flex align-items-center gap-2 flex-grow-1">
                                        <span className="small">{step.id}. {step.title}</span>
                                        {((isLoading || isVerifying) && activeStep === step.id) && (
                                            <div className="spinner-border spinner-border-sm text-primary-glow" role="status"></div>
                                        )}
                                    </div>
                                    {activeExperiment.currentStep > step.id && <i className="bi bi-check-circle-fill text-success"></i>}
                                </li>
                            ))}
                        </ul>
                    )}
                </div>
            </aside>

            <main className="content-area">
                <div className="card shadow-sm border-secondary border-opacity-25 position-relative overflow-hidden">
                    {(isLoading || isVerifying || reviewCountdown !== null) && (
                        <div className="progress rounded-0" style={{ height: '4px', position: 'absolute', top: 0, left: 0, right: 0, zIndex: 100 }}>
                            <div className={`progress-bar progress-bar-striped progress-bar-animated ${reviewCountdown !== null ? 'bg-info' : 'bg-primary-glow'}`} 
                                 style={{ width: reviewCountdown !== null ? `${(reviewCountdown / 15) * 100}%` : '100%' }}></div>
                        </div>
                    )}
                    <div className="card-body p-4" style={{ minHeight: '60vh' }}>
                        <div className="d-flex justify-content-between align-items-start mb-4">
                            <div>
                                <div className="badge bg-primary bg-opacity-10 text-primary-glow mb-2">Step {activeStep}</div>
                                <h4 className="fw-bold mb-1">{WORKFLOW_STEPS[activeStep - 1]?.title || 'Node Overview'}</h4>
                                <p className="text-white-50 small mb-0">{WORKFLOW_STEPS[activeStep - 1]?.description}</p>
                            </div>
                            <div className="d-flex flex-column align-items-end">
                                {activeExperiment.automationMode === 'automated' && (
                                    <>
                                        <span className={`badge ${automationPaused ? 'bg-warning text-dark' : 'bg-primary'} px-3 py-2 rounded-pill shadow-sm mb-2`}>
                                            <i className={`bi ${automationPaused ? 'bi-pause-circle-fill' : 'bi-cpu-fill'} me-1`}></i> 
                                            {automationPaused ? 'PAUSED' : 'AUTO'}
                                        </span>
                                        {automationPaused && (
                                            <button className="btn btn-xs btn-outline-warning" onClick={() => setAutomationPaused(false)}>
                                                RESUME
                                            </button>
                                        )}
                                        {reviewCountdown !== null && (
                                            <div className="text-info small fw-bold mt-1">
                                                Next in {reviewCountdown}s...
                                                <button className="btn btn-link btn-xs text-info p-0 ms-2" onClick={() => handleCompleteStep()}>SKIP</button>
                                            </div>
                                        )}
                                    </>
                                )}
                            </div>
                        </div>
                        <hr className="border-secondary opacity-10 mb-4" />

                        {currentStepData?.blockers && (
                            <BlockerDisplay 
                                blockers={currentStepData.blockers} 
                                onResolve={handleResolveBlocker} 
                            />
                        )}

                        {renderStepContent()}
                    </div>

                    {activeStep <= WORKFLOW_STEPS.length && (
                        <div className="card-footer d-flex flex-column flex-md-row justify-content-between align-items-center p-3 bg-dark bg-opacity-25 border-top border-secondary border-opacity-10 gap-3">
                            <button className="btn btn-sm btn-outline-secondary w-100 w-md-auto" onClick={() => setFineTuneModalOpen(true)}>
                                <i className="bi bi-sliders me-1"></i> Tuning
                            </button>
                            <button 
                                className={`btn btn-${hasCriticalBlocker ? 'outline-danger' : 'success'} px-4 shadow-sm w-100 w-md-auto`} 
                                onClick={() => handleCompleteStep()} 
                                disabled={isVerifying || !hasOutput || hasCriticalBlocker}
                            >
                                {isVerifying ? (
                                    <span className="spinner-border spinner-border-sm me-2"></span>
                                ) : (
                                    <i className={`bi ${hasCriticalBlocker ? 'bi-lock-fill' : (hasOutput ? 'bi-check-circle-fill' : 'bi-lock-fill')} me-2`}></i> 
                                )}
                                {hasCriticalBlocker ? 'BLOCKED' : (activeStep === 10 ? "Finish Project" : "Verify & Continue")}
                            </button>
                        </div>
                    )}
                </div>
            </main>

            {fineTuneModalOpen && (
                <FineTuneModal stepId={activeStep} onClose={() => setFineTuneModalOpen(false)} />
            )}
        </div>
    );
};

