                    width: 400px;
                    max-width: 100%;
                    height: 100%;
                    background: var(--bg-dark);
                    border-left: 1px solid var(--border-color);
                    display: flex;
                    flex-direction: column;
                    animation: slideInRight 0.3s ease-out;
                    box-shadow: -10px 0 30px rgba(0,0,0,0.5);
