import React, { useState, useEffect, useMemo } from 'react';
import { renderMarkdown } from '../../utils/markdownRenderer';
import { useExperiment, extractJson } from '../../services';
import { useToast } from '../../toast';
import { UniquenessMeter } from './UniquenessMeter';
import { DataAnalysisView } from './DataAnalysisView';

interface GeneratedOutputProps {
    stepId: number;
    onGenerate: (feedback?: string) => Promise<void>;
    isLoading: boolean;
    statusMessage?: string;
    streamingText?: string | null;
}

export const GeneratedOutput: React.FC<GeneratedOutputProps> = ({ 
    stepId, 
    onGenerate, 
    isLoading, 
    statusMessage,
    streamingText 
}) => {
    const { activeExperiment, updateExperiment } = useExperiment();
    const { addToast } = useToast();

    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState('');
    const [showRegenInput, setShowRegenInput] = useState(false);
    const [regenFeedback, setRegenFeedback] = useState('');
    const [guidanceInput, setGuidanceInput] = useState('');

    const stepData = (activeExperiment.stepData && activeExperiment.stepData[stepId]) || {};
    const savedOutput = typeof stepData.output === 'string' ? stepData.output : '';
    const currentText = typeof streamingText === 'string' ? streamingText : savedOutput;

    useEffect(() => {
        setEditText(savedOutput);
    }, [savedOutput]);

    const handleSave = () => {
        updateExperiment({ 
            ...activeExperiment, 
            stepData: { 
                ...activeExperiment.stepData, 
                [stepId]: { ...stepData, output: editText } 
            } 
        });
        setIsEditing(false);
        addToast("Archival node updated.", "success");
    };

    const handleRegenerate = () => {
        if (isLoading) return;
        // For Step 3, we prioritize the dedicated guidance input
        const feedback = stepId === 3 ? guidanceInput : regenFeedback;
        onGenerate(feedback);
        if (stepId !== 3) {
            setShowRegenInput(false);
        }
        setRegenFeedback('');
    };

    const renderedHtml = useMemo(() => {
        if (!currentText) return '';
        try {
            return renderMarkdown(currentText, !isLoading);
        } catch (e) {
            console.error("Critical rendering error detected:", e);
            return `<div class="alert alert-danger">Rendering Error: Content Stream Interrupted.</div><pre class="text-white-50 small">${currentText.slice(0, 500)}...</pre>`;
        }
    }, [currentText, isLoading]);

    const renderJsonContent = (text: string) => {
        try {
            const clean = extractJson(text);
            if (!clean) throw new Error("No JSON found");
            const data = JSON.parse(clean);

            if (stepId === 1) {
                return (
                   <div className="animate-in">
                       <div className="mb-4" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.research_question || '', true) }} />
                       {data.uniqueness_score !== undefined && (
                           <UniquenessMeter 
                                score={data.uniqueness_score} 
                                justification={data.justification || ''} 
                           />
                       )}
                   </div>
               );
            }

            if (stepId === 2) {
                return (
                    <div className="lit-review-output animate-in">
                        <h5 className="fw-bold text-primary-glow border-bottom border-secondary border-opacity-25 pb-2 mb-3">Synthesis of Findings</h5>
                        <div className="generated-text-container mb-4" dangerouslySetInnerHTML={{ __html: renderMarkdown(data.summary || '', true) }} />
                        {data.references && Array.isArray(data.references) && data.references.length > 0 && (
                            <section>
                                <h5 className="fw-bold text-info small text-uppercase ls-1 border-bottom border-secondary border-opacity-10 pb-2 mb-3">Grounding Links</h5>
                                <div className="list-group list-group-flush bg-transparent">
                                    {data.references.map((ref: any, i: number) => (
                                        <div key={i} className="list-group-item bg-transparent border-secondary border-opacity-10 px-0 py-2">
                                            <div className="fw-bold text-white small">{ref.title}</div>
                                            <div className="text-white-50" style={{fontSize: '0.75rem'}}>{ref.authors?.join(', ')} ({ref.year})</div>
                                            {ref.url && <a href={ref.url} target="_blank" rel="noopener noreferrer" className="small text-primary-glow">View Source &raquo;</a>}
                                        </div>
                                    ))}
                                </div>
                            </section>
                        )}
                    </div>
                );
            }

            if (stepId === 7) return <DataAnalysisView analysisData={data} />;
            return <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />;
        } catch (e) {
            return (
                <div>
                     <div className="alert alert-warning small">
                        <i className="bi bi-exclamation-triangle me-2"></i>
                        Visual rendering failed due to malformed data. Raw output displayed below.
                    </div>
                    <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />
                </div>
            );
        }
    };

    const isJsonStep = stepId === 1 || stepId === 2 || stepId === 7;

    return (
        <div className="generated-content-container">
            {isLoading && (
                <div className="archive-status-line mb-4 px-3 py-3 rounded d-flex flex-column gap-2 border border-primary border-opacity-25 bg-primary bg-opacity-5">
                    <div className="d-flex align-items-center justify-content-between">
                         <div className="d-flex align-items-center">
                              <div className="spinner-border spinner-border-sm text-primary-glow me-2" role="status"></div>
                              <span className="small text-uppercase fw-bold ls-1 text-primary-glow">
                                {statusMessage || "Processing..."}
                              </span>
                         </div>
                         <div className="spinner-grow spinner-grow-sm text-primary-glow opacity-50" role="status"></div>
                    </div>
                    <div className="progress bg-dark" style={{height: '2px'}}>
                         <div className="progress-bar progress-bar-striped progress-bar-animated bg-primary-glow w-100"></div>
                    </div>
                </div>
            )}

            {!currentText && !isLoading ? (
                <div className="text-center p-5 border border-secondary border-opacity-10 rounded-4 bg-dark bg-opacity-10 my-3">
                    <i className="bi bi-cpu mb-3 text-primary-glow opacity-50 d-block" style={{ fontSize: '2.5rem' }}></i>
                    <h5 className="fw-bold mb-2">Initialize Archival Node</h5>
                    <p className="text-white-50 small mb-4 mx-auto" style={{maxWidth: '350px'}}>
                        Synthesize discovery data from previous steps into a verifiable research node.
                    </p>

                    {stepId === 3 && (
                        <div className="mb-4 text-start mx-auto p-3 rounded bg-black bg-opacity-20 border border-secondary border-opacity-25" style={{maxWidth: '450px'}}>
                            <label className="form-label small fw-bold text-warning mb-1">
                                <i className="bi bi-compass me-1"></i> Directional Guidance (Optional)
                            </label>
                            <div className="input-group">
                                <input
                                    type="text"
                                    className="form-control bg-dark border-secondary text-white small"
                                    placeholder="E.g., 'Focus on counter-intuitive mechanisms' or 'Prioritize low-cost methods'"
                                    value={guidanceInput}
                                    onChange={(e) => setGuidanceInput(e.target.value)}
                                    style={{fontSize: '0.9rem'}}
                                />
                            </div>
                            <div className="form-text text-white-50" style={{fontSize: '0.75rem'}}>
                                Use the <strong>Tuning</strong> menu below for precise parameter control.
                            </div>
                        </div>
                    )}

                    <button className="btn btn-primary px-5 py-2 rounded-pill shadow-sm" onClick={() => handleRegenerate()}>
                        <i className="bi bi-lightning-charge-fill me-2"></i> Generate {stepId === 3 ? 'Hypotheses' : 'Output'}
                    </button>
                </div>
            ) : null}

            {currentText && !isLoading && !isEditing && (
                <div className="animate-in">
                    {isJsonStep ? renderJsonContent(currentText) : <div dangerouslySetInnerHTML={{ __html: renderedHtml }} />}

                    <div className="mt-4 pt-3 border-top border-secondary border-opacity-10 d-flex justify-content-between align-items-center">
                        <div className="d-flex gap-2 align-items-center flex-wrap">
                            <button className="btn btn-sm btn-outline-secondary" onClick={() => setIsEditing(true)}>
                                <i className="bi bi-pencil me-1"></i> Edit Content
                            </button>

                            {stepId === 3 ? (
                                <div className="input-group input-group-sm ms-2" style={{width: '320px'}}>
                                    <span className="input-group-text bg-dark border-secondary text-white-50">
                                        <i className="bi bi-arrow-clockwise"></i>
                                    </span>
                                    <input
                                        type="text"
                                        className="form-control bg-dark border-secondary text-white"
                                        placeholder="Pivot (e.g. 'Make it more abstract')"
                                        value={guidanceInput}
                                        onChange={(e) => setGuidanceInput(e.target.value)}
                                    />
                                    <button className="btn btn-outline-warning" onClick={handleRegenerate} title="Regenerate with guidance">
                                        Go
                                    </button>
                                </div>
                            ) : (
                                <>
                                    <button 
                                        className={`btn btn-sm ${showRegenInput ? 'btn-secondary' : 'btn-outline-secondary'}`} 
                                        onClick={() => setShowRegenInput(!showRegenInput)}
                                    >
                                        <i className="bi bi-arrow-clockwise me-1"></i> Regenerate
                                    </button>

                                    {showRegenInput && (
                                        <div className="d-flex gap-2 animate-in">
                                            <input 
                                                type="text" 
                                                className="form-control form-control-sm bg-dark text-white border-secondary" 
                                                placeholder="Instructions (e.g., 'Be more concise')"
                                                value={regenFeedback}
                                                onChange={(e) => setRegenFeedback(e.target.value)}
                                                autoFocus
                                            />
                                            <button className="btn btn-sm btn-warning" onClick={handleRegenerate}>Go</button>
                                        </div>
                                    )}
                                </>
                            )}
                        </div>
                        <div className="text-white-50 small fst-italic">
                            AI-Generated • Verify before proceeding
                        </div>
                    </div>
                </div>
            )}

            {isEditing && (
                <div className="editing-interface animate-in">
                    <div className="d-flex justify-content-between align-items-center mb-2">
                        <h6 className="fw-bold text-primary-glow">Editing Archival Node</h6>
                        <span className="badge bg-secondary">Manual Override</span>
                    </div>
                    <textarea 
                        className="form-control mb-3 font-monospace small bg-dark text-white border-secondary" 
                        rows={15} 
                        value={editText}
                        onChange={(e) => setEditText(e.target.value)}
                    ></textarea>
                    <div className="d-flex justify-content-end gap-2">
                        <button className="btn btn-outline-secondary" onClick={() => setIsEditing(false)}>Cancel</button>
                        <button className="btn btn-success" onClick={handleSave}><i className="bi bi-save me-1"></i> Save Changes</button>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useExperiment, runManualFormQA } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry, extractJson } from '../../../services';
import { DYNAMIC_TABLE_SCHEMA } from '../../../config';
import { AgenticAnalysisView } from '../../common/AgenticAnalysisView';
import * as XLSX from 'xlsx';

export const ManualDataEntry = ({ onComplete, context }) => {
    const { isAuthenticated, activeExperiment } = useExperiment();
    const [columns, setColumns] = useState<string[]>([]);
    const [rows, setRows] = useState<Record<string, string>[]>([]);
    const [agenticRun, setAgenticRun] = useState({
        status: 'idle',
        logs: [],
        iterations: 0,
        maxIterations: 5,
    });
    const { addToast } = useToast();
    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        if (activeExperiment?.automationMode === 'automated') {
             addToast("Manual Data Entry required. Automation paused for user input.", "info");
        }
        return () => { isMounted.current = false; };
    }, [activeExperiment?.automationMode, addToast]);

    const initializeForm = useCallback(async () => {
        if (!isAuthenticated || agenticRun.status === 'running') return;

        setAgenticRun(prev => ({ ...prev, status: 'running', logs: [], iterations: 0 }));
        let lastFeedback = "";

        for (let i = 0; i < agenticRun.maxIterations; i++) {
            if (!isMounted.current) return;

            try {
                const attempt = i + 1;
                setAgenticRun(prev => ({ 
                    ...prev, 
                    iterations: attempt,
                    logs: [...prev.logs, { agent: 'Architect', message: `Attempt ${attempt}: Generating data entry schema...` }] 
                }));

                const prompt = `ACT AS: Scientific Database Architect.
                Based on the data collection plan: "${context.data_collection_plan_summary}", generate a JSON array of column objects for a data table.

                ${lastFeedback ? `CRITICAL FAILURE IN PREVIOUS ATTEMPT: ${lastFeedback}. You MUST fix these structural issues.` : ''}

                REQUIREMENTS:
                1. Output a JSON array where each object has "columnName" and "dataType".
                2. Columns MUST map directly to the variables in the methodology.

                Output ONLY raw JSON array.`;

                const response = await callGeminiWithRetry('gemini-3-flash-preview', { 
                    contents: prompt, 
                    config: { responseMimeType: "application/json", responseSchema: DYNAMIC_TABLE_SCHEMA } 
                });

                const schemaText = extractJson(response.text);

                setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Auditor', message: 'Analyzing schema integrity against methodology...' }] }));
                const qa = await runManualFormQA(schemaText, context);

                if (qa.is_valid && qa.quality_score > 0.6) {
                    const schemaArray = JSON.parse(schemaText);
                    const newColumns = schemaArray.map((col: any) => col.columnName);
                    if (newColumns.length === 0) throw new Error("Architect returned zero columns.");

                    setColumns(newColumns);
                    setRows([Object.fromEntries(newColumns.map((c: string) => [c, '']))]);
                    setAgenticRun(prev => ({ ...prev, status: 'success' }));
                    addToast("Data entry portal initialized and verified.", "success");
                    return;
                } else {
                    lastFeedback = qa.issues.join('; ');
                    setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Auditor', message: `SCHEMA REJECTED: ${lastFeedback}. Retrying...` }] }));
                    // Small delay to prevent tight-loop 429s during self-healing
                    await new Promise(r => setTimeout(r, 2000));
                }
            } catch (err) {
                const msg = parseGeminiError(err);
                setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'System', message: `RECOVERY MODE: ${msg}` }] }));
                await new Promise(r => setTimeout(r, 3000));
            }
        }
        setAgenticRun(prev => ({ ...prev, status: 'failed' }));
    }, [isAuthenticated, context, agenticRun.status, agenticRun.maxIterations, addToast]);

    useEffect(() => {
        if (columns.length === 0 && agenticRun.status === 'idle') {
            initializeForm();
        }
    }, [columns.length, agenticRun.status, initializeForm]);

    const handleRowChange = (index, col, value) => {
        const newRows = [...rows];
        newRows[index][col] = value;
        setRows(newRows);
    };

    const addRow = () => setRows([...rows, Object.fromEntries(columns.map(c => [c, '']))]);
    const removeRow = (index) => setRows(rows.filter((_, i) => i !== index));

    const handleSubmit = () => {
        if (rows.some(r => Object.values(r).some(v => !(v as string).trim()))) {
            if (!window.confirm("PROTOCOL WARNING: Some fields are empty. This may degrade analysis quality. Proceed anyway?")) return;
        }
        const header = columns.join(',');
        const body = rows.map(row => columns.map(col => `"${(row[col] || '').replace(/"/g, '""')}"`).join(',')).join('\n');
        onComplete(`${header}\n${body}`, "Manually entered forensic data.");
    };

    const handleDownloadTemplate = () => {
        if (columns.length === 0) {
            addToast("Initialize the table structure first.", "warning");
            return;
        }
        try {
            const ws = XLSX.utils.aoa_to_sheet([columns]);
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, ws, "Template");
            XLSX.writeFile(wb, "hypatia_data_template.xlsx");
            addToast("Template downloaded successfully.", "success");
        } catch (e) {
            console.error(e);
            addToast("Failed to generate Excel template.", "danger");
        }
    };

    if (agenticRun.status === 'running') return <AgenticAnalysisView agenticRun={agenticRun} title="Building Data Entry Portal" subtitle="Agents are negotiating table structure and variable mapping." />;

    return (
        <div className="animate-in">
            {agenticRun.status === 'failed' ? (
                <div className="alert alert-danger">
                    <h6 className="fw-bold">Form Generation Protocol Failed</h6>
                    <p className="small mb-2">The AI Architect could not produce a stable schema. This is usually due to an underspecified methodology.</p>
                    <button className="btn btn-sm btn-outline-danger" onClick={() => { setAgenticRun(p => ({...p, status: 'idle'})); setColumns([]); }}>Retry Initialization</button>
                </div>
            ) : (
                <div className="card mb-4 border-secondary border-opacity-25 bg-black bg-opacity-20 shadow-sm">
                    <div className="card-body">
                        <div className="d-flex justify-content-between align-items-center mb-3">
                            <h6 className="fw-bold mb-0">Step 6: Forensic Data Entry</h6>
                            <div className="d-flex gap-2">
                                <button className="btn btn-xs btn-outline-success" onClick={handleDownloadTemplate} title="Download Excel Template" disabled={columns.length === 0}>
                                    <i className="bi bi-file-earmark-excel me-1"></i> Template
                                </button>
                                <button className="btn btn-xs btn-outline-secondary" onClick={() => { if(window.confirm("Reset table structure?")) { setColumns([]); setAgenticRun(p=>({...p, status:'idle'})); }}} title="Re-initialize Architect Agents">
                                    <i className="bi bi-gear-wide-connected"></i>
                                </button>
                            </div>
                        </div>
                        <div className="table-responsive">
                            <table className="table table-bordered border-secondary border-opacity-10 mb-3">
                                <thead className="bg-dark bg-opacity-50">
                                    <tr>{columns.map(c => <th key={c} className="small text-uppercase ls-1">{c}</th>)}<th style={{ width: '50px' }}></th></tr>
                                </thead>
                                <tbody>
                                    {rows.map((row, rowIndex) => (
                                        <tr key={rowIndex}>
                                            {columns.map(col => <td key={col} className="p-1"><input type="text" className="form-control form-control-sm border-0 bg-transparent text-white" value={row[col] || ''} onChange={e => handleRowChange(rowIndex, col, e.target.value)} /></td>)}
                                            <td className="p-1 text-center"><button className="btn btn-sm text-danger" onClick={() => removeRow(rowIndex)} disabled={rows.length <= 1}><i className="bi bi-x-lg"></i></button></td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="d-flex justify-content-between">
                            <button className="btn btn-sm btn-outline-secondary" onClick={addRow}><i className="bi bi-plus-lg me-1"></i> Add Record</button>
                            <button className="btn btn-success px-4" onClick={handleSubmit}><i className="bi bi-check-circle-fill me-1"></i> Finalize Entry</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useExperiment, runDataQA } from '../../../services';
import { useToast } from '../../../toast';
import { parseGeminiError, callGeminiWithRetry, extractJson } from '../../../services';
import { AgenticAnalysisView } from '../../common/AgenticAnalysisView';
import { cleanAndFormatCsv } from '../../../utils/csvUtils';

export const DataSynthesizer = ({ onComplete, context }) => {
    const { isAuthenticated } = useExperiment();
    const [result, setResult] = useState<{ summary: string, csv: string } | null>(null);
    const [agenticRun, setAgenticRun] = useState({
        status: 'idle',
        logs: [],
        iterations: 0,
        maxIterations: 10,
    });
    const { addToast } = useToast();

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; };
    }, []);

    const handleSynthesize = useCallback(async () => {
        if (!isAuthenticated || agenticRun.status === 'running') return;

        setAgenticRun(prev => ({ ...prev, status: 'running', logs: [], iterations: 0 }));
        let lastFeedback = "";

        for (let i = 0; i < agenticRun.maxIterations; i++) {
            if (!isMounted.current) return;

            const attempt = i + 1;
            setAgenticRun(prev => ({ 
                ...prev, 
                iterations: attempt,
                logs: [...prev.logs, { agent: 'Synthesizer', message: `Attempt ${attempt}: Generating plausible data vectors...` }] 
            }));

            const prompt = `DATA PROVENANCE REQUIREMENT: You are synthesizing synthetic data. 
            Based on Methodology: "${context.methodology_summary}" and Data Plan: "${context.data_collection_plan_summary}", generate a plausible estimated dataset.

            ${lastFeedback ? `PREVIOUS ATTEMPT FAILED QA: ${lastFeedback}. Fix formatting and ensure data is present in ALL cells.` : ''}

            **CRITICAL**: YOU MUST ENSURE DATA IS PRESENT IN ALL COLUMNS FOR ALL ROWS. NO NULLS.

            Output valid JSON object with:
            1. "summary": A brief one-sentence description.
            2. "data": Array of objects, where keys are column names and values are data points.

            Output ONLY raw JSON.`;

            try {
                const response = await callGeminiWithRetry('gemini-3-flash-preview', { 
                    contents: prompt,
                    config: { responseMimeType: "application/json" }
                });
                if (!isMounted.current) return;

                const jsonText = extractJson(response.text);
                const parsed = JSON.parse(jsonText);
                const summary = parsed.summary || "Data synthesized by AI.";
                const dataArray = parsed.data || [];

                if (!Array.isArray(dataArray) || dataArray.length === 0) throw new Error("Generated data is empty.");

                // Convert to CSV
                const columns = Object.keys(dataArray[0]);
                const csvHeader = columns.join(',');
                const csvRows = dataArray.map((row: any) => 
                    columns.map(col => {
                        const val = row[col] === undefined || row[col] === null ? '' : String(row[col]);
                        return `"${val.replace(/"/g, '""')}"`;
                    }).join(',')
                );
                const rawCsv = [csvHeader, ...csvRows].join('\n');
                const cleanCsv = cleanAndFormatCsv(rawCsv);

                setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Auditor', message: 'Analyzing dataset structure and completeness...' }] }));
                const qa = await runDataQA(cleanCsv, context);

                if (qa.is_valid && qa.quality_score > 0.5) {
                    setResult({ summary, csv: cleanCsv });
                    setAgenticRun(prev => ({ ...prev, status: 'success' }));
                    addToast("Synthetic dataset verified by Auditor.", "success");
                    return;
                } else {
                    lastFeedback = qa.issues.join('; ');
                    setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'Auditor', message: `Dataset rejected: ${lastFeedback}. Retrying generation...` }] }));
                }
            } catch (err) {
                const msg = parseGeminiError(err);
                setAgenticRun(prev => ({ ...prev, logs: [...prev.logs, { agent: 'System', message: `ERROR: ${msg}` }] }));
                await new Promise(r => setTimeout(r, 2000));
            }
        }
        setAgenticRun(prev => ({ ...prev, status: 'failed' }));
    }, [isAuthenticated, context, agenticRun.status, agenticRun.maxIterations, addToast]);

    return (
        <div className="data-synthesizer-node">
            {agenticRun.status === 'idle' && (
                <div className="text-center p-4">
                    <h6 className="fw-bold"><i className="bi bi-magic me-2"></i>AI Data Synthesis</h6>
                    <p className="text-white-50 small mb-4">Autonomous generation of high-fidelity theoretical datasets.</p>
                    <button className="btn btn-primary px-5 py-2 rounded-pill" onClick={handleSynthesize}>Execute Synthesis Protocol</button>
                </div>
            )}

            {agenticRun.status === 'running' && (
                <AgenticAnalysisView agenticRun={agenticRun} title="Synthetic Data Orchestration" subtitle="Generating and auditing theoretical data nodes via JSON-first protocol." />
            )}

            {agenticRun.status === 'failed' && (
                <div className="alert alert-danger text-center">
                    <h6>Synthesis protocol aborted.</h6>
                    <button className="btn btn-sm btn-outline-danger mt-2" onClick={handleSynthesize}>Re-Initiate</button>
                </div>
            )}

            {agenticRun.status === 'success' && result && (
                <div className="mt-2 animate-in">
                    <div className="alert alert-success border-success border-opacity-25 bg-success bg-opacity-5 p-3 mb-4">
                        <i className="bi bi-check-circle-fill me-2"></i>
                        <strong>QA APPROVED:</strong> Archival integrity score high. Data ready for analysis.
                    </div>
                    <p className="small"><strong>Disclosure:</strong> {result.summary}</p>
                    <textarea className="form-control font-monospace mb-3 bg-black text-primary-glow" readOnly rows={6} value={result.csv} />
                    <button className="btn btn-success w-100 py-2 shadow-sm" onClick={() => onComplete(result.csv, result.summary)}>Load Dataset into Analysis Node</button>
                </div>
            )}
        </div>
    );
};

import { Experiment, LITERATURE_REVIEW_SCHEMA, DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA, DATA_QA_SCHEMA, DYNAMIC_TABLE_SCHEMA } from '../config';
import { callGeminiWithRetry, extractJson, isValidJsonForSchema, parseBlockers } from './api';
import { getStepContext } from './prompts';
import { ensureChartStyling } from '../utils/chartUtils';

export const executeStepWorkflow = async (
    modelName: string, 
    params: any, 
    context: any, 
    isJsonMode: boolean, 
    schema: any
): Promise<string> => {
    if (isJsonMode && schema) {
        params.config = { 
            ...params.config, 
            responseMimeType: "application/json", 
            responseSchema: schema 
        };
    }

    const response = await callGeminiWithRetry(modelName, params);
    let output = response.text;

    if (isJsonMode) {
        output = extractJson(output);
        if (!isValidJsonForSchema(output, schema)) {
            // Self-Correction Loop
            console.warn("Schema validation failed, attempting self-correction...");
            const repairPrompt = `The previous output did not match the required JSON schema. 
            ERROR: Invalid Schema. 
            REQUIRED SCHEMA: ${JSON.stringify(schema)}
            PREVIOUS OUTPUT: ${output}

            Fix the JSON structure and return only the valid JSON object. Do not include markdown code blocks.`;

            const repairResponse = await callGeminiWithRetry('gemini-3-flash-preview', { contents: repairPrompt, config: { responseMimeType: "application/json", responseSchema: schema } });
            output = extractJson(repairResponse.text);
        }
    }
    return output;
};


// --- AGENTIC WORKFLOWS ---

/**
 * Manual Form QA Agent: Checks if the generated table schema is valid for data collection.
 */
export const runManualFormQA = async (schemaJson: string, context: any) => {
    const prompt = `
    ACT AS: Scientific Database Architect.
    TASK: Audit the proposed data entry table schema for an experiment.

    PROPOSED SCHEMA:
    ${schemaJson}

    CONTEXT:
    - Methodology: ${context.methodology_summary}
    - Data Plan: ${context.data_collection_plan_summary}

    AUDIT CHECKLIST:
    1. Validity: Is it a non-empty array of column objects?
    2. Alignment: Do columns match the independent and dependent variables in the plan?
    3. Completeness: Are there enough columns to capture the full observation protocol?

    If the schema is flawed (e.g., missing keys like "columnName" or "dataType"), you MUST provide a corrected JSON version.

    Output ONLY valid JSON matching the QA schema.
    `;

    const response = await callGeminiWithRetry('gemini-3-flash-preview', { 
        contents: prompt,
        config: { responseMimeType: "application/json", responseSchema: DATA_QA_SCHEMA }
    });

    return JSON.parse(extractJson(response.text));
};

/**
 * QA Agent to verify experimental data quality before analysis.
 * ENFORCES: Data presence in all columns and correct formatting.
 */
export const runDataQA = async (csvData: string, context: any) => {
    const prompt = `
    ACT AS: Scientific Data Auditor (QA).
    TASK: Verify the structural integrity and scientific plausibility of the following experimental dataset.

    DATASET:
    ${csvData.substring(0, 5000)}

    RESEARCH CONTEXT:
    - Hypothesis: ${context.hypothesis}
    - Methodology: ${context.methodology_summary}

    STRICT COMPLIANCE RULES:
    1. CSV structure: Must have a header row and consistent column counts for every data row.
    2. Data Presence: EVERY column in EVERY row MUST have data. No empty fields or nulls allowed.
    3. Plausibility: Data must represent the variables defined in the methodology. 
    4. Formatting: No stray characters, commas in unquoted fields, or malformed lines.

    Output ONLY valid JSON matching the QA schema.
    `;

    const response = await callGeminiWithRetry('gemini-3-flash-preview', { 
        contents: prompt,
        config: { responseMimeType: "application/json", responseSchema: DATA_QA_SCHEMA }
    });

    return JSON.parse(extractJson(response.text));
};

export const runDataAnalysisAgent = async ({ experiment, csvData, updateLog }: { experiment: Experiment, csvData: string, updateLog: (agent: string, msg: string) => void }) => {
    updateLog('Manager', 'Initiating Data Analysis Agent Swarm...');

    const context = await getStepContext(experiment, 7);

    // 0. Data QA First
    updateLog('Auditor', 'Performing quality assurance on acquisition node...');
    const qaResult = await runDataQA(csvData, context);
    if (!qaResult.is_valid || qaResult.quality_score < 0.4) {
        updateLog('Auditor', `DATA QUALITY FAILURE: ${qaResult.issues.join('; ')}`);
        throw new Error(`DATA_QUALITY_FAILURE: ${qaResult.recommendation || "The dataset is unsuitable for analysis."}`);
    }
    updateLog('Auditor', `Data integrity verified (Quality Score: ${qaResult.quality_score}).`);

    // 1. Data Profiler
    updateLog('Profiler', 'Scanning dataset structure and quality...');
    const profilerPrompt = `
    Analyze this dataset to identify its structure, variables, and potential anomalies.

    DATASET (First 5000 chars):
    ${csvData.substring(0, 5000)}

    RESEARCH CONTEXT:
    - Question: ${context.question}
    - Hypothesis: ${context.hypothesis}
    `;

    const profileRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: profilerPrompt });
    updateLog('Profiler', 'Data profile generated.');

    // 2. Statistician & Visualizer
    updateLog('Analyst', 'Executing statistical tests and generating high-fidelity visualizations...');
    const analysisPrompt = `
    ACT AS: Senior Data Scientist.
    TASK: Perform a rigorous statistical analysis on the provided dataset to test the hypothesis.

    DATA PROFILE: ${profileRes.text}
    RAW DATA: ${csvData}
    HYPOTHESIS TO TEST: ${context.hypothesis}

    REQUIREMENTS:
    1. Perform appropriate tests (ANOVA, t-test, Regression).
    2. Generate a detailed Markdown summary of the results.
    3. Generate AT LEAST TWO (2) distinct Chart.js configuration objects (as JSON strings).
       - For Scatter charts, ensure data is [{"x": 1, "y": 2}, ...].

    CRITICAL: Output MUST be valid JSON matching the schema.
    `;

    const analysisRes = await callGeminiWithRetry('gemini-3-pro-preview', { 
        contents: analysisPrompt,
        config: { 
            responseMimeType: "application/json", 
            responseSchema: DATA_ANALYSIS_IMAGE_OUTPUT_SCHEMA
        }
    });

    let resultJson = extractJson(analysisRes.text);

    try {
        const parsed = JSON.parse(resultJson);
        if (parsed.charts && Array.isArray(parsed.charts)) {
            parsed.charts = parsed.charts.map((c: any) => {
                const config = typeof c.chartConfig === 'string' ? JSON.parse(c.chartConfig) : c.chartConfig;
                const styledConfig = ensureChartStyling(config);
                return { ...c, chartConfig: JSON.stringify(styledConfig) };
            });
            resultJson = JSON.stringify(parsed);
        }
        updateLog('Visualizer', 'Visual assets synthesized.');
    } catch (e) {
        console.error("Analysis post-processing error:", e);
    }

    const blockerPrompt = `Analyze the results for any scientific integrity blockers.
    RESULTS: ${resultJson}
    Output JSON: { "BLOCKER_ALERT": [ { "severity": "critical"|"warning", "msg": "..." } ] } or empty.`;

    const blockerRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: blockerPrompt });
    const blockers = parseBlockers(blockerRes.text);

    return { finalOutput: resultJson, blockers, logSummary: profileRes.text };
};

export const runInterpretationAgent = async ({ experiment, updateLog }: { experiment: Experiment, updateLog: (agent: string, msg: string) => void }) => {
    updateLog('Manager', 'Initiating Interpretation Node...');
    const context = await getStepContext(experiment, 8);

    updateLog('Philosopher', 'Cross-referencing hypothesis with statistical evidence...');
    const analysisPrompt = `
    ACT AS: Principal Investigator.
    TASK: Evaluate the robustness of the experimental findings.

    HYPOTHESIS: ${context.hypothesis}
    ANALYSIS SUMMARY: ${context.analysis_summary}
    FIELD: ${experiment.field}

    Discuss:
    1. Does the evidence reject the null hypothesis?
    2. Threats to internal and external validity.
    3. Specific recommendations for follow-up research.

    Output a rigorous Markdown report.
    `;

    const res = await callGeminiWithRetry('gemini-3-pro-preview', { contents: analysisPrompt });

    updateLog('Auditor', 'Checking for over-claiming or logical leaps...');
    const blockerPrompt = `Analyze this conclusion for over-claiming.
    CONCLUSION: ${res.text}
    Output JSON: { "BLOCKER_ALERT": [ { "severity": "critical"|"warning", "msg": "..." } ] } or empty.`;

    const blockerRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: blockerPrompt });
    const blockers = parseBlockers(blockerRes.text);

    return { finalOutput: res.text, blockers };
};

export const runPublicationAgent = async ({ experiment, updateLog }: { experiment: Experiment, updateLog: (agent: string, msg: string) => void }) => {
    updateLog('Manager', 'Compiling project dossier...');
