export const runLiteratureReviewAgent = async ({ experiment, updateLog }: { experiment: Experiment, updateLog: (agent: string, msg: string) => void }) => {
    updateLog('Librarian', 'Formulating search queries...');
    const context = await getStepContext(experiment, 2);

    const searchPrompt = `Research Question: ${context.question}. Find 5 seminal papers. Use googleSearch.`;
    const searchRes = await callGeminiWithRetry('gemini-3-flash-preview', { contents: searchPrompt, config: { tools: [{ googleSearch: {} }] } });

